			}
			object[] item = new object[2]
			{
				color,
				new float[5] { thickness, thicknessMul, yPosition, yPositionMul, cap }
			};
			object[][] original = null;
			if (attributes.ContainsKey("UNDERLINE"))
			{
				original = (object[][])attributes["UNDERLINE"];
