		public virtual void RegisterFamily(string familyName, string fullName, string path)
		{
			if (path != null)
			{
				trueTypeFonts[fullName] = path;
			}
			List<string> value;
			lock (fontFamilies)
			{
				fontFamilies.TryGetValue(familyName, out value);
				if (value == null)
				{
					value = new List<string>();
					value.Add(fullName);
					fontFamilies[familyName] = value;
				}
			}
			lock (value)
			{
				if (value.Contains(fullName))
				{
					return;
				}
				int length = fullName.Length;
				bool flag = false;
				for (int i = 0; i < value.Count; i++)
				{
					if (value[i].Length >= length)
					{
						value.Insert(i, fullName);
						flag = true;
						break;
					}
				}
				if (!flag)
				{
					value.Add(fullName);
					string text = fullName.ToLower();
					if (text.EndsWith("regular"))
					{
						text = text.Substring(0, text.Length - 7).Trim();
						value.Insert(0, fullName.Substring(0, text.Length));
					}
				}
			}
		}

		public virtual void Register(string path)
		{
			Register(path, null);
		}

		public virtual void Register(string path, string alias)
		{
			try
			{
				if (path.ToLower(CultureInfo.InvariantCulture).EndsWith(".ttf") || path.ToLower(CultureInfo.InvariantCulture).EndsWith(".otf") || path.ToLower(CultureInfo.InvariantCulture).IndexOf(".ttc,") > 0)
				{
					object[] allFontNames = BaseFont.GetAllFontNames(path, "Cp1252", null);
					trueTypeFonts[((string)allFontNames[0]).ToLower(CultureInfo.InvariantCulture)] = path;
					if (alias != null)
					{
						string text = alias.ToLower(CultureInfo.InvariantCulture);
						trueTypeFonts[text] = path;
						if (text.EndsWith("regular"))
						{
							SaveCopyOfRegularFont(text, path);
						}
					}
					string[][] array = (string[][])allFontNames[2];
					for (int i = 0; i < array.Length; i++)
					{
						string text2 = array[i][3].ToLower(CultureInfo.InvariantCulture);
						trueTypeFonts[text2] = path;
						if (text2.EndsWith("regular"))
						{
							SaveCopyOfRegularFont(text2, path);
						}
					}
					string text3 = null;
					string text4 = null;
					array = (string[][])allFontNames[1];
					for (int j = 0; j < TTFamilyOrder.Length; j += 3)
					{
						string[][] array2 = array;
						foreach (string[] array3 in array2)
						{
							if (TTFamilyOrder[j].Equals(array3[0]) && TTFamilyOrder[j + 1].Equals(array3[1]) && TTFamilyOrder[j + 2].Equals(array3[2]))
							{
								text4 = array3[3].ToLower(CultureInfo.InvariantCulture);
								j = TTFamilyOrder.Length;
								break;
							}
						}
					}
					if (text4 != null)
					{
						string value = "";
						array = (string[][])allFontNames[2];
						string[][] array4 = array;
						foreach (string[] array5 in array4)
						{
							for (int m = 0; m < TTFamilyOrder.Length; m += 3)
							{
								if (TTFamilyOrder[m].Equals(array5[0]) && TTFamilyOrder[m + 1].Equals(array5[1]) && TTFamilyOrder[m + 2].Equals(array5[2]))
								{
									text3 = array5[3];
									if (!text3.Equals(value))
									{
										value = text3;
										RegisterFamily(text4, text3, null);
										break;
									}
								}
							}
						}
					}
				}
				else if (path.ToLower(CultureInfo.InvariantCulture).EndsWith(".ttc"))
				{
					if (alias != null)
					{
						LOGGER.Error("You can't define an alias for a true type collection.");
					}
					string[] array6 = BaseFont.EnumerateTTCNames(path);
					for (int n = 0; n < array6.Length; n++)
					{
						Register(path + "," + n);
					}
				}
				else if (path.ToLower(CultureInfo.InvariantCulture).EndsWith(".afm") || path.ToLower(CultureInfo.InvariantCulture).EndsWith(".pfm"))
				{
					BaseFont baseFont = BaseFont.CreateFont(path, "Cp1252", embedded: false);
					string text5 = baseFont.FullFontName[0][3].ToLower(CultureInfo.InvariantCulture);
					string familyName = baseFont.FamilyFontName[0][3].ToLower(CultureInfo.InvariantCulture);
					string key = baseFont.PostscriptFontName.ToLower(CultureInfo.InvariantCulture);
					RegisterFamily(familyName, text5, null);
					trueTypeFonts[key] = path;
					trueTypeFonts[text5] = path;
				}
				if (LOGGER.IsLogging(Level.TRACE))
				{
					LOGGER.Trace($"Registered {path}");
				}
			}
			catch (DocumentException ex)
			{
				throw ex;
			}
			catch (IOException ex2)
			{
				throw ex2;
			}
		}

		protected bool SaveCopyOfRegularFont(string regularFontName, string path)
		{
			string key = regularFontName.Substring(0, regularFontName.Length - 7).Trim();
			if (!trueTypeFonts.ContainsKey(key))
			{
				trueTypeFonts[key] = path;
				return true;
			}
			return false;
		}

		public virtual int RegisterDirectory(string dir)
		{
			return RegisterDirectory(dir, scanSubdirectories: false);
		}

		public virtual int RegisterDirectory(string dir, bool scanSubdirectories)
		{
			if (LOGGER.IsLogging(Level.DEBUG))
			{
				LOGGER.Debug($"Registering directory {dir}, looking for fonts");
			}
			int num = 0;
			try
			{
				if (!Directory.Exists(dir))
				{
					return 0;
				}
				string[] files = Directory.GetFiles(dir);
				if (files == null)
				{
					return 0;
				}
				for (int i = 0; i < files.Length; i++)
				{
					try
					{
						if (Directory.Exists(files[i]))
						{
							if (scanSubdirectories)
							{
								num += RegisterDirectory(System.IO.Path.GetFullPath(files[i]), scanSubdirectories: true);
							}
							continue;
						}
						string fullPath = System.IO.Path.GetFullPath(files[i]);
						string value = ((fullPath.Length < 4) ? null : fullPath.Substring(fullPath.Length - 4).ToLower(CultureInfo.InvariantCulture));
						if (".afm".Equals(value) || ".pfm".Equals(value))
						{
							string path = fullPath.Substring(0, fullPath.Length - 4) + ".pfb";
							if (File.Exists(path))
							{
								Register(fullPath, null);
								num++;
							}
						}
						else if (".ttf".Equals(value) || ".otf".Equals(value) || ".ttc".Equals(value))
						{
							Register(fullPath, null);
							num++;
						}
					}
					catch
					{
					}
				}
			}
			catch
			{
			}
			return num;
		}

		public virtual int RegisterDirectories()
		{
			if (Environment.OSVersion.Platform == PlatformID.Unix || Environment.OSVersion.Platform == PlatformID.MacOSX)
			{
				int num = 0;
				num += RegisterDirectory("/usr/share/X11/fonts", scanSubdirectories: true);
				num += RegisterDirectory("/usr/X/lib/X11/fonts", scanSubdirectories: true);
				num += RegisterDirectory("/usr/openwin/lib/X11/fonts", scanSubdirectories: true);
				num += RegisterDirectory("/usr/share/fonts", scanSubdirectories: true);
				num += RegisterDirectory("/usr/X11R6/lib/X11/fonts", scanSubdirectories: true);
				num += RegisterDirectory("/Library/Fonts");
				return num + RegisterDirectory("/System/Library/Fonts");
			}
			try
			{
				if (SystemPath == null)
				{
					SystemPath = Directory.GetParent(Environment.GetFolderPath(Environment.SpecialFolder.System)).FullName;
				}
				string dir = System.IO.Path.Combine(SystemPath, "Fonts");
				return RegisterDirectory(dir);
			}
			catch (Exception)
			{
			}
			return 0;
		}

		public virtual bool IsRegistered(string fontname)
		{
			return trueTypeFonts.ContainsKey(fontname.ToLower(CultureInfo.InvariantCulture));
		}
	}
