			: base(numbered: true, symbolIndent)
		{
			SetGreekFont();
		}

		public GreekList(bool greeklower, int symbolIndent)
			: base(numbered: true, symbolIndent)
		{
			lowercase = greeklower;
			SetGreekFont();
		}

		protected virtual void SetGreekFont()
		{
			float size = symbol.Font.Size;
			symbol.Font = FontFactory.GetFont("Symbol", size, 0);
		}

		public override bool Add(IElement o)
		{
			if (o is ListItem)
			{
				ListItem listItem = (ListItem)o;
				Chunk chunk = new Chunk(preSymbol, symbol.Font);
				chunk.Attributes = symbol.Attributes;
				chunk.Append(GreekAlphabetFactory.GetString(first + base.list.Count, lowercase));
				chunk.Append(postSymbol);
				listItem.ListSymbol = chunk;
				listItem.SetIndentationLeft(symbolIndent, autoindent);
				listItem.IndentationRight = 0f;
				base.list.Add(listItem);
				return true;
			}
			if (o is List)
			{
				List list = (List)o;
				list.IndentationLeft += symbolIndent;
				first--;
				base.list.Add(list);
				return true;
			}
			return false;
		}

		public override List CloneShallow()
		{
			GreekList greekList = new GreekList();
			PopulateProperties(greekList);
			return greekList;
		}
	}
	public class Meta : IElement
	{
		public const string UNKNOWN = "unknown";

		public const string PRODUCER = "producer";

		public const string CREATIONDATE = "creationdate";

		public const string AUTHOR = "author";

		public const string KEYWORDS = "keywords";

		public const string SUBJECT = "subject";

		public const string TITLE = "title";

		private int type;

		private StringBuilder content;

		public virtual int Type => type;

		public virtual IList<Chunk> Chunks => new List<Chunk>();

		public virtual string Content => content.ToString();

		public virtual string Name => type switch
		{
			2 => "subject", 
			3 => "keywords", 
			4 => "author", 
			1 => "title", 
			5 => "producer", 
			6 => "creationdate", 
			_ => "unknown", 
		};

		public Meta(int type, string content)
		{
			this.type = type;
			this.content = new StringBuilder(content);
		}

		public Meta(string tag, string content)
		{
			type = GetType(tag);
			this.content = new StringBuilder(content);
		}

		public virtual bool Process(IElementListener listener)
		{
			try
			{
				return listener.Add(this);
			}
			catch (DocumentException)
			{
				return false;
			}
		}

		public virtual bool IsContent()
		{
			return false;
		}

		public virtual bool IsNestable()
		{
			return false;
		}

		public virtual StringBuilder Append(string str)
		{
			return content.Append(str);
		}

		public static int GetType(string tag)
		{
			if ("subject".Equals(tag))
			{
				return 2;
			}
			if ("keywords".Equals(tag))
			{
				return 3;
			}
			if ("author".Equals(tag))
			{
				return 4;
			}
			if ("title".Equals(tag))
			{
				return 1;
			}
			if ("producer".Equals(tag))
			{
				return 5;
			}
			if ("creationdate".Equals(tag))
			{
				return 6;
			}
			return 0;
		}

		public override string ToString()
		{
			return base.ToString();
		}
	}
	public class Header : Meta
	{
		private StringBuilder name;

		public override string Name => name.ToString();

		public Header(string name, string content)
			: base(0, content)
		{
			this.name = new StringBuilder(name);
		}
	}
