namespace iTextSharp.text.html
{
	[Obsolete]
	public static class HtmlEncoder
	{
		private static string[] HTML_CODE;

		private static Dictionary<string, object> NEWLINETAGS;

		static HtmlEncoder()
		{
			HTML_CODE = new string[256];
			NEWLINETAGS = new Dictionary<string, object>();
			NEWLINETAGS["p"] = null;
			NEWLINETAGS["blockquote"] = null;
			NEWLINETAGS["br"] = null;
			for (int i = 0; i < 10; i++)
			{
				HTML_CODE[i] = "&#00" + i + ";";
			}
			for (int j = 10; j < 32; j++)
			{
				HTML_CODE[j] = "&#0" + j + ";";
			}
			for (int k = 32; k < 128; k++)
			{
				HTML_CODE[k] = ((char)k).ToString();
			}
			HTML_CODE[9] = "\t";
			HTML_CODE[10] = "<br />\n";
			HTML_CODE[34] = "&quot;";
			HTML_CODE[38] = "&amp;";
			HTML_CODE[60] = "&lt;";
			HTML_CODE[62] = "&gt;";
			for (int l = 128; l < 256; l++)
			{
				HTML_CODE[l] = "&#" + l + ";";
			}
		}

		public static string Encode(string str)
		{
			int length = str.Length;
			StringBuilder stringBuilder = new StringBuilder();
			for (int i = 0; i < length; i++)
			{
				char c = str[i];
				if (c < 'Ā')
				{
					stringBuilder.Append(HTML_CODE[(uint)c]);
				}
				else
				{
					stringBuilder.Append("&#").Append((int)c).Append(';');
				}
			}
			return stringBuilder.ToString();
		}

		public static string Encode(BaseColor color)
		{
			StringBuilder stringBuilder = new StringBuilder("#");
			if (color.R < 16)
			{
				stringBuilder.Append('0');
			}
			stringBuilder.Append(Convert.ToString(color.R, 16));
			if (color.G < 16)
			{
				stringBuilder.Append('0');
			}
			stringBuilder.Append(Convert.ToString(color.G, 16));
			if (color.B < 16)
			{
				stringBuilder.Append('0');
			}
			stringBuilder.Append(Convert.ToString(color.B, 16));
			return stringBuilder.ToString();
		}

		public static string GetAlignment(int alignment)
		{
			switch (alignment)
			{
			case 0:
				return "left";
			case 1:
				return "center";
			case 2:
				return "right";
			case 3:
			case 8:
				return "justify";
			case 4:
				return "top";
			case 5:
				return "middle";
			case 6:
				return "bottom";
			case 7:
				return "baseline";
			default:
				return "";
			}
		}

		public static bool IsNewLineTag(string tag)
		{
			return NEWLINETAGS.ContainsKey(tag);
		}
	}
