namespace iTextSharp.text.html.simpleparser
{
	[Obsolete]
	public class ChainedProperties
	{
		public sealed class TagAttributes
		{
			internal string tag;

			internal IDictionary<string, string> attrs;

			internal TagAttributes(string tag, IDictionary<string, string> attrs)
			{
				this.tag = tag;
				this.attrs = attrs;
			}
		}

		public IList<TagAttributes> chain = new List<TagAttributes>();

		public string this[string key]
		{
			get
			{
				for (int num = chain.Count - 1; num >= 0; num--)
				{
					TagAttributes tagAttributes = chain[num];
					IDictionary<string, string> attrs = tagAttributes.attrs;
					if (attrs.ContainsKey(key))
					{
						return attrs[key];
					}
				}
				return null;
			}
		}

		public virtual bool HasProperty(string key)
		{
			for (int num = chain.Count - 1; num >= 0; num--)
			{
				TagAttributes tagAttributes = chain[num];
				IDictionary<string, string> attrs = tagAttributes.attrs;
				if (attrs.ContainsKey(key))
				{
					return true;
				}
			}
			return false;
		}

		public virtual void AddToChain(string tag, IDictionary<string, string> props)
		{
			AdjustFontSize(props);
			chain.Add(new TagAttributes(tag, props));
		}

		public virtual void RemoveChain(string tag)
		{
			for (int num = chain.Count - 1; num >= 0; num--)
			{
				if (tag.Equals(chain[num].tag))
				{
					chain.RemoveAt(num);
					break;
				}
			}
		}

		protected internal virtual void AdjustFontSize(IDictionary<string, string> attrs)
		{
			attrs.TryGetValue("size", out var value);
			if (value != null)
			{
				if (value.EndsWith("pt"))
				{
					attrs["size"] = value.Substring(0, value.Length - 2);
					return;
				}
				string previous = this["size"];
				attrs["size"] = HtmlUtilities.GetIndexedFontSize(value, previous).ToString();
			}
		}
	}
}
