namespace iTextSharp.text.html.simpleparser
{
	[Obsolete]
	public class HTMLWorker : ISimpleXMLDocHandler, IDocListener, IElementListener, IDisposable
	{
		public const string IMG_PROVIDER = "img_provider";

		public const string IMG_PROCESSOR = "img_interface";

		public const string IMG_STORE = "img_static";

		public const string IMG_BASEURL = "img_baseurl";

		public const string FONT_PROVIDER = "font_factory";

		public const string LINK_PROVIDER = "alink_interface";

		private static readonly ILogger LOGGER = LoggerFactory.GetLogger(typeof(HTMLWorker));

		protected IDocListener document;

		protected internal IDictionary<string, IHTMLTagProcessor> tags;

		private StyleSheet style = new StyleSheet();

		protected Stack<IElement> stack = new Stack<IElement>();

		protected Paragraph currentParagraph;

		private ChainedProperties chain = new ChainedProperties();

		private IDictionary<string, object> providers = new Dictionary<string, object>();

		private ElementFactory factory = new ElementFactory();

		private Stack<bool[]> tableState = new Stack<bool[]>();

		private bool pendingTR;

		private bool pendingTD;

		private bool pendingLI;

		private bool insidePRE;

		protected internal bool skipText;

		protected List<IElement> objectList;

		public virtual int PageCount
		{
			set
			{
			}
		}

		public HTMLWorker(IDocListener document)
			: this(document, null, null)
		{
		}

		public HTMLWorker(IDocListener document, IDictionary<string, IHTMLTagProcessor> tags, StyleSheet style)
		{
			this.document = document;
			SetSupportedTags(tags);
			SetStyleSheet(style);
		}

		public virtual void SetSupportedTags(IDictionary<string, IHTMLTagProcessor> tags)
		{
			if (tags == null)
			{
				tags = new HTMLTagProcessors();
			}
			this.tags = tags;
		}

		public virtual void SetStyleSheet(StyleSheet style)
		{
			if (style == null)
			{
				style = new StyleSheet();
			}
			this.style = style;
		}

		public virtual void Parse(TextReader reader)
		{
			LOGGER.Info("Please note, there is a more extended version of the HTMLWorker available in the iText XMLWorker");
			SimpleXMLParser.Parse(this, null, reader, html: true);
		}

		public virtual void StartDocument()
		{
			Dictionary<string, string> dictionary = new Dictionary<string, string>();
			style.ApplyStyle("body", dictionary);
			chain.AddToChain("body", dictionary);
		}

		public virtual void StartElement(string tag, IDictionary<string, string> attrs)
		{
			tags.TryGetValue(tag, out var value);
			if (value != null)
			{
				style.ApplyStyle(tag, attrs);
				StyleSheet.ResolveStyleAttribute(attrs, chain);
				value.StartElement(this, tag, attrs);
			}
		}

		public virtual void Text(string content)
		{
			if (skipText)
			{
				return;
			}
			if (currentParagraph == null)
			{
				currentParagraph = CreateParagraph();
			}
			if (!insidePRE)
			{
				if (content.Trim().Length == 0 && content.IndexOf(' ') < 0)
				{
					return;
				}
				content = HtmlUtilities.EliminateWhiteSpace(content);
			}
			Chunk element = CreateChunk(content);
			currentParagraph.Add(element);
		}

		public virtual void EndElement(string tag)
		{
			tags.TryGetValue(tag, out var value);
			value?.EndElement(this, tag);
		}

		public virtual void EndDocument()
		{
			foreach (IElement item in stack)
			{
				document.Add(item);
			}
			if (currentParagraph != null)
			{
				document.Add(currentParagraph);
			}
			currentParagraph = null;
		}

		public virtual void NewLine()
		{
			if (currentParagraph == null)
			{
				currentParagraph = new Paragraph();
			}
			currentParagraph.Add(CreateChunk("\n"));
		}

		public virtual void CarriageReturn()
		{
			if (currentParagraph == null)
			{
				return;
			}
			if (stack.Count == 0)
			{
				document.Add(currentParagraph);
			}
			else
			{
				IElement element = stack.Pop();
				if (element is ITextElementArray)
				{
					ITextElementArray textElementArray = (ITextElementArray)element;
					textElementArray.Add(currentParagraph);
				}
				stack.Push(element);
			}
			currentParagraph = null;
		}

		public virtual void FlushContent()
		{
			PushToStack(currentParagraph);
			currentParagraph = new Paragraph();
		}

		public virtual void PushToStack(IElement element)
		{
			if (element != null)
			{
				stack.Push(element);
			}
		}

		public virtual void UpdateChain(string tag, IDictionary<string, string> attrs)
		{
			chain.AddToChain(tag, attrs);
		}

		public virtual void UpdateChain(string tag)
		{
			chain.RemoveChain(tag);
		}

		public virtual void SetProviders(IDictionary<string, object> providers)
		{
			if (providers != null)
			{
				this.providers = providers;
				IFontProvider fontProvider = null;
				if (providers.ContainsKey("font_factory"))
				{
					fontProvider = (IFontProvider)providers["font_factory"];
				}
				if (fontProvider != null)
				{
					factory.FontProvider = fontProvider;
				}
			}
		}

		public virtual Chunk CreateChunk(string content)
		{
			return factory.CreateChunk(content, chain);
		}

		public virtual Paragraph CreateParagraph()
		{
			return factory.CreateParagraph(chain);
		}

		public virtual List CreateList(string tag)
		{
			return factory.CreateList(tag, chain);
		}

		public virtual ListItem CreateListItem()
		{
			return factory.CreateListItem(chain);
		}

		public virtual LineSeparator CreateLineSeparator(IDictionary<string, string> attrs)
		{
			return factory.CreateLineSeparator(attrs, currentParagraph.Leading / 2f);
		}

		public virtual Image CreateImage(IDictionary<string, string> attrs)
		{
			attrs.TryGetValue("src", out var value);
			if (value == null)
			{
				return null;
			}
			return factory.CreateImage(value, attrs, chain, document, providers.ContainsKey("img_provider") ? ((IImageProvider)providers["img_provider"]) : null, providers.ContainsKey("img_static") ? ((ImageStore)providers["img_static"]) : null, providers.ContainsKey("img_baseurl") ? ((string)providers["img_baseurl"]) : null);
		}

		public virtual CellWrapper CreateCell(string tag)
		{
			return new CellWrapper(tag, chain);
		}

		public virtual void ProcessLink()
		{
			if (currentParagraph == null)
			{
				currentParagraph = new Paragraph();
			}
			ILinkProcessor linkProcessor = null;
			if (providers.ContainsKey("alink_interface"))
			{
				linkProcessor = (ILinkProcessor)providers["alink_interface"];
			}
			if (linkProcessor == null || !linkProcessor.Process(currentParagraph, chain))
			{
				string text = chain["href"];
				if (text != null)
				{
					foreach (Chunk chunk in currentParagraph.Chunks)
					{
						chunk.SetAnchor(text);
					}
				}
			}
			if (stack.Count == 0)
			{
				Paragraph paragraph = new Paragraph(new Phrase(currentParagraph));
				currentParagraph = paragraph;
			}
			else
			{
				Paragraph paragraph2 = (Paragraph)stack.Pop();
				paragraph2.Add(new Phrase(currentParagraph));
				currentParagraph = paragraph2;
			}
		}

		public virtual void ProcessList()
		{
			if (stack.Count != 0)
			{
				IElement element = stack.Pop();
				if (!(element is List))
				{
					stack.Push(element);
				}
				else if (stack.Count == 0)
				{
					document.Add(element);
				}
				else
				{
					((ITextElementArray)stack.Peek()).Add(element);
				}
			}
		}

		public virtual void ProcessListItem()
		{
			if (stack.Count == 0)
			{
				return;
			}
			IElement element = stack.Pop();
			if (!(element is ListItem))
			{
				stack.Push(element);
				return;
			}
			if (stack.Count == 0)
			{
				document.Add(element);
				return;
			}
			ListItem listItem = (ListItem)element;
			IElement element2 = stack.Pop();
			if (!(element2 is List))
			{
				stack.Push(element2);
				return;
			}
			((List)element2).Add(listItem);
			listItem.AdjustListSymbolFont();
			stack.Push(element2);
		}

		public virtual void ProcessImage(Image img, IDictionary<string, string> attrs)
		{
			IImageProcessor imageProcessor = null;
			if (providers.ContainsKey("img_interface"))
			{
				imageProcessor = (IImageProcessor)providers["img_interface"];
			}
			if (imageProcessor == null || !imageProcessor.Process(img, attrs, chain, document))
			{
				attrs.TryGetValue("align", out var value);
				if (value != null)
				{
					CarriageReturn();
				}
				if (currentParagraph == null)
				{
					currentParagraph = CreateParagraph();
				}
				currentParagraph.Add(new Chunk(img, 0f, 0f, changeLeading: true));
				currentParagraph.Alignment = HtmlUtilities.AlignmentValue(value);
				if (value != null)
				{
					CarriageReturn();
				}
			}
		}

		public virtual void ProcessTable()
		{
			TableWrapper tableWrapper = (TableWrapper)stack.Pop();
			PdfPTable pdfPTable = tableWrapper.CreateTable();
			pdfPTable.SplitRows = true;
			if (stack.Count == 0)
			{
				document.Add(pdfPTable);
			}
			else
			{
				((ITextElementArray)stack.Peek()).Add(pdfPTable);
			}
		}

		public virtual void ProcessRow()
		{
			List<PdfPCell> list = new List<PdfPCell>();
			List<float> list2 = new List<float>();
			bool flag = false;
			float num = 0f;
			int num2 = 0;
			TableWrapper tableWrapper = null;
			IElement element;
			do
			{
				element = stack.Pop();
				if (element is CellWrapper)
				{
					CellWrapper cellWrapper = (CellWrapper)element;
					float width = cellWrapper.Width;
					list2.Add(width);
					flag |= cellWrapper.IsPercentage;
					if (width == 0f)
					{
						num2++;
					}
					else
					{
						num += width;
					}
					list.Add(cellWrapper.Cell);
				}
			}
			while (!(element is TableWrapper));
			tableWrapper = (TableWrapper)element;
			tableWrapper.AddRow(list);
			if (list2.Count > 0)
			{
				num = 100f - num;
				list2.Reverse();
				float[] array = new float[list2.Count];
				bool flag2 = false;
				for (int i = 0; i < array.Length; i++)
				{
					array[i] = list2[i];
					if (array[i] == 0f && flag && num2 > 0)
					{
						array[i] = num / (float)num2;
					}
					if (array[i] == 0f)
					{
						flag2 = true;
						break;
					}
				}
				if (!flag2)
				{
					tableWrapper.ColWidths = array;
				}
			}
			stack.Push(tableWrapper);
		}

		public virtual void PushTableState()
		{
			tableState.Push(new bool[2] { pendingTR, pendingTD });
		}

		public virtual void PopTableState()
		{
			bool[] array = tableState.Pop();
			pendingTR = array[0];
			pendingTD = array[1];
		}

		public virtual bool IsPendingTR()
		{
			return pendingTR;
		}

		public virtual void SetPendingTR(bool pendingTR)
		{
			this.pendingTR = pendingTR;
		}

		public virtual bool IsPendingTD()
		{
			return pendingTD;
		}

		public virtual void SetPendingTD(bool pendingTD)
		{
			this.pendingTD = pendingTD;
		}

		public virtual bool IsPendingLI()
		{
			return pendingLI;
		}

		public virtual void SetPendingLI(bool pendingLI)
		{
			this.pendingLI = pendingLI;
		}

		public virtual bool IsInsidePRE()
		{
			return insidePRE;
		}

		public virtual void SetInsidePRE(bool insidePRE)
		{
			this.insidePRE = insidePRE;
		}

		public virtual bool IsSkipText()
		{
			return skipText;
		}

		public virtual void SetSkipText(bool skipText)
		{
			this.skipText = skipText;
		}

		public static List<IElement> ParseToList(TextReader reader, StyleSheet style)
		{
			return ParseToList(reader, style, null);
		}

		public static List<IElement> ParseToList(TextReader reader, StyleSheet style, Dictionary<string, object> providers)
		{
			return ParseToList(reader, style, null, providers);
		}

		public static List<IElement> ParseToList(TextReader reader, StyleSheet style, IDictionary<string, IHTMLTagProcessor> tags, Dictionary<string, object> providers)
		{
			HTMLWorker hTMLWorker = new HTMLWorker(null, tags, style);
			hTMLWorker.document = hTMLWorker;
			hTMLWorker.SetProviders(providers);
			hTMLWorker.objectList = new List<IElement>();
			hTMLWorker.Parse(reader);
			return hTMLWorker.objectList;
