	[Obsolete]
	public class StyleSheet
	{
		protected internal IDictionary<string, IDictionary<string, string>> tagMap = new Dictionary<string, IDictionary<string, string>>();

		protected internal IDictionary<string, IDictionary<string, string>> classMap = new Dictionary<string, IDictionary<string, string>>();

		public virtual void LoadTagStyle(string tag, IDictionary<string, string> attrs)
		{
			tagMap[tag.ToLowerInvariant()] = attrs;
		}

		public virtual void LoadTagStyle(string tag, string key, string value)
		{
			tag = tag.ToLowerInvariant();
			tagMap.TryGetValue(tag, out var value2);
			if (value2 == null)
			{
				value2 = new Dictionary<string, string>();
				tagMap[tag] = value2;
			}
			value2[key] = value;
		}

		public virtual void LoadStyle(string className, Dictionary<string, string> attrs)
		{
			classMap[className.ToLowerInvariant()] = attrs;
		}

		public virtual void LoadStyle(string className, string key, string value)
		{
			className = className.ToLowerInvariant();
			classMap.TryGetValue(className, out var value2);
			if (value2 == null)
			{
				value2 = new Dictionary<string, string>();
				classMap[className] = value2;
			}
			value2[key] = value;
		}

		public virtual void ApplyStyle(string tag, IDictionary<string, string> attrs)
		{
			tagMap.TryGetValue(tag.ToLowerInvariant(), out var value);
			if (value != null)
			{
				IDictionary<string, string> dictionary = new Dictionary<string, string>(value);
				foreach (KeyValuePair<string, string> attr in attrs)
				{
					dictionary[attr.Key] = attr.Value;
				}
				foreach (KeyValuePair<string, string> item in dictionary)
				{
					attrs[item.Key] = item.Value;
				}
			}
			attrs.TryGetValue("class", out var value2);
			if (value2 == null)
			{
				return;
			}
			classMap.TryGetValue(value2.ToLowerInvariant(), out value);
			if (value == null)
			{
				return;
			}
			attrs.Remove("class");
			IDictionary<string, string> dictionary2 = new Dictionary<string, string>(value);
			foreach (KeyValuePair<string, string> attr2 in attrs)
			{
				dictionary2[attr2.Key] = attr2.Value;
			}
			foreach (KeyValuePair<string, string> item2 in dictionary2)
			{
				attrs[item2.Key] = item2.Value;
			}
		}

		public static void ResolveStyleAttribute(IDictionary<string, string> h, ChainedProperties chain)
		{
			h.TryGetValue("style", out var value);
			if (value == null)
			{
				return;
			}
			Properties properties = HtmlUtilities.ParseAttributes(value);
			foreach (string key in properties.Keys)
			{
				if (key.Equals("font-family"))
				{
					h["face"] = properties[key];
				}
				else if (key.Equals("font-size"))
				{
					float num = HtmlUtilities.ParseLength(chain["size"], 12f);
					if (num <= 0f)
					{
						num = 12f;
					}
					h["size"] = HtmlUtilities.ParseLength(properties[key], num).ToString(CultureInfo.InvariantCulture) + "pt";
				}
				else if (key.Equals("font-style"))
				{
					string text = properties[key].Trim().ToLowerInvariant();
					if (text.Equals("italic") || text.Equals("oblique"))
					{
						h["i"] = null;
					}
				}
				else if (key.Equals("font-weight"))
				{
					string text2 = properties[key].Trim().ToLowerInvariant();
					if (text2.Equals("bold") || text2.Equals("700") || text2.Equals("800") || text2.Equals("900"))
					{
						h["b"] = null;
					}
				}
				else if (key.Equals("text-decoration"))
				{
					string text3 = properties[key].Trim().ToLowerInvariant();
					if (text3.Equals("underline"))
					{
						h["u"] = null;
					}
				}
				else if (key.Equals("color"))
				{
					BaseColor baseColor = HtmlUtilities.DecodeColor(properties[key]);
					if (baseColor != null)
					{
						string text4 = baseColor.ToArgb().ToString("x");
						text4 = "000000" + text4;
						text4 = "#" + text4.Substring(text4.Length - 6);
						h["color"] = text4;
					}
				}
				else if (key.Equals("line-height"))
				{
					string text5 = properties[key].Trim();
					float num2 = HtmlUtilities.ParseLength(chain["size"], 12f);
					if (num2 <= 0f)
					{
						num2 = 12f;
					}
					float num3 = HtmlUtilities.ParseLength(properties[key], num2);
					if (text5.EndsWith("%"))
					{
						h["leading"] = "0," + num3 / 100f;
						break;
					}
					if (Util.EqualsIgnoreCase("normal", text5))
					{
						h["leading"] = "0,1.5";
						break;
					}
					h["leading"] = num3 + ",0";
				}
				else if (key.Equals("text-align"))
				{
					string value2 = properties[key].Trim().ToLowerInvariant();
					h["align"] = value2;
				}
				else if (key.Equals("padding-left"))
				{
					string str = properties[key].Trim().ToLowerInvariant();
					h["indent"] = HtmlUtilities.ParseLength(str).ToString(CultureInfo.InvariantCulture);
				}
			}
		}
	}
