		private static bool MissingHashColorFormat(string colStr)
		{
			int length = colStr.Length;
			if (length == 3 || length == 6)
			{
				Regex regex = new Regex("[0-9a-f]{" + length + "}");
				return regex.IsMatch(colStr);
			}
			return false;
		}

		public static BaseColor GetRGBColor(string name)
		{
			int[] array = new int[4] { 0, 0, 0, 255 };
			string text = name.ToLower();
			bool flag = MissingHashColorFormat(text);
			if (text.StartsWith("#") || flag)
			{
				if (!flag)
				{
					text = text.Substring(1);
				}
				if (text.Length == 3)
				{
					string text2 = text.Substring(0, 1);
					array[0] = int.Parse(text2 + text2, NumberStyles.HexNumber);
					string text3 = text.Substring(1, 1);
					array[1] = int.Parse(text3 + text3, NumberStyles.HexNumber);
					string text4 = text.Substring(2);
					array[2] = int.Parse(text4 + text4, NumberStyles.HexNumber);
					return new BaseColor(array[0], array[1], array[2], array[3]);
				}
				if (text.Length == 6)
				{
					array[0] = int.Parse(text.Substring(0, 2), NumberStyles.HexNumber);
					array[1] = int.Parse(text.Substring(2, 2), NumberStyles.HexNumber);
					array[2] = int.Parse(text.Substring(4), NumberStyles.HexNumber);
					return new BaseColor(array[0], array[1], array[2], array[3]);
				}
				throw new FormatException(MessageLocalization.GetComposedMessage("unknown.color.format.must.be.rgb.or.rrggbb"));
			}
			if (text.StartsWith("rgb("))
			{
				string delim = "rgb(), \t\r\n\f";
				StringTokenizer stringTokenizer = new StringTokenizer(text, delim);
				for (int i = 0; i < 3; i++)
				{
					if (stringTokenizer.HasMoreTokens())
					{
						array[i] = GetRGBChannelValue(stringTokenizer.NextToken());
						array[i] = Math.Max(0, array[i]);
						array[i] = Math.Min(255, array[i]);
					}
				}
				return new BaseColor(array[0], array[1], array[2], array[3]);
			}
			if (text.StartsWith("rgba("))
			{
				StringTokenizer stringTokenizer2 = new StringTokenizer(text, "rgba(), \t\r\n\f");
				for (int j = 0; j < 3; j++)
				{
					if (stringTokenizer2.HasMoreTokens())
					{
						array[j] = GetRGBChannelValue(stringTokenizer2.NextToken());
						array[j] = Math.Max(0, array[j]);
						array[j] = Math.Min(255, array[j]);
					}
				}
				if (stringTokenizer2.HasMoreTokens())
				{
					array[3] = (int)((double)(255f * float.Parse(stringTokenizer2.NextToken(), CultureInfo.InvariantCulture)) + 0.5);
				}
				return new BaseColor(array[0], array[1], array[2], array[3]);
			}
			if (!NAMES.ContainsKey(text))
			{
				throw new FormatException(MessageLocalization.GetComposedMessage("color.not.found", text));
			}
			array = NAMES[text];
			return new BaseColor(array[0], array[1], array[2], array[3]);
		}

		private static int GetRGBChannelValue(string rgbChannel)
		{
			if (rgbChannel.EndsWith("%"))
			{
				return int.Parse(rgbChannel.Substring(0, rgbChannel.Length - 1)) * 255 / 100;
			}
			return int.Parse(rgbChannel);
		}
	}
