		public Paragraph(Phrase phrase)
			: base(phrase)
		{
			if (phrase is Paragraph)
			{
				Paragraph paragraph = (Paragraph)phrase;
				Alignment = paragraph.Alignment;
				IndentationLeft = paragraph.IndentationLeft;
				IndentationRight = paragraph.IndentationRight;
				FirstLineIndent = paragraph.FirstLineIndent;
				SpacingAfter = paragraph.SpacingAfter;
				SpacingBefore = paragraph.SpacingBefore;
				ExtraParagraphSpace = paragraph.ExtraParagraphSpace;
				Role = paragraph.role;
				id = paragraph.ID;
				if (paragraph.accessibleAttributes != null)
				{
					accessibleAttributes = new Dictionary<PdfName, PdfObject>(paragraph.accessibleAttributes);
				}
			}
		}

		public virtual Paragraph CloneShallow(bool spacingBefore)
		{
			Paragraph paragraph = new Paragraph();
			PopulateProperties(paragraph, spacingBefore);
			return paragraph;
		}

		protected void PopulateProperties(Paragraph copy, bool spacingBefore)
		{
			copy.Font = Font;
			copy.Alignment = Alignment;
			copy.SetLeading(Leading, multipliedLeading);
			copy.IndentationLeft = IndentationLeft;
			copy.IndentationRight = IndentationRight;
			copy.FirstLineIndent = FirstLineIndent;
			copy.SpacingAfter = SpacingAfter;
			if (spacingBefore)
			{
				copy.SpacingBefore = SpacingBefore;
			}
			copy.ExtraParagraphSpace = ExtraParagraphSpace;
			copy.Role = Role;
			copy.id = ID;
			if (accessibleAttributes != null)
			{
				copy.accessibleAttributes = new Dictionary<PdfName, PdfObject>(accessibleAttributes);
			}
			copy.TabSettings = TabSettings;
			copy.KeepTogether = KeepTogether;
		}

