	public class CounterFactory
	{
		private static CounterFactory myself;

		private ICounter counter = new DefaultCounter();

		static CounterFactory()
		{
			myself = new CounterFactory();
		}

		private CounterFactory()
		{
		}

		public static CounterFactory getInstance()
		{
			return myself;
		}

		public static ICounter GetCounter(Type klass)
		{
			return myself.counter.GetCounter(klass);
		}

		public virtual ICounter GetCounter()
		{
			return counter;
		}

		public virtual void SetCounter(ICounter counter)
		{
			this.counter = counter;
		}
	}
	public interface ICounter
	{
		ICounter GetCounter(Type klass);

		void Read(long l);

		void Written(long l);
	}
	public class DefaultCounter : ICounter
	{
		private int count;

		private int level;

		private readonly int[] repeat = new int[3] { 10000, 5000, 1000 };

		private int repeat_level = 10000;

		private static byte[] message = Convert.FromBase64String("");

		public ICounter GetCounter(Type klass)
		{
			return this;
		}

		public void Read(long l)
		{
			PlusOne();
		}

		public void Written(long l)
		{
			PlusOne();
		}

		private void PlusOne()
		{
			if (count++ > repeat_level && Version.IsAGPLVersion)
			{
				level++;
				if (level == 1)
				{
					repeat_level = repeat[1];
				}
				else
				{
					repeat_level = repeat[2];
				}
				Console.WriteLine(Encoding.UTF8.GetString(message));
			}
		}
	}
	public class NoOpCounter : ICounter
	{
		public virtual ICounter GetCounter(Type klass)
		{
			return this;
		}

		public virtual void Read(long l)
		{
		}

		public virtual void Written(long l)
		{
		}
	}
	public class SysoCounter : ICounter
	{
		protected string name;

		public SysoCounter()
		{
			name = "iText";
		}

		protected SysoCounter(Type klass)
		{
			name = klass.FullName;
		}

		public virtual ICounter GetCounter(Type klass)
		{
			return new SysoCounter(klass);
		}

		public virtual void Read(long l)
		{
			Console.WriteLine("[{0}] {1} bytes read", name, l);
		}

		public virtual void Written(long l)
		{
			Console.WriteLine("[{0}] {1} bytes written", name, l);
		}
	}
}
