		private class InstHit
		{
			private IntHashtable hits;

			public InstHit(int[] inst)
			{
				if (inst != null)
				{
					hits = new IntHashtable();
					for (int i = 0; i < inst.Length; i++)
					{
						hits[inst[i]] = 1;
					}
				}
			}

			public virtual bool IsHit(int n)
			{
