		private class ContentsChecker : PdfReader
		{
			private long contentsStart;

			private long contentsEnd;

			private int currentLevel;

			private int contentsLevel = 1;

			private bool searchInV = true;

			private bool rangeIsCorrect;

			public ContentsChecker(RandomAccessFileOrArray raf)
				: base(raf, null)
			{
			}

			public bool CheckWhetherSignatureCoversWholeDocument(Item signatureField)
			{
				rangeIsCorrect = false;
				int number;
				PdfDictionary pdfDictionary;
				if (signatureField.GetValue(0).Get(PdfName.V) is PRIndirectReference)
				{
					number = ((PdfIndirectReference)signatureField.GetValue(0).Get(PdfName.V)).Number;
					pdfDictionary = (PdfDictionary)GetPdfObject(number);
					searchInV = true;
				}
				else
				{
					pdfDictionary = (PdfDictionary)signatureField.GetValue(0).Get(PdfName.V);
					number = signatureField.GetWidgetRef(0).Number;
					searchInV = false;
					contentsLevel++;
				}
				long[] array = ((PdfArray)pdfDictionary.Get(PdfName.BYTERANGE)).AsLongArray();
				if (4 != array.Length || 0 != array[0] || FileLength != array[2] + array[3])
				{
					return false;
				}
				contentsStart = array[1];
				contentsEnd = array[2];
				long pos = xref[2 * number];
				try
				{
					tokens.Seek(pos);
					tokens.NextValidToken();
					tokens.NextValidToken();
					tokens.NextValidToken();
					ReadPRObject();
				}
				catch (Exception)
				{
					return false;
				}
				return rangeIsCorrect;
			}

			protected internal override PdfDictionary ReadDictionary()
			{
				currentLevel++;
				PdfDictionary pdfDictionary = new PdfDictionary();
				while (!rangeIsCorrect)
				{
					tokens.NextValidToken();
					if (tokens.TokenType == PRTokeniser.TokType.END_DIC)
					{
						currentLevel--;
						break;
					}
					if (tokens.TokenType != PRTokeniser.TokType.NAME)
					{
						tokens.ThrowError(MessageLocalization.GetComposedMessage("dictionary.key.1.is.not.a.name", tokens.StringValue));
					}
					PdfName pdfName = new PdfName(tokens.StringValue, lengthCheck: false);
					PdfObject pdfObject;
					if (PdfName.CONTENTS.Equals(pdfName) && searchInV && contentsLevel == currentLevel)
					{
						long filePointer = tokens.FilePointer;
						int num = -1;
						int num2;
						do
						{
							num2 = tokens.Read();
							num++;
						}
						while (num2 != -1 && PRTokeniser.IsWhitespace(num2));
						tokens.Seek(filePointer);
						pdfObject = ReadPRObject();
						long filePointer2 = tokens.FilePointer;
						if (filePointer2 == contentsEnd && filePointer + num == contentsStart)
						{
							rangeIsCorrect = true;
						}
					}
					else if (PdfName.V.Equals(pdfName) && !searchInV && 1 == currentLevel)
					{
						searchInV = true;
						pdfObject = ReadPRObject();
						searchInV = false;
					}
					else
					{
						pdfObject = ReadPRObject();
					}
					int type = pdfObject.Type;
					if (-type == 8)
					{
						tokens.ThrowError(MessageLocalization.GetComposedMessage("unexpected.gt.gt"));
					}
					if (-type == 6)
					{
						tokens.ThrowError(MessageLocalization.GetComposedMessage("unexpected.close.bracket"));
					}
					pdfDictionary.Put(pdfName, pdfObject);
				}
				return pdfDictionary;
			}
		}

