				return;
			}
			PdfArray asArray2 = merged.GetAsArray(PdfName.BORDER);
			if (asArray2 != null)
			{
				if (asArray2.Size >= 3)
				{
					tx.BorderWidth = asArray2.GetAsNumber(2).FloatValue;
