		internal int GetPageRotation(PdfDictionary page)
		{
			PdfNumber asNumber = page.GetAsNumber(PdfName.ROTATE);
			if (asNumber == null)
			{
				return 0;
			}
			int intValue = asNumber.IntValue;
			intValue %= 360;
			if (intValue >= 0)
			{
				return intValue;
			}
			return intValue + 360;
		}

