		private static bool IsVowel(char s)
		{
			if (s < '\u064b' || s > '\u0655')
			{
				return s == '\u0670';
			}
			return true;
		}

		private static char Charshape(char s, int which)
		{
			if (s >= 'ء' && s <= 'ۓ')
			{
				if (maptable.TryGetValue(s, out var value))
				{
					return value[which + 1];
				}
			}
			else if (s >= 'ﻵ' && s <= 'ﻻ')
			{
				return (char)(s + which);
			}
			return s;
		}

		private static int Shapecount(char s)
		{
			if (s >= 'ء' && s <= 'ۓ' && !IsVowel(s))
			{
				if (maptable.TryGetValue(s, out var value))
				{
					return value.Length - 1;
				}
			}
			else if (s == '\u200d')
			{
				return 4;
			}
			return 1;
		}

		private static int Ligature(char newchar, Charstruct oldchar)
		{
			int result = 0;
			if (oldchar.basechar == '\0')
			{
				return 0;
			}
			if (IsVowel(newchar))
			{
				result = 1;
				if (oldchar.vowel != 0 && newchar != '\u0651')
				{
					result = 2;
				}
				switch (newchar)
				{
				case '\u0651':
					if (oldchar.mark1 == '\0')
					{
						oldchar.mark1 = '\u0651';
						break;
					}
					return 0;
				case '\u0655':
					switch (oldchar.basechar)
					{
					case 'ا':
						oldchar.basechar = 'إ';
						result = 2;
						break;
					case 'ﻻ':
						oldchar.basechar = 'ﻹ';
						result = 2;
						break;
					default:
						oldchar.mark1 = '\u0655';
						break;
					}
					break;
				case '\u0654':
					switch (oldchar.basechar)
					{
					case 'ا':
						oldchar.basechar = 'أ';
						result = 2;
						break;
					case 'ﻻ':
						oldchar.basechar = 'ﻷ';
						result = 2;
						break;
					case 'و':
						oldchar.basechar = 'ؤ';
						result = 2;
						break;
					case 'ى':
					case 'ي':
					case 'ی':
						oldchar.basechar = 'ئ';
						result = 2;
						break;
					default:
						oldchar.mark1 = '\u0654';
						break;
					}
					break;
				case '\u0653':
				{
					char basechar = oldchar.basechar;
					if (basechar == 'ا')
					{
						oldchar.basechar = 'آ';
						result = 2;
					}
					break;
				}
				default:
					oldchar.vowel = newchar;
					break;
				}
				if (result == 1)
				{
					oldchar.lignum++;
				}
				return result;
			}
			if (oldchar.vowel != 0)
			{
				return 0;
			}
			switch (oldchar.basechar)
			{
			case 'ل':
				switch (newchar)
				{
				case 'ا':
					oldchar.basechar = 'ﻻ';
					oldchar.numshapes = 2;
					result = 3;
					break;
				case 'أ':
					oldchar.basechar = 'ﻷ';
					oldchar.numshapes = 2;
					result = 3;
					break;
				case 'إ':
					oldchar.basechar = 'ﻹ';
					oldchar.numshapes = 2;
					result = 3;
					break;
				case 'آ':
					oldchar.basechar = 'ﻵ';
					oldchar.numshapes = 2;
					result = 3;
					break;
				}
				break;
			case '\0':
				oldchar.basechar = newchar;
				oldchar.numshapes = Shapecount(newchar);
				result = 1;
				break;
			}
			return result;
		}

		private static void Copycstostring(StringBuilder str, Charstruct s, int level)
		{
			if (s.basechar == '\0')
			{
				return;
			}
			str.Append(s.basechar);
			s.lignum--;
			if (s.mark1 != 0)
			{
				if ((level & 1) == 0)
				{
					str.Append(s.mark1);
					s.lignum--;
				}
				else
				{
					s.lignum--;
				}
			}
			if (s.vowel != 0)
			{
				if ((level & 1) == 0)
				{
					str.Append(s.vowel);
					s.lignum--;
				}
				else
				{
					s.lignum--;
				}
			}
		}

