	public class Barcode128 : Barcode
	{
		public enum Barcode128CodeSet
		{
			A,
			B,
			C,
			AUTO
		}

		public const char CODE_AB_TO_C = 'c';

		public const char CODE_AC_TO_B = 'd';

		public const char CODE_BC_TO_A = 'e';

		public const char FNC1_INDEX = 'f';

		public const char START_A = 'g';

		public const char START_B = 'h';

		public const char START_C = 'i';

		public const char FNC1 = 'Ê';

		public const char DEL = 'Ã';

		public const char FNC3 = 'Ä';

		public const char FNC2 = 'Å';

		public const char SHIFT = 'Æ';

		public const char CODE_C = 'Ç';

		public const char CODE_A = 'È';

		public const char FNC4 = 'È';

		public const char STARTA = 'Ë';

		public const char STARTB = 'Ì';

		public const char STARTC = 'Í';

		private static readonly byte[][] BARS;

		private static readonly byte[] BARS_STOP;

		private static IntHashtable ais;

		private Barcode128CodeSet codeSet = Barcode128CodeSet.AUTO;

		public virtual Barcode128CodeSet CodeSet
		{
			get
			{
				return codeSet;
			}
			set
			{
				codeSet = value;
			}
		}

		public override Rectangle BarcodeSize
		{
			get
			{
				float val = 0f;
				float num = 0f;
				string text;
				if (font != null)
				{
					num = ((!(baseline > 0f)) ? (0f - baseline + size) : (baseline - font.GetFontDescriptor(3, size)));
					if (codeType != 11)
					{
						text = ((codeType != 10) ? RemoveFNC1(code) : GetHumanReadableUCCEAN(code));
					}
					else
					{
						int num2 = code.IndexOf('\uffff');
						text = ((num2 >= 0) ? code.Substring(num2 + 1) : "");
					}
					val = font.GetWidthPoint((altText != null) ? altText : text, size);
				}
				if (codeType == 11)
				{
					int num3 = code.IndexOf('\uffff');
					text = ((num3 < 0) ? code : code.Substring(0, num3));
				}
				else
				{
					text = GetRawText(code, codeType == 10, codeSet);
				}
				int length = text.Length;
				float val2 = (float)((length + 2) * 11) * x + 2f * x;
				val2 = Math.Max(val2, val);
				float ury = barHeight + num;
				return new Rectangle(val2, ury);
			}
		}

		public override string Code
		{
			set
			{
				if (CodeType == 10 && value.StartsWith("("))
				{
					int num = 0;
					StringBuilder stringBuilder = new StringBuilder();
					while (num >= 0)
					{
						int num2 = value.IndexOf(')', num);
						if (num2 < 0)
						{
							throw new ArgumentException(MessageLocalization.GetComposedMessage("badly.formed.ucc.string.1", value));
						}
						string text = value.Substring(num + 1, num2 - (num + 1));
						if (text.Length < 2)
						{
							throw new ArgumentException(MessageLocalization.GetComposedMessage("ai.too.short.1", text));
						}
						int key = int.Parse(text);
						int num3 = ais[key];
						if (num3 == 0)
						{
							throw new ArgumentException(MessageLocalization.GetComposedMessage("ai.not.found.1", text));
						}
						text = key.ToString();
						if (text.Length == 1)
						{
							text = "0" + text;
						}
						num = value.IndexOf('(', num2);
						int num4 = ((num < 0) ? value.Length : num);
						stringBuilder.Append(text).Append(value.Substring(num2 + 1, num4 - (num2 + 1)));
						if (num3 < 0)
						{
							if (num >= 0)
							{
								stringBuilder.Append('Ê');
							}
						}
						else if (num4 - num2 - 1 + text.Length != num3)
						{
							throw new ArgumentException(MessageLocalization.GetComposedMessage("invalid.ai.length.1", text));
						}
					}
					base.Code = stringBuilder.ToString();
				}
				else
				{
					base.Code = value;
				}
			}
		}

		public Barcode128()
		{
			x = 0.8f;
			font = BaseFont.CreateFont("Helvetica", "winansi", embedded: false);
			size = 8f;
			baseline = size;
			barHeight = size * 3f;
			textAlignment = 1;
			codeType = 9;
		}

		public static char GetStartSymbol(Barcode128CodeSet codeSet)
		{
			return codeSet switch
			{
				Barcode128CodeSet.A => 'g', 
				Barcode128CodeSet.B => 'h', 
				Barcode128CodeSet.C => 'i', 
				_ => 'h', 
			};
		}

		public static string RemoveFNC1(string code)
		{
			int length = code.Length;
			StringBuilder stringBuilder = new StringBuilder(length);
			for (int i = 0; i < length; i++)
			{
				char c = code[i];
				if (c >= ' ' && c <= '~')
				{
					stringBuilder.Append(c);
				}
			}
			return stringBuilder.ToString();
		}

		public static string GetHumanReadableUCCEAN(string code)
		{
			StringBuilder stringBuilder = new StringBuilder();
			string value = 'Ê'.ToString();
			try
			{
				while (true)
				{
					if (code.StartsWith(value))
					{
						code = code.Substring(1);
						continue;
					}
					int num = 0;
					int num2 = 0;
					for (int i = 2; i < 5 && code.Length >= i; i++)
					{
						if ((num = ais[int.Parse(code.Substring(0, i))]) != 0)
						{
							num2 = i;
							break;
						}
					}
					if (num2 == 0)
					{
						break;
					}
					stringBuilder.Append('(').Append(code.Substring(0, num2)).Append(')');
					code = code.Substring(num2);
					if (num > 0)
					{
						num -= num2;
						if (code.Length <= num)
						{
							break;
						}
						stringBuilder.Append(RemoveFNC1(code.Substring(0, num)));
						code = code.Substring(num);
					}
					else
					{
						int num3 = code.IndexOf('Ê');
						if (num3 < 0)
						{
							break;
						}
						stringBuilder.Append(code.Substring(0, num3));
						code = code.Substring(num3 + 1);
					}
				}
			}
			catch
			{
			}
			stringBuilder.Append(RemoveFNC1(code));
			return stringBuilder.ToString();
		}

		internal static bool IsNextDigits(string text, int textIndex, int numDigits)
		{
			int length = text.Length;
