			private static void ReedSolomonBlock(byte[] wd, int nd, byte[] ncout, int nc, int[] c)
			{
				for (int i = 0; i <= nc; i++)
				{
					ncout[i] = 0;
				}
				for (int i = 0; i < nd; i++)
				{
					int num = (ncout[0] ^ wd[i]) & 0xFF;
					for (int j = 0; j < nc; j++)
					{
						ncout[j] = (byte)(ncout[j + 1] ^ ((num != 0) ? ((byte)alog[(log[num] + log[c[nc - j - 1]]) % 255]) : 0));
					}
				}
			}

			internal static void GenerateECC(byte[] wd, int nd, int datablock, int nc)
			{
				int num = (nd + 2) / datablock;
				byte[] array = new byte[256];
				byte[] array2 = new byte[256];
				int[] poly = GetPoly(nc);
				for (int i = 0; i < num; i++)
				{
					int nd2 = 0;
					for (int j = i; j < nd; j += num)
					{
						array[nd2++] = wd[j];
					}
					ReedSolomonBlock(array, nd2, array2, nc, poly);
					nd2 = 0;
					for (int j = i; j < nc * num; j += num)
					{
						wd[nd + j] = array2[nd2++];
					}
				}
			}
		}

