		private void SetBit(int x, int y, int xByte)
		{
			image[y * xByte + x / 8] |= (byte)(128 >> (x & 7));
		}

		private void Draw(byte[] data, int dataSize, DmParams dm)
		{
			int xByte = (dm.width + ws * 2 + 7) / 8;
			for (int i = 0; i < image.Length; i++)
			{
				image[i] = 0;
			}
			for (int j = ws; j < dm.height + ws; j += dm.heightSection)
			{
				for (int k = ws; k < dm.width + ws; k += 2)
				{
					SetBit(k, j, xByte);
				}
			}
			for (int j = dm.heightSection - 1 + ws; j < dm.height + ws; j += dm.heightSection)
			{
				for (int k = ws; k < dm.width + ws; k++)
				{
					SetBit(k, j, xByte);
				}
			}
			for (int j = ws; j < dm.width + ws; j += dm.widthSection)
			{
				for (int k = ws; k < dm.height + ws; k++)
				{
					SetBit(j, k, xByte);
				}
			}
			for (int j = dm.widthSection - 1 + ws; j < dm.width + ws; j += dm.widthSection)
			{
				for (int k = 1 + ws; k < dm.height + ws; k += 2)
				{
					SetBit(j, k, xByte);
				}
			}
			int num = 0;
			for (int l = 0; l < dm.height; l += dm.heightSection)
			{
				for (int m = 1; m < dm.heightSection - 1; m++)
				{
					for (int n = 0; n < dm.width; n += dm.widthSection)
					{
						for (int num2 = 1; num2 < dm.widthSection - 1; num2++)
						{
							int num3 = place[num++];
							if (num3 == 1 || (num3 > 1 && (data[num3 / 8 - 1] & 0xFFu & (uint)(128 >> num3 % 8)) != 0))
							{
								SetBit(num2 + n + ws, m + l + ws, xByte);
							}
						}
					}
				}
			}
		}

		private static void MakePadding(byte[] data, int position, int count)
		{
			if (count <= 0)
			{
				return;
			}
			data[position++] = 129;
			while (--count > 0)
			{
				int num = 129 + (position + 1) * 149 % 253 + 1;
				if (num > 254)
				{
					num -= 254;
				}
				data[position++] = (byte)num;
			}
		}

		private static bool IsDigit(int c)
		{
			if (c >= 48)
			{
				return c <= 57;
			}
			return false;
		}

		private static int AsciiEncodation(byte[] text, int textOffset, int textLength, byte[] data, int dataOffset, int dataLength, int symbolIndex, int prevEnc, int origDataOffset)
		{
			int num = textOffset;
			int num2 = dataOffset;
			textLength += textOffset;
			dataLength += dataOffset;
			while (num < textLength)
			{
				int num3 = text[num++] & 0xFF;
				if (IsDigit(num3) && symbolIndex > 0 && prevEnc == 1 && IsDigit(text[num - 2] & 0xFF) && data[dataOffset - 1] > 48 && data[dataOffset - 1] < 59)
				{
					data[num2 - 1] = (byte)(((text[num - 2] & 0xFF) - 48) * 10 + num3 - 48 + 130);
					return num2 - origDataOffset;
				}
				if (num2 >= dataLength)
				{
					return -1;
				}
				if (IsDigit(num3) && symbolIndex < 0 && num < textLength && IsDigit(text[num] & 0xFF))
				{
					data[num2++] = (byte)((num3 - 48) * 10 + (text[num++] & 0xFF) - 48 + 130);
				}
				else if (num3 > 127)
				{
					if (num2 + 1 >= dataLength)
					{
						return -1;
					}
					data[num2++] = 235;
					data[num2++] = (byte)(num3 - 128 + 1);
				}
				else
				{
					data[num2++] = (byte)(num3 + 1);
				}
			}
			return num2 - origDataOffset;
		}

		private static int B256Encodation(byte[] text, int textOffset, int textLength, byte[] data, int dataOffset, int dataLength, int symbolIndex, int prevEnc, int origDataOffset)
		{
			if (textLength == 0)
			{
				return 0;
			}
			int num = dataOffset;
			if (prevEnc != 4)
			{
				if (textLength < 250 && textLength + 2 > dataLength)
				{
					return -1;
				}
				if (textLength >= 250 && textLength + 3 > dataLength)
				{
					return -1;
				}
				data[dataOffset] = 231;
			}
			else
			{
				int num2 = symbolIndex - 1;
				while (num2 > 0 && switchMode[3][num2] == 4)
				{
					num2--;
				}
				textLength = symbolIndex - num2 + 1;
				if (textLength != 250 && 1 > dataLength)
				{
					return -1;
				}
				if (textLength == 250 && 2 > dataLength)
				{
					return -1;
				}
				num -= textLength - 1 + ((textLength < 250) ? 2 : 3);
			}
			int num3;
			if (textLength < 250)
			{
				data[num + 1] = (byte)textLength;
				num3 = ((prevEnc != 4) ? 2 : 0);
			}
			else if (textLength == 250 && prevEnc == 4)
			{
				data[num + 1] = (byte)(textLength / 250 + 249);
				for (int num4 = dataOffset + 1; num4 > num + 2; num4--)
				{
					data[num4] = data[num4 - 1];
				}
				data[num + 2] = (byte)(textLength % 250);
				num3 = 1;
			}
			else
			{
				data[num + 1] = (byte)(textLength / 250 + 249);
				data[num + 2] = (byte)(textLength % 250);
				num3 = ((prevEnc != 4) ? 3 : 0);
			}
			if (prevEnc == 4)
			{
				textLength = 1;
			}
			Array.Copy(text, textOffset, data, num3 + dataOffset, textLength);
			for (int i = ((prevEnc != 4) ? (dataOffset + 1) : dataOffset); i < num3 + textLength + dataOffset; i++)
			{
				RandomizationAlgorithm255(data, i);
			}
			if (prevEnc == 4)
			{
				RandomizationAlgorithm255(data, num + 1);
			}
			return textLength + dataOffset + num3 - origDataOffset;
		}

		private static void RandomizationAlgorithm255(byte[] data, int j)
		{
			int num = data[j] & 0xFF;
			int num2 = 149 * (j + 1) % 255 + 1;
			int num3 = num + num2;
			if (num3 > 255)
			{
				num3 -= 256;
			}
			data[j] = (byte)num3;
		}

		private static int X12Encodation(byte[] text, int textOffset, int textLength, byte[] data, int dataOffset, int dataLength, int symbolIndex, int prevEnc, int origDataOffset)
		{
			bool flag = true;
			if (textLength == 0)
			{
				return 0;
			}
			int i = 0;
			int num = 0;
			byte[] array = new byte[textLength];
			int num2 = 0;
