	public class BarcodePDF417
	{
		protected class Segment
		{
			public char type;

			public int start;

			public int end;

			public Segment(char type, int start, int end)
			{
				this.type = type;
				this.start = start;
				this.end = end;
			}
		}

		protected class SegmentList
		{
			protected List<Segment> list = new List<Segment>();

			public virtual int Size => list.Count;

			public virtual void Add(char type, int start, int end)
			{
				list.Add(new Segment(type, start, end));
			}

			public virtual Segment Get(int idx)
			{
				if (idx < 0 || idx >= list.Count)
				{
					return null;
				}
				return list[idx];
			}

			public virtual void Remove(int idx)
			{
				if (idx >= 0 && idx < list.Count)
				{
					list.RemoveAt(idx);
				}
			}
		}

