					{
						int num2 = num * i + j / 8;
						array[num2] |= (byte)(128 >> j % 8);
					}
				}
			}
			return array;
		}

		public virtual Image GetImage()
		{
			byte[] bitMatrix = GetBitMatrix();
			byte[] data = CCITTG4Encoder.Compress(bitMatrix, bm.GetWidth(), bm.GetHeight());
			return Image.GetInstance(bm.GetWidth(), bm.GetHeight(), reverseBits: false, 256, 1, data, null);
		}

		public void PlaceBarcode(PdfContentByte cb, BaseColor foreground, float moduleSide)
		{
			int width = bm.GetWidth();
			int height = bm.GetHeight();
			sbyte[][] array = bm.GetArray();
			cb.SetColorFill(foreground);
			for (int i = 0; i < height; i++)
			{
				sbyte[] array2 = array[i];
				for (int j = 0; j < width; j++)
				{
					if (array2[j] == 0)
					{
						cb.Rectangle((float)j * moduleSide, (float)(height - i - 1) * moduleSide, moduleSide, moduleSide);
					}
				}
			}
			cb.Fill();
		}

		public Rectangle GetBarcodeSize()
		{
			return new Rectangle(0f, 0f, bm.GetWidth(), bm.GetHeight());
		}
	}
