			char c = '\0';
			for (; i <= endIdx; i++)
			{
				c = (char)detailChunks[i].GetUnicodeEquivalent(text[i]);
				if (!IsWS(c) && !PdfChunk.NoPrint(c))
				{
					if (!detailChunks[i].IsTab() || !detailChunks[i].IsAttribute("TABSETTINGS"))
					{
						break;
