					object[] array = (object[])detailChunks[i].GetAttribute("TAB");
					if (!(bool)array[1])
					{
						break;
					}
				}
			}
			return i;
		}

		public virtual void Reorder(int start, int end)
		{
			byte b = orderLevels[start];
			byte b2 = b;
			byte b3 = b;
			byte b4 = b;
			for (int i = start + 1; i <= end; i++)
			{
				byte b5 = orderLevels[i];
				if (b5 > b)
				{
					b = b5;
				}
				else if (b5 < b2)
				{
					b2 = b5;
				}
				b3 &= b5;
				b4 |= b5;
			}
			if ((b4 & 1) == 0)
			{
				return;
			}
			if ((b3 & 1) == 1)
			{
				Flip(start, end + 1);
				return;
			}
			b2 = (byte)(b2 | 1u);
			while (b >= b2)
			{
				int num = start;
				while (true)
				{
					if (num <= end && orderLevels[num] < b)
					{
						num++;
						continue;
					}
					if (num > end)
					{
						break;
					}
					int j;
					for (j = num + 1; j <= end && orderLevels[j] >= b; j++)
					{
					}
					Flip(num, j);
					num = j + 1;
				}
				b--;
			}
		}

		public virtual void Flip(int start, int end)
		{
			int num = (start + end) / 2;
			end--;
			while (start < num)
			{
				int num2 = indexChars[start];
				indexChars[start] = indexChars[end];
				indexChars[end] = num2;
				start++;
				end--;
			}
		}

