		private int FindRunLimit(int index, int limit, sbyte[] validSet)
		{
			index--;
			while (++index < limit)
			{
				sbyte b = resultTypes[index];
				int num = 0;
				while (true)
				{
					if (num < validSet.Length)
					{
						if (b == validSet[num])
						{
							break;
						}
						num++;
						continue;
					}
					return index;
				}
			}
			return limit;
		}

		private int FindRunStart(int index, sbyte[] validSet)
		{
			while (--index >= 0)
			{
				sbyte b = resultTypes[index];
				int num = 0;
				while (true)
				{
					if (num < validSet.Length)
					{
						if (b == validSet[num])
						{
							break;
						}
						num++;
						continue;
					}
					return index + 1;
				}
			}
			return 0;
		}

