		private float GetDescNumber(string name)
		{
			return int.Parse((string)fontDesc[name]);
		}

		private float GetBBox(int idx)
		{
			string str = (string)fontDesc["FontBBox"];
			StringTokenizer stringTokenizer = new StringTokenizer(str, " []\r\n\t\f");
			string s = stringTokenizer.NextToken();
			for (int i = 0; i < idx; i++)
			{
				s = stringTokenizer.NextToken();
			}
			return int.Parse(s);
		}

		public override float GetFontDescriptor(int key, float fontSize)
		{
			switch (key)
			{
			case 1:
			case 9:
				return GetDescNumber("Ascent") * fontSize / 1000f;
			case 2:
				return GetDescNumber("CapHeight") * fontSize / 1000f;
			case 3:
			case 10:
				return GetDescNumber("Descent") * fontSize / 1000f;
			case 4:
				return GetDescNumber("ItalicAngle");
			case 5:
				return fontSize * GetBBox(0) / 1000f;
			case 6:
				return fontSize * GetBBox(1) / 1000f;
			case 7:
				return fontSize * GetBBox(2) / 1000f;
			case 8:
				return fontSize * GetBBox(3) / 1000f;
			case 11:
				return 0f;
			case 12:
				return fontSize * (GetBBox(2) - GetBBox(0)) / 1000f;
			default:
				return 0f;
			}
		}

		internal static IntHashtable CreateMetric(string s)
		{
			IntHashtable intHashtable = new IntHashtable();
			StringTokenizer stringTokenizer = new StringTokenizer(s);
			while (stringTokenizer.HasMoreTokens())
			{
				int key = int.Parse(stringTokenizer.NextToken());
				intHashtable[key] = int.Parse(stringTokenizer.NextToken());
			}
			return intHashtable;
		}

		internal static string ConvertToHCIDMetrics(int[] keys, IntHashtable h)
		{
			if (keys.Length == 0)
			{
				return null;
			}
			int num = 0;
			int num2 = 0;
			int i;
			for (i = 0; i < keys.Length; i++)
			{
				num = keys[i];
				num2 = h[num];
				if (num2 != 0)
				{
					i++;
					break;
				}
			}
			if (num2 == 0)
			{
				return null;
			}
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append('[');
			stringBuilder.Append(num);
			int num3 = 0;
			for (int j = i; j < keys.Length; j++)
			{
				int num4 = keys[j];
				int num5 = h[num4];
				if (num5 == 0)
				{
					continue;
				}
				switch (num3)
				{
				case 0:
					if (num4 == num + 1 && num5 == num2)
					{
						num3 = 2;
					}
					else if (num4 == num + 1)
					{
						num3 = 1;
						stringBuilder.Append('[').Append(num2);
					}
					else
					{
						stringBuilder.Append('[').Append(num2).Append(']')
							.Append(num4);
					}
					break;
				case 1:
					if (num4 == num + 1 && num5 == num2)
					{
						num3 = 2;
						stringBuilder.Append(']').Append(num);
					}
					else if (num4 == num + 1)
					{
						stringBuilder.Append(' ').Append(num2);
					}
					else
					{
						num3 = 0;
						stringBuilder.Append(' ').Append(num2).Append(']')
							.Append(num4);
					}
					break;
				case 2:
					if (num4 != num + 1 || num5 != num2)
					{
						stringBuilder.Append(' ').Append(num).Append(' ')
							.Append(num2)
							.Append(' ')
							.Append(num4);
						num3 = 0;
					}
					break;
				}
				num2 = num5;
				num = num4;
			}
			switch (num3)
			{
			case 0:
				stringBuilder.Append('[').Append(num2).Append("]]");
				break;
			case 1:
				stringBuilder.Append(' ').Append(num2).Append("]]");
				break;
			case 2:
				stringBuilder.Append(' ').Append(num).Append(' ')
					.Append(num2)
					.Append(']');
				break;
			}
			return stringBuilder.ToString();
		}

		internal static string ConvertToVCIDMetrics(int[] keys, IntHashtable v, IntHashtable h)
		{
			if (keys.Length == 0)
			{
				return null;
			}
			int num = 0;
			int num2 = 0;
			int num3 = 0;
			int i;
			for (i = 0; i < keys.Length; i++)
			{
				num = keys[i];
				num2 = v[num];
				if (num2 != 0)
				{
					i++;
					break;
				}
				num3 = h[num];
			}
			if (num2 == 0)
			{
				return null;
			}
			if (num3 == 0)
			{
				num3 = 1000;
			}
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append('[');
			stringBuilder.Append(num);
			int num4 = 0;
			for (int j = i; j < keys.Length; j++)
			{
				int num5 = keys[j];
				int num6 = v[num5];
				if (num6 == 0)
				{
					continue;
				}
				int num7 = h[num];
				if (num7 == 0)
				{
					num7 = 1000;
				}
				switch (num4)
				{
				case 0:
					if (num5 == num + 1 && num6 == num2 && num7 == num3)
					{
						num4 = 2;
					}
					else
					{
						stringBuilder.Append(' ').Append(num).Append(' ')
							.Append(-num2)
							.Append(' ')
							.Append(num3 / 2)
							.Append(' ')
							.Append(880)
							.Append(' ')
							.Append(num5);
					}
					break;
				case 2:
					if (num5 != num + 1 || num6 != num2 || num7 != num3)
					{
						stringBuilder.Append(' ').Append(num).Append(' ')
							.Append(-num2)
							.Append(' ')
							.Append(num3 / 2)
							.Append(' ')
							.Append(880)
							.Append(' ')
							.Append(num5);
						num4 = 0;
					}
					break;
				}
				num2 = num6;
				num = num5;
				num3 = num7;
			}
			stringBuilder.Append(' ').Append(num).Append(' ')
				.Append(-num2)
				.Append(' ')
				.Append(num3 / 2)
				.Append(' ')
				.Append(880)
				.Append(" ]");
			return stringBuilder.ToString();
		}

		internal static Dictionary<string, object> ReadFontProperties(string name)
		{
			name += ".properties";
			Stream resourceStream = StreamUtil.GetResourceStream("iTextSharp.text.pdf.fonts.cmaps." + name);
			Properties properties = new Properties();
			properties.Load(resourceStream);
			resourceStream.Close();
			IntHashtable value = CreateMetric(properties["W"]);
			properties.Remove("W");
			IntHashtable value2 = CreateMetric(properties["W2"]);
			properties.Remove("W2");
			Dictionary<string, object> dictionary = new Dictionary<string, object>();
			foreach (string key in properties.Keys)
			{
				dictionary[key] = properties[key];
			}
			dictionary["W"] = value;
			dictionary["W2"] = value2;
			return dictionary;
		}

		public override int GetUnicodeEquivalent(int c)
		{
			if (cidDirect)
			{
				if (c == 32767)
				{
					return 10;
				}
				return cidUni.Lookup(c);
			}
			return c;
		}

