			fontName = ((asName != null) ? PdfName.DecodeName(asName.ToString()) : "Unspecified Font Name");
			PdfName asName2 = font.GetAsName(PdfName.SUBTYPE);
			if (PdfName.TYPE1.Equals(asName2) || PdfName.TRUETYPE.Equals(asName2))
