				char[] array = text.ToCharArray();
				int num = array.Length;
				byte[] array2 = new byte[num * 2];
				int num2 = 0;
				for (int i = 0; i < num; i++)
				{
					metrics.TryGetValue(array[i], out var value);
					if (value != null)
