	public class CMapAwareDocumentFont : DocumentFont
	{
		private static readonly ILogger LOGGER = LoggerFactory.GetLogger(typeof(CMapAwareDocumentFont));

		private PdfDictionary fontDic;

		private int spaceWidth;

		private CMapToUnicode toUnicodeCmap;

		private CMapByteCid byteCid;

		private CMapCidUni cidUni;

		private char[] cidbyte2uni;

		private IDictionary<int, int> uni2cid;

		public CMapAwareDocumentFont(PdfDictionary font)
			: base(font)
		{
			fontDic = font;
			InitFont();
		}

		public CMapAwareDocumentFont(PRIndirectReference refFont)
			: base(refFont)
		{
			fontDic = (PdfDictionary)PdfReader.GetPdfObjectRelease(refFont);
			InitFont();
		}

		private void InitFont()
		{
			ProcessToUnicode();
			ProcessUni2Byte();
			spaceWidth = base.GetWidth(32);
			if (spaceWidth == 0)
			{
				spaceWidth = ComputeAverageWidth();
			}
			if (cjkEncoding != null)
			{
				byteCid = CMapCache.GetCachedCMapByteCid(cjkEncoding);
				cidUni = CMapCache.GetCachedCMapCidUni(uniMap);
			}
		}

		private void ProcessToUnicode()
		{
			PdfObject pdfObjectRelease = PdfReader.GetPdfObjectRelease(fontDic.Get(PdfName.TOUNICODE));
			if (pdfObjectRelease is PRStream)
			{
				try
				{
					byte[] streamBytes = PdfReader.GetStreamBytes((PRStream)pdfObjectRelease);
					CidLocationFromByte location = new CidLocationFromByte(streamBytes);
					toUnicodeCmap = new CMapToUnicode();
					CMapParserEx.ParseCid("", toUnicodeCmap, location);
					uni2cid = toUnicodeCmap.CreateReverseMapping();
					return;
				}
				catch
				{
					toUnicodeCmap = null;
					uni2cid = null;
					return;
				}
			}
			if (!isType0)
			{
				return;
			}
			try
			{
				PdfName asName = fontDic.GetAsName(PdfName.ENCODING);
				if (asName == null)
				{
					return;
				}
				string text = PdfName.DecodeName(asName.ToString());
				if (!text.Equals("Identity-H"))
				{
					return;
				}
				PdfArray pdfArray = (PdfArray)PdfReader.GetPdfObjectRelease(fontDic.Get(PdfName.DESCENDANTFONTS));
				PdfDictionary pdfDictionary = (PdfDictionary)PdfReader.GetPdfObjectRelease(pdfArray[0]);
				PdfDictionary asDict = pdfDictionary.GetAsDict(PdfName.CIDSYSTEMINFO);
				if (asDict == null)
				{
					return;
				}
				PdfString asString = asDict.GetAsString(PdfName.ORDERING);
				if (asString != null)
				{
					CMapToUnicode mapFromOrdering = IdentityToUnicode.GetMapFromOrdering(asString.ToUnicodeString());
					if (mapFromOrdering != null)
					{
						toUnicodeCmap = mapFromOrdering;
						uni2cid = toUnicodeCmap.CreateReverseMapping();
					}
				}
			}
			catch (IOException)
			{
				toUnicodeCmap = null;
				uni2cid = null;
			}
		}

		private void ProcessUni2Byte()
		{
			IntHashtable byte2Uni = base.Byte2Uni;
			int[] array = byte2Uni.ToOrderedKeys();
			if (array.Length == 0)
			{
				return;
			}
			cidbyte2uni = new char[256];
			foreach (int num in array)
			{
				if (num <= 255)
				{
					cidbyte2uni[num] = (char)byte2Uni[num];
				}
				else
				{
					LOGGER.Warn("Font has illegal differences array.");
				}
			}
			if (toUnicodeCmap != null)
			{
				IDictionary<int, int> dictionary = toUnicodeCmap.CreateDirectMapping();
				foreach (KeyValuePair<int, int> item in dictionary)
				{
					if (item.Key < 256)
					{
						cidbyte2uni[item.Key] = (char)item.Value;
					}
				}
			}
			IntHashtable intHashtable = base.Diffmap;
			if (intHashtable == null)
			{
				return;
			}
			array = intHashtable.ToOrderedKeys();
			for (int j = 0; j < array.Length; j++)
			{
				int num2 = intHashtable[array[j]];
				if (num2 < 256)
				{
					cidbyte2uni[num2] = (char)array[j];
				}
			}
		}

		private int ComputeAverageWidth()
		{
			int num = 0;
			int num2 = 0;
			for (int i = 0; i < widths.Length; i++)
			{
				if (widths[i] != 0)
				{
					num2 += widths[i];
					num++;
				}
			}
			if (num == 0)
			{
				return 0;
			}
			return num2 / num;
		}

		public override int GetWidth(int char1)
		{
			if (char1 == 32)
			{
				return spaceWidth;
			}
			return base.GetWidth(char1);
		}

		private string DecodeSingleCID(byte[] bytes, int offset, int len)
		{
			if (toUnicodeCmap != null)
			{
				if (offset + len > bytes.Length)
				{
					throw new IndexOutOfRangeException(MessageLocalization.GetComposedMessage("invalid.index.1", offset + len));
				}
				string text = toUnicodeCmap.Lookup(bytes, offset, len);
				if (text != null)
				{
					return text;
				}
				if (len != 1 || cidbyte2uni == null)
				{
					return null;
				}
			}
			if (len == 1)
			{
				if (cidbyte2uni == null)
				{
					return "";
				}
				return new string(cidbyte2uni, 0xFF & bytes[offset], 1);
			}
			throw new ArgumentException("Multi-byte glyphs not implemented yet");
		}

		public virtual string Decode(byte[] cidbytes, int offset, int len)
		{
			StringBuilder stringBuilder = new StringBuilder();
			if (toUnicodeCmap == null && byteCid != null)
			{
				CMapSequence seq = new CMapSequence(cidbytes, offset, len);
				string text = byteCid.DecodeSequence(seq);
				string text2 = text;
				foreach (char character in text2)
				{
					int num = cidUni.Lookup(character);
					if (num > 0)
					{
						stringBuilder.Append(Utilities.ConvertFromUtf32(num));
					}
				}
			}
			else
			{
				for (int j = offset; j < offset + len; j++)
				{
					string text3 = DecodeSingleCID(cidbytes, j, 1);
					if (text3 == null && j < offset + len - 1)
					{
						text3 = DecodeSingleCID(cidbytes, j, 2);
						j++;
					}
					if (text3 != null)
					{
						stringBuilder.Append(text3);
					}
				}
			}
			return stringBuilder.ToString();
		}

		public virtual string DecodeSingleCharacter(byte[] cidbytes, int offset, int len)
		{
			string result = "";
			if (toUnicodeCmap == null && byteCid != null)
			{
				CMapSequence seq = new CMapSequence(cidbytes, offset, len);
				int num = byteCid.DecodeSingle(seq);
				if (num >= 0)
				{
					int num2 = cidUni.Lookup(num);
					if (num2 > 0)
					{
						result = Utilities.ConvertFromUtf32(num2);
					}
				}
			}
			else
			{
				string text = DecodeSingleCID(cidbytes, offset, 1);
				if (text == null && len > 1)
				{
					text = DecodeSingleCID(cidbytes, offset, 2);
				}
				if (text != null)
				{
					result = text;
				}
			}
			return result;
		}

		public virtual string Encode(byte[] bytes, int offset, int len)
		{
			return Decode(bytes, offset, len);
		}
	}
	public class CMYKColor : ExtendedColor
	{
		private float ccyan;

		private float cmagenta;

		private float cyellow;

		private float cblack;

		public virtual float Cyan => ccyan;

		public virtual float Magenta => cmagenta;

		public virtual float Yellow => cyellow;

		public virtual float Black => cblack;

		public CMYKColor(int intCyan, int intMagenta, int intYellow, int intBlack)
			: this((float)intCyan / 255f, (float)intMagenta / 255f, (float)intYellow / 255f, (float)intBlack / 255f)
		{
		}

		public CMYKColor(float floatCyan, float floatMagenta, float floatYellow, float floatBlack)
			: base(2, 1f - floatCyan - floatBlack, 1f - floatMagenta - floatBlack, 1f - floatYellow - floatBlack)
		{
			ccyan = ExtendedColor.Normalize(floatCyan);
			cmagenta = ExtendedColor.Normalize(floatMagenta);
			cyellow = ExtendedColor.Normalize(floatYellow);
			cblack = ExtendedColor.Normalize(floatBlack);
		}

		public override bool Equals(object obj)
		{
			if (!(obj is CMYKColor))
			{
				return false;
			}
			CMYKColor cMYKColor = (CMYKColor)obj;
			if (ccyan == cMYKColor.ccyan && cmagenta == cMYKColor.cmagenta && cyellow == cMYKColor.cyellow)
			{
				return cblack == cMYKColor.cblack;
			}
			return false;
		}

		public override int GetHashCode()
		{
			return ccyan.GetHashCode() ^ cmagenta.GetHashCode() ^ cyellow.GetHashCode() ^ cblack.GetHashCode();
		}
	}
