		private byte[] GetPalette(int group)
		{
			if (palette == null)
			{
				return null;
			}
			byte[] array = new byte[palette.Length / group * 3];
			int num = palette.Length / group;
			for (int i = 0; i < num; i++)
			{
				int num2 = i * group;
				int num3 = i * 3;
				array[num3 + 2] = palette[num2++];
				array[num3 + 1] = palette[num2++];
				array[num3] = palette[num2];
			}
			return array;
		}

