		public virtual void Fax4Encode(byte[] data, int offset, int size)
		{
			dataBp = data;
			offsetData = offset;
			for (sizeData = size; sizeData > 0; sizeData -= rowbytes)
			{
				Fax3Encode2DRow();
				Array.Copy(dataBp, offsetData, refline, 0, rowbytes);
				offsetData += rowbytes;
			}
		}

