				additional.Put(PdfName.MASK, new PdfLiteral("[" + num2 + " " + num2 + "]"));
			}
			bool flag = interlaceMethod == 1 || bitDepth == 16 || ((uint)colorType & 4u) != 0 || palShades || genBWMask;
			switch (colorType)
			{
			case 0:
				inputBands = 1;
				break;
			case 2:
				inputBands = 3;
				break;
			case 3:
				inputBands = 1;
				break;
			case 4:
				inputBands = 2;
				break;
			case 6:
				inputBands = 4;
				break;
			}
			if (flag)
			{
				DecodeIdat();
			}
			int num4 = inputBands;
			if (((uint)colorType & 4u) != 0)
			{
				num4--;
			}
			int num5 = bitDepth;
			if (num5 == 16)
			{
				num5 = 8;
			}
			Image image;
			if (this.image != null)
			{
				image = ((colorType != 3) ? Image.GetInstance(width, height, num4, num5, this.image) : new ImgRaw(width, height, num4, num5, this.image));
			}
			else
			{
				image = new ImgRaw(width, height, num4, num5, idat.ToArray());
				image.Deflated = true;
				PdfDictionary pdfDictionary = new PdfDictionary();
				pdfDictionary.Put(PdfName.BITSPERCOMPONENT, new PdfNumber(bitDepth));
				pdfDictionary.Put(PdfName.PREDICTOR, new PdfNumber(15));
				pdfDictionary.Put(PdfName.COLUMNS, new PdfNumber(width));
				pdfDictionary.Put(PdfName.COLORS, new PdfNumber((colorType == 3 || (colorType & 2) == 0) ? 1 : 3));
				additional.Put(PdfName.DECODEPARMS, pdfDictionary);
			}
			if (additional.Get(PdfName.COLORSPACE) == null)
			{
				additional.Put(PdfName.COLORSPACE, GetColorspace());
			}
			if (intent != null)
			{
				additional.Put(PdfName.INTENT, intent);
			}
			if (additional.Size > 0)
			{
				image.Additional = additional;
			}
			if (icc_profile != null)
			{
				image.TagICC = icc_profile;
			}
			if (palShades)
			{
				Image instance = Image.GetInstance(width, height, 1, 8, smask);
				instance.MakeMask();
				image.ImageMask = instance;
			}
			if (genBWMask)
			{
				Image instance2 = Image.GetInstance(width, height, 1, 1, smask);
				instance2.MakeMask();
				image.ImageMask = instance2;
			}
			image.SetDpi(dpiX, dpiY);
			image.XYRatio = XYRatio;
			image.OriginalType = 2;
			return image;
		}

		private void DecodeIdat()
		{
			int num = bitDepth;
			if (num == 16)
			{
				num = 8;
			}
			int num2 = -1;
			bytesPerPixel = ((bitDepth != 16) ? 1 : 2);
			switch (colorType)
			{
			case 0:
				num2 = (num * width + 7) / 8 * height;
				break;
			case 2:
				num2 = width * 3 * height;
				bytesPerPixel *= 3;
				break;
			case 3:
				if (interlaceMethod == 1)
				{
					num2 = (num * width + 7) / 8 * height;
				}
				bytesPerPixel = 1;
				break;
			case 4:
				num2 = width * height;
				bytesPerPixel *= 2;
				break;
			case 6:
				num2 = width * 3 * height;
				bytesPerPixel *= 4;
				break;
			}
			if (num2 >= 0)
			{
				image = new byte[num2];
			}
			if (palShades)
			{
				smask = new byte[width * height];
			}
			else if (genBWMask)
			{
				smask = new byte[(width + 7) / 8 * height];
			}
			idat.Position = 0L;
			dataStream = new ZInflaterInputStream(idat);
			if (interlaceMethod != 1)
			{
				DecodePass(0, 0, 1, 1, width, height);
			}
			else
			{
				DecodePass(0, 0, 8, 8, (width + 7) / 8, (height + 7) / 8);
				DecodePass(4, 0, 8, 8, (width + 3) / 8, (height + 7) / 8);
				DecodePass(0, 4, 4, 8, (width + 3) / 4, (height + 3) / 8);
				DecodePass(2, 0, 4, 4, (width + 1) / 4, (height + 3) / 4);
				DecodePass(0, 2, 2, 4, (width + 1) / 2, (height + 1) / 4);
				DecodePass(1, 0, 2, 2, width / 2, (height + 1) / 2);
				DecodePass(0, 1, 1, 2, width, height / 2);
			}
			try
			{
				dataStream.Close();
			}
			catch (IOException)
			{
				LOGGER.Warn("Datastream of PngImage#decodeIdat didn't close properly.");
			}
		}

		private void DecodePass(int xOffset, int yOffset, int xStep, int yStep, int passWidth, int passHeight)
		{
			if (passWidth == 0 || passHeight == 0)
			{
				return;
			}
			int num = (inputBands * passWidth * bitDepth + 7) / 8;
			byte[] array = new byte[num];
			byte[] array2 = new byte[num];
			int num2 = 0;
			int num3 = yOffset;
			while (num2 < passHeight)
			{
				int num4 = 0;
				try
				{
					num4 = dataStream.ReadByte();
					ReadFully(dataStream, array, 0, num);
				}
				catch
				{
				}
				switch (num4)
				{
				case 1:
					DecodeSubFilter(array, num, bytesPerPixel);
					break;
				case 2:
					DecodeUpFilter(array, array2, num);
					break;
				case 3:
					DecodeAverageFilter(array, array2, num, bytesPerPixel);
					break;
				case 4:
					DecodePaethFilter(array, array2, num, bytesPerPixel);
					break;
				default:
					throw new Exception(MessageLocalization.GetComposedMessage("png.filter.unknown"));
				case 0:
					break;
				}
				ProcessPixels(array, xOffset, xStep, num3, passWidth);
				byte[] array3 = array2;
				array2 = array;
				array = array3;
				num2++;
				num3 += yStep;
			}
		}

		private void ProcessPixels(byte[] curr, int xOffset, int step, int y, int width)
		{
			int[] pixel = GetPixel(curr);
			int num = 0;
			switch (colorType)
			{
			case 0:
			case 3:
			case 4:
				num = 1;
				break;
			case 2:
			case 6:
				num = 3;
				break;
			}
			if (image != null)
			{
				int num2 = xOffset;
				int bytesPerRow = (num * this.width * ((bitDepth == 16) ? 8 : bitDepth) + 7) / 8;
				for (int i = 0; i < width; i++)
				{
					SetPixel(image, pixel, inputBands * i, num, num2, y, bitDepth, bytesPerRow);
					num2 += step;
				}
			}
			if (palShades)
			{
				int num2;
				if (((uint)colorType & 4u) != 0)
				{
					if (bitDepth == 16)
					{
						for (int j = 0; j < width; j++)
						{
							int num3 = j * inputBands + num;
							pixel[num3] = Util.USR(pixel[num3], 8);
						}
					}
					int bytesPerRow2 = this.width;
					num2 = xOffset;
					for (int i = 0; i < width; i++)
					{
						SetPixel(smask, pixel, inputBands * i + num, 1, num2, y, 8, bytesPerRow2);
						num2 += step;
					}
					return;
				}
				int bytesPerRow3 = this.width;
				int[] array = new int[1];
				num2 = xOffset;
				for (int i = 0; i < width; i++)
				{
					int num4 = pixel[i];
					if (num4 < trans.Length)
					{
						array[0] = trans[num4];
					}
					else
					{
						array[0] = 255;
					}
					SetPixel(smask, array, 0, 1, num2, y, 8, bytesPerRow3);
					num2 += step;
				}
			}
			else
			{
				if (!genBWMask)
				{
					return;
				}
				switch (colorType)
				{
				case 3:
				{
					int bytesPerRow5 = (this.width + 7) / 8;
					int[] array3 = new int[1];
					int num2 = xOffset;
					for (int i = 0; i < width; i++)
					{
						int num6 = pixel[i];
						array3[0] = ((num6 < trans.Length && trans[num6] == 0) ? 1 : 0);
						SetPixel(smask, array3, 0, 1, num2, y, 1, bytesPerRow5);
						num2 += step;
					}
					break;
				}
				case 0:
				{
					int bytesPerRow6 = (this.width + 7) / 8;
					int[] array4 = new int[1];
					int num2 = xOffset;
					for (int i = 0; i < width; i++)
					{
						int num7 = pixel[i];
						array4[0] = ((num7 == transRedGray) ? 1 : 0);
						SetPixel(smask, array4, 0, 1, num2, y, 1, bytesPerRow6);
						num2 += step;
					}
					break;
				}
				case 2:
				{
					int bytesPerRow4 = (this.width + 7) / 8;
					int[] array2 = new int[1];
					int num2 = xOffset;
					for (int i = 0; i < width; i++)
					{
						int num5 = inputBands * i;
						array2[0] = ((pixel[num5] == transRedGray && pixel[num5 + 1] == transGreen && pixel[num5 + 2] == transBlue) ? 1 : 0);
						SetPixel(smask, array2, 0, 1, num2, y, 1, bytesPerRow4);
						num2 += step;
					}
					break;
				}
				case 1:
					break;
				}
			}
		}

		private static int GetPixel(byte[] image, int x, int y, int bitDepth, int bytesPerRow)
		{
			if (bitDepth == 8)
			{
				int num = bytesPerRow * y + x;
				return image[num] & 0xFF;
			}
			int num2 = bytesPerRow * y + x / (8 / bitDepth);
			int num3 = image[num2] >> 8 - bitDepth * (x % (8 / bitDepth)) - bitDepth;
			return num3 & ((1 << bitDepth) - 1);
		}

		private static void SetPixel(byte[] image, int[] data, int offset, int size, int x, int y, int bitDepth, int bytesPerRow)
		{
			switch (bitDepth)
			{
			case 8:
			{
				int num4 = bytesPerRow * y + size * x;
				for (int j = 0; j < size; j++)
				{
					image[num4 + j] = (byte)data[j + offset];
				}
				break;
			}
			case 16:
			{
				int num3 = bytesPerRow * y + size * x;
				for (int i = 0; i < size; i++)
				{
					image[num3 + i] = (byte)(data[i + offset] >> 8);
				}
				break;
			}
			default:
			{
				int num = bytesPerRow * y + x / (8 / bitDepth);
				int num2 = data[offset] << 8 - bitDepth * (x % (8 / bitDepth)) - bitDepth;
				image[num] |= (byte)num2;
				break;
			}
			}
		}

		private int[] GetPixel(byte[] curr)
		{
			switch (bitDepth)
			{
			case 8:
			{
				int[] array3 = new int[curr.Length];
				for (int k = 0; k < array3.Length; k++)
				{
					array3[k] = curr[k] & 0xFF;
				}
				return array3;
			}
			case 16:
			{
				int[] array2 = new int[curr.Length / 2];
				for (int j = 0; j < array2.Length; j++)
				{
					array2[j] = ((curr[j * 2] & 0xFF) << 8) + (curr[j * 2 + 1] & 0xFF);
				}
				return array2;
			}
			default:
			{
				int[] array = new int[curr.Length * 8 / bitDepth];
				int num = 0;
				int num2 = 8 / bitDepth;
				int num3 = (1 << bitDepth) - 1;
				for (int i = 0; i < curr.Length; i++)
				{
					for (int num4 = num2 - 1; num4 >= 0; num4--)
					{
						array[num++] = Util.USR(curr[i], bitDepth * num4) & num3;
					}
				}
				return array;
			}
			}
		}

		private int GetExpectedIccNumberOfComponents()
		{
			if (colorType == 0 || colorType == 4)
			{
				return 1;
			}
			return 3;
		}

		private void CheckIccProfile()
		{
			if (icc_profile != null && icc_profile.NumComponents != GetExpectedIccNumberOfComponents())
			{
				LoggerFactory.GetLogger(typeof(PngImage)).Warn(MessageLocalization.GetComposedMessage("unexpected.color.space.in.embedded.icc.profile"));
				icc_profile = null;
			}
		}

		private static void DecodeSubFilter(byte[] curr, int count, int bpp)
		{
			for (int i = bpp; i < count; i++)
			{
				int num = curr[i] & 0xFF;
				num += curr[i - bpp] & 0xFF;
				curr[i] = (byte)num;
			}
		}

		private static void DecodeUpFilter(byte[] curr, byte[] prev, int count)
		{
			for (int i = 0; i < count; i++)
			{
				int num = curr[i] & 0xFF;
				int num2 = prev[i] & 0xFF;
				curr[i] = (byte)(num + num2);
			}
		}

		private static void DecodeAverageFilter(byte[] curr, byte[] prev, int count, int bpp)
		{
			for (int i = 0; i < bpp; i++)
			{
				int num = curr[i] & 0xFF;
				int num2 = prev[i] & 0xFF;
				curr[i] = (byte)(num + num2 / 2);
			}
			for (int j = bpp; j < count; j++)
			{
				int num = curr[j] & 0xFF;
				int num3 = curr[j - bpp] & 0xFF;
				int num2 = prev[j] & 0xFF;
				curr[j] = (byte)(num + (num3 + num2) / 2);
			}
		}

		private static int PaethPredictor(int a, int b, int c)
		{
			int num = a + b - c;
			int num2 = Math.Abs(num - a);
			int num3 = Math.Abs(num - b);
			int num4 = Math.Abs(num - c);
			if (num2 <= num3 && num2 <= num4)
			{
				return a;
			}
			if (num3 <= num4)
			{
				return b;
			}
			return c;
		}

		private static void DecodePaethFilter(byte[] curr, byte[] prev, int count, int bpp)
		{
			for (int i = 0; i < bpp; i++)
			{
				int num = curr[i] & 0xFF;
				int num2 = prev[i] & 0xFF;
				curr[i] = (byte)(num + num2);
			}
			for (int j = bpp; j < count; j++)
			{
				int num = curr[j] & 0xFF;
				int a = curr[j - bpp] & 0xFF;
				int num2 = prev[j] & 0xFF;
				int c = prev[j - bpp] & 0xFF;
				curr[j] = (byte)(num + PaethPredictor(a, num2, c));
			}
		}

		public static int GetInt(Stream isp)
		{
			return (isp.ReadByte() << 24) + (isp.ReadByte() << 16) + (isp.ReadByte() << 8) + isp.ReadByte();
		}

		public static int GetWord(Stream isp)
		{
			return (isp.ReadByte() << 8) + isp.ReadByte();
		}

		public static string GetString(Stream isp)
		{
			StringBuilder stringBuilder = new StringBuilder();
			for (int i = 0; i < 4; i++)
			{
				stringBuilder.Append((char)isp.ReadByte());
			}
			return stringBuilder.ToString();
		}

		private static void ReadFully(Stream inp, byte[] b, int offset, int count)
		{
			while (count > 0)
			{
				int num = inp.Read(b, offset, count);
				if (num <= 0)
				{
					throw new IOException(MessageLocalization.GetComposedMessage("insufficient.data"));
				}
				count -= num;
				offset += num;
			}
		}
	}
	public class PngWriter
	{
		private static readonly byte[] PNG_SIGNTURE = new byte[8] { 137, 80, 78, 71, 13, 10, 26, 10 };

		private static readonly byte[] IHDR = DocWriter.GetISOBytes("IHDR");

		private static readonly byte[] PLTE = DocWriter.GetISOBytes("PLTE");

		private static readonly byte[] IDAT = DocWriter.GetISOBytes("IDAT");

		private static readonly byte[] IEND = DocWriter.GetISOBytes("IEND");

		private static readonly byte[] iCCP = DocWriter.GetISOBytes("iCCP");

		private static uint[] crc_table;

		private Stream outp;

		public PngWriter(Stream outp)
		{
			this.outp = outp;
			outp.Write(PNG_SIGNTURE, 0, PNG_SIGNTURE.Length);
		}

		public virtual void WriteHeader(int width, int height, int bitDepth, int colorType)
		{
			MemoryStream memoryStream = new MemoryStream();
			OutputInt(width, memoryStream);
			OutputInt(height, memoryStream);
			memoryStream.WriteByte((byte)bitDepth);
			memoryStream.WriteByte((byte)colorType);
			memoryStream.WriteByte(0);
			memoryStream.WriteByte(0);
			memoryStream.WriteByte(0);
			WriteChunk(IHDR, memoryStream.ToArray());
		}

		public virtual void WriteEnd()
		{
			WriteChunk(IEND, new byte[0]);
		}

		public virtual void WriteData(byte[] data, int stride)
		{
			MemoryStream memoryStream = new MemoryStream();
			ZDeflaterOutputStream zDeflaterOutputStream = new ZDeflaterOutputStream(memoryStream, 5);
			int i;
			for (i = 0; i < data.Length - stride; i += stride)
			{
				zDeflaterOutputStream.WriteByte(0);
				zDeflaterOutputStream.Write(data, i, stride);
			}
			int num = data.Length - i;
			if (num > 0)
			{
				zDeflaterOutputStream.WriteByte(0);
				zDeflaterOutputStream.Write(data, i, num);
			}
			zDeflaterOutputStream.Close();
			WriteChunk(IDAT, memoryStream.ToArray());
		}

		public virtual void WritePalette(byte[] data)
		{
			WriteChunk(PLTE, data);
		}

		public virtual void WriteIccProfile(byte[] data)
		{
			MemoryStream memoryStream = new MemoryStream();
			memoryStream.WriteByte(73);
			memoryStream.WriteByte(67);
			memoryStream.WriteByte(67);
			memoryStream.WriteByte(0);
			memoryStream.WriteByte(0);
			ZDeflaterOutputStream zDeflaterOutputStream = new ZDeflaterOutputStream(memoryStream, 5);
			zDeflaterOutputStream.Write(data, 0, data.Length);
			zDeflaterOutputStream.Close();
			WriteChunk(iCCP, memoryStream.ToArray());
		}

		private static void make_crc_table()
		{
			if (crc_table != null)
			{
				return;
			}
			uint[] array = new uint[256];
			for (uint num = 0u; num < 256; num++)
			{
				uint num2 = num;
				for (int i = 0; i < 8; i++)
				{
					num2 = (((num2 & 1) == 0) ? (num2 >> 1) : (0xEDB88320u ^ (num2 >> 1)));
				}
				array[num] = num2;
			}
			crc_table = array;
		}

		private static uint update_crc(uint crc, byte[] buf, int offset, int len)
		{
			uint num = crc;
			if (crc_table == null)
			{
				make_crc_table();
			}
			for (int i = 0; i < len; i++)
			{
				num = crc_table[(num ^ buf[i + offset]) & 0xFF] ^ (num >> 8);
			}
			return num;
		}

		private static uint crc(byte[] buf, int offset, int len)
		{
			return update_crc(uint.MaxValue, buf, offset, len) ^ 0xFFFFFFFFu;
		}

		private static uint crc(byte[] buf)
		{
			return update_crc(uint.MaxValue, buf, 0, buf.Length) ^ 0xFFFFFFFFu;
		}

		public virtual void OutputInt(int n)
		{
			OutputInt(n, outp);
		}

		public static void OutputInt(int n, Stream s)
		{
			s.WriteByte((byte)(n >> 24));
			s.WriteByte((byte)(n >> 16));
			s.WriteByte((byte)(n >> 8));
			s.WriteByte((byte)n);
		}

		public virtual void WriteChunk(byte[] chunkType, byte[] data)
		{
			OutputInt(data.Length);
			outp.Write(chunkType, 0, 4);
			outp.Write(data, 0, data.Length);
			uint num = update_crc(uint.MaxValue, chunkType, 0, chunkType.Length);
			num = update_crc(num, data, 0, data.Length) ^ 0xFFFFFFFFu;
			OutputInt((int)num);
		}
	}
	public class TIFFConstants
	{
		public const int TIFFTAG_SUBFILETYPE = 254;

