				byte b = buffer[num2];
				while (num4 > 0 && bitNum < num)
				{
					b |= (byte)num4;
					num4 >>= 1;
					bitNum++;
				}
				buffer[num2] = b;
			}
			num2 = bitNum >> 3;
			while (bitNum < num - 7)
			{
				buffer[num2++] = byte.MaxValue;
				bitNum += 8;
			}
			while (bitNum < num)
			{
				num2 = bitNum >> 3;
				buffer[num2] |= (byte)(1 << 7 - (bitNum & 7));
