					float num7 = state.TransformY(meta.ReadShort()) - state.TransformY(0);
					float num8 = state.TransformX(meta.ReadShort()) - state.TransformX(0);
					float num9 = state.TransformY(meta.ReadShort());
					float num10 = state.TransformX(meta.ReadShort());
					byte[] array = new byte[num * 2 - (meta.Length - length)];
					for (int i = 0; i < array.Length; i++)
					{
						array[i] = (byte)meta.ReadByte();
					}
					try
					{
						MemoryStream isp = new MemoryStream(array);
						Image image = BmpImage.GetImage(isp, noHeader: true, array.Length);
						cb.SaveState();
						cb.Rectangle(num10, num9, num8, num7);
						cb.Clip();
						cb.NewPath();
						image.ScaleAbsolute(num8 * image.Width / (float)num4, (0f - num7) * image.Height / (float)num3);
						image.SetAbsolutePosition(num10 - num8 * (float)num6 / (float)num4, num9 + num7 * (float)num5 / (float)num3 - image.ScaledHeight);
						cb.AddImage(image);
						cb.RestoreState();
					}
					catch
					{
					}
					break;
				}
				}
				meta.Skip(num * 2 - (meta.Length - length));
			}
			state.Cleanup(cb);
		}

		public virtual void OutputText(int x, int y, int flag, int x1, int y1, int x2, int y2, string text)
		{
			MetaFont currentFont = state.CurrentFont;
			float e = state.TransformX(x);
			float f = state.TransformY(y);
			float num = state.TransformAngle(currentFont.Angle);
			float num2 = (float)Math.Sin(num);
			float num3 = (float)Math.Cos(num);
			float fontSize = currentFont.GetFontSize(state);
			BaseFont font = currentFont.Font;
			int textAlign = state.TextAlign;
			float widthPoint = font.GetWidthPoint(text, fontSize);
			float x3 = 0f;
			float num4 = 0f;
			float fontDescriptor = font.GetFontDescriptor(3, fontSize);
			float fontDescriptor2 = font.GetFontDescriptor(8, fontSize);
			cb.SaveState();
			cb.ConcatCTM(num3, num2, 0f - num2, num3, e, f);
			if ((textAlign & MetaState.TA_CENTER) == MetaState.TA_CENTER)
			{
				x3 = (0f - widthPoint) / 2f;
			}
			else if ((textAlign & MetaState.TA_RIGHT) == MetaState.TA_RIGHT)
			{
				x3 = 0f - widthPoint;
			}
			num4 = (((textAlign & MetaState.TA_BASELINE) == MetaState.TA_BASELINE) ? 0f : (((textAlign & MetaState.TA_BOTTOM) != MetaState.TA_BOTTOM) ? (0f - fontDescriptor2) : (0f - fontDescriptor)));
			BaseColor currentBackgroundColor;
			if (state.BackgroundMode == MetaState.OPAQUE)
			{
				currentBackgroundColor = state.CurrentBackgroundColor;
				cb.SetColorFill(currentBackgroundColor);
				cb.Rectangle(x3, num4 + fontDescriptor, widthPoint, fontDescriptor2 - fontDescriptor);
				cb.Fill();
			}
			currentBackgroundColor = state.CurrentTextColor;
			cb.SetColorFill(currentBackgroundColor);
			cb.BeginText();
			cb.SetFontAndSize(font, fontSize);
			cb.SetTextMatrix(x3, num4);
			cb.ShowText(text);
			cb.EndText();
			if (currentFont.IsUnderline())
			{
				cb.Rectangle(x3, num4 - fontSize / 4f, widthPoint, fontSize / 15f);
				cb.Fill();
			}
			if (currentFont.IsStrikeout())
			{
				cb.Rectangle(x3, num4 + fontSize / 3f, widthPoint, fontSize / 15f);
				cb.Fill();
			}
			cb.RestoreState();
		}

		public virtual bool IsNullStrokeFill(bool isRectangle)
		{
			MetaPen currentPen = state.CurrentPen;
			MetaBrush currentBrush = state.CurrentBrush;
			bool flag = currentPen.Style == 5;
			bool flag2 = currentBrush.Style switch
			{
				2 => state.BackgroundMode == MetaState.OPAQUE, 
				0 => true, 
				_ => false, 
			};
			bool result = flag && !flag2;
			if (!flag)
			{
				if (isRectangle)
				{
					state.LineJoinRectangle = cb;
				}
				else
				{
					state.LineJoinPolygon = cb;
				}
			}
			return result;
		}

		public virtual void StrokeAndFill()
		{
			MetaPen currentPen = state.CurrentPen;
			MetaBrush currentBrush = state.CurrentBrush;
			int style = currentPen.Style;
			int style2 = currentBrush.Style;
			if (style == 5)
			{
				cb.ClosePath();
				if (state.PolyFillMode == MetaState.ALTERNATE)
				{
					cb.EoFill();
				}
				else
				{
					cb.Fill();
				}
			}
			else if (style2 == 0 || (style2 == 2 && state.BackgroundMode == MetaState.OPAQUE))
			{
				if (state.PolyFillMode == MetaState.ALTERNATE)
				{
					cb.ClosePathEoFillStroke();
				}
				else
				{
					cb.ClosePathFillStroke();
				}
			}
			else
			{
				cb.ClosePathStroke();
			}
		}

		internal static double GetArc(double xCenter, double yCenter, double xDot, double yDot)
		{
			double num = Math.Atan2(yDot - yCenter, xDot - xCenter);
			if (num < 0.0)
			{
				num += Math.PI * 2.0;
			}
			return num / Math.PI * 180.0;
		}

		public static byte[] WrapBMP(Image image)
		{
			if (image.OriginalType != 4)
			{
				throw new IOException(MessageLocalization.GetComposedMessage("only.bmp.can.be.wrapped.in.wmf"));
			}
			byte[] array = null;
			if (image.OriginalData == null)
			{
				WebRequest webRequest = WebRequest.Create(image.Url);
				webRequest.Credentials = CredentialCache.DefaultCredentials;
				Stream responseStream = webRequest.GetResponse().GetResponseStream();
				MemoryStream memoryStream = new MemoryStream();
				int num = 0;
				while ((num = responseStream.ReadByte()) != -1)
				{
					memoryStream.WriteByte((byte)num);
				}
				responseStream.Close();
				array = memoryStream.ToArray();
			}
			else
			{
				array = image.OriginalData;
			}
			int num2 = array.Length - 14 + 1 >> 1;
			MemoryStream memoryStream2 = new MemoryStream();
			WriteWord(memoryStream2, 1);
			WriteWord(memoryStream2, 9);
			WriteWord(memoryStream2, 768);
			WriteDWord(memoryStream2, 23 + (13 + num2) + 3);
			WriteWord(memoryStream2, 1);
			WriteDWord(memoryStream2, 14 + num2);
			WriteWord(memoryStream2, 0);
			WriteDWord(memoryStream2, 4);
			WriteWord(memoryStream2, 259);
			WriteWord(memoryStream2, 8);
			WriteDWord(memoryStream2, 5);
			WriteWord(memoryStream2, 523);
			WriteWord(memoryStream2, 0);
			WriteWord(memoryStream2, 0);
			WriteDWord(memoryStream2, 5);
			WriteWord(memoryStream2, 524);
			WriteWord(memoryStream2, (int)image.Height);
			WriteWord(memoryStream2, (int)image.Width);
			WriteDWord(memoryStream2, 13 + num2);
			WriteWord(memoryStream2, 2881);
			WriteDWord(memoryStream2, 13369376);
			WriteWord(memoryStream2, (int)image.Height);
			WriteWord(memoryStream2, (int)image.Width);
			WriteWord(memoryStream2, 0);
			WriteWord(memoryStream2, 0);
			WriteWord(memoryStream2, (int)image.Height);
			WriteWord(memoryStream2, (int)image.Width);
			WriteWord(memoryStream2, 0);
			WriteWord(memoryStream2, 0);
			memoryStream2.Write(array, 14, array.Length - 14);
			if ((array.Length & 1) == 1)
			{
				memoryStream2.WriteByte(0);
			}
			WriteDWord(memoryStream2, 3);
			WriteWord(memoryStream2, 0);
			memoryStream2.Close();
			return memoryStream2.ToArray();
		}

		public static void WriteWord(Stream os, int v)
		{
			os.WriteByte((byte)((uint)v & 0xFFu));
			os.WriteByte((byte)((uint)(v >> 8) & 0xFFu));
		}

		public static void WriteDWord(Stream os, int v)
		{
			WriteWord(os, v & 0xFFFF);
			WriteWord(os, (v >> 16) & 0xFFFF);
		}
	}
	public class MetaFont : MetaObject
	{
		internal const int MARKER_BOLD = 1;

		internal const int MARKER_ITALIC = 2;

		internal const int MARKER_COURIER = 0;

		internal const int MARKER_HELVETICA = 4;

		internal const int MARKER_TIMES = 8;

		internal const int MARKER_SYMBOL = 12;

		internal const int DEFAULT_PITCH = 0;

		internal const int FIXED_PITCH = 1;

		internal const int VARIABLE_PITCH = 2;

		internal const int FF_DONTCARE = 0;

		internal const int FF_ROMAN = 1;

		internal const int FF_SWISS = 2;

		internal const int FF_MODERN = 3;

		internal const int FF_SCRIPT = 4;

		internal const int FF_DECORATIVE = 5;

		internal const int BOLDTHRESHOLD = 600;

		internal const int nameSize = 32;

		internal const int ETO_OPAQUE = 2;

		internal const int ETO_CLIPPED = 4;

		private static string[] fontNames = new string[14]
		{
			"Courier", "Courier-Bold", "Courier-Oblique", "Courier-BoldOblique", "Helvetica", "Helvetica-Bold", "Helvetica-Oblique", "Helvetica-BoldOblique", "Times-Roman", "Times-Bold",
			"Times-Italic", "Times-BoldItalic", "Symbol", "ZapfDingbats"
		};

		private int height;

		private float angle;

		private int bold;

		private int italic;

		private bool underline;

		private bool strikeout;

		private int charset;

		private int pitchAndFamily;

		private string faceName = "arial";

		private BaseFont font;

		public virtual BaseFont Font
		{
			get
			{
				if (this.font != null)
				{
					return this.font;
				}
				Font font = FontFactory.GetFont(faceName, "Cp1252", embedded: true, 10f, ((italic != 0) ? 2 : 0) | ((bold != 0) ? 1 : 0));
				this.font = font.BaseFont;
				if (this.font != null)
				{
					return this.font;
				}
				string name;
				if (faceName.IndexOf("courier") != -1 || faceName.IndexOf("terminal") != -1 || faceName.IndexOf("fixedsys") != -1)
				{
					name = fontNames[italic + bold];
				}
				else if (faceName.IndexOf("ms sans serif") != -1 || faceName.IndexOf("arial") != -1 || faceName.IndexOf("system") != -1)
				{
					name = fontNames[4 + italic + bold];
				}
				else if (faceName.IndexOf("arial black") != -1)
				{
					name = fontNames[4 + italic + 1];
				}
				else if (faceName.IndexOf("times") != -1 || faceName.IndexOf("ms serif") != -1 || faceName.IndexOf("roman") != -1)
				{
					name = fontNames[8 + italic + bold];
				}
				else if (faceName.IndexOf("symbol") != -1)
				{
					name = fontNames[12];
				}
				else
				{
					int num = pitchAndFamily & 3;
					switch ((pitchAndFamily >> 4) & 7)
					{
					case 3:
						name = fontNames[italic + bold];
						break;
					case 1:
						name = fontNames[8 + italic + bold];
						break;
					case 2:
					case 4:
					case 5:
						name = fontNames[4 + italic + bold];
						break;
					default:
					{
						int num2 = num;
						name = ((num2 != 1) ? fontNames[4 + italic + bold] : fontNames[italic + bold]);
						break;
					}
					}
				}
				this.font = BaseFont.CreateFont(name, "Cp1252", embedded: false);
				return this.font;
			}
		}

		public virtual float Angle => angle;

		public MetaFont()
		{
			type = 3;
		}

		public virtual void Init(InputMeta meta)
		{
			height = Math.Abs(meta.ReadShort());
			meta.Skip(2);
			angle = (float)((double)meta.ReadShort() / 1800.0 * Math.PI);
			meta.Skip(2);
			bold = ((meta.ReadShort() >= 600) ? 1 : 0);
			italic = ((meta.ReadByte() != 0) ? 2 : 0);
			underline = meta.ReadByte() != 0;
			strikeout = meta.ReadByte() != 0;
			charset = meta.ReadByte();
			meta.Skip(3);
			pitchAndFamily = meta.ReadByte();
			byte[] array = new byte[32];
			int i;
			for (i = 0; i < 32; i++)
			{
				int num = meta.ReadByte();
				if (num == 0)
				{
					break;
				}
				array[i] = (byte)num;
			}
			try
			{
				faceName = Encoding.GetEncoding(1252).GetString(array, 0, i);
			}
			catch
			{
				faceName = Encoding.ASCII.GetString(array, 0, i);
			}
			faceName = faceName.ToLower(CultureInfo.InvariantCulture);
		}

		public virtual bool IsUnderline()
		{
			return underline;
		}

		public virtual bool IsStrikeout()
		{
			return strikeout;
		}

		public virtual float GetFontSize(MetaState state)
		{
			return Math.Abs(state.TransformY(height) - state.TransformY(0)) * Document.WmfFontCorrection;
		}
	}
