			{
			case 1:
				Put(PdfName.VIEW, PdfName.T);
				break;
			case 2:
				Put(PdfName.VIEW, PdfName.H);
				break;
			case 3:
				Put(PdfName.VIEW, PdfName.C);
				break;
			default:
				Put(PdfName.VIEW, PdfName.D);
				break;
			}
		}
