				os_2.sTypoLineGap = (short)(hhea.LineGap * 2);
				os_2.usWinAscent = hhea.Ascender;
				os_2.usWinDescent = hhea.Descender;
				os_2.ulCodePageRange1 = 0;
				os_2.ulCodePageRange2 = 0;
				os_2.sCapHeight = (int)(0.7 * (double)head.unitsPerEm);
