				int num9 = rf.ReadUnsignedShort();
				if (num9 == 4)
				{
					cmap31 = ReadFormat4();
				}
			}
			if (num4 > 0)
			{
				rf.Seek(value[0] + num4);
				int num10 = rf.ReadUnsignedShort();
				if (num10 == 4)
