		internal Dictionary<int, int[]> ReadFormat12()
		{
			Dictionary<int, int[]> dictionary = new Dictionary<int, int[]>();
			rf.SkipBytes(2L);
			rf.ReadInt();
			rf.SkipBytes(4L);
			int num = rf.ReadInt();
			for (int i = 0; i < num; i++)
			{
				int num2 = rf.ReadInt();
				int num3 = rf.ReadInt();
				int num4 = rf.ReadInt();
				for (int j = num2; j <= num3; j++)
				{
					int[] array = new int[2];
					array[0] = num4;
					array[1] = GetGlyphWidth(array[0]);
					dictionary[j] = array;
					num4++;
