	public class FieldPositioningEvents : PdfPageEventHelper, IPdfPCellEvent
	{
		protected Dictionary<string, PdfFormField> genericChunkFields = new Dictionary<string, PdfFormField>();

		protected PdfFormField cellField;

		protected PdfWriter fieldWriter;

		protected PdfFormField parent;

		public float padding;

		public virtual float Padding
		{
			get
			{
				return padding;
			}
			set
			{
				padding = value;
			}
		}

		public virtual PdfFormField Parent
		{
			get
			{
				return parent;
			}
			set
			{
				parent = value;
			}
		}

		public FieldPositioningEvents()
		{
		}

		public virtual void AddField(string text, PdfFormField field)
		{
			genericChunkFields[text] = field;
		}

		public FieldPositioningEvents(PdfWriter writer, PdfFormField field)
		{
			cellField = field;
			fieldWriter = writer;
		}

		public FieldPositioningEvents(PdfFormField parent, PdfFormField field)
		{
			cellField = field;
			this.parent = parent;
		}

		public FieldPositioningEvents(PdfWriter writer, string text)
		{
			fieldWriter = writer;
			cellField = new TextField(writer, new Rectangle(0f, 0f), text)
			{
				FontSize = 14f
			}.GetTextField();
		}

		public FieldPositioningEvents(PdfWriter writer, PdfFormField parent, string text)
		{
			this.parent = parent;
			cellField = new TextField(writer, new Rectangle(0f, 0f), text)
			{
				FontSize = 14f
			}.GetTextField();
		}

		public override void OnGenericTag(PdfWriter writer, Document document, Rectangle rect, string text)
		{
			rect.Bottom -= 3f;
			genericChunkFields.TryGetValue(text, out var value);
			if (value == null)
			{
				TextField textField = new TextField(writer, new Rectangle(rect.GetLeft(padding), rect.GetBottom(padding), rect.GetRight(padding), rect.GetTop(padding)), text);
				textField.FontSize = 14f;
				value = textField.GetTextField();
			}
			else
			{
				value.Put(PdfName.RECT, new PdfRectangle(rect.GetLeft(padding), rect.GetBottom(padding), rect.GetRight(padding), rect.GetTop(padding)));
			}
			if (parent == null)
			{
				writer.AddAnnotation(value);
			}
			else
			{
				parent.AddKid(value);
			}
		}

		public virtual void CellLayout(PdfPCell cell, Rectangle rect, PdfContentByte[] canvases)
		{
			if (cellField == null || (fieldWriter == null && parent == null))
			{
				throw new ArgumentException(MessageLocalization.GetComposedMessage("you.have.used.the.wrong.constructor.for.this.fieldpositioningevents.class"));
			}
			cellField.Put(PdfName.RECT, new PdfRectangle(rect.GetLeft(padding), rect.GetBottom(padding), rect.GetRight(padding), rect.GetTop(padding)));
			if (parent == null)
			{
				fieldWriter.AddAnnotation(cellField);
			}
			else
			{
				parent.AddKid(cellField);
			}
		}
	}
	public class IndexEvents : PdfPageEventHelper
	{
		private class ISortIndex : IComparer<Entry>
		{
			public virtual int Compare(Entry en1, Entry en2)
			{
				int result = 0;
				if (en1.GetIn1() != null && en2.GetIn1() != null && (result = Util.CompareToIgnoreCase(en1.GetIn1(), en2.GetIn1())) == 0 && en1.GetIn2() != null && en2.GetIn2() != null && (result = Util.CompareToIgnoreCase(en1.GetIn2(), en2.GetIn2())) == 0 && en1.GetIn3() != null && en2.GetIn3() != null)
				{
					result = Util.CompareToIgnoreCase(en1.GetIn3(), en2.GetIn3());
				}
				return result;
			}
		}

		public class Entry
		{
			private string in1;

			private string in2;

			private string in3;

			private string tag;

			private List<int> pagenumbers = new List<int>();

			private List<string> tags = new List<string>();

			private IndexEvents parent;

			public Entry(string aIn1, string aIn2, string aIn3, string aTag, IndexEvents parent)
			{
				in1 = aIn1;
				in2 = aIn2;
				in3 = aIn3;
				tag = aTag;
				this.parent = parent;
			}

			public virtual string GetIn1()
			{
				return in1;
			}

			public virtual string GetIn2()
			{
				return in2;
			}

			public virtual string GetIn3()
			{
				return in3;
			}

			public virtual string GetTag()
			{
				return tag;
			}

			public virtual int GetPageNumber()
			{
				if (parent.indextag.ContainsKey(tag))
				{
					return parent.indextag[tag];
				}
				return -1;
			}

			public virtual void AddPageNumberAndTag(int number, string tag)
			{
				pagenumbers.Add(number);
				tags.Add(tag);
			}

			public virtual string GetKey()
			{
				return in1 + "!" + in2 + "!" + in3;
			}

			public virtual List<int> GetPagenumbers()
			{
				return pagenumbers;
			}

			public virtual List<string> GetTags()
			{
				return tags;
			}

			public override string ToString()
			{
				StringBuilder stringBuilder = new StringBuilder();
				stringBuilder.Append(in1).Append(' ');
				stringBuilder.Append(in2).Append(' ');
				stringBuilder.Append(in3).Append(' ');
				for (int i = 0; i < pagenumbers.Count; i++)
				{
					stringBuilder.Append(pagenumbers[i]).Append(' ');
				}
				return stringBuilder.ToString();
			}
		}

		private Dictionary<string, int> indextag = new Dictionary<string, int>();

		private long indexcounter;

		private List<Entry> indexentry = new List<Entry>();

		private IComparer<Entry> comparator = new ISortIndex();

		public override void OnGenericTag(PdfWriter writer, Document document, Rectangle rect, string text)
		{
			indextag[text] = writer.PageNumber;
		}

		public virtual Chunk Create(string text, string in1, string in2, string in3)
		{
			Chunk chunk = new Chunk(text);
			string text2 = "idx_" + indexcounter++;
			chunk.SetGenericTag(text2);
			chunk.SetLocalDestination(text2);
			Entry item = new Entry(in1, in2, in3, text2, this);
			indexentry.Add(item);
			return chunk;
		}

		public virtual Chunk Create(string text, string in1)
		{
			return Create(text, in1, "", "");
		}

		public virtual Chunk Create(string text, string in1, string in2)
		{
			return Create(text, in1, in2, "");
		}

		public virtual void Create(Chunk text, string in1, string in2, string in3)
		{
			string text2 = "idx_" + indexcounter++;
			text.SetGenericTag(text2);
			text.SetLocalDestination(text2);
			Entry item = new Entry(in1, in2, in3, text2, this);
			indexentry.Add(item);
		}

		public virtual void Create(Chunk text, string in1)
		{
			Create(text, in1, "", "");
		}

		public virtual void Create(Chunk text, string in1, string in2)
		{
			Create(text, in1, in2, "");
		}

		public virtual void SetComparator(IComparer<Entry> aComparator)
		{
			comparator = aComparator;
		}

		public virtual List<Entry> GetSortedEntries()
		{
			Dictionary<string, Entry> dictionary = new Dictionary<string, Entry>();
			for (int i = 0; i < indexentry.Count; i++)
			{
				Entry entry = indexentry[i];
				string key = entry.GetKey();
				dictionary.TryGetValue(key, out var value);
				if (value != null)
				{
					value.AddPageNumberAndTag(entry.GetPageNumber(), entry.GetTag());
					continue;
				}
				entry.AddPageNumberAndTag(entry.GetPageNumber(), entry.GetTag());
				dictionary[key] = entry;
			}
			List<Entry> list = new List<Entry>(dictionary.Values);
			list.Sort(0, list.Count, comparator);
			return list;
		}
	}
