						documentOCG[layer] = null;
						documentOCGorder.Add(layer);
					}
				}
				else
				{
					documentOCGorder.Add(layer);
				}
				return;
			}
			throw new ArgumentException(MessageLocalization.GetComposedMessage("only.pdflayer.is.accepted"));
		}

