			{
				subset = value;
			}
		}

		internal FontDetails(PdfName fontName, PdfIndirectReference indirectReference, BaseFont baseFont)
		{
			this.fontName = fontName;
			this.indirectReference = indirectReference;
			this.baseFont = baseFont;
			fontType = baseFont.FontType;
			switch (fontType)
			{
			case 0:
			case 1:
				shortTag = new byte[256];
				break;
			case 2:
				cjkTag = new IntHashtable();
				cjkFont = (CJKFont)baseFont;
				break;
			case 3:
				longTag = new Dictionary<int, int[]>();
				ttu = (TrueTypeFontUnicode)baseFont;
				symbolic = baseFont.IsFontSpecific();
				break;
			}
		}

		internal virtual object[] ConvertToBytesGid(string gids)
		{
			if (fontType != 3)
			{
				throw new ArgumentException("GID require TT Unicode");
			}
			try
			{
				StringBuilder stringBuilder = new StringBuilder();
				int num = 0;
				char[] array = gids.ToCharArray();
				foreach (char c in array)
				{
					int glyphWidth = ttu.GetGlyphWidth(c);
					num += glyphWidth;
					int charFromGlyphId = ttu.GetCharFromGlyphId(c);
					if (charFromGlyphId != 0)
					{
						stringBuilder.Append(Utilities.ConvertFromUtf32(charFromGlyphId));
					}
					int key = c;
					if (!longTag.ContainsKey(key))
					{
						longTag[key] = new int[3] { c, glyphWidth, charFromGlyphId };
					}
				}
				return new object[3]
				{
					Encoding.GetEncoding("UNICODEBIGUNMARKED").GetBytes(gids),
					stringBuilder.ToString(),
					num
				};
			}
			catch (Exception)
			{
				throw;
			}
		}

		internal byte[] ConvertToBytes(string text)
		{
			byte[] array = null;
			switch (fontType)
			{
			case 5:
				return baseFont.ConvertToBytes(text);
			case 0:
			case 1:
			{
				array = baseFont.ConvertToBytes(text);
				int num4 = array.Length;
				for (int m = 0; m < num4; m++)
				{
					shortTag[array[m] & 0xFF] = 1;
				}
				break;
			}
			case 2:
			{
				int length2 = text.Length;
				if (cjkFont.IsIdentity())
				{
					foreach (char key2 in text)
					{
						cjkTag[key2] = 0;
					}
				}
				else
				{
					for (int l = 0; l < length2; l++)
					{
						int c;
						if (Utilities.IsSurrogatePair(text, l))
						{
							c = Utilities.ConvertToUtf32(text, l);
							l++;
						}
						else
						{
							c = text[l];
						}
						cjkTag[cjkFont.GetCidCode(c)] = 0;
					}
				}
				array = cjkFont.ConvertToBytes(text);
				break;
			}
			case 4:
				array = baseFont.ConvertToBytes(text);
				break;
			case 3:
			{
				int length = text.Length;
				int[] array2 = null;
				char[] array3 = new char[length];
				int num = 0;
				if (symbolic)
				{
					array = PdfEncodings.ConvertToBytes(text, "symboltt");
					length = array.Length;
					for (int i = 0; i < length; i++)
					{
						array2 = ttu.GetMetricsTT(array[i] & 0xFF);
						if (array2 != null)
						{
							longTag[array2[0]] = new int[3]
							{
								array2[0],
								array2[1],
								ttu.GetUnicodeDifferences(array[i] & 0xFF)
							};
							array3[num++] = (char)array2[0];
						}
					}
				}
				else
				{
					for (int j = 0; j < length; j++)
					{
						int num2;
						if (Utilities.IsSurrogatePair(text, j))
						{
							num2 = Utilities.ConvertToUtf32(text, j);
							j++;
						}
						else
						{
							num2 = text[j];
						}
						array2 = ttu.GetMetricsTT(num2);
						if (array2 != null)
						{
							int num3 = array2[0];
							int key = num3;
							if (!longTag.ContainsKey(key))
							{
								longTag[key] = new int[3]
								{
									num3,
									array2[1],
									num2
								};
							}
							array3[num++] = (char)num3;
						}
					}
				}
				char[] array4 = new char[num];
				Array.Copy(array3, array4, num);
				array = StringUtils.ConvertCharsToBytes(array4);
				break;
			}
			}
			return array;
		}

		public virtual void WriteFont(PdfWriter writer)
		{
			switch (fontType)
			{
			case 5:
				baseFont.WriteFont(writer, indirectReference, null);
				break;
			case 0:
			case 1:
			{
				int i;
				for (i = 0; i < 256 && shortTag[i] == 0; i++)
				{
				}
				int num = 255;
				while (num >= i && shortTag[num] == 0)
				{
					num--;
				}
				if (i > 255)
				{
					i = 255;
					num = 255;
				}
				baseFont.WriteFont(writer, indirectReference, new object[4] { i, num, shortTag, subset });
				break;
			}
			case 2:
				baseFont.WriteFont(writer, indirectReference, new object[1] { cjkTag });
				break;
			case 3:
				baseFont.WriteFont(writer, indirectReference, new object[2] { longTag, subset });
				break;
			case 4:
				break;
			}
		}
	}
	public class FontSelector
	{
		private static readonly ILogger LOGGER = LoggerFactory.GetLogger(typeof(PdfSmartCopy));

		protected List<Font> fonts = new List<Font>();

		protected List<Font> unsupportedFonts = new List<Font>();

		protected Font currentFont;

		public virtual void AddFont(Font font)
		{
			if (!IsSupported(font))
			{
				unsupportedFonts.Add(font);
				return;
			}
			if (font.BaseFont != null)
			{
				fonts.Add(font);
				return;
			}
			BaseFont calculatedBaseFont = font.GetCalculatedBaseFont(specialEncoding: true);
			Font item = new Font(calculatedBaseFont, font.Size, font.CalculatedStyle, font.Color);
			fonts.Add(item);
		}

		public virtual Phrase Process(string text)
		{
			if (GetSize() == 0)
			{
				throw new ArgumentOutOfRangeException(MessageLocalization.GetComposedMessage("no.font.is.defined"));
			}
			char[] array = text.ToCharArray();
			int num = array.Length;
			StringBuilder stringBuilder = new StringBuilder();
			Phrase phrase = new Phrase();
			currentFont = null;
			for (int i = 0; i < num; i++)
			{
				Chunk chunk = ProcessChar(array, i, stringBuilder);
				if (chunk != null)
				{
					phrase.Add(chunk);
				}
			}
			if (stringBuilder.Length > 0)
			{
				Chunk element = new Chunk(stringBuilder.ToString(), currentFont ?? GetFont(0));
				phrase.Add(element);
			}
			return phrase;
		}

		protected virtual Chunk ProcessChar(char[] cc, int k, StringBuilder sb)
		{
			Chunk result = null;
			char c = cc[k];
			if (c == '\n' || c == '\r')
			{
				sb.Append(c);
			}
			else
			{
				Font font = null;
				if (Utilities.IsSurrogatePair(cc, k))
				{
					int num = Utilities.ConvertToUtf32(cc, k);
					for (int i = 0; i < GetSize(); i++)
					{
						font = GetFont(i);
						if (!font.BaseFont.CharExists(num) && CharUnicodeInfo.GetUnicodeCategory(char.ConvertFromUtf32(num), 0) != UnicodeCategory.Format)
						{
							continue;
						}
						if (currentFont != font)
						{
							if (sb.Length > 0 && currentFont != null)
							{
								result = new Chunk(sb.ToString(), currentFont);
								sb.Length = 0;
							}
							currentFont = font;
						}
						sb.Append(c);
						sb.Append(cc[++k]);
						break;
					}
				}
				else
				{
					for (int j = 0; j < GetSize(); j++)
					{
						font = GetFont(j);
						if (!font.BaseFont.CharExists(c) && char.GetUnicodeCategory(c) != UnicodeCategory.Format)
						{
							continue;
						}
						if (currentFont != font)
						{
							if (sb.Length > 0 && currentFont != null)
							{
								result = new Chunk(sb.ToString(), currentFont);
								sb.Length = 0;
							}
							currentFont = font;
						}
						sb.Append(c);
						break;
					}
				}
			}
			return result;
		}

		protected int GetSize()
		{
			return fonts.Count + unsupportedFonts.Count;
		}

		protected Font GetFont(int i)
		{
			if (i >= fonts.Count)
			{
				return unsupportedFonts[i - fonts.Count];
			}
			return fonts[i];
		}

		private bool IsSupported(Font font)
		{
			BaseFont baseFont = font.BaseFont;
			if (baseFont is TrueTypeFont && "Cp1252".Equals(baseFont.Encoding) && !((TrueTypeFont)baseFont).IsWinAnsiSupported())
			{
				LOGGER.Warn($"cmap(1, 0) not found for TrueType Font {font}, it is required for WinAnsi encoding.");
				return false;
			}
			return true;
		}
	}
	public class GlyphList
	{
		private static Dictionary<int, string> unicode2names;

		private static Dictionary<string, int[]> names2unicode;

		static GlyphList()
		{
			unicode2names = new Dictionary<int, string>();
			names2unicode = new Dictionary<string, int[]>();
			Stream stream = null;
			try
			{
				stream = StreamUtil.GetResourceStream("iTextSharp.text.pdf.fonts.glyphlist.txt");
				if (stream == null)
				{
					string message = "glyphlist.txt not found as resource.";
					throw new Exception(message);
				}
				byte[] array = new byte[1024];
				MemoryStream memoryStream = new MemoryStream();
				while (true)
				{
					int num = stream.Read(array, 0, array.Length);
					if (num == 0)
					{
						break;
					}
					memoryStream.Write(array, 0, num);
				}
				stream.Close();
				stream = null;
				string str = PdfEncodings.ConvertToString(memoryStream.ToArray(), null);
				StringTokenizer stringTokenizer = new StringTokenizer(str, "\r\n");
				while (stringTokenizer.HasMoreTokens())
				{
					string text = stringTokenizer.NextToken();
					if (text.StartsWith("#"))
					{
						continue;
					}
					StringTokenizer stringTokenizer2 = new StringTokenizer(text, " ;\r\n\t\f");
					string text2 = null;
					string text3 = null;
					if (stringTokenizer2.HasMoreTokens())
					{
						text2 = stringTokenizer2.NextToken();
						if (stringTokenizer2.HasMoreTokens())
						{
							text3 = stringTokenizer2.NextToken();
							int num2 = int.Parse(text3, NumberStyles.HexNumber);
							unicode2names[num2] = text2;
							names2unicode[text2] = new int[1] { num2 };
						}
					}
				}
			}
			catch (Exception ex)
			{
				Console.Error.WriteLine("glyphlist.txt loading error: " + ex.Message);
			}
			finally
			{
				if (stream != null)
				{
					try
					{
						stream.Close();
					}
					catch
					{
					}
				}
			}
		}

		public static int[] NameToUnicode(string name)
		{
			names2unicode.TryGetValue(name, out var value);
			if (value == null && name.Length == 7 && name.ToLowerInvariant().StartsWith("uni"))
			{
				try
				{
					return new int[1] { int.Parse(name.Substring(3), NumberStyles.HexNumber) };
				}
				catch
				{
				}
			}
			return value;
		}

		public static string UnicodeToName(int num)
		{
			unicode2names.TryGetValue(num, out var value);
			return value;
		}
	}
	public class GrayColor : ExtendedColor
	{
