	public interface IHyphenationEvent
	{
		string HyphenSymbol { get; }

		string HyphenatedWordPost { get; }

		string GetHyphenatedWordPre(string word, BaseFont font, float fontSize, float remainingWidth);
	}
	public class HyphenationAuto : IHyphenationEvent
	{
		protected Hyphenator hyphenator;

		protected string post;

		public virtual string HyphenSymbol => "-";

		public virtual string HyphenatedWordPost => post;

		public HyphenationAuto(string lang, string country, int leftMin, int rightMin)
		{
			hyphenator = new Hyphenator(lang, country, leftMin, rightMin);
		}

		public virtual string GetHyphenatedWordPre(string word, BaseFont font, float fontSize, float remainingWidth)
		{
			post = word;
			string hyphenSymbol = HyphenSymbol;
			float widthPoint = font.GetWidthPoint(hyphenSymbol, fontSize);
			if (widthPoint > remainingWidth)
			{
				return "";
			}
			Hyphenation hyphenation = hyphenator.Hyphenate(word);
			if (hyphenation == null)
			{
				return "";
			}
			int length = hyphenation.Length;
			int i;
			for (i = 0; i < length && !(font.GetWidthPoint(hyphenation.GetPreHyphenText(i), fontSize) + widthPoint > remainingWidth); i++)
			{
			}
			i--;
			if (i < 0)
			{
				return "";
			}
			post = hyphenation.GetPostHyphenText(i);
			return hyphenation.GetPreHyphenText(i) + hyphenSymbol;
		}
	}
}
