	public class ByteVector
	{
		private static int DEFAULT_BLOCK_SIZE = 2048;

		private int BLOCK_SIZE;

		private byte[] arr;

		private int n;

		public virtual byte[] Arr => arr;

		public virtual int Length => n;

		public virtual int Capacity => arr.Length;

		public byte this[int index]
		{
			get
			{
				return arr[index];
			}
			set
			{
				arr[index] = value;
			}
		}

		public ByteVector()
			: this(DEFAULT_BLOCK_SIZE)
		{
		}

		public ByteVector(int capacity)
		{
			if (capacity > 0)
			{
				BLOCK_SIZE = capacity;
			}
			else
			{
				BLOCK_SIZE = DEFAULT_BLOCK_SIZE;
			}
			arr = new byte[BLOCK_SIZE];
			n = 0;
		}

		public ByteVector(byte[] a)
		{
			BLOCK_SIZE = DEFAULT_BLOCK_SIZE;
			arr = a;
			n = 0;
		}

		public ByteVector(byte[] a, int capacity)
		{
			if (capacity > 0)
			{
				BLOCK_SIZE = capacity;
			}
			else
			{
				BLOCK_SIZE = DEFAULT_BLOCK_SIZE;
			}
			arr = a;
			n = 0;
		}

		public virtual int Alloc(int size)
		{
			int result = n;
			int num = arr.Length;
			if (n + size >= num)
			{
				byte[] destinationArray = new byte[num + BLOCK_SIZE];
				Array.Copy(arr, 0, destinationArray, 0, num);
				arr = destinationArray;
			}
			n += size;
			return result;
		}

		public virtual void TrimToSize()
		{
			if (n < arr.Length)
			{
				byte[] destinationArray = new byte[n];
				Array.Copy(arr, 0, destinationArray, 0, n);
				arr = destinationArray;
			}
		}
	}
