	public class Hyphen
	{
		public string preBreak;

		public string noBreak;

		public string postBreak;

		internal Hyphen(string pre, string no, string post)
		{
			preBreak = pre;
			noBreak = no;
			postBreak = post;
		}

		internal Hyphen(string pre)
		{
			preBreak = pre;
			noBreak = null;
			postBreak = null;
		}

		public override string ToString()
		{
			if (noBreak == null && postBreak == null && preBreak != null && preBreak.Equals("-"))
			{
				return "-";
			}
			StringBuilder stringBuilder = new StringBuilder("{");
			stringBuilder.Append(preBreak);
			stringBuilder.Append("}{");
			stringBuilder.Append(postBreak);
			stringBuilder.Append("}{");
			stringBuilder.Append(noBreak);
			stringBuilder.Append('}');
			return stringBuilder.ToString();
		}
	}
	public class Hyphenation
	{
		private int[] hyphenPoints;

		private string word;

		private int len;

		public virtual int Length => len;

		public virtual int[] HyphenationPoints => hyphenPoints;

		public Hyphenation(string word, int[] points)
		{
			this.word = word;
			hyphenPoints = points;
			len = points.Length;
		}

		public virtual string GetPreHyphenText(int index)
		{
			return word.Substring(0, hyphenPoints[index]);
		}

		public virtual string GetPostHyphenText(int index)
		{
			return word.Substring(hyphenPoints[index]);
		}

		public override string ToString()
		{
			StringBuilder stringBuilder = new StringBuilder();
			int num = 0;
			for (int i = 0; i < len; i++)
			{
				stringBuilder.Append(word.Substring(num, hyphenPoints[i] - num) + "-");
				num = hyphenPoints[i];
			}
			stringBuilder.Append(word.Substring(num));
			return stringBuilder.ToString();
		}
	}
