	public class TernaryTree : ICloneable
	{
		public class Iterator
		{
			private class Item : ICloneable
			{
				internal char parent;

				internal char child;

				public Item()
				{
					parent = '\0';
					child = '\0';
				}

				public Item(char p, char c)
				{
					parent = p;
					child = c;
				}

				public virtual object Clone()
				{
					return new Item(parent, child);
				}
			}

			private int cur;

			private string curkey;

			private TernaryTree parent;

			private Stack ns;

			private StringBuilder ks;

			public virtual char Value
			{
				get
				{
					if (cur >= 0)
					{
						return parent.eq[cur];
					}
					return '\0';
				}
			}

			public Iterator(TernaryTree parent)
			{
				this.parent = parent;
				cur = -1;
				ns = new Stack();
				ks = new StringBuilder();
				Rewind();
			}

			public virtual void Rewind()
			{
				ns.Clear();
				ks.Length = 0;
				cur = parent.root;
				Run();
			}

			public virtual object NextElement()
			{
				string result = curkey;
				cur = Up();
				Run();
				return result;
			}

			public virtual bool HasMoreElements()
			{
				return cur != -1;
			}

			private int Up()
			{
				Item item = new Item();
				int result = 0;
				if (ns.Count == 0)
				{
					return -1;
				}
				if (cur != 0 && parent.sc[cur] == '\0')
				{
					return parent.lo[cur];
				}
				bool flag = true;
				while (flag)
				{
					item = (Item)ns.Pop();
					item.child += '\u0001';
					switch (item.child)
					{
					case '\u0001':
						if (parent.sc[(uint)item.parent] != 0)
						{
							result = parent.eq[(uint)item.parent];
							ns.Push(item.Clone());
							ks.Append(parent.sc[(uint)item.parent]);
						}
						else
						{
							item.child += '\u0001';
							ns.Push(item.Clone());
							result = parent.hi[(uint)item.parent];
						}
						flag = false;
						break;
					case '\u0002':
						result = parent.hi[(uint)item.parent];
						ns.Push(item.Clone());
						if (ks.Length > 0)
						{
							ks.Length -= 1;
						}
						flag = false;
						break;
					default:
						if (ns.Count == 0)
						{
							return -1;
						}
						flag = true;
						break;
					}
				}
				return result;
			}

			private int Run()
			{
				if (cur == -1)
				{
					return -1;
				}
				bool flag = false;
				while (true)
				{
					if (cur != 0)
					{
						if (parent.sc[cur] == '\uffff')
						{
							flag = true;
						}
						else
						{
							ns.Push(new Item((char)cur, '\0'));
							if (parent.sc[cur] != 0)
							{
								cur = parent.lo[cur];
								continue;
							}
							flag = true;
						}
					}
					if (flag)
					{
						break;
					}
					cur = Up();
					if (cur == -1)
					{
						return -1;
					}
				}
				StringBuilder stringBuilder = new StringBuilder(ks.ToString());
				if (parent.sc[cur] == '\uffff')
				{
					int index = parent.lo[cur];
					while (parent.kv[index] != 0)
					{
						stringBuilder.Append(parent.kv[index++]);
					}
				}
				curkey = stringBuilder.ToString();
				return 0;
			}
		}

		protected char[] lo;

		protected char[] hi;

		protected char[] eq;

		protected char[] sc;

		protected CharVector kv;

		protected char root;

		protected char freenode;

		protected int length;

		protected static int BLOCK_SIZE = 2048;

		public virtual int Size => length;

		public virtual Iterator Keys => new Iterator(this);

		internal TernaryTree()
		{
			Init();
		}

		protected virtual void Init()
		{
			root = '\0';
			freenode = '\u0001';
			length = 0;
			lo = new char[BLOCK_SIZE];
			hi = new char[BLOCK_SIZE];
			eq = new char[BLOCK_SIZE];
			sc = new char[BLOCK_SIZE];
			kv = new CharVector();
		}

		public virtual void Insert(string key, char val)
		{
			int num = key.Length + 1;
			if (freenode + num > eq.Length)
			{
				RedimNodeArrays(eq.Length + BLOCK_SIZE);
			}
			char[] array = new char[num--];
			key.CopyTo(0, array, 0, num);
			array[num] = '\0';
			root = Insert(root, array, 0, val);
		}

		public virtual void Insert(char[] key, int start, char val)
		{
			int num = Strlen(key) + 1;
			if (freenode + num > eq.Length)
			{
				RedimNodeArrays(eq.Length + BLOCK_SIZE);
			}
			root = Insert(root, key, start, val);
		}

		private char Insert(char p, char[] key, int start, char val)
		{
			int num = Strlen(key, start);
			if (p == '\0')
			{
				p = freenode++;
				eq[(uint)p] = val;
				length++;
				hi[(uint)p] = '\0';
				if (num > 0)
				{
					sc[(uint)p] = '\uffff';
					lo[(uint)p] = (char)kv.Alloc(num + 1);
					Strcpy(kv.Arr, lo[(uint)p], key, start);
				}
				else
				{
					sc[(uint)p] = '\0';
					lo[(uint)p] = '\0';
				}
				return p;
			}
			if (sc[(uint)p] == '\uffff')
			{
				char c = freenode++;
				lo[(uint)c] = lo[(uint)p];
				eq[(uint)c] = eq[(uint)p];
				lo[(uint)p] = '\0';
				if (num <= 0)
				{
					sc[(uint)c] = '\uffff';
					hi[(uint)p] = c;
					sc[(uint)p] = '\0';
					eq[(uint)p] = val;
					length++;
					return p;
				}
				sc[(uint)p] = kv[lo[(uint)c]];
				eq[(uint)p] = c;
				lo[(uint)c] += '\u0001';
				if (kv[lo[(uint)c]] == '\0')
				{
					lo[(uint)c] = '\0';
					sc[(uint)c] = '\0';
					hi[(uint)c] = '\0';
				}
				else
				{
					sc[(uint)c] = '\uffff';
				}
			}
			char c2 = key[start];
			if (c2 < sc[(uint)p])
			{
				lo[(uint)p] = Insert(lo[(uint)p], key, start, val);
			}
			else if (c2 == sc[(uint)p])
			{
				if (c2 != 0)
				{
					eq[(uint)p] = Insert(eq[(uint)p], key, start + 1, val);
				}
				else
				{
					eq[(uint)p] = val;
				}
			}
			else
			{
				hi[(uint)p] = Insert(hi[(uint)p], key, start, val);
			}
			return p;
		}

		public static int Strcmp(char[] a, int startA, char[] b, int startB)
		{
			while (a[startA] == b[startB])
			{
				if (a[startA] == '\0')
				{
					return 0;
				}
				startA++;
				startB++;
			}
			return a[startA] - b[startB];
		}

		public static int Strcmp(string str, char[] a, int start)
		{
			int num = str.Length;
			int i;
			for (i = 0; i < num; i++)
			{
				int num2 = str[i] - a[start + i];
				if (num2 != 0)
				{
					return num2;
				}
				if (a[start + i] == '\0')
				{
					return num2;
				}
			}
			if (a[start + i] != 0)
			{
				return 0 - a[start + i];
			}
			return 0;
		}

		public static void Strcpy(char[] dst, int di, char[] src, int si)
		{
			while (src[si] != 0)
			{
				dst[di++] = src[si++];
			}
			dst[di] = '\0';
		}

		public static int Strlen(char[] a, int start)
		{
			int num = 0;
			for (int i = start; i < a.Length && a[i] != 0; i++)
			{
				num++;
			}
			return num;
		}

		public static int Strlen(char[] a)
		{
			return Strlen(a, 0);
		}

		public virtual int Find(string key)
		{
			int num = key.Length;
			char[] array = new char[num + 1];
			key.CopyTo(0, array, 0, num);
			array[num] = '\0';
			return Find(array, 0);
		}

		public virtual int Find(char[] key, int start)
		{
			char c = root;
			int num = start;
			while (c != 0)
			{
				if (sc[(uint)c] == '\uffff')
				{
					if (Strcmp(key, num, kv.Arr, lo[(uint)c]) == 0)
					{
						return eq[(uint)c];
					}
					return -1;
				}
				char c2 = key[num];
				int num2 = c2 - sc[(uint)c];
				if (num2 == 0)
				{
					if (c2 == '\0')
					{
						return eq[(uint)c];
					}
					num++;
					c = eq[(uint)c];
				}
				else
				{
					c = ((num2 >= 0) ? hi[(uint)c] : lo[(uint)c]);
				}
			}
			return -1;
		}

		public virtual bool Knows(string key)
		{
			return Find(key) >= 0;
		}

		private void RedimNodeArrays(int newsize)
		{
			int num = ((newsize < lo.Length) ? newsize : lo.Length);
			char[] destinationArray = new char[newsize];
			Array.Copy(lo, 0, destinationArray, 0, num);
			lo = destinationArray;
			destinationArray = new char[newsize];
			Array.Copy(hi, 0, destinationArray, 0, num);
			hi = destinationArray;
			destinationArray = new char[newsize];
			Array.Copy(eq, 0, destinationArray, 0, num);
			eq = destinationArray;
			destinationArray = new char[newsize];
			Array.Copy(sc, 0, destinationArray, 0, num);
			sc = destinationArray;
		}

		public virtual object Clone()
		{
			TernaryTree ternaryTree = new TernaryTree();
			ternaryTree.lo = (char[])lo.Clone();
			ternaryTree.hi = (char[])hi.Clone();
			ternaryTree.eq = (char[])eq.Clone();
			ternaryTree.sc = (char[])sc.Clone();
			ternaryTree.kv = (CharVector)kv.Clone();
			ternaryTree.root = root;
			ternaryTree.freenode = freenode;
			ternaryTree.length = length;
			return ternaryTree;
		}

		protected virtual void InsertBalanced(string[] k, char[] v, int offset, int n)
		{
			if (n >= 1)
			{
				int num = n >> 1;
				Insert(k[num + offset], v[num + offset]);
				InsertBalanced(k, v, offset, num);
				InsertBalanced(k, v, offset + num + 1, n - num - 1);
			}
		}

		public virtual void Balance()
		{
			int num = 0;
			int num2 = length;
			string[] array = new string[num2];
			char[] array2 = new char[num2];
			Iterator iterator = new Iterator(this);
			while (iterator.HasMoreElements())
			{
				array2[num] = iterator.Value;
				array[num++] = (string)iterator.NextElement();
			}
			Init();
			InsertBalanced(array, array2, 0, num2);
		}

		public virtual void TrimToSize()
		{
			Balance();
			RedimNodeArrays(freenode);
			CharVector charVector = new CharVector();
			charVector.Alloc(1);
			TernaryTree map = new TernaryTree();
			Compact(charVector, map, root);
			kv = charVector;
			kv.TrimToSize();
		}

		private void Compact(CharVector kx, TernaryTree map, char p)
		{
			if (p == '\0')
			{
				return;
			}
			if (sc[(uint)p] == '\uffff')
			{
				int num = map.Find(kv.Arr, lo[(uint)p]);
				if (num < 0)
				{
					num = kx.Alloc(Strlen(kv.Arr, lo[(uint)p]) + 1);
					Strcpy(kx.Arr, num, kv.Arr, lo[(uint)p]);
					map.Insert(kx.Arr, num, (char)num);
				}
				lo[(uint)p] = (char)num;
			}
			else
			{
				Compact(kx, map, lo[(uint)p]);
				if (sc[(uint)p] != 0)
				{
					Compact(kx, map, eq[(uint)p]);
				}
				Compact(kx, map, hi[(uint)p]);
			}
		}

		public virtual void PrintStats()
		{
			Console.Error.WriteLine("Number of keys = " + length);
			Console.Error.WriteLine("Node count = " + freenode);
			Console.Error.WriteLine("Key Array length = " + kv.Length);
		}
	}
	public interface IPatternConsumer
	{
		void AddClass(string chargroup);

		void AddException(string word, List<object> hyphenatedword);

		void AddPattern(string pattern, string values);
	}
	public class HyphenationTree : TernaryTree, IPatternConsumer
	{
		protected ByteVector vspace;

		protected Dictionary<string, List<object>> stoplist;

		protected TernaryTree classmap;

		private TernaryTree ivalues;

		public HyphenationTree()
		{
			stoplist = new Dictionary<string, List<object>>(23);
			classmap = new TernaryTree();
			vspace = new ByteVector();
			vspace.Alloc(1);
		}

		protected virtual int PackValues(string values)
		{
			int num = values.Length;
			int num2 = (((num & 1) == 1) ? ((num >> 1) + 2) : ((num >> 1) + 1));
			int num3 = vspace.Alloc(num2);
			byte[] arr = vspace.Arr;
			for (int i = 0; i < num; i++)
			{
				int num4 = i >> 1;
				byte b = (byte)((uint)(values[i] - 48 + 1) & 0xFu);
				if ((i & 1) == 1)
				{
					arr[num4 + num3] = (byte)(arr[num4 + num3] | b);
				}
				else
				{
					arr[num4 + num3] = (byte)(b << 4);
				}
			}
			arr[num2 - 1 + num3] = 0;
			return num3;
		}

		protected virtual string UnpackValues(int k)
		{
			StringBuilder stringBuilder = new StringBuilder();
			for (byte b = vspace[k++]; b != 0; b = vspace[k++])
			{
				char value = (char)((b >> 4) - 1 + 48);
				stringBuilder.Append(value);
				value = (char)(b & 0xFu);
				if (value == '\0')
				{
					break;
				}
				value = (char)(value - 1 + 48);
				stringBuilder.Append(value);
			}
			return stringBuilder.ToString();
		}

		public virtual void LoadSimplePatterns(Stream stream)
		{
			SimplePatternParser simplePatternParser = new SimplePatternParser();
			ivalues = new TernaryTree();
			simplePatternParser.Parse(stream, this);
			TrimToSize();
			vspace.TrimToSize();
			classmap.TrimToSize();
			ivalues = null;
		}

		public virtual string FindPattern(string pat)
		{
			int num = base.Find(pat);
			if (num >= 0)
			{
				return UnpackValues(num);
			}
			return "";
		}

		protected virtual int Hstrcmp(char[] s, int si, char[] t, int ti)
		{
			while (s[si] == t[ti])
			{
				if (s[si] == '\0')
				{
					return 0;
				}
				si++;
				ti++;
			}
			if (t[ti] == '\0')
			{
				return 0;
			}
			return s[si] - t[ti];
		}

		protected virtual byte[] GetValues(int k)
		{
			StringBuilder stringBuilder = new StringBuilder();
			for (byte b = vspace[k++]; b != 0; b = vspace[k++])
			{
				char value = (char)((b >> 4) - 1);
				stringBuilder.Append(value);
				value = (char)(b & 0xFu);
				if (value == '\0')
				{
					break;
				}
				value = (char)(value - 1);
				stringBuilder.Append(value);
			}
			byte[] array = new byte[stringBuilder.Length];
			for (int i = 0; i < array.Length; i++)
			{
				array[i] = (byte)stringBuilder[i];
			}
			return array;
		}

		protected virtual void SearchPatterns(char[] word, int index, byte[] il)
		{
			int num = index;
			char c = word[num];
			char c2 = root;
			while (c2 > '\0' && c2 < sc.Length)
			{
				if (sc[(uint)c2] == '\uffff')
				{
					if (Hstrcmp(word, num, kv.Arr, lo[(uint)c2]) != 0)
					{
						break;
					}
					byte[] values = GetValues(eq[(uint)c2]);
					int num2 = index;
					for (int i = 0; i < values.Length; i++)
					{
						if (num2 < il.Length && values[i] > il[num2])
						{
							il[num2] = values[i];
						}
						num2++;
					}
					break;
				}
				int num3 = c - sc[(uint)c2];
				if (num3 == 0)
				{
					if (c == '\0')
					{
						break;
					}
					c = word[++num];
					c2 = eq[(uint)c2];
					char c3 = c2;
					while (c3 > '\0' && c3 < sc.Length && sc[(uint)c3] != '\uffff')
					{
						if (sc[(uint)c3] == '\0')
						{
							byte[] values = GetValues(eq[(uint)c3]);
							int num4 = index;
							for (int j = 0; j < values.Length; j++)
							{
								if (num4 < il.Length && values[j] > il[num4])
								{
									il[num4] = values[j];
								}
								num4++;
							}
							break;
						}
						c3 = lo[(uint)c3];
					}
				}
				else
				{
					c2 = ((num3 < 0) ? lo[(uint)c2] : hi[(uint)c2]);
				}
			}
		}

		public virtual Hyphenation Hyphenate(string word, int remainCharCount, int pushCharCount)
		{
			char[] array = word.ToCharArray();
			return Hyphenate(array, 0, array.Length, remainCharCount, pushCharCount);
		}

		public virtual Hyphenation Hyphenate(char[] w, int offset, int len, int remainCharCount, int pushCharCount)
		{
			char[] array = new char[len + 3];
			char[] array2 = new char[2];
			int num = 0;
			int num2 = len;
			bool flag = false;
			for (int i = 1; i <= len; i++)
			{
				array2[0] = w[offset + i - 1];
				int num3 = classmap.Find(array2, 0);
				if (num3 < 0)
				{
					if (i == 1 + num)
					{
						num++;
					}
					else
					{
						flag = true;
					}
					num2--;
				}
				else
				{
					if (flag)
					{
						return null;
					}
					array[i - num] = (char)num3;
				}
			}
			int num4 = len;
			len = num2;
			if (len < remainCharCount + pushCharCount)
			{
				return null;
			}
			int[] array3 = new int[len + 1];
			int num5 = 0;
			string key = new string(array, 1, len);
			if (stoplist.ContainsKey(key))
			{
				List<object> list = stoplist[key];
				int num6 = 0;
				for (int i = 0; i < list.Count; i++)
				{
					object obj = list[i];
					if (obj is string)
					{
						num6 += ((string)obj).Length;
						if (num6 >= remainCharCount && num6 < len - pushCharCount)
						{
							array3[num5++] = num6 + num;
						}
					}
				}
			}
			else
			{
				array[0] = '.';
				array[len + 1] = '.';
				array[len + 2] = '\0';
				byte[] array4 = new byte[len + 3];
				for (int i = 0; i < len + 1; i++)
				{
					SearchPatterns(array, i, array4);
				}
				for (int i = 0; i < len; i++)
				{
					if ((array4[i + 1] & 1) == 1 && i >= remainCharCount && i <= len - pushCharCount)
					{
						array3[num5++] = i + num;
					}
				}
			}
			if (num5 > 0)
			{
				int[] array5 = new int[num5];
				Array.Copy(array3, 0, array5, 0, num5);
				return new Hyphenation(new string(w, offset, num4), array5);
			}
			return null;
		}

		public virtual void AddClass(string chargroup)
		{
			if (chargroup.Length > 0)
			{
				char val = chargroup[0];
				char[] array = new char[2] { '\0', '\0' };
				for (int i = 0; i < chargroup.Length; i++)
				{
					array[0] = chargroup[i];
					classmap.Insert(array, 0, val);
				}
			}
		}

		public virtual void AddException(string word, List<object> hyphenatedword)
		{
			stoplist[word] = hyphenatedword;
		}

		public virtual void AddPattern(string pattern, string ivalue)
		{
			int num = ivalues.Find(ivalue);
			if (num <= 0)
			{
				num = PackValues(ivalue);
				ivalues.Insert(ivalue, (char)num);
			}
			Insert(pattern, (char)num);
		}

		public override void PrintStats()
		{
			Console.Out.WriteLine("Value space size = " + vspace.Length);
			base.PrintStats();
		}
	}
	public class Hyphenator
	{
		private const string defaultHyphLocation = "iTextSharp.text.pdf.hyphenation.hyph.";

		private static Hashtable hyphenTrees = Hashtable.Synchronized(new Hashtable());

		private HyphenationTree hyphenTree;

		private int remainCharCount = 2;

		private int pushCharCount = 2;

		public Hyphenator(string lang, string country, int leftMin, int rightMin)
		{
			hyphenTree = GetHyphenationTree(lang, country);
			remainCharCount = leftMin;
			pushCharCount = rightMin;
		}

		public static HyphenationTree GetHyphenationTree(string lang, string country)
		{
			string text = lang;
			if (country != null && !country.Equals("none"))
			{
				text = text + "_" + country;
			}
			if (hyphenTrees.ContainsKey(text))
			{
				return (HyphenationTree)hyphenTrees[text];
			}
			if (hyphenTrees.ContainsKey(lang))
			{
				return (HyphenationTree)hyphenTrees[lang];
			}
			HyphenationTree resourceHyphenationTree = GetResourceHyphenationTree(text);
			if (resourceHyphenationTree != null)
			{
				hyphenTrees[text] = resourceHyphenationTree;
			}
			return resourceHyphenationTree;
		}

		public static HyphenationTree GetResourceHyphenationTree(string key)
		{
			try
			{
				Stream resourceStream = StreamUtil.GetResourceStream("iTextSharp.text.pdf.hyphenation.hyph." + key + ".xml");
				if (resourceStream == null && key.Length > 2)
				{
					resourceStream = StreamUtil.GetResourceStream("iTextSharp.text.pdf.hyphenation.hyph." + key.Substring(0, 2) + ".xml");
				}
				if (resourceStream == null)
				{
					return null;
				}
				HyphenationTree hyphenationTree = new HyphenationTree();
				hyphenationTree.LoadSimplePatterns(resourceStream);
				return hyphenationTree;
			}
			catch
			{
				return null;
			}
		}

		public static Hyphenation Hyphenate(string lang, string country, string word, int leftMin, int rightMin)
		{
			return GetHyphenationTree(lang, country)?.Hyphenate(word, leftMin, rightMin);
		}

		public static Hyphenation Hyphenate(string lang, string country, char[] word, int offset, int len, int leftMin, int rightMin)
		{
			return GetHyphenationTree(lang, country)?.Hyphenate(word, offset, len, leftMin, rightMin);
		}

		public virtual void SetMinRemainCharCount(int min)
		{
			remainCharCount = min;
		}

		public virtual void SetMinPushCharCount(int min)
		{
			pushCharCount = min;
		}

		public virtual void SetLanguage(string lang, string country)
		{
			hyphenTree = GetHyphenationTree(lang, country);
		}

		public virtual Hyphenation Hyphenate(char[] word, int offset, int len)
		{
			if (hyphenTree == null)
			{
				return null;
			}
			return hyphenTree.Hyphenate(word, offset, len, remainCharCount, pushCharCount);
		}

		public virtual Hyphenation Hyphenate(string word)
		{
			if (hyphenTree == null)
			{
				return null;
			}
			return hyphenTree.Hyphenate(word, remainCharCount, pushCharCount);
		}
	}
	public class SimplePatternParser : ISimpleXMLDocHandler
	{
		internal const int ELEM_CLASSES = 1;

		internal const int ELEM_EXCEPTIONS = 2;

		internal const int ELEM_PATTERNS = 3;

		internal const int ELEM_HYPHEN = 4;

		internal int currElement;

		internal IPatternConsumer consumer;

		internal StringBuilder token;

		internal List<object> exception;

		internal char hyphenChar;

		public SimplePatternParser()
		{
			token = new StringBuilder();
			hyphenChar = '-';
		}

		public virtual void Parse(Stream stream, IPatternConsumer consumer)
		{
			this.consumer = consumer;
			try
			{
				SimpleXMLParser.Parse(this, stream);
			}
			finally
			{
				try
				{
					stream.Close();
				}
				catch
				{
				}
			}
		}

		protected static string GetPattern(string word)
		{
			StringBuilder stringBuilder = new StringBuilder();
			int length = word.Length;
			for (int i = 0; i < length; i++)
			{
				if (!char.IsDigit(word[i]))
				{
					stringBuilder.Append(word[i]);
				}
			}
			return stringBuilder.ToString();
		}

		protected virtual List<object> NormalizeException(List<object> ex)
		{
			List<object> list = new List<object>();
			for (int i = 0; i < ex.Count; i++)
			{
				object obj = ex[i];
				if (obj is string)
				{
					string text = (string)obj;
					StringBuilder stringBuilder = new StringBuilder();
					foreach (char c in text)
					{
						if (c != hyphenChar)
						{
							stringBuilder.Append(c);
							continue;
						}
						list.Add(stringBuilder.ToString());
						stringBuilder.Length = 0;
						list.Add(new Hyphen(new string(new char[1] { hyphenChar }), null, null));
					}
					if (stringBuilder.Length > 0)
					{
						list.Add(stringBuilder.ToString());
					}
				}
				else
				{
					list.Add(obj);
				}
			}
			return list;
		}

		protected virtual string GetExceptionWord(List<object> ex)
		{
			StringBuilder stringBuilder = new StringBuilder();
			for (int i = 0; i < ex.Count; i++)
			{
				object obj = ex[i];
				if (obj is string)
				{
					stringBuilder.Append((string)obj);
				}
				else if (((Hyphen)obj).noBreak != null)
				{
					stringBuilder.Append(((Hyphen)obj).noBreak);
				}
			}
			return stringBuilder.ToString();
		}

		protected static string GetInterletterValues(string pat)
		{
			StringBuilder stringBuilder = new StringBuilder();
			string text = pat + "a";
			int length = text.Length;
			for (int i = 0; i < length; i++)
			{
				char c = text[i];
				if (char.IsDigit(c))
				{
					stringBuilder.Append(c);
					i++;
				}
				else
				{
					stringBuilder.Append('0');
				}
			}
			return stringBuilder.ToString();
		}

		public virtual void EndDocument()
		{
		}

		public virtual void EndElement(string tag)
		{
			if (token.Length > 0)
			{
				string text = token.ToString();
				switch (currElement)
				{
				case 1:
					consumer.AddClass(text);
					break;
				case 2:
					exception.Add(text);
					exception = NormalizeException(exception);
					consumer.AddException(GetExceptionWord(exception), new List<object>(exception));
					break;
				case 3:
					consumer.AddPattern(GetPattern(text), GetInterletterValues(text));
					break;
				}
				if (currElement != 4)
				{
					token.Length = 0;
				}
			}
			if (currElement == 4)
			{
				currElement = 2;
			}
			else
			{
				currElement = 0;
			}
		}

		public virtual void StartDocument()
		{
		}

		public virtual void StartElement(string tag, IDictionary<string, string> h)
		{
			if (tag.Equals("hyphen-char"))
			{
				h.TryGetValue("value", out var value);
				if (value != null && value.Length == 1)
				{
					hyphenChar = value[0];
				}
			}
			else if (tag.Equals("classes"))
			{
				currElement = 1;
			}
			else if (tag.Equals("patterns"))
			{
				currElement = 3;
			}
			else if (tag.Equals("exceptions"))
			{
				currElement = 2;
				exception = new List<object>();
			}
			else if (tag.Equals("hyphen"))
			{
				if (token.Length > 0)
				{
					exception.Add(token.ToString());
				}
				h.TryGetValue("pre", out var value2);
				h.TryGetValue("no", out var value3);
				h.TryGetValue("post", out var value4);
				exception.Add(new Hyphen(value2, value3, value4));
				currElement = 4;
			}
			token.Length = 0;
		}

		public virtual void Text(string str)
		{
			StringTokenizer stringTokenizer = new StringTokenizer(str);
			while (stringTokenizer.HasMoreTokens())
			{
				string text = stringTokenizer.NextToken();
				switch (currElement)
				{
				case 1:
					consumer.AddClass(text);
					break;
				case 2:
					exception.Add(text);
					exception = NormalizeException(exception);
					consumer.AddException(GetExceptionWord(exception), new List<object>(exception));
					exception.Clear();
					break;
				case 3:
					consumer.AddPattern(GetPattern(text), GetInterletterValues(text));
					break;
				}
			}
		}
	}
}
namespace iTextSharp.text.pdf
{
	public class ICC_Profile
	{
		protected byte[] data;

		protected int numComponents;

		private static Dictionary<string, int> cstags;

		public virtual byte[] Data => data;

		public virtual int NumComponents => numComponents;

		protected ICC_Profile()
		{
		}

		public static ICC_Profile GetInstance(byte[] data, int numComponents)
		{
			if (data.Length < 128 || data[36] != 97 || data[37] != 99 || data[38] != 115 || data[39] != 112)
			{
				throw new ArgumentException(MessageLocalization.GetComposedMessage("invalid.icc.profile"));
			}
			ICC_Profile iCC_Profile = new ICC_Profile();
			iCC_Profile.data = data;
			if (!cstags.TryGetValue(Encoding.ASCII.GetString(data, 16, 4), out iCC_Profile.numComponents))
			{
				iCC_Profile.numComponents = 0;
			}
			if (iCC_Profile.numComponents != numComponents)
			{
				throw new ArgumentException("ICC profile contains " + iCC_Profile.numComponents + " component(s), the image data contains " + numComponents + " component(s)");
			}
			return iCC_Profile;
		}

		public static ICC_Profile GetInstance(byte[] data)
		{
			if (!cstags.TryGetValue(Encoding.ASCII.GetString(data, 16, 4), out var value))
			{
				value = 0;
			}
			return GetInstance(data, value);
		}

		public static ICC_Profile GetInstance(Stream file)
		{
			byte[] array = new byte[128];
			int num = array.Length;
			int num2 = 0;
			while (num > 0)
			{
				int num3 = file.Read(array, num2, num);
				if (num3 <= 0)
				{
					throw new ArgumentException(MessageLocalization.GetComposedMessage("invalid.icc.profile"));
				}
				num -= num3;
				num2 += num3;
			}
			if (array[36] != 97 || array[37] != 99 || array[38] != 115 || array[39] != 112)
			{
				throw new ArgumentException(MessageLocalization.GetComposedMessage("invalid.icc.profile"));
			}
			num = ((array[0] & 0xFF) << 24) | ((array[1] & 0xFF) << 16) | ((array[2] & 0xFF) << 8) | (array[3] & 0xFF);
			byte[] array2 = new byte[num];
			Array.Copy(array, 0, array2, 0, array.Length);
			num -= array.Length;
			num2 = array.Length;
			while (num > 0)
			{
				int num4 = file.Read(array2, num2, num);
				if (num4 <= 0)
				{
					throw new ArgumentException(MessageLocalization.GetComposedMessage("invalid.icc.profile"));
				}
				num -= num4;
				num2 += num4;
			}
			return GetInstance(array2);
		}

		public static ICC_Profile GetInstance(string fname)
		{
			FileStream fileStream = new FileStream(fname, FileMode.Open, FileAccess.Read, FileShare.Read);
			ICC_Profile instance = GetInstance(fileStream);
			fileStream.Close();
			return instance;
		}

		static ICC_Profile()
		{
			cstags = new Dictionary<string, int>();
			cstags["XYZ "] = 3;
			cstags["Lab "] = 3;
			cstags["Luv "] = 3;
			cstags["YCbr"] = 3;
			cstags["Yxy "] = 3;
			cstags["RGB "] = 3;
			cstags["GRAY"] = 1;
			cstags["HSV "] = 3;
			cstags["HLS "] = 3;
			cstags["CMYK"] = 4;
			cstags["CMY "] = 3;
			cstags["2CLR"] = 2;
			cstags["3CLR"] = 3;
			cstags["4CLR"] = 4;
			cstags["5CLR"] = 5;
			cstags["6CLR"] = 6;
			cstags["7CLR"] = 7;
			cstags["8CLR"] = 8;
			cstags["9CLR"] = 9;
			cstags["ACLR"] = 10;
			cstags["BCLR"] = 11;
			cstags["CCLR"] = 12;
			cstags["DCLR"] = 13;
			cstags["ECLR"] = 14;
			cstags["FCLR"] = 15;
		}
	}
