namespace iTextSharp.text.pdf.languages
{
	public interface ILanguageProcessor
	{
		string Process(string s);

		bool IsRTL();
	}
	public abstract class IndicLigaturizer : ILanguageProcessor
	{
		public static int MATRA_AA = 0;

		public static int MATRA_I = 1;

		public static int MATRA_E = 2;

		public static int MATRA_AI = 3;

		public static int MATRA_HLR = 4;

		public static int MATRA_HLRR = 5;

		public static int LETTER_A = 6;

		public static int LETTER_AU = 7;

		public static int LETTER_KA = 8;

		public static int LETTER_HA = 9;

		public static int HALANTA = 10;

		protected char[] langTable;

		public virtual string Process(string s)
		{
			if (string.IsNullOrEmpty(s))
			{
				return "";
			}
			StringBuilder stringBuilder = new StringBuilder();
			foreach (char c in s)
			{
				if (IsVyanjana(c) || IsSwaraLetter(c))
				{
					stringBuilder.Append(c);
				}
				else if (IsSwaraMatra(c))
				{
					int num = stringBuilder.Length - 1;
					if (num >= 0)
					{
						if (stringBuilder[num] == langTable[HALANTA])
						{
							stringBuilder.Remove(num, 1);
						}
						stringBuilder.Append(c);
						int num2 = stringBuilder.Length - 2;
						if (c == langTable[MATRA_I] && num2 >= 0)
						{
							Swap(stringBuilder, num2, stringBuilder.Length - 1);
						}
					}
					else
					{
						stringBuilder.Append(c);
					}
				}
				else
				{
					stringBuilder.Append(c);
				}
			}
			return stringBuilder.ToString();
		}

		public virtual bool IsRTL()
		{
			return false;
		}

		protected virtual bool IsSwaraLetter(char ch)
		{
			if (ch >= langTable[LETTER_A])
			{
				return ch <= langTable[LETTER_AU];
			}
			return false;
		}

		protected virtual bool IsSwaraMatra(char ch)
		{
			if ((ch < langTable[MATRA_AA] || ch > langTable[MATRA_AI]) && ch != langTable[MATRA_HLR])
			{
				return ch == langTable[MATRA_HLRR];
			}
			return true;
		}

		protected virtual bool IsVyanjana(char ch)
		{
			if (ch >= langTable[LETTER_KA])
			{
				return ch <= langTable[LETTER_HA];
			}
			return false;
		}

		private static void Swap(StringBuilder s, int i, int j)
		{
			char value = s[i];
			s[i] = s[j];
			s[j] = value;
		}
	}
}
