			refi = null;
			this.inlineImageInfo = inlineImageInfo;
			this.colorSpaceDictionary = colorSpaceDictionary;
			this.markedContentInfos = new List<MarkedContentInfo>();
			if (markedContentInfos == null || markedContentInfos.Count <= 0)
			{
				return;
			}
			foreach (MarkedContentInfo markedContentInfo in markedContentInfos)
