	public class LineDashPattern
	{
		public class DashArrayElem
		{
			private float val;

			private bool isGap;

			public float Value
			{
				get
				{
					return val;
				}
				set
				{
					val = value;
				}
			}

			public bool IsGap
			{
				get
				{
					return isGap;
				}
				set
				{
					isGap = value;
				}
			}

			public DashArrayElem(float val, bool isGap)
			{
				this.val = val;
				this.isGap = isGap;
			}
		}

		private PdfArray dashArray;

		private float dashPhase;

		private int currentIndex;

		private int elemOrdinalNumber = 1;

		private DashArrayElem currentElem;

		public PdfArray DashArray
		{
			get
			{
				return dashArray;
			}
			set
			{
				dashArray = value;
			}
		}

		public float DashPhase
		{
			get
			{
				return dashPhase;
			}
			set
			{
				dashPhase = value;
			}
		}

		public LineDashPattern(PdfArray dashArray, float dashPhase)
		{
			this.dashArray = new PdfArray(dashArray);
			this.dashPhase = dashPhase;
			InitFirst(dashPhase);
		}

		public DashArrayElem Next()
		{
			DashArrayElem result = currentElem;
			if (dashArray.Size > 0)
			{
				currentIndex = (currentIndex + 1) % DashArray.Size;
				currentElem = new DashArrayElem(dashArray.GetAsNumber(currentIndex).FloatValue, IsEven(++elemOrdinalNumber));
			}
			return result;
		}

		public bool IsSolid()
		{
			if (dashArray.Size % 2 != 0)
			{
				return false;
			}
			float num = 0f;
			for (int i = 1; i < dashArray.Size; i += 2)
			{
				num += dashArray.GetAsNumber(i).FloatValue;
			}
			return Util.Compare(num, 0f) == 0;
		}

		public void Reset()
		{
			currentIndex = 0;
			elemOrdinalNumber = 1;
			InitFirst(dashPhase);
		}

		private void InitFirst(float phase)
		{
			if (dashArray.Size > 0)
			{
				while (phase > 0f)
				{
					phase -= dashArray.GetAsNumber(currentIndex).FloatValue;
					currentIndex = (currentIndex + 1) % DashArray.Size;
					elemOrdinalNumber++;
				}
				if (phase < 0f)
				{
					elemOrdinalNumber--;
					currentIndex--;
					currentElem = new DashArrayElem(0f - phase, IsEven(elemOrdinalNumber));
				}
				else
				{
					currentElem = new DashArrayElem(dashArray.GetAsNumber(currentIndex).FloatValue, IsEven(elemOrdinalNumber));
				}
			}
		}

		private bool IsEven(int num)
		{
			return num % 2 == 0;
		}
	}
