		public virtual RectangleJ GetBoundingRectange()
		{
			float num = GetStartPoint()[0];
			float num2 = GetStartPoint()[1];
			float num3 = GetEndPoint()[0];
			float num4 = GetEndPoint()[1];
			return new RectangleJ(Math.Min(num, num3), Math.Min(num2, num4), Math.Abs(num3 - num), Math.Abs(num4 - num2));
		}

		public virtual LineSegment TransformBy(Matrix m)
		{
			Vector vector = startPoint.Cross(m);
			Vector vector2 = endPoint.Cross(m);
			return new LineSegment(vector, vector2);
		}
	}
	public class LocationTextExtractionStrategy : ITextExtractionStrategy, IRenderListener
	{
		public interface ITextChunkLocationStrategy
		{
			ITextChunkLocation CreateLocation(TextRenderInfo renderInfo, LineSegment baseline);
		}

		public interface ITextChunkLocation : IComparable<ITextChunkLocation>
		{
			Vector StartLocation { get; }

			Vector EndLocation { get; }

			int OrientationMagnitude { get; }

			int DistPerpendicular { get; }

			float DistParallelStart { get; }

			float DistParallelEnd { get; }

			float CharSpaceWidth { get; }

			bool SameLine(ITextChunkLocation other);

			float DistanceFromEndOf(ITextChunkLocation other);

			bool IsAtWordBoundary(ITextChunkLocation previous);
		}

		public class TextChunkLocationStrategyDefaultImp : ITextChunkLocationStrategy
		{
			public ITextChunkLocation CreateLocation(TextRenderInfo renderInfo, LineSegment baseline)
			{
				return new TextChunkLocationDefaultImp(baseline.GetStartPoint(), baseline.GetEndPoint(), renderInfo.GetSingleSpaceWidth());
			}
		}

		public class TextChunkLocationDefaultImp : ITextChunkLocation, IComparable<ITextChunkLocation>
		{
			private readonly Vector orientationVector;

			private readonly Vector startLocation;

			private readonly Vector endLocation;

			private readonly int orientationMagnitude;

			private readonly int distPerpendicular;

			private readonly float distParallelStart;

			private readonly float distParallelEnd;

			private readonly float charSpaceWidth;

			public virtual Vector StartLocation => startLocation;

			public virtual Vector EndLocation => endLocation;

			public virtual int OrientationMagnitude => orientationMagnitude;

			public virtual int DistPerpendicular => distPerpendicular;

			public virtual float DistParallelStart => distParallelStart;

			public virtual float DistParallelEnd => distParallelEnd;

			public virtual float CharSpaceWidth => charSpaceWidth;

			public TextChunkLocationDefaultImp(Vector startLocation, Vector endLocation, float charSpaceWidth)
			{
				this.startLocation = startLocation;
				this.endLocation = endLocation;
				this.charSpaceWidth = charSpaceWidth;
				Vector vector = endLocation.Subtract(startLocation);
				if (vector.Length == 0f)
				{
					vector = new Vector(1f, 0f, 0f);
				}
				orientationVector = vector.Normalize();
				orientationMagnitude = (int)(Math.Atan2(orientationVector[1], orientationVector[0]) * 1000.0);
				Vector v = new Vector(0f, 0f, 1f);
				distPerpendicular = (int)startLocation.Subtract(v).Cross(orientationVector)[2];
				distParallelStart = orientationVector.Dot(startLocation);
				distParallelEnd = orientationVector.Dot(endLocation);
			}

			public virtual bool SameLine(ITextChunkLocation other)
			{
				if (OrientationMagnitude == other.OrientationMagnitude)
				{
					return DistPerpendicular == other.DistPerpendicular;
				}
				return false;
			}

			public virtual float DistanceFromEndOf(ITextChunkLocation other)
			{
				return DistParallelStart - other.DistParallelEnd;
			}

			public virtual bool IsAtWordBoundary(ITextChunkLocation previous)
			{
				float num = DistanceFromEndOf(previous);
				if (num < 0f)
				{
					num = previous.DistanceFromEndOf(this);
					if (num < 0f)
					{
						return false;
					}
				}
				return num > CharSpaceWidth / 2f;
			}

			public virtual int CompareTo(ITextChunkLocation other)
			{
				if (this == other)
				{
					return 0;
				}
				int num = CompareInts(OrientationMagnitude, other.OrientationMagnitude);
				if (num != 0)
				{
					return num;
				}
				num = CompareInts(DistPerpendicular, other.DistPerpendicular);
				if (num != 0)
				{
					return num;
				}
				return (!(DistParallelStart < other.DistParallelStart)) ? 1 : (-1);
			}
		}

		public class TextChunk : IComparable<TextChunk>
		{
			private readonly string text;

			private readonly ITextChunkLocation location;

			public virtual Vector StartLocation => Location.StartLocation;

			public virtual Vector EndLocation => Location.EndLocation;

			public virtual float CharSpaceWidth => Location.CharSpaceWidth;

			public virtual string Text => text;

			public virtual ITextChunkLocation Location => location;

			public TextChunk(string str, Vector startLocation, Vector endLocation, float charSpaceWidth)
				: this(str, new TextChunkLocationDefaultImp(startLocation, endLocation, charSpaceWidth))
			{
			}

			public TextChunk(string str, ITextChunkLocation location)
			{
				text = str;
				this.location = location;
			}

			public virtual void PrintDiagnostics()
			{
				Console.Out.WriteLine(string.Concat("Text (@", StartLocation, " -> ", EndLocation, "): ", Text));
				Console.Out.WriteLine("orientationMagnitude: " + Location.OrientationMagnitude);
				Console.Out.WriteLine("distPerpendicular: " + Location.DistPerpendicular);
				Console.Out.WriteLine("distParallel: " + Location.DistParallelStart);
			}

			public virtual float DistanceFromEndOf(TextChunk other)
			{
				return Location.DistanceFromEndOf(other.Location);
			}

			public virtual int CompareTo(TextChunk other)
			{
				return Location.CompareTo(other.Location);
			}

			public virtual bool SameLine(TextChunk lastChunk)
			{
				return Location.SameLine(lastChunk.Location);
			}
		}

		public interface ITextChunkFilter
		{
			bool Accept(TextChunk textChunk);
		}

		public static bool DUMP_STATE;

		private List<TextChunk> locationalResult = new List<TextChunk>();

		private readonly ITextChunkLocationStrategy tclStrat;

		public LocationTextExtractionStrategy()
			: this(new TextChunkLocationStrategyDefaultImp())
		{
		}

		public LocationTextExtractionStrategy(ITextChunkLocationStrategy strat)
		{
			tclStrat = strat;
		}

		public virtual void BeginTextBlock()
		{
		}

		public virtual void EndTextBlock()
		{
		}

		private bool StartsWithSpace(string str)
		{
			if (str.Length == 0)
			{
				return false;
			}
			return str[0] == ' ';
		}

		private bool EndsWithSpace(string str)
		{
			if (str.Length == 0)
			{
				return false;
			}
			return str[str.Length - 1] == ' ';
		}

		private List<TextChunk> filterTextChunks(List<TextChunk> textChunks, ITextChunkFilter filter)
		{
			if (filter == null)
			{
				return textChunks;
			}
			List<TextChunk> list = new List<TextChunk>();
			foreach (TextChunk textChunk in textChunks)
			{
				if (filter.Accept(textChunk))
				{
					list.Add(textChunk);
				}
			}
			return list;
		}

		protected virtual bool IsChunkAtWordBoundary(TextChunk chunk, TextChunk previousChunk)
		{
			return chunk.Location.IsAtWordBoundary(previousChunk.Location);
		}

		public virtual string GetResultantText(ITextChunkFilter chunkFilter)
		{
			if (DUMP_STATE)
			{
				DumpState();
			}
			List<TextChunk> list = filterTextChunks(locationalResult, chunkFilter);
			list.Sort();
			StringBuilder stringBuilder = new StringBuilder();
			TextChunk textChunk = null;
			foreach (TextChunk item in list)
			{
				if (textChunk == null)
				{
					stringBuilder.Append(item.Text);
				}
				else if (item.SameLine(textChunk))
				{
					if (IsChunkAtWordBoundary(item, textChunk) && !StartsWithSpace(item.Text) && !EndsWithSpace(textChunk.Text))
					{
						stringBuilder.Append(' ');
					}
					stringBuilder.Append(item.Text);
				}
				else
				{
					stringBuilder.Append('\n');
					stringBuilder.Append(item.Text);
				}
				textChunk = item;
			}
			return stringBuilder.ToString();
		}

		public virtual string GetResultantText()
		{
			return GetResultantText(null);
		}

		private void DumpState()
		{
			foreach (TextChunk item in locationalResult)
			{
				item.PrintDiagnostics();
				Console.Out.WriteLine();
			}
		}

		public virtual void RenderText(TextRenderInfo renderInfo)
		{
			LineSegment lineSegment = renderInfo.GetBaseline();
			if (renderInfo.GetRise() != 0f)
			{
				Matrix m = new Matrix(0f, 0f - renderInfo.GetRise());
				lineSegment = lineSegment.TransformBy(m);
			}
			TextChunk item = new TextChunk(renderInfo.GetText(), tclStrat.CreateLocation(renderInfo, lineSegment));
			locationalResult.Add(item);
		}

		private static int CompareInts(int int1, int int2)
		{
			if (int1 != int2)
			{
				if (int1 >= int2)
				{
					return 1;
				}
				return -1;
			}
			return 0;
		}

		public virtual void RenderImage(ImageRenderInfo renderInfo)
		{
		}
	}
