	public class Matrix
	{
		public const int I11 = 0;

		public const int I12 = 1;

		public const int I13 = 2;

		public const int I21 = 3;

		public const int I22 = 4;

		public const int I23 = 5;

		public const int I31 = 6;

		public const int I32 = 7;

		public const int I33 = 8;

		private readonly float[] vals = new float[9];

		public float this[int index] => vals[index];

		public Matrix()
		{
			vals[0] = 1f;
			vals[1] = 0f;
			vals[2] = 0f;
			vals[3] = 0f;
			vals[4] = 1f;
			vals[5] = 0f;
			vals[6] = 0f;
			vals[7] = 0f;
			vals[8] = 1f;
		}

		public Matrix(float tx, float ty)
			: this()
		{
			vals[6] = tx;
			vals[7] = ty;
		}

		public Matrix(float a, float b, float c, float d, float e, float f)
		{
			vals[0] = a;
			vals[1] = b;
			vals[2] = 0f;
			vals[3] = c;
			vals[4] = d;
			vals[5] = 0f;
			vals[6] = e;
			vals[7] = f;
			vals[8] = 1f;
		}

		public virtual Matrix Multiply(Matrix by)
		{
			Matrix matrix = new Matrix();
			float[] array = vals;
			float[] array2 = by.vals;
			float[] array3 = matrix.vals;
			array3[0] = array[0] * array2[0] + array[1] * array2[3] + array[2] * array2[6];
			array3[1] = array[0] * array2[1] + array[1] * array2[4] + array[2] * array2[7];
			array3[2] = array[0] * array2[2] + array[1] * array2[5] + array[2] * array2[8];
			array3[3] = array[3] * array2[0] + array[4] * array2[3] + array[5] * array2[6];
			array3[4] = array[3] * array2[1] + array[4] * array2[4] + array[5] * array2[7];
			array3[5] = array[3] * array2[2] + array[4] * array2[5] + array[5] * array2[8];
			array3[6] = array[6] * array2[0] + array[7] * array2[3] + array[8] * array2[6];
			array3[7] = array[6] * array2[1] + array[7] * array2[4] + array[8] * array2[7];
			array3[8] = array[6] * array2[2] + array[7] * array2[5] + array[8] * array2[8];
			return matrix;
		}

		public virtual Matrix Subtract(Matrix arg)
		{
			Matrix matrix = new Matrix();
			float[] array = vals;
			float[] array2 = arg.vals;
			float[] array3 = matrix.vals;
			array3[0] = array[0] - array2[0];
			array3[1] = array[1] - array2[1];
			array3[2] = array[2] - array2[2];
			array3[3] = array[3] - array2[3];
			array3[4] = array[4] - array2[4];
			array3[5] = array[5] - array2[5];
			array3[6] = array[6] - array2[6];
			array3[7] = array[7] - array2[7];
			array3[8] = array[8] - array2[8];
			return matrix;
		}

		public virtual float GetDeterminant()
		{
			return vals[0] * vals[4] * vals[8] + vals[1] * vals[5] * vals[6] + vals[2] * vals[3] * vals[7] - vals[0] * vals[5] * vals[7] - vals[1] * vals[3] * vals[8] - vals[2] * vals[4] * vals[6];
		}

		public override bool Equals(object obj)
		{
			if (!(obj is Matrix))
			{
				return false;
			}
			Matrix matrix = (Matrix)obj;
			for (int i = 0; i < vals.Length; i++)
			{
				if (vals[i] != matrix.vals[i])
				{
					return false;
				}
			}
			return true;
		}

		public override int GetHashCode()
		{
			int num = 1;
			for (int i = 0; i < vals.Length; i++)
			{
				num = 31 * num + vals[i].GetHashCode();
			}
			return num;
		}

		public override string ToString()
		{
			return vals[0] + "\t" + vals[1] + "\t" + vals[2] + "\n" + vals[3] + "\t" + vals[4] + "\t" + vals[2] + "\n" + vals[6] + "\t" + vals[7] + "\t" + vals[8];
		}
	}
	public class MultiFilteredRenderListener : IRenderListener
	{
		private List<IRenderListener> delegates;

		private List<RenderFilter[]> filters;

		public MultiFilteredRenderListener()
		{
			delegates = new List<IRenderListener>();
			filters = new List<RenderFilter[]>();
		}

		public virtual E AttachRenderListener<E>(E deleg, params RenderFilter[] filterSet) where E : IRenderListener
		{
			delegates.Add(deleg);
			filters.Add(filterSet);
			return deleg;
		}

		public virtual void BeginTextBlock()
		{
			foreach (IRenderListener @delegate in delegates)
			{
				@delegate.BeginTextBlock();
			}
		}

		public virtual void RenderText(TextRenderInfo renderInfo)
		{
			for (int i = 0; i < delegates.Count; i++)
			{
				bool flag = true;
				RenderFilter[] array = filters[i];
				foreach (RenderFilter renderFilter in array)
				{
					if (!renderFilter.AllowText(renderInfo))
					{
						flag = false;
						break;
					}
				}
				if (flag)
				{
					delegates[i].RenderText(renderInfo);
				}
			}
		}

		public virtual void EndTextBlock()
		{
			foreach (IRenderListener @delegate in delegates)
			{
				@delegate.EndTextBlock();
			}
		}

		public virtual void RenderImage(ImageRenderInfo renderInfo)
		{
			for (int i = 0; i < delegates.Count; i++)
			{
				bool flag = true;
				RenderFilter[] array = filters[i];
				foreach (RenderFilter renderFilter in array)
				{
					if (!renderFilter.AllowImage(renderInfo))
					{
						flag = false;
						break;
					}
				}
				if (flag)
				{
					delegates[i].RenderImage(renderInfo);
				}
			}
		}
	}
	public class Path
	{
		private static readonly string START_PATH_ERR_MSG = "Path shall start with \"re\" or \"m\" operator";

		private IList<Subpath> subpaths = new List<Subpath>();

		private Point2D currentPoint;

		public virtual IList<Subpath> Subpaths => subpaths;

		public virtual Point2D CurrentPoint => currentPoint;

		private Subpath LastSubpath
		{
			get
			{
				if (subpaths.Count <= 0)
				{
					return null;
				}
				return subpaths[subpaths.Count - 1];
			}
		}

		public Path()
		{
		}

		public Path(IList<Subpath> subpaths)
		{
			AddSubpaths(subpaths);
		}

		public void AddSubpath(Subpath subpath)
		{
			subpaths.Add(subpath);
			currentPoint = subpath.GetLastPoint();
		}

		public void AddSubpaths(IList<Subpath> subpaths)
		{
			if (subpaths.Count > 0)
			{
				Util.AddAll(this.subpaths, subpaths);
				currentPoint = this.subpaths[subpaths.Count - 1].GetLastPoint();
			}
		}

		public virtual void MoveTo(float x, float y)
		{
			currentPoint = new Point2D.Float(x, y);
			Subpath lastSubpath = LastSubpath;
			if (lastSubpath != null && lastSubpath.IsSinglePointOpen())
			{
				lastSubpath.SetStartPoint(currentPoint);
			}
			else
			{
				subpaths.Add(new Subpath(currentPoint));
			}
		}

		public virtual void LineTo(float x, float y)
		{
			if (currentPoint == null)
			{
				throw new Exception(START_PATH_ERR_MSG);
			}
			Point2D p = new Point2D.Float(x, y);
			LastSubpath.AddSegment(new Line(currentPoint, p));
			currentPoint = p;
		}

		public virtual void CurveTo(float x1, float y1, float x2, float y2, float x3, float y3)
		{
			if (currentPoint == null)
			{
				throw new Exception(START_PATH_ERR_MSG);
			}
			Point2D point2D = new Point2D.Float(x1, y1);
			Point2D point2D2 = new Point2D.Float(x2, y2);
			Point2D point2D3 = new Point2D.Float(x3, y3);
			IList<Point2D> controlPoints = new List<Point2D>(new Point2D[4] { currentPoint, point2D, point2D2, point2D3 });
			LastSubpath.AddSegment(new BezierCurve(controlPoints));
			currentPoint = point2D3;
		}

		public virtual void CurveTo(float x2, float y2, float x3, float y3)
		{
			if (currentPoint == null)
			{
				throw new Exception(START_PATH_ERR_MSG);
			}
			CurveTo((float)currentPoint.GetX(), (float)currentPoint.GetY(), x2, y2, x3, y3);
		}

		public virtual void CurveFromTo(float x1, float y1, float x3, float y3)
		{
			if (currentPoint == null)
			{
				throw new Exception(START_PATH_ERR_MSG);
			}
			CurveTo(x1, y1, x3, y3, x3, y3);
		}

		public virtual void Rectangle(float x, float y, float w, float h)
		{
			MoveTo(x, y);
			LineTo(x + w, y);
			LineTo(x + w, y + h);
			LineTo(x, y + h);
			CloseSubpath();
		}

		public virtual void CloseSubpath()
		{
			Subpath lastSubpath = LastSubpath;
			lastSubpath.Closed = true;
			Point2D startPoint = lastSubpath.GetStartPoint();
			MoveTo((float)startPoint.GetX(), (float)startPoint.GetY());
		}

		public virtual void CloseAllSubpaths()
		{
			foreach (Subpath subpath in subpaths)
			{
				subpath.Closed = true;
			}
		}

		public virtual IList<int> ReplaceCloseWithLine()
		{
			IList<int> list = new List<int>();
			int num = 0;
			foreach (Subpath subpath in subpaths)
			{
				if (subpath.Closed)
				{
					subpath.Closed = false;
					subpath.AddSegment(new Line(subpath.GetLastPoint(), subpath.GetStartPoint()));
					list.Add(num);
				}
				num++;
			}
			return list;
		}

		public virtual bool IsEmpty()
		{
			return subpaths.Count == 0;
		}
	}
