	public class PdfContentReaderTool
	{
		public static string GetDictionaryDetail(PdfDictionary dic)
		{
			return GetDictionaryDetail(dic, 0);
		}

		public static string GetDictionaryDetail(PdfDictionary dic, int depth)
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append('(');
			IList<PdfName> list = new List<PdfName>();
			foreach (PdfName key in dic.Keys)
			{
				PdfObject directObject = dic.GetDirectObject(key);
				if (directObject.IsDictionary())
				{
					list.Add(key);
				}
				stringBuilder.Append(key);
				stringBuilder.Append('=');
				stringBuilder.Append(directObject);
				stringBuilder.Append(", ");
			}
			stringBuilder.Length -= 2;
			stringBuilder.Append(')');
			foreach (PdfName item in list)
			{
				stringBuilder.Append('\n');
				for (int i = 0; i < depth + 1; i++)
				{
					stringBuilder.Append('\t');
				}
				stringBuilder.Append("Subdictionary ");
				stringBuilder.Append(item);
				stringBuilder.Append(" = ");
				stringBuilder.Append(GetDictionaryDetail(dic.GetAsDict(item), depth + 1));
			}
			return stringBuilder.ToString();
		}

		public static string GetXObjectDetail(PdfDictionary resourceDic)
		{
			StringBuilder stringBuilder = new StringBuilder();
			PdfDictionary asDict = resourceDic.GetAsDict(PdfName.XOBJECT);
			if (asDict == null)
			{
				return "No XObjects";
			}
			foreach (PdfName key in asDict.Keys)
			{
				PdfStream asStream = asDict.GetAsStream(key);
				stringBuilder.Append(string.Concat("------ ", key, " - subtype = ", asStream.Get(PdfName.SUBTYPE), " = ", asStream.GetAsNumber(PdfName.LENGTH), " bytes ------\n"));
				if (!asStream.Get(PdfName.SUBTYPE).Equals(PdfName.IMAGE))
				{
					byte[] contentBytesFromContentObject = ContentByteUtils.GetContentBytesFromContentObject(asStream);
					byte[] array = contentBytesFromContentObject;
					foreach (byte value in array)
					{
						stringBuilder.Append((char)value);
					}
					stringBuilder.Append(string.Concat("------ ", key, " - subtype = ", asStream.Get(PdfName.SUBTYPE), "End of Content------\n"));
				}
			}
			return stringBuilder.ToString();
		}

		public static void ListContentStreamForPage(PdfReader reader, int pageNum, TextWriter outp)
		{
			outp.WriteLine("==============Page " + pageNum + "====================");
			outp.WriteLine("- - - - - Dictionary - - - - - -");
			PdfDictionary pageN = reader.GetPageN(pageNum);
			outp.WriteLine(GetDictionaryDetail(pageN));
			outp.WriteLine("- - - - - XObject Summary - - - - - -");
			outp.WriteLine(GetXObjectDetail(pageN.GetAsDict(PdfName.RESOURCES)));
			outp.WriteLine("- - - - - Content Stream - - - - - -");
			RandomAccessFileOrArray safeFile = reader.SafeFile;
			byte[] pageContent = reader.GetPageContent(pageNum, safeFile);
			safeFile.Close();
			outp.Flush();
			byte[] array = pageContent;
			foreach (byte value in array)
			{
				outp.Write((char)value);
			}
			outp.Flush();
			outp.WriteLine("- - - - - Text Extraction - - - - - -");
			string textFromPage = PdfTextExtractor.GetTextFromPage(reader, pageNum, new LocationTextExtractionStrategy());
			if (textFromPage.Length != 0)
			{
				outp.WriteLine(textFromPage);
			}
			else
			{
				outp.WriteLine("No text found on page " + pageNum);
			}
			outp.WriteLine();
		}

		public static void ListContentStream(string pdfFile, TextWriter outp)
		{
			PdfReader pdfReader = new PdfReader(pdfFile);
			int numberOfPages = pdfReader.NumberOfPages;
			for (int i = 1; i <= numberOfPages; i++)
			{
				ListContentStreamForPage(pdfReader, i, outp);
			}
		}

		public static void ListContentStream(string pdfFile, int pageNum, TextWriter outp)
		{
			PdfReader reader = new PdfReader(pdfFile);
			ListContentStreamForPage(reader, pageNum, outp);
		}

		public static void Main(string[] args)
		{
			try
			{
				if (args.Length < 1 || args.Length > 3)
				{
					Console.Out.WriteLine("Usage:  PdfContentReaderTool <pdf file> [<output file>|stdout] [<page num>]");
					return;
				}
				TextWriter textWriter = Console.Out;
				if (args.Length >= 2 && !Util.EqualsIgnoreCase(args[1], "stdout"))
				{
					Console.Out.WriteLine("Writing PDF content to " + args[1]);
					textWriter = new StreamWriter(args[1]);
				}
				int num = -1;
				if (args.Length >= 3)
				{
					num = int.Parse(args[2]);
				}
				if (num == -1)
				{
					ListContentStream(args[0], textWriter);
				}
				else
				{
					ListContentStream(args[0], num, textWriter);
				}
				textWriter.Flush();
				if (args.Length >= 2)
				{
					textWriter.Close();
					Console.Out.WriteLine("Finished writing content to " + args[1]);
				}
			}
			catch (Exception ex)
			{
				Console.Out.WriteLine(ex.ToString());
			}
		}
	}
	public class PdfContentStreamProcessor
	{
		private class ResourceDictionary : PdfDictionary
		{
			private IList<PdfDictionary> resourcesStack = new List<PdfDictionary>();

			public virtual void Push(PdfDictionary resources)
			{
				resourcesStack.Add(resources);
			}

			public virtual void Pop()
			{
				resourcesStack.RemoveAt(resourcesStack.Count - 1);
			}

			public override PdfObject GetDirectObject(PdfName key)
			{
				for (int num = resourcesStack.Count - 1; num >= 0; num--)
				{
					PdfDictionary pdfDictionary = resourcesStack[num];
					if (pdfDictionary != null)
					{
						PdfObject directObject = pdfDictionary.GetDirectObject(key);
						if (directObject != null)
						{
							return directObject;
						}
					}
				}
				return base.GetDirectObject(key);
			}
		}

