			public virtual void HandleXObject(PdfContentStreamProcessor processor, PdfStream xobjectStream, PdfIndirectReference refi, ICollection markedContentInfoStack)
			{
			}
		}

		public const string DEFAULTOPERATOR = "DefaultOperator";

		private IDictionary<string, IContentOperator> operators;

		private ResourceDictionary resources;

		private Stack<GraphicsState> gsStack = new Stack<GraphicsState>();

		private Matrix textMatrix;

		private Matrix textLineMatrix;

		private IRenderListener renderListener;

		private IDictionary<PdfName, IXObjectDoHandler> xobjectDoHandlers;

		private IDictionary<int, WeakReference> cachedFonts = new Dictionary<int, WeakReference>();

		private Stack<MarkedContentInfo> markedContentStack = new Stack<MarkedContentInfo>();

		public virtual ICollection<string> RegisteredOperatorStrings => new List<string>(operators.Keys);

		public virtual IRenderListener RenderListener => renderListener;

		public PdfContentStreamProcessor(IRenderListener renderListener)
		{
			this.renderListener = renderListener;
			operators = new Dictionary<string, IContentOperator>();
			PopulateOperators();
			xobjectDoHandlers = new Dictionary<PdfName, IXObjectDoHandler>();
			PopulateXObjectDoHandlers();
			Reset();
		}

		private void PopulateXObjectDoHandlers()
		{
			RegisterXObjectDoHandler(PdfName.DEFAULT, new IgnoreXObjectDoHandler());
			RegisterXObjectDoHandler(PdfName.FORM, new FormXObjectDoHandler());
			RegisterXObjectDoHandler(PdfName.IMAGE, new ImageXObjectDoHandler());
		}

		public virtual IXObjectDoHandler RegisterXObjectDoHandler(PdfName xobjectSubType, IXObjectDoHandler handler)
		{
			xobjectDoHandlers.TryGetValue(xobjectSubType, out var value);
			xobjectDoHandlers[xobjectSubType] = handler;
			return value;
		}

		private CMapAwareDocumentFont GetFont(PRIndirectReference ind)
		{
			cachedFonts.TryGetValue(ind.Number, out var value);
			CMapAwareDocumentFont cMapAwareDocumentFont;
			if (value == null || value.Target == null)
			{
				cMapAwareDocumentFont = new CMapAwareDocumentFont(ind);
				cachedFonts[ind.Number] = new WeakReference(cMapAwareDocumentFont, trackResurrection: true);
			}
			else
			{
				cMapAwareDocumentFont = value.Target as CMapAwareDocumentFont;
			}
			return cMapAwareDocumentFont;
		}

		private CMapAwareDocumentFont GetFont(PdfDictionary fontResource)
		{
			return new CMapAwareDocumentFont(fontResource);
		}

		private void PopulateOperators()
		{
			RegisterContentOperator("DefaultOperator", new IgnoreOperatorContentOperator());
			RegisterContentOperator("q", new PushGraphicsState());
			RegisterContentOperator("Q", new PopGraphicsState());
			RegisterContentOperator("g", new SetGrayFill());
			RegisterContentOperator("G", new SetGrayStroke());
			RegisterContentOperator("rg", new SetRGBFill());
			RegisterContentOperator("RG", new SetRGBStroke());
			RegisterContentOperator("k", new SetCMYKFill());
			RegisterContentOperator("K", new SetCMYKStroke());
			RegisterContentOperator("cs", new SetColorSpaceFill());
			RegisterContentOperator("CS", new SetColorSpaceStroke());
			RegisterContentOperator("sc", new SetColorFill());
			RegisterContentOperator("SC", new SetColorStroke());
			RegisterContentOperator("scn", new SetColorFill());
			RegisterContentOperator("SCN", new SetColorStroke());
			RegisterContentOperator("cm", new ModifyCurrentTransformationMatrix());
			RegisterContentOperator("gs", new ProcessGraphicsStateResource());
			SetTextCharacterSpacing setTextCharacterSpacing = new SetTextCharacterSpacing();
			RegisterContentOperator("Tc", setTextCharacterSpacing);
			SetTextWordSpacing setTextWordSpacing = new SetTextWordSpacing();
			RegisterContentOperator("Tw", setTextWordSpacing);
			RegisterContentOperator("Tz", new SetTextHorizontalScaling());
			SetTextLeading setTextLeading = new SetTextLeading();
			RegisterContentOperator("TL", setTextLeading);
			RegisterContentOperator("Tf", new SetTextFont());
			RegisterContentOperator("Tr", new SetTextRenderMode());
			RegisterContentOperator("Ts", new SetTextRise());
			RegisterContentOperator("BT", new BeginTextC());
			RegisterContentOperator("ET", new EndTextC());
			RegisterContentOperator("BMC", new BeginMarkedContentC());
			RegisterContentOperator("BDC", new BeginMarkedContentDictionary());
			RegisterContentOperator("EMC", new EndMarkedContentC());
			TextMoveStartNextLine textMoveStartNextLine = new TextMoveStartNextLine();
			RegisterContentOperator("Td", textMoveStartNextLine);
			RegisterContentOperator("TD", new TextMoveStartNextLineWithLeading(textMoveStartNextLine, setTextLeading));
			RegisterContentOperator("Tm", new TextSetTextMatrix());
			TextMoveNextLine textMoveNextLine = new TextMoveNextLine(textMoveStartNextLine);
			RegisterContentOperator("T*", textMoveNextLine);
			ShowText showText = new ShowText();
			RegisterContentOperator("Tj", showText);
			MoveNextLineAndShowText moveNextLineAndShowText = new MoveNextLineAndShowText(textMoveNextLine, showText);
			RegisterContentOperator("'", moveNextLineAndShowText);
			RegisterContentOperator("\"", new MoveNextLineAndShowTextWithSpacing(setTextWordSpacing, setTextCharacterSpacing, moveNextLineAndShowText));
			RegisterContentOperator("TJ", new ShowTextArray());
			RegisterContentOperator("Do", new Do());
			RegisterContentOperator("w", new SetLineWidth());
			RegisterContentOperator("J", new SetLineCap());
			RegisterContentOperator("j", new SetLineJoin());
			RegisterContentOperator("M", new SetMiterLimit());
			RegisterContentOperator("d", new SetLineDashPattern());
			if (renderListener is IExtRenderListener)
			{
				int operation = 3;
				RegisterContentOperator("m", new MoveTo());
				RegisterContentOperator("l", new LineTo());
				RegisterContentOperator("c", new Curve());
				RegisterContentOperator("v", new CurveFirstPointDuplicated());
				RegisterContentOperator("y", new CurveFourhPointDuplicated());
				RegisterContentOperator("h", new CloseSubpath());
				RegisterContentOperator("re", new Rectangle());
				RegisterContentOperator("S", new PaintPathOp(1, -1, close: false));
				RegisterContentOperator("s", new PaintPathOp(1, -1, close: true));
				RegisterContentOperator("f", new PaintPathOp(2, 1, close: false));
				RegisterContentOperator("F", new PaintPathOp(2, 1, close: false));
				RegisterContentOperator("f*", new PaintPathOp(2, 2, close: false));
				RegisterContentOperator("B", new PaintPathOp(operation, 1, close: false));
				RegisterContentOperator("B*", new PaintPathOp(operation, 2, close: false));
				RegisterContentOperator("b", new PaintPathOp(operation, 1, close: true));
				RegisterContentOperator("b*", new PaintPathOp(operation, 2, close: true));
				RegisterContentOperator("n", new PaintPathOp(0, -1, close: false));
				RegisterContentOperator("W", new ClipPathOp(1));
				RegisterContentOperator("W*", new ClipPathOp(2));
			}
		}

		public virtual IContentOperator RegisterContentOperator(string operatorString, IContentOperator oper)
		{
			IContentOperator result = null;
			if (operators.ContainsKey(operatorString))
			{
				result = operators[operatorString];
			}
			operators[operatorString] = oper;
			return result;
		}

		public virtual void Reset()
		{
			gsStack.Clear();
			gsStack.Push(new GraphicsState());
			textMatrix = null;
			textLineMatrix = null;
			resources = new ResourceDictionary();
		}

		public GraphicsState Gs()
		{
			return gsStack.Peek();
		}

		private void InvokeOperator(PdfLiteral oper, List<PdfObject> operands)
		{
			operators.TryGetValue(oper.ToString(), out var value);
			if (value == null)
			{
				value = operators["DefaultOperator"];
			}
			value.Invoke(this, oper, operands);
		}

		private void BeginMarkedContent(PdfName tag, PdfDictionary dict)
		{
			markedContentStack.Push(new MarkedContentInfo(tag, dict));
		}

		private void EndMarkedContent()
		{
			markedContentStack.Pop();
		}

		private void BeginText()
		{
			renderListener.BeginTextBlock();
		}

		private void EndText()
		{
			renderListener.EndTextBlock();
		}

		private void DisplayPdfString(PdfString str)
		{
			TextRenderInfo textRenderInfo = new TextRenderInfo(str, Gs(), textMatrix, markedContentStack);
			renderListener.RenderText(textRenderInfo);
			textMatrix = new Matrix(textRenderInfo.GetUnscaledWidth(), 0f).Multiply(textMatrix);
		}

		private void DisplayXObject(PdfName xobjectName)
		{
			PdfDictionary asDict = resources.GetAsDict(PdfName.XOBJECT);
			PdfObject pdfObjectRelease = PdfReader.GetPdfObjectRelease(asDict.Get(xobjectName));
			PdfStream pdfStream = (PdfStream)pdfObjectRelease;
			PdfName asName = pdfStream.GetAsName(PdfName.SUBTYPE);
			if (pdfObjectRelease.IsStream())
			{
				xobjectDoHandlers.TryGetValue(asName, out var value);
				if (value == null)
				{
					value = xobjectDoHandlers[PdfName.DEFAULT];
				}
				value.HandleXObject(this, pdfStream, asDict.GetAsIndirectObject(xobjectName), markedContentStack);
				return;
			}
			throw new InvalidOperationException(MessageLocalization.GetComposedMessage("XObject.1.is.not.a.stream", xobjectName));
		}

		private void PaintPath(int operation, int rule, bool close)
		{
			if (close)
			{
				ModifyPath(6, null);
			}
			PathPaintingRenderInfo renderInfo = new PathPaintingRenderInfo(operation, rule, Gs());
			((IExtRenderListener)renderListener).RenderPath(renderInfo);
		}

		private void ModifyPath(int operation, IList<float> segmentData)
		{
			PathConstructionRenderInfo renderInfo = new PathConstructionRenderInfo(operation, segmentData, Gs().GetCtm());
			((IExtRenderListener)renderListener).ModifyPath(renderInfo);
		}

		private void ClipPath(int rule)
		{
			((IExtRenderListener)renderListener).ClipPath(rule);
		}

		private void ApplyTextAdjust(float tj)
		{
			float tx = (0f - tj) / 1000f * Gs().fontSize * Gs().horizontalScaling;
			textMatrix = new Matrix(tx, 0f).Multiply(textMatrix);
		}

		public virtual void ProcessContent(byte[] contentBytes, PdfDictionary resources)
		{
			this.resources.Push(resources);
			PRTokeniser tokeniser = new PRTokeniser(new RandomAccessFileOrArray(new RandomAccessSourceFactory().CreateSource(contentBytes)));
			PdfContentParser pdfContentParser = new PdfContentParser(tokeniser);
			List<PdfObject> list = new List<PdfObject>();
			while (pdfContentParser.Parse(list).Count > 0)
			{
				PdfLiteral pdfLiteral = (PdfLiteral)list[list.Count - 1];
				if ("BI".Equals(pdfLiteral.ToString()))
				{
					PdfDictionary colorSpaceDic = resources?.GetAsDict(PdfName.COLORSPACE);
					HandleInlineImage(InlineImageUtils.ParseInlineImage(pdfContentParser, colorSpaceDic), colorSpaceDic);
				}
				else
				{
					InvokeOperator(pdfLiteral, list);
				}
			}
			this.resources.Pop();
		}

		protected virtual void HandleInlineImage(InlineImageInfo info, PdfDictionary colorSpaceDic)
		{
			ImageRenderInfo renderInfo = ImageRenderInfo.CreateForEmbeddedImage(Gs(), info, colorSpaceDic, markedContentStack);
			renderListener.RenderImage(renderInfo);
		}

		private static BaseColor GetColor(PdfName colorSpace, List<PdfObject> operands)
		{
			if (PdfName.DEVICEGRAY.Equals(colorSpace))
			{
				return GetColor(1, operands);
			}
			if (PdfName.DEVICERGB.Equals(colorSpace))
			{
				return GetColor(3, operands);
			}
			if (PdfName.DEVICECMYK.Equals(colorSpace))
			{
				return GetColor(4, operands);
			}
			return null;
		}

		private static BaseColor GetColor(int nOperands, List<PdfObject> operands)
		{
			float[] array = new float[nOperands];
			for (int i = 0; i < nOperands; i++)
			{
				array[i] = ((PdfNumber)operands[i]).FloatValue;
				if (array[i] > 1f)
				{
					array[i] = 1f;
				}
				else if (array[i] < 0f)
				{
					array[i] = 0f;
				}
			}
			return nOperands switch
			{
				1 => new GrayColor(array[0]), 
				3 => new BaseColor(array[0], array[1], array[2]), 
				4 => new CMYKColor(array[0], array[1], array[2], array[3]), 
				_ => null, 
			};
		}
	}
	public interface IXObjectDoHandler
	{
		void HandleXObject(PdfContentStreamProcessor processor, PdfStream stream, PdfIndirectReference refi);

		void HandleXObject(PdfContentStreamProcessor processor, PdfStream stream, PdfIndirectReference refi, ICollection markedContentInfoStack);
	}
	public class PdfImageObject
	{
		public sealed class ImageBytesType
		{
			public static readonly ImageBytesType PNG = new ImageBytesType("png");

			public static readonly ImageBytesType JPG = new ImageBytesType("jpg");

			public static readonly ImageBytesType JP2 = new ImageBytesType("jp2");

			public static readonly ImageBytesType CCITT = new ImageBytesType("tif");

			public static readonly ImageBytesType JBIG2 = new ImageBytesType("jbig2");

			private string fileExtension;

			public string FileExtension => fileExtension;

			private ImageBytesType(string fileExtension)
			{
				this.fileExtension = fileExtension;
			}
		}

		private sealed class TrackingFilter : FilterHandlers.IFilterHandler
		{
			public PdfName lastFilterName;

			public byte[] Decode(byte[] b, PdfName filterName, PdfObject decodeParams, PdfDictionary streamDictionary)
			{
				lastFilterName = filterName;
				return b;
			}
		}

		private PdfDictionary dictionary;

		private byte[] imageBytes;

		private PdfDictionary colorSpaceDic;

		private int pngColorType = -1;

		private int pngBitDepth;

		private int width;

		private int height;

		private int bpc;

		private byte[] palette;

		private byte[] icc;

		private int stride;

		private ImageBytesType streamContentType;

		public virtual string GetFileType()
		{
			return streamContentType.FileExtension;
		}

		public virtual ImageBytesType GetImageBytesType()
		{
			return streamContentType;
		}

		public PdfImageObject(PRStream stream)
			: this(stream, PdfReader.GetStreamBytesRaw(stream), null)
		{
		}

		public PdfImageObject(PRStream stream, PdfDictionary colorSpaceDic)
			: this(stream, PdfReader.GetStreamBytesRaw(stream), colorSpaceDic)
		{
		}

		protected internal PdfImageObject(PdfDictionary dictionary, byte[] samples, PdfDictionary colorSpaceDic)
		{
			this.dictionary = dictionary;
			this.colorSpaceDic = colorSpaceDic;
			TrackingFilter trackingFilter = new TrackingFilter();
			imageBytes = PdfReader.DecodeBytes(samples, dictionary, new Dictionary<PdfName, FilterHandlers.IFilterHandler>(FilterHandlers.GetDefaultFilterHandlers())
			{
				[PdfName.JBIG2DECODE] = trackingFilter,
				[PdfName.DCTDECODE] = trackingFilter,
				[PdfName.JPXDECODE] = trackingFilter
			});
			if (trackingFilter.lastFilterName != null)
			{
				if (PdfName.JBIG2DECODE.Equals(trackingFilter.lastFilterName))
				{
					streamContentType = ImageBytesType.JBIG2;
				}
				else if (PdfName.DCTDECODE.Equals(trackingFilter.lastFilterName))
				{
					streamContentType = ImageBytesType.JPG;
				}
				else if (PdfName.JPXDECODE.Equals(trackingFilter.lastFilterName))
				{
					streamContentType = ImageBytesType.JP2;
				}
			}
			else
			{
				DecodeImageBytes();
			}
		}

		public virtual PdfObject Get(PdfName key)
		{
			return dictionary.Get(key);
		}

		public virtual PdfDictionary GetDictionary()
		{
			return dictionary;
		}

		private void FindColorspace(PdfObject colorspace, bool allowIndexed)
		{
			if (colorspace == null && bpc == 1)
			{
				stride = (width * bpc + 7) / 8;
				pngColorType = 0;
			}
			else if (PdfName.DEVICEGRAY.Equals(colorspace))
			{
				stride = (width * bpc + 7) / 8;
				pngColorType = 0;
			}
			else if (PdfName.DEVICERGB.Equals(colorspace))
			{
				if (bpc == 8 || bpc == 16)
				{
					stride = (width * bpc * 3 + 7) / 8;
					pngColorType = 2;
				}
			}
			else
			{
				if (!(colorspace is PdfArray))
				{
					return;
				}
				PdfArray pdfArray = (PdfArray)colorspace;
				PdfObject directObject = pdfArray.GetDirectObject(0);
				if (PdfName.CALGRAY.Equals(directObject))
				{
					stride = (width * bpc + 7) / 8;
					pngColorType = 0;
				}
				else if (PdfName.CALRGB.Equals(directObject))
				{
					if (bpc == 8 || bpc == 16)
					{
						stride = (width * bpc * 3 + 7) / 8;
						pngColorType = 2;
					}
				}
				else if (PdfName.ICCBASED.Equals(directObject))
				{
					PRStream pRStream = (PRStream)pdfArray.GetDirectObject(1);
					switch (pRStream.GetAsNumber(PdfName.N).IntValue)
					{
					case 1:
						stride = (width * bpc + 7) / 8;
						pngColorType = 0;
						icc = PdfReader.GetStreamBytes(pRStream);
						break;
					case 3:
						stride = (width * bpc * 3 + 7) / 8;
						pngColorType = 2;
						icc = PdfReader.GetStreamBytes(pRStream);
						break;
					}
				}
				else
				{
					if (!allowIndexed || !PdfName.INDEXED.Equals(directObject))
					{
						return;
					}
					FindColorspace(pdfArray.GetDirectObject(1), allowIndexed: false);
					if (pngColorType == 2)
					{
						PdfObject directObject2 = pdfArray.GetDirectObject(3);
						if (directObject2 is PdfString)
						{
							palette = ((PdfString)directObject2).GetBytes();
						}
						else if (directObject2 is PRStream)
						{
							palette = PdfReader.GetStreamBytes((PRStream)directObject2);
						}
						stride = (width * bpc + 7) / 8;
						pngColorType = 3;
					}
				}
			}
		}

		private void DecodeImageBytes()
		{
			if (streamContentType != null)
			{
				throw new ArgumentException(MessageLocalization.GetComposedMessage("Decoding.can't.happen.on.this.type.of.stream.(.1.)", streamContentType.FileExtension));
			}
			pngColorType = -1;
			PdfArray asArray = dictionary.GetAsArray(PdfName.DECODE);
			width = dictionary.GetAsNumber(PdfName.WIDTH).IntValue;
			height = dictionary.GetAsNumber(PdfName.HEIGHT).IntValue;
			bpc = dictionary.GetAsNumber(PdfName.BITSPERCOMPONENT).IntValue;
			pngBitDepth = bpc;
			PdfObject pdfObject = dictionary.GetDirectObject(PdfName.COLORSPACE);
			if (pdfObject is PdfName && colorSpaceDic != null)
			{
				PdfObject directObject = colorSpaceDic.GetDirectObject((PdfName)pdfObject);
				if (directObject != null)
				{
					pdfObject = directObject;
				}
			}
			palette = null;
			icc = null;
			stride = 0;
			FindColorspace(pdfObject, allowIndexed: true);
			MemoryStream memoryStream = new MemoryStream();
			if (pngColorType < 0)
			{
				if (bpc != 8)
				{
					throw new UnsupportedPdfException(MessageLocalization.GetComposedMessage("the.color.depth.1.is.not.supported", bpc));
				}
				if (!PdfName.DEVICECMYK.Equals(pdfObject))
				{
					if (!(pdfObject is PdfArray))
					{
						throw new UnsupportedPdfException(MessageLocalization.GetComposedMessage("the.color.space.1.is.not.supported", pdfObject));
					}
					PdfArray pdfArray = (PdfArray)pdfObject;
					PdfObject directObject2 = pdfArray.GetDirectObject(0);
					if (!PdfName.ICCBASED.Equals(directObject2))
					{
						throw new UnsupportedPdfException(MessageLocalization.GetComposedMessage("the.color.space.1.is.not.supported", pdfObject));
					}
					PRStream pRStream = (PRStream)pdfArray.GetDirectObject(1);
					int intValue = pRStream.GetAsNumber(PdfName.N).IntValue;
					if (intValue != 4)
					{
						throw new UnsupportedPdfException(MessageLocalization.GetComposedMessage("N.value.1.is.not.supported", intValue));
					}
					icc = PdfReader.GetStreamBytes(pRStream);
				}
				stride = 4 * width;
				TiffWriter tiffWriter = new TiffWriter();
				tiffWriter.AddField(new TiffWriter.FieldShort(277, 4));
				tiffWriter.AddField(new TiffWriter.FieldShort(258, new int[4] { 8, 8, 8, 8 }));
				tiffWriter.AddField(new TiffWriter.FieldShort(262, 5));
				tiffWriter.AddField(new TiffWriter.FieldLong(256, width));
				tiffWriter.AddField(new TiffWriter.FieldLong(257, height));
				tiffWriter.AddField(new TiffWriter.FieldShort(259, 5));
				tiffWriter.AddField(new TiffWriter.FieldShort(317, 2));
				tiffWriter.AddField(new TiffWriter.FieldLong(278, height));
				tiffWriter.AddField(new TiffWriter.FieldRational(282, new int[2] { 300, 1 }));
				tiffWriter.AddField(new TiffWriter.FieldRational(283, new int[2] { 300, 1 }));
				tiffWriter.AddField(new TiffWriter.FieldShort(296, 2));
				tiffWriter.AddField(new TiffWriter.FieldAscii(305, Version.GetInstance().GetVersion));
				MemoryStream memoryStream2 = new MemoryStream();
				TiffWriter.CompressLZW(memoryStream2, 2, imageBytes, height, 4, stride);
				byte[] array = memoryStream2.ToArray();
				tiffWriter.AddField(new TiffWriter.FieldImage(array));
				tiffWriter.AddField(new TiffWriter.FieldLong(279, array.Length));
				if (icc != null)
				{
					tiffWriter.AddField(new TiffWriter.FieldUndefined(34675, icc));
				}
				tiffWriter.WriteFile(memoryStream);
				streamContentType = ImageBytesType.CCITT;
				imageBytes = memoryStream.ToArray();
				return;
			}
			PngWriter pngWriter = new PngWriter(memoryStream);
			if (asArray != null && pngBitDepth == 1 && asArray.GetAsNumber(0).IntValue == 1 && asArray.GetAsNumber(1).IntValue == 0)
			{
				int num = imageBytes.Length;
				for (int i = 0; i < num; i++)
				{
					imageBytes[i] ^= byte.MaxValue;
				}
			}
			pngWriter.WriteHeader(width, height, pngBitDepth, pngColorType);
			if (icc != null)
			{
				pngWriter.WriteIccProfile(icc);
			}
			if (palette != null)
			{
				pngWriter.WritePalette(palette);
			}
			pngWriter.WriteData(imageBytes, stride);
			pngWriter.WriteEnd();
			streamContentType = ImageBytesType.PNG;
			imageBytes = memoryStream.ToArray();
		}

		public virtual byte[] GetImageAsBytes()
		{
			return imageBytes;
		}

		public Image GetDrawingImage()
		{
			byte[] imageAsBytes = GetImageAsBytes();
			if (imageAsBytes == null)
			{
				return null;
			}
			return Image.FromStream((Stream)new MemoryStream(imageAsBytes));
		}
	}
}
namespace iTextSharp.text.pdf
{
	public sealed class FilterHandlers
	{
		public interface IFilterHandler
		{
			byte[] Decode(byte[] b, PdfName filterName, PdfObject decodeParams, PdfDictionary streamDictionary);
		}

		private class Filter_FLATEDECODE : IFilterHandler
		{
			public byte[] Decode(byte[] b, PdfName filterName, PdfObject decodeParams, PdfDictionary streamDictionary)
			{
				MemoryStream outS = EnableMemoryLimitsAwareHandler(streamDictionary);
				b = PdfReader.FlateDecode(b, outS);
				b = PdfReader.DecodePredictor(b, decodeParams);
				return b;
			}
		}

		private class Filter_ASCIIHEXDECODE : IFilterHandler
		{
			public byte[] Decode(byte[] b, PdfName filterName, PdfObject decodeParams, PdfDictionary streamDictionary)
			{
				MemoryStream outp = EnableMemoryLimitsAwareHandler(streamDictionary);
				b = PdfReader.ASCIIHexDecode(b, outp);
				return b;
			}
		}

		private class Filter_ASCII85DECODE : IFilterHandler
		{
			public byte[] Decode(byte[] b, PdfName filterName, PdfObject decodeParams, PdfDictionary streamDictionary)
			{
				MemoryStream outp = EnableMemoryLimitsAwareHandler(streamDictionary);
