	public class PdfReaderContentParser
	{
		private PdfReader reader;

		public PdfReaderContentParser(PdfReader reader)
		{
			this.reader = reader;
		}

		public virtual E ProcessContent<E>(int pageNumber, E renderListener, IDictionary<string, IContentOperator> additionalContentOperators) where E : IRenderListener
		{
			PdfDictionary pageN = reader.GetPageN(pageNumber);
			PdfDictionary asDict = pageN.GetAsDict(PdfName.RESOURCES);
			PdfContentStreamProcessor pdfContentStreamProcessor = new PdfContentStreamProcessor(renderListener);
			foreach (KeyValuePair<string, IContentOperator> additionalContentOperator in additionalContentOperators)
			{
				pdfContentStreamProcessor.RegisterContentOperator(additionalContentOperator.Key, additionalContentOperator.Value);
			}
			pdfContentStreamProcessor.ProcessContent(ContentByteUtils.GetContentBytesForPage(reader, pageNumber), asDict);
			return renderListener;
		}

		public virtual E ProcessContent<E>(int pageNumber, E renderListener) where E : IRenderListener
		{
			return ProcessContent(pageNumber, renderListener, new Dictionary<string, IContentOperator>());
		}
	}
