	public class RegionTextRenderFilter : RenderFilter
	{
		private RectangleJ filterRect;

		public RegionTextRenderFilter(RectangleJ filterRect)
		{
			this.filterRect = filterRect;
		}

		public RegionTextRenderFilter(Rectangle filterRect)
		{
			this.filterRect = new RectangleJ(filterRect);
		}

		public override bool AllowText(TextRenderInfo renderInfo)
		{
			LineSegment baseline = renderInfo.GetBaseline();
			Vector startPoint = baseline.GetStartPoint();
			Vector endPoint = baseline.GetEndPoint();
			float num = startPoint[0];
			float num2 = startPoint[1];
			float num3 = endPoint[0];
			float num4 = endPoint[1];
			return filterRect.IntersectsLine(num, num2, num3, num4);
		}
	}
	public class SimpleTextExtractionStrategy : ITextExtractionStrategy, IRenderListener
	{
		private Vector lastStart;

		private Vector lastEnd;

		private StringBuilder result = new StringBuilder();

		public virtual void BeginTextBlock()
		{
		}

		public virtual void EndTextBlock()
		{
		}

		public virtual string GetResultantText()
		{
			return result.ToString();
		}

		protected void AppendTextChunk(string text)
		{
			result.Append(text);
		}

		protected void AppendTextChunk(char text)
		{
			result.Append(text);
		}

		public virtual void RenderText(TextRenderInfo renderInfo)
		{
			bool flag = result.Length == 0;
			bool flag2 = false;
			LineSegment baseline = renderInfo.GetBaseline();
			Vector startPoint = baseline.GetStartPoint();
			Vector endPoint = baseline.GetEndPoint();
			if (!flag)
			{
				Vector v = startPoint;
				Vector vector = lastStart;
				Vector vector2 = lastEnd;
				float num = vector2.Subtract(vector).Cross(vector.Subtract(v)).LengthSquared / vector2.Subtract(vector).LengthSquared;
				float num2 = 1f;
				if (num > num2)
				{
					flag2 = true;
				}
			}
			if (flag2)
			{
				AppendTextChunk('\n');
			}
			else if (!flag && result[result.Length - 1] != ' ' && renderInfo.GetText().Length > 0 && renderInfo.GetText()[0] != ' ')
			{
				float length = lastEnd.Subtract(startPoint).Length;
				if (length > renderInfo.GetSingleSpaceWidth() / 2f)
				{
					AppendTextChunk(' ');
				}
			}
			AppendTextChunk(renderInfo.GetText());
			lastStart = startPoint;
			lastEnd = endPoint;
		}

		public virtual void RenderImage(ImageRenderInfo renderInfo)
		{
		}
	}
	public class Subpath
	{
		private Point2D startPoint;

		private IList<IShape> segments = new List<IShape>();

		private bool closed;

		public virtual bool Closed
		{
			get
			{
				return closed;
			}
			set
			{
				closed = value;
			}
		}

		public Subpath()
		{
		}

		public Subpath(Subpath subpath)
		{
			startPoint = subpath.startPoint;
			Util.AddAll(segments, subpath.GetSegments());
			closed = subpath.closed;
		}

		public Subpath(Point2D startPoint)
			: this((float)startPoint.GetX(), (float)startPoint.GetY())
		{
		}

		public Subpath(float startPointX, float startPointY)
		{
			startPoint = new Point2D.Float(startPointX, startPointY);
		}

		public virtual void SetStartPoint(Point2D startPoint)
		{
			SetStartPoint((float)startPoint.GetX(), (float)startPoint.GetY());
		}

		public virtual void SetStartPoint(float x, float y)
		{
			startPoint = new Point2D.Float(x, y);
		}

		public virtual Point2D GetStartPoint()
		{
			return startPoint;
		}

		public Point2D GetLastPoint()
		{
			Point2D result = startPoint;
			if (segments.Count > 0 && !closed)
			{
				IShape shape = segments[segments.Count - 1];
				result = shape.GetBasePoints()[shape.GetBasePoints().Count - 1];
			}
			return result;
		}

		public virtual void AddSegment(IShape segment)
		{
			if (!closed)
			{
				if (IsSinglePointOpen())
				{
					startPoint = segment.GetBasePoints()[0];
				}
				segments.Add(segment);
			}
		}

		public virtual IList<IShape> GetSegments()
		{
			return segments;
		}

		public virtual bool IsEmpty()
		{
			return startPoint == null;
		}

		public virtual bool IsSinglePointOpen()
		{
			if (segments.Count == 0)
			{
				return !closed;
			}
			return false;
		}

		public virtual bool IsSinglePointClosed()
		{
			if (segments.Count == 0)
			{
				return closed;
			}
			return false;
		}

		public virtual bool IsDegenerate()
		{
			if (segments.Count > 0 && closed)
			{
				return false;
			}
			foreach (IShape segment in segments)
			{
				HashSet2<Point2D> hashSet = new HashSet2<Point2D>(segment.GetBasePoints());
				if (hashSet.Count != 1)
				{
					return false;
				}
			}
			if (segments.Count <= 0)
			{
				return closed;
			}
			return true;
		}

		public virtual IList<Point2D> GetPiecewiseLinearApproximation()
		{
			IList<Point2D> list = new List<Point2D>();
			if (segments.Count == 0)
			{
				return list;
			}
			if (segments[0] is BezierCurve)
			{
				Util.AddAll(list, ((BezierCurve)segments[0]).GetPiecewiseLinearApproximation());
			}
			else
			{
				Util.AddAll(list, segments[0].GetBasePoints());
			}
			for (int i = 1; i < segments.Count; i++)
			{
				if (segments[i] is BezierCurve)
				{
					Util.AddAll(list, ((BezierCurve)segments[i]).GetPiecewiseLinearApproximation(), 1);
				}
				else
				{
					Util.AddAll(list, segments[i].GetBasePoints(), 1);
				}
			}
			return list;
		}
	}
	public class TaggedPdfReaderTool
	{
		protected internal PdfReader reader;

		protected internal StreamWriter outp;

		public virtual void ConvertToXml(PdfReader reader, Stream os, Encoding encoding)
		{
			this.reader = reader;
			outp = new StreamWriter(os, encoding);
			PdfDictionary catalog = reader.Catalog;
			PdfDictionary asDict = catalog.GetAsDict(PdfName.STRUCTTREEROOT);
			if (asDict == null)
			{
				throw new IOException(MessageLocalization.GetComposedMessage("no.structtreeroot.found"));
			}
			InspectChild(asDict.GetDirectObject(PdfName.K));
			outp.Flush();
			outp.Close();
		}

		public virtual void ConvertToXml(PdfReader reader, Stream os)
		{
			ConvertToXml(reader, os, Encoding.UTF8);
		}

		public virtual void InspectChild(PdfObject k)
		{
			if (k != null)
			{
				if (k is PdfArray)
				{
					InspectChildArray((PdfArray)k);
				}
				else if (k is PdfDictionary)
				{
					InspectChildDictionary((PdfDictionary)k);
				}
			}
		}

		public virtual void InspectChildArray(PdfArray k)
		{
			if (k != null)
			{
				for (int i = 0; i < k.Size; i++)
				{
					InspectChild(k.GetDirectObject(i));
				}
			}
		}

		public virtual void InspectChildDictionary(PdfDictionary k)
		{
			InspectChildDictionary(k, inspectAttributes: false);
		}

		public virtual void InspectChildDictionary(PdfDictionary k, bool inspectAttributes)
		{
			if (k == null)
			{
				return;
			}
			PdfName asName = k.GetAsName(PdfName.S);
			if (asName != null)
			{
				string tag = PdfName.DecodeName(asName.ToString());
				string value = FixTagName(tag);
				outp.Write("<");
				outp.Write(value);
				if (inspectAttributes)
				{
					PdfDictionary asDict = k.GetAsDict(PdfName.A);
					if (asDict != null)
					{
						Dictionary<PdfName, PdfObject>.KeyCollection keys = asDict.Keys;
						foreach (PdfName item in keys)
						{
							outp.Write(' ');
							PdfObject obj = asDict.Get(item);
							obj = PdfReader.GetPdfObject(obj);
							outp.Write(XmlName(item));
							outp.Write("=\"");
							outp.Write(obj.ToString());
							outp.Write("\"");
						}
					}
				}
				outp.Write(">");
				PdfObject pdfObject = k.Get(PdfName.ALT);
				if (pdfObject != null && pdfObject.ToString() != null)
				{
					outp.Write("<alt><![CDATA[");
					outp.Write(Regex.Replace(pdfObject.ToString(), "[\\000]*", ""));
					outp.Write("]]></alt>");
				}
				PdfDictionary asDict2 = k.GetAsDict(PdfName.PG);
				if (asDict2 != null)
				{
					ParseTag(tag, k.GetDirectObject(PdfName.K), asDict2);
				}
				InspectChild(k.GetDirectObject(PdfName.K));
				outp.Write("</");
				outp.Write(value);
				outp.WriteLine(">");
			}
			else
			{
				InspectChild(k.GetDirectObject(PdfName.K));
			}
		}

		protected virtual string XmlName(PdfName name)
		{
			string text = name.ToString();
			string text2 = text.Remove(text.IndexOf("/"), 1);
			return text2.ToLower()[0] + text2.Substring(1);
		}

		private static string FixTagName(string tag)
		{
			StringBuilder stringBuilder = new StringBuilder();
			for (int i = 0; i < tag.Length; i++)
			{
				char c = tag[i];
				bool flag = c == ':' || (c >= 'A' && c <= 'Z') || c == '_' || (c >= 'a' && c <= 'z') || (c >= 'À' && c <= 'Ö') || (c >= 'Ø' && c <= 'ö') || (c >= 'ø' && c <= '\u02ff') || (c >= 'Ͱ' && c <= 'ͽ') || (c >= 'Ϳ' && c <= '\u1fff') || (c >= '\u200c' && c <= '\u200d') || (c >= '⁰' && c <= '\u218f') || (c >= 'Ⰰ' && c <= '\u2fef') || (c >= '、' && c <= '\ud7ff') || (c >= '豈' && c <= '\ufdcf') || (c >= 'ﷰ' && c <= '\ufffd');
				bool flag2 = c == '-' || c == '.' || (c >= '0' && c <= '9') || c == '·' || (c >= '\u0300' && c <= '\u036f') || (c >= '\u203f' && c <= '\u2040') || flag;
				if (i == 0)
				{
					if (!flag)
					{
						c = '_';
					}
				}
				else if (!flag2)
				{
					c = '-';
				}
				stringBuilder.Append(c);
			}
			return stringBuilder.ToString();
		}

		public virtual void ParseTag(string tag, PdfObject obj, PdfDictionary page)
		{
			if (obj is PdfNumber)
			{
				PdfNumber pdfNumber = (PdfNumber)obj;
				RenderFilter renderFilter = new MarkedContentRenderFilter(pdfNumber.IntValue);
				ITextExtractionStrategy deleg = new SimpleTextExtractionStrategy();
				FilteredTextRenderListener filteredTextRenderListener = new FilteredTextRenderListener(deleg, renderFilter);
				PdfContentStreamProcessor pdfContentStreamProcessor = new PdfContentStreamProcessor(filteredTextRenderListener);
				pdfContentStreamProcessor.ProcessContent(PdfReader.GetPageContent(page), page.GetAsDict(PdfName.RESOURCES));
				outp.Write(XMLUtil.EscapeXML(filteredTextRenderListener.GetResultantText(), onlyASCII: true));
			}
			else if (obj is PdfArray)
			{
				PdfArray pdfArray = (PdfArray)obj;
				int size = pdfArray.Size;
				for (int i = 0; i < size; i++)
				{
					ParseTag(tag, pdfArray[i], page);
					if (i < size - 1)
					{
						outp.WriteLine();
					}
				}
			}
			else if (obj is PdfDictionary)
			{
				PdfDictionary pdfDictionary = (PdfDictionary)obj;
				ParseTag(tag, pdfDictionary.GetDirectObject(PdfName.MCID), pdfDictionary.GetAsDict(PdfName.PG));
			}
		}
	}
