	public class TextRenderInfo
	{
		private readonly PdfString @string;

		private string text;

		private Matrix textToUserSpaceTransformMatrix;

		private GraphicsState gs;

		private float? unscaledWidth = null;

		private double[] fontMatrix;

		private static Encoding utf_16BeEncoding;

		private ICollection<MarkedContentInfo> markedContentInfos;

		public virtual PdfString PdfString => @string;

		private Encoding Utf_16BeEncoding
		{
			get
			{
				if (utf_16BeEncoding != null)
				{
					return utf_16BeEncoding;
				}
				return utf_16BeEncoding = Encoding.GetEncoding("UTF-16BE");
			}
		}

		internal TextRenderInfo(PdfString @string, GraphicsState gs, Matrix textMatrix, ICollection markedContentInfo)
		{
			this.@string = @string;
			textToUserSpaceTransformMatrix = textMatrix.Multiply(gs.ctm);
			this.gs = gs;
			markedContentInfos = new List<MarkedContentInfo>();
			if (markedContentInfo.Count > 0)
			{
				foreach (MarkedContentInfo item in markedContentInfo)
				{
					markedContentInfos.Add(item);
				}
			}
			fontMatrix = gs.font.GetFontMatrix();
		}

		private TextRenderInfo(TextRenderInfo parent, PdfString @string, float horizontalOffset)
		{
			this.@string = @string;
			textToUserSpaceTransformMatrix = new Matrix(horizontalOffset, 0f).Multiply(parent.textToUserSpaceTransformMatrix);
			gs = parent.gs;
			markedContentInfos = parent.markedContentInfos;
			fontMatrix = gs.font.GetFontMatrix();
		}

		public virtual string GetText()
		{
			if (text == null)
			{
				text = Decode(@string);
			}
			return text;
		}

		public virtual bool HasMcid(int mcid)
		{
			return HasMcid(mcid, checkTheTopmostLevelOnly: false);
		}

		public virtual bool HasMcid(int mcid, bool checkTheTopmostLevelOnly)
		{
			if (checkTheTopmostLevelOnly)
			{
				if (markedContentInfos is IList)
				{
					int? mcid2 = GetMcid();
					if (!mcid2.HasValue)
					{
						return false;
					}
					return mcid2 == mcid;
				}
			}
			else
			{
				foreach (MarkedContentInfo markedContentInfo in markedContentInfos)
				{
					if (markedContentInfo.HasMcid() && markedContentInfo.GetMcid() == mcid)
					{
						return true;
					}
				}
			}
			return false;
		}

		public virtual int? GetMcid()
		{
			if (markedContentInfos is IList)
			{
				IList<MarkedContentInfo> list = (IList<MarkedContentInfo>)markedContentInfos;
				MarkedContentInfo markedContentInfo = ((list.Count > 0) ? list[0] : null);
				if (markedContentInfo == null || !markedContentInfo.HasMcid())
				{
					return null;
				}
				return markedContentInfo.GetMcid();
			}
			return null;
		}

		internal float GetUnscaledWidth()
		{
			if (!unscaledWidth.HasValue)
			{
				unscaledWidth = GetPdfStringWidth(@string, singleCharString: false);
			}
			return unscaledWidth.Value;
		}

		public virtual LineSegment GetBaseline()
		{
			return GetUnscaledBaselineWithOffset(0f + gs.rise).TransformBy(textToUserSpaceTransformMatrix);
		}

		public virtual LineSegment GetUnscaledBaseline()
		{
			return GetUnscaledBaselineWithOffset(0f + gs.rise);
		}

		public virtual LineSegment GetAscentLine()
		{
			float fontDescriptor = gs.GetFont().GetFontDescriptor(1, gs.GetFontSize());
			return GetUnscaledBaselineWithOffset(fontDescriptor + gs.rise).TransformBy(textToUserSpaceTransformMatrix);
		}

		public virtual LineSegment GetDescentLine()
		{
			float fontDescriptor = gs.GetFont().GetFontDescriptor(3, gs.GetFontSize());
			return GetUnscaledBaselineWithOffset(fontDescriptor + gs.rise).TransformBy(textToUserSpaceTransformMatrix);
		}

		private LineSegment GetUnscaledBaselineWithOffset(float yOffset)
		{
			string text = @string.ToUnicodeString();
			float x = GetUnscaledWidth() - (gs.characterSpacing + ((text.Length > 0 && text[text.Length - 1] == ' ') ? gs.wordSpacing : 0f)) * gs.horizontalScaling;
			return new LineSegment(new Vector(0f, yOffset, 1f), new Vector(x, yOffset, 1f));
		}

		public virtual DocumentFont GetFont()
		{
			return gs.GetFont();
		}

		public virtual float GetRise()
		{
			if (gs.rise == 0f)
			{
				return 0f;
			}
			return ConvertHeightFromTextSpaceToUserSpace(gs.rise);
		}

		private float ConvertWidthFromTextSpaceToUserSpace(float width)
		{
			LineSegment lineSegment = new LineSegment(new Vector(0f, 0f, 1f), new Vector(width, 0f, 1f));
			LineSegment lineSegment2 = lineSegment.TransformBy(textToUserSpaceTransformMatrix);
			return lineSegment2.GetLength();
		}

		private float ConvertHeightFromTextSpaceToUserSpace(float height)
		{
			LineSegment lineSegment = new LineSegment(new Vector(0f, 0f, 1f), new Vector(0f, height, 1f));
			LineSegment lineSegment2 = lineSegment.TransformBy(textToUserSpaceTransformMatrix);
			return lineSegment2.GetLength();
		}

		public virtual float GetSingleSpaceWidth()
		{
			return ConvertWidthFromTextSpaceToUserSpace(GetUnscaledFontSpaceWidth());
		}

		public virtual int GetTextRenderMode()
		{
			return gs.renderMode;
		}

		public virtual BaseColor GetFillColor()
		{
			return gs.fillColor;
		}

		public virtual BaseColor GetStrokeColor()
		{
			return gs.strokeColor;
		}

		private float GetUnscaledFontSpaceWidth()
		{
			char @char = ' ';
			if (gs.font.GetWidth(@char) == 0)
			{
				@char = '\u00a0';
			}
			return GetStringWidth(@char.ToString());
		}

		private float GetStringWidth(string @string)
		{
			float num = 0f;
			foreach (char c in @string)
			{
				float num2 = (float)gs.font.GetWidth(c) / 1000f;
				float num3 = ((c == ' ') ? gs.wordSpacing : 0f);
				num += (num2 * gs.fontSize + gs.characterSpacing + num3) * gs.horizontalScaling;
			}
			return num;
		}

		private float GetPdfStringWidth(PdfString @string, bool singleCharString)
		{
			if (singleCharString)
			{
				float[] widthAndWordSpacing = GetWidthAndWordSpacing(@string, singleCharString);
				return (widthAndWordSpacing[0] * gs.fontSize + gs.characterSpacing + widthAndWordSpacing[1]) * gs.horizontalScaling;
			}
			float num = 0f;
			PdfString[] array = SplitString(@string);
			foreach (PdfString pdfString in array)
			{
				num += GetPdfStringWidth(pdfString, singleCharString: true);
			}
			return num;
		}

		public virtual IList<TextRenderInfo> GetCharacterRenderInfos()
		{
			IList<TextRenderInfo> list = new List<TextRenderInfo>(@string.Length);
			PdfString[] array = SplitString(@string);
			float num = 0f;
			for (int i = 0; i < array.Length; i++)
			{
				float[] widthAndWordSpacing = GetWidthAndWordSpacing(array[i], singleCharString: true);
				TextRenderInfo item = new TextRenderInfo(this, array[i], num);
				list.Add(item);
				num += (widthAndWordSpacing[0] * gs.fontSize + gs.characterSpacing + widthAndWordSpacing[1]) * gs.horizontalScaling;
			}
			foreach (TextRenderInfo item2 in list)
			{
				item2.GetUnscaledWidth();
			}
			return list;
		}

		private float[] GetWidthAndWordSpacing(PdfString @string, bool singleCharString)
		{
			if (!singleCharString)
			{
				throw new InvalidOperationException();
			}
			float[] array = new float[2];
			string text = DecodeSingleCharacter(@string);
			array[0] = (float)((double)gs.font.GetWidth(GetCharCode(text)) * fontMatrix[0]);
			array[1] = (text.Equals(" ") ? gs.wordSpacing : 0f);
			return array;
		}

		private string Decode(PdfString @in)
		{
			byte[] bytes = @in.GetBytes();
			return gs.font.Decode(bytes, 0, bytes.Length);
		}

		private string DecodeSingleCharacter(PdfString @in)
		{
			byte[] bytes = @in.GetBytes();
			return gs.font.DecodeSingleCharacter(bytes, 0, bytes.Length);
		}

		private int GetCharCode(string @string)
		{
			try
			{
				byte[] bytes = Utf_16BeEncoding.GetBytes(@string);
				int num = 0;
				for (int i = 0; i < bytes.Length - 1; i++)
				{
					num += bytes[i] & 0xFF;
					num <<= 8;
				}
				if (bytes.Length > 0)
				{
					num += bytes[^1] & 0xFF;
				}
				return num;
			}
			catch (ArgumentException)
			{
			}
			return 0;
		}

		private PdfString[] SplitString(PdfString @string)
		{
			List<PdfString> list = new List<PdfString>();
			string text = @string.ToString();
			for (int i = 0; i < text.Length; i++)
			{
				PdfString pdfString = new PdfString(text.Substring(i, 1), @string.Encoding);
				string text2 = DecodeSingleCharacter(pdfString);
				if (text2.Length == 0 && i < text.Length - 1)
				{
					pdfString = new PdfString(text.Substring(i, 2), @string.Encoding);
					i++;
				}
				list.Add(pdfString);
			}
			return list.ToArray();
		}
	}
	public class Vector
	{
		public const int I1 = 0;

		public const int I2 = 1;

		public const int I3 = 2;

		private float[] vals = new float[3];

		public float this[int index] => vals[index];

		public virtual float Length => (float)Math.Sqrt(LengthSquared);

		public virtual float LengthSquared => vals[0] * vals[0] + vals[1] * vals[1] + vals[2] * vals[2];

		public Vector(float x, float y, float z)
		{
			vals[0] = x;
			vals[1] = y;
			vals[2] = z;
		}

		public virtual Vector Cross(Matrix by)
		{
			float x = vals[0] * by[0] + vals[1] * by[3] + vals[2] * by[6];
			float y = vals[0] * by[1] + vals[1] * by[4] + vals[2] * by[7];
			float z = vals[0] * by[2] + vals[1] * by[5] + vals[2] * by[8];
			return new Vector(x, y, z);
		}

		public virtual Vector Subtract(Vector v)
		{
			float x = vals[0] - v.vals[0];
			float y = vals[1] - v.vals[1];
			float z = vals[2] - v.vals[2];
			return new Vector(x, y, z);
		}

		public virtual Vector Cross(Vector with)
		{
			float x = vals[1] * with.vals[2] - vals[2] * with.vals[1];
			float y = vals[2] * with.vals[0] - vals[0] * with.vals[2];
			float z = vals[0] * with.vals[1] - vals[1] * with.vals[0];
			return new Vector(x, y, z);
		}

		public virtual Vector Normalize()
		{
			float length = Length;
			float x = vals[0] / length;
			float y = vals[1] / length;
			float z = vals[2] / length;
			return new Vector(x, y, z);
		}

		public virtual Vector Multiply(float by)
		{
			float x = vals[0] * by;
			float y = vals[1] * by;
			float z = vals[2] * by;
			return new Vector(x, y, z);
		}

		public virtual float Dot(Vector with)
		{
			return vals[0] * with.vals[0] + vals[1] * with.vals[1] + vals[2] * with.vals[2];
		}

		public override string ToString()
		{
			return vals[0] + "," + vals[1] + "," + vals[2];
		}

		public override bool Equals(object obj)
		{
			if (this == obj)
			{
				return true;
			}
			if (obj == null)
			{
				return false;
			}
			if (!(obj is Vector))
			{
				return false;
			}
			Vector vector = (Vector)obj;
			if (vector.vals[0] == vals[0] && vector.vals[1] == vals[1])
			{
				return vector.vals[2] == vals[2];
			}
			return false;
		}

		public override int GetHashCode()
		{
			int num = 1;
			for (int i = 0; i < vals.Length; i++)
			{
				num = 31 * num + vals[i].GetHashCode();
			}
			return num;
		}
	}
}
