			PdfAppearance pdfAppearance3 = PdfAppearance.CreateAppearance(writer, urx - llx, ury - lly);
			pdfAppearance3.DrawTextField(0f, 0f, urx - llx, ury - lly);
			field.SetAppearance(PdfAnnotation.APPEARANCE_NORMAL, "Off", pdfAppearance3);
		}

		public virtual PdfFormField GetRadioGroup(string name, string defaultValue, bool noToggleToOff)
		{
			PdfFormField pdfFormField = PdfFormField.CreateRadioButton(writer, noToggleToOff);
			pdfFormField.FieldName = name;
			pdfFormField.ValueAsName = defaultValue;
			return pdfFormField;
		}

		public virtual void AddRadioGroup(PdfFormField radiogroup)
		{
			AddFormField(radiogroup);
		}

		public virtual PdfFormField AddRadioButton(PdfFormField radiogroup, string value, float llx, float lly, float urx, float ury)
		{
			PdfFormField pdfFormField = PdfFormField.CreateEmpty(writer);
			pdfFormField.SetWidget(new Rectangle(llx, lly, urx, ury), PdfAnnotation.HIGHLIGHT_TOGGLE);
			string text = ((PdfName)radiogroup.Get(PdfName.V)).ToString().Substring(1);
			if (text.Equals(value))
			{
				pdfFormField.AppearanceState = value;
			}
			else
			{
				pdfFormField.AppearanceState = "Off";
			}
			DrawRadioAppearences(pdfFormField, value, llx, lly, urx, ury);
			radiogroup.AddKid(pdfFormField);
			return pdfFormField;
		}

		public virtual void DrawRadioAppearences(PdfFormField field, string value, float llx, float lly, float urx, float ury)
		{
			PdfAppearance pdfAppearance = PdfAppearance.CreateAppearance(writer, urx - llx, ury - lly);
			pdfAppearance.DrawRadioField(0f, 0f, urx - llx, ury - lly, on: true);
			field.SetAppearance(PdfAnnotation.APPEARANCE_NORMAL, value, pdfAppearance);
			PdfAppearance pdfAppearance2 = PdfAppearance.CreateAppearance(writer, urx - llx, ury - lly);
			pdfAppearance2.DrawRadioField(0f, 0f, urx - llx, ury - lly, on: false);
			field.SetAppearance(PdfAnnotation.APPEARANCE_NORMAL, "Off", pdfAppearance2);
		}

		public virtual PdfFormField AddSelectList(string name, string[] options, string defaultValue, BaseFont font, float fontSize, float llx, float lly, float urx, float ury)
		{
			PdfFormField pdfFormField = PdfFormField.CreateList(writer, options, 0);
			SetChoiceParams(pdfFormField, name, defaultValue, llx, lly, urx, ury);
			StringBuilder stringBuilder = new StringBuilder();
			foreach (string value in options)
			{
				stringBuilder.Append(value).Append('\n');
			}
			DrawMultiLineOfText(pdfFormField, stringBuilder.ToString(), font, fontSize, llx, lly, urx, ury);
			AddFormField(pdfFormField);
			return pdfFormField;
		}

		public virtual PdfFormField AddSelectList(string name, string[,] options, string defaultValue, BaseFont font, float fontSize, float llx, float lly, float urx, float ury)
		{
			PdfFormField pdfFormField = PdfFormField.CreateList(writer, options, 0);
			SetChoiceParams(pdfFormField, name, defaultValue, llx, lly, urx, ury);
			StringBuilder stringBuilder = new StringBuilder();
			for (int i = 0; i < options.GetLength(0); i++)
			{
				stringBuilder.Append(options[i, 1]).Append('\n');
			}
			DrawMultiLineOfText(pdfFormField, stringBuilder.ToString(), font, fontSize, llx, lly, urx, ury);
			AddFormField(pdfFormField);
			return pdfFormField;
		}

		public virtual PdfFormField AddComboBox(string name, string[] options, string defaultValue, bool editable, BaseFont font, float fontSize, float llx, float lly, float urx, float ury)
		{
			PdfFormField pdfFormField = PdfFormField.CreateCombo(writer, editable, options, 0);
			SetChoiceParams(pdfFormField, name, defaultValue, llx, lly, urx, ury);
			if (defaultValue == null)
			{
				defaultValue = options[0];
			}
			DrawSingleLineOfText(pdfFormField, defaultValue, font, fontSize, llx, lly, urx, ury);
			AddFormField(pdfFormField);
			return pdfFormField;
		}

		public virtual PdfFormField AddComboBox(string name, string[,] options, string defaultValue, bool editable, BaseFont font, float fontSize, float llx, float lly, float urx, float ury)
		{
			PdfFormField pdfFormField = PdfFormField.CreateCombo(writer, editable, options, 0);
			SetChoiceParams(pdfFormField, name, defaultValue, llx, lly, urx, ury);
			string text = null;
			for (int i = 0; i < options.GetLength(0); i++)
			{
				if (options[i, 0].Equals(defaultValue))
				{
					text = options[i, 1];
					break;
				}
			}
			if (text == null)
			{
				text = options[0, 1];
			}
			DrawSingleLineOfText(pdfFormField, text, font, fontSize, llx, lly, urx, ury);
			AddFormField(pdfFormField);
			return pdfFormField;
		}

		public virtual void SetChoiceParams(PdfFormField field, string name, string defaultValue, float llx, float lly, float urx, float ury)
		{
			field.SetWidget(new Rectangle(llx, lly, urx, ury), PdfAnnotation.HIGHLIGHT_INVERT);
			if (defaultValue != null)
			{
				field.ValueAsString = defaultValue;
				field.DefaultValueAsString = defaultValue;
			}
			field.FieldName = name;
			field.Flags = 4;
			field.SetPage();
			field.BorderStyle = new PdfBorderDictionary(2f, 0);
		}

		public virtual PdfFormField AddSignature(string name, float llx, float lly, float urx, float ury)
		{
			PdfFormField pdfFormField = PdfFormField.CreateSignature(writer);
			SetSignatureParams(pdfFormField, name, llx, lly, urx, ury);
			DrawSignatureAppearences(pdfFormField, llx, lly, urx, ury);
			AddFormField(pdfFormField);
			return pdfFormField;
		}

		public virtual void SetSignatureParams(PdfFormField field, string name, float llx, float lly, float urx, float ury)
		{
			field.SetWidget(new Rectangle(llx, lly, urx, ury), PdfAnnotation.HIGHLIGHT_INVERT);
			field.FieldName = name;
			field.Flags = 4;
			field.SetPage();
			field.MKBorderColor = BaseColor.BLACK;
			field.MKBackgroundColor = BaseColor.WHITE;
		}

		public virtual void DrawSignatureAppearences(PdfFormField field, float llx, float lly, float urx, float ury)
		{
			PdfAppearance pdfAppearance = PdfAppearance.CreateAppearance(writer, urx - llx, ury - lly);
			pdfAppearance.SetGrayFill(1f);
			pdfAppearance.Rectangle(0f, 0f, urx - llx, ury - lly);
			pdfAppearance.Fill();
			pdfAppearance.SetGrayStroke(0f);
			pdfAppearance.SetLineWidth(1f);
			pdfAppearance.Rectangle(0.5f, 0.5f, urx - llx - 0.5f, ury - lly - 0.5f);
			pdfAppearance.ClosePathStroke();
			pdfAppearance.SaveState();
			pdfAppearance.Rectangle(1f, 1f, urx - llx - 2f, ury - lly - 2f);
			pdfAppearance.Clip();
			pdfAppearance.NewPath();
			pdfAppearance.RestoreState();
			field.SetAppearance(PdfAnnotation.APPEARANCE_NORMAL, pdfAppearance);
		}

		public override void ToPdf(PdfWriter writer, Stream os)
		{
			PdfWriter.CheckPdfIsoConformance(writer, 15, this);
			base.ToPdf(writer, os);
		}
	}
	public class PdfAction : PdfDictionary
	{
		public const int FIRSTPAGE = 1;

		public const int PREVPAGE = 2;

		public const int NEXTPAGE = 3;

		public const int LASTPAGE = 4;

		public const int PRINTDIALOG = 5;

		public const int SUBMIT_EXCLUDE = 1;

		public const int SUBMIT_INCLUDE_NO_VALUE_FIELDS = 2;

		public const int SUBMIT_HTML_FORMAT = 4;

		public const int SUBMIT_HTML_GET = 8;

		public const int SUBMIT_COORDINATES = 16;

		public const int SUBMIT_XFDF = 32;

		public const int SUBMIT_INCLUDE_APPEND_SAVES = 64;

		public const int SUBMIT_INCLUDE_ANNOTATIONS = 128;

		public const int SUBMIT_PDF = 256;

		public const int SUBMIT_CANONICAL_FORMAT = 512;

		public const int SUBMIT_EXCL_NON_USER_ANNOTS = 1024;

		public const int SUBMIT_EXCL_F_KEY = 2048;

		public const int SUBMIT_EMBED_FORM = 8196;

		public const int RESET_EXCLUDE = 1;

		public PdfAction()
		{
		}

		public PdfAction(Uri url)
			: this(url.AbsoluteUri)
		{
		}

		public PdfAction(Uri url, bool isMap)
			: this(url.AbsoluteUri, isMap)
		{
		}

		public PdfAction(string url)
			: this(url, isMap: false)
		{
		}

		public PdfAction(string url, bool isMap)
		{
			Put(PdfName.S, PdfName.URI);
			Put(PdfName.URI, new PdfString(url));
			if (isMap)
			{
				Put(PdfName.ISMAP, PdfBoolean.PDFTRUE);
			}
		}

		internal PdfAction(PdfIndirectReference destination)
		{
			Put(PdfName.S, PdfName.GOTO);
			Put(PdfName.D, destination);
		}

		public PdfAction(string filename, string name)
		{
			Put(PdfName.S, PdfName.GOTOR);
			Put(PdfName.F, new PdfString(filename));
			Put(PdfName.D, new PdfString(name));
		}

		public PdfAction(string filename, int page)
		{
			Put(PdfName.S, PdfName.GOTOR);
			Put(PdfName.F, new PdfString(filename));
			Put(PdfName.D, new PdfLiteral("[" + (page - 1) + " /FitH 10000]"));
		}

		public PdfAction(int named)
		{
			Put(PdfName.S, PdfName.NAMED);
			switch (named)
			{
			case 1:
				Put(PdfName.N, PdfName.FIRSTPAGE);
				break;
			case 4:
				Put(PdfName.N, PdfName.LASTPAGE);
				break;
			case 3:
				Put(PdfName.N, PdfName.NEXTPAGE);
				break;
			case 2:
				Put(PdfName.N, PdfName.PREVPAGE);
				break;
			case 5:
				Put(PdfName.S, PdfName.JAVASCRIPT);
				Put(PdfName.JS, new PdfString("this.print(true);\r"));
				break;
			default:
				throw new ArgumentException(MessageLocalization.GetComposedMessage("invalid.named.action"));
			}
		}

		public PdfAction(string application, string parameters, string operation, string defaultDir)
		{
			Put(PdfName.S, PdfName.LAUNCH);
			if (parameters == null && operation == null && defaultDir == null)
			{
				Put(PdfName.F, new PdfString(application));
				return;
			}
			PdfDictionary pdfDictionary = new PdfDictionary();
			pdfDictionary.Put(PdfName.F, new PdfString(application));
			if (parameters != null)
			{
				pdfDictionary.Put(PdfName.P, new PdfString(parameters));
			}
			if (operation != null)
			{
				pdfDictionary.Put(PdfName.O, new PdfString(operation));
			}
			if (defaultDir != null)
			{
				pdfDictionary.Put(PdfName.D, new PdfString(defaultDir));
			}
			Put(PdfName.WIN, pdfDictionary);
		}

		public static PdfAction CreateLaunch(string application, string parameters, string operation, string defaultDir)
		{
			return new PdfAction(application, parameters, operation, defaultDir);
		}

		public static PdfAction Rendition(string file, PdfFileSpecification fs, string mimeType, PdfIndirectReference refi)
		{
			PdfAction pdfAction = new PdfAction();
			pdfAction.Put(PdfName.S, PdfName.RENDITION);
			pdfAction.Put(PdfName.R, new PdfRendition(file, fs, mimeType));
			pdfAction.Put(new PdfName("OP"), new PdfNumber(0));
			pdfAction.Put(new PdfName("AN"), refi);
			return pdfAction;
		}

		public static PdfAction JavaScript(string code, PdfWriter writer, bool unicode)
		{
			PdfAction pdfAction = new PdfAction();
			pdfAction.Put(PdfName.S, PdfName.JAVASCRIPT);
			if (unicode && code.Length < 50)
			{
				pdfAction.Put(PdfName.JS, new PdfString(code, "UnicodeBig"));
			}
			else if (!unicode && code.Length < 100)
			{
				pdfAction.Put(PdfName.JS, new PdfString(code));
			}
			else
			{
				try
				{
					byte[] array = PdfEncodings.ConvertToBytes(code, unicode ? "UnicodeBig" : "PDF");
					PdfStream pdfStream = new PdfStream(array);
					pdfStream.FlateCompress(writer.CompressionLevel);
					pdfAction.Put(PdfName.JS, writer.AddToBody(pdfStream).IndirectReference);
				}
				catch
				{
					pdfAction.Put(PdfName.JS, new PdfString(code));
				}
			}
			return pdfAction;
		}

		public static PdfAction JavaScript(string code, PdfWriter writer)
		{
			return JavaScript(code, writer, unicode: false);
		}

		internal static PdfAction CreateHide(PdfObject obj, bool hide)
		{
			PdfAction pdfAction = new PdfAction();
			pdfAction.Put(PdfName.S, PdfName.HIDE);
			pdfAction.Put(PdfName.T, obj);
			if (!hide)
			{
				pdfAction.Put(PdfName.H, PdfBoolean.PDFFALSE);
			}
			return pdfAction;
		}

		public static PdfAction CreateHide(PdfAnnotation annot, bool hide)
		{
			return CreateHide(annot.IndirectReference, hide);
		}

		public static PdfAction CreateHide(string name, bool hide)
		{
			return CreateHide(new PdfString(name), hide);
		}

		internal static PdfArray BuildArray(object[] names)
		{
			PdfArray pdfArray = new PdfArray();
			foreach (object obj in names)
			{
				if (obj is string)
				{
					pdfArray.Add(new PdfString((string)obj));
					continue;
				}
				if (obj is PdfAnnotation)
				{
					pdfArray.Add(((PdfAnnotation)obj).IndirectReference);
					continue;
				}
				throw new ArgumentException(MessageLocalization.GetComposedMessage("the.array.must.contain.string.or.pdfannotation"));
			}
			return pdfArray;
		}

		public static PdfAction CreateHide(object[] names, bool hide)
		{
			return CreateHide(BuildArray(names), hide);
		}

		public static PdfAction CreateSubmitForm(string file, object[] names, int flags)
		{
			PdfAction pdfAction = new PdfAction();
			pdfAction.Put(PdfName.S, PdfName.SUBMITFORM);
			PdfDictionary pdfDictionary = new PdfDictionary();
			pdfDictionary.Put(PdfName.F, new PdfString(file));
			pdfDictionary.Put(PdfName.FS, PdfName.URL);
			pdfAction.Put(PdfName.F, pdfDictionary);
			if (names != null)
			{
				pdfAction.Put(PdfName.FIELDS, BuildArray(names));
			}
			pdfAction.Put(PdfName.FLAGS, new PdfNumber(flags));
			return pdfAction;
		}

		public static PdfAction CreateResetForm(object[] names, int flags)
		{
			PdfAction pdfAction = new PdfAction();
			pdfAction.Put(PdfName.S, PdfName.RESETFORM);
			if (names != null)
			{
				pdfAction.Put(PdfName.FIELDS, BuildArray(names));
			}
			pdfAction.Put(PdfName.FLAGS, new PdfNumber(flags));
			return pdfAction;
		}

		public static PdfAction CreateImportData(string file)
		{
			PdfAction pdfAction = new PdfAction();
			pdfAction.Put(PdfName.S, PdfName.IMPORTDATA);
			pdfAction.Put(PdfName.F, new PdfString(file));
			return pdfAction;
		}

		public virtual void Next(PdfAction na)
		{
			PdfObject pdfObject = Get(PdfName.NEXT);
			if (pdfObject == null)
			{
				Put(PdfName.NEXT, na);
			}
			else if (pdfObject.IsDictionary())
			{
				PdfArray pdfArray = new PdfArray(pdfObject);
				pdfArray.Add(na);
				Put(PdfName.NEXT, pdfArray);
			}
			else
			{
				((PdfArray)pdfObject).Add(na);
			}
		}

		public static PdfAction GotoLocalPage(int page, PdfDestination dest, PdfWriter writer)
		{
			PdfIndirectReference pageReference = writer.GetPageReference(page);
			PdfDestination pdfDestination = new PdfDestination(dest);
			pdfDestination.AddPage(pageReference);
			PdfAction pdfAction = new PdfAction();
			pdfAction.Put(PdfName.S, PdfName.GOTO);
			pdfAction.Put(PdfName.D, pdfDestination);
			return pdfAction;
		}

		public static PdfAction GotoLocalPage(string dest, bool isName)
		{
			PdfAction pdfAction = new PdfAction();
			pdfAction.Put(PdfName.S, PdfName.GOTO);
			if (isName)
			{
				pdfAction.Put(PdfName.D, new PdfName(dest));
			}
			else
			{
				pdfAction.Put(PdfName.D, new PdfString(dest, "UnicodeBig"));
			}
			return pdfAction;
		}

		public static PdfAction GotoRemotePage(string filename, string dest, bool isName, bool newWindow)
		{
			PdfAction pdfAction = new PdfAction();
			pdfAction.Put(PdfName.F, new PdfString(filename));
			pdfAction.Put(PdfName.S, PdfName.GOTOR);
			if (isName)
			{
				pdfAction.Put(PdfName.D, new PdfName(dest));
			}
			else
			{
				pdfAction.Put(PdfName.D, new PdfString(dest, "UnicodeBig"));
			}
			if (newWindow)
			{
				pdfAction.Put(PdfName.NEWWINDOW, PdfBoolean.PDFTRUE);
			}
			return pdfAction;
		}

		public static PdfAction GotoEmbedded(string filename, PdfTargetDictionary target, string dest, bool isName, bool newWindow)
		{
			if (isName)
			{
				return GotoEmbedded(filename, target, new PdfName(dest), newWindow);
			}
			return GotoEmbedded(filename, target, new PdfString(dest, "UnicodeBig"), newWindow);
		}

		public static PdfAction GotoEmbedded(string filename, PdfTargetDictionary target, PdfObject dest, bool newWindow)
		{
			PdfAction pdfAction = new PdfAction();
			pdfAction.Put(PdfName.S, PdfName.GOTOE);
			pdfAction.Put(PdfName.T, target);
			pdfAction.Put(PdfName.D, dest);
			pdfAction.Put(PdfName.NEWWINDOW, new PdfBoolean(newWindow));
			if (filename != null)
			{
				pdfAction.Put(PdfName.F, new PdfString(filename));
			}
			return pdfAction;
		}

		public static PdfAction SetOCGstate(List<object> state, bool preserveRB)
		{
			PdfAction pdfAction = new PdfAction();
			pdfAction.Put(PdfName.S, PdfName.SETOCGSTATE);
			PdfArray pdfArray = new PdfArray();
			for (int i = 0; i < state.Count; i++)
			{
				object obj = state[i];
				if (obj == null)
				{
					continue;
				}
				if (obj is PdfIndirectReference)
				{
					pdfArray.Add((PdfIndirectReference)obj);
					continue;
				}
				if (obj is PdfLayer)
				{
					pdfArray.Add(((PdfLayer)obj).Ref);
					continue;
				}
				if (obj is PdfName)
				{
					pdfArray.Add((PdfName)obj);
					continue;
				}
				if (obj is string)
				{
					PdfName pdfName = null;
					string text = (string)obj;
					if (Util.EqualsIgnoreCase(text, "on"))
					{
						pdfName = PdfName.ON;
					}
					else if (Util.EqualsIgnoreCase(text, "off"))
					{
						pdfName = PdfName.OFF;
					}
					else
					{
						if (!Util.EqualsIgnoreCase(text, "toggle"))
						{
							throw new ArgumentException(MessageLocalization.GetComposedMessage("a.string.1.was.passed.in.state.only.on.off.and.toggle.are.allowed", text));
						}
						pdfName = PdfName.TOGGLE;
					}
					pdfArray.Add(pdfName);
					continue;
				}
				throw new ArgumentException(MessageLocalization.GetComposedMessage("invalid.type.was.passed.in.state.1", obj.GetType().ToString()));
			}
			pdfAction.Put(PdfName.STATE, pdfArray);
			if (!preserveRB)
			{
				pdfAction.Put(PdfName.PRESERVERB, PdfBoolean.PDFFALSE);
			}
			return pdfAction;
		}

		public override void ToPdf(PdfWriter writer, Stream os)
		{
			PdfWriter.CheckPdfIsoConformance(writer, 14, this);
			base.ToPdf(writer, os);
		}
	}
	public class PdfAnnotation : PdfDictionary, IAccessibleElement
	{
		public class PdfImportedLink
		{
			private float llx;

			private float lly;

			private float urx;

			private float ury;

			private Dictionary<PdfName, PdfObject> parameters;

			private PdfArray destination;

			private int newPage;

			private PdfArray rect;

			internal PdfImportedLink(PdfDictionary annotation)
			{
				parameters = new Dictionary<PdfName, PdfObject>(annotation.hashMap);
				try
				{
					if (parameters.ContainsKey(PdfName.DEST))
					{
						destination = (PdfArray)parameters[PdfName.DEST];
					}
					parameters.Remove(PdfName.DEST);
				}
				catch (Exception)
				{
					throw new ArgumentException(MessageLocalization.GetComposedMessage("you.have.to.consolidate.the.named.destinations.of.your.reader"));
				}
				if (destination != null)
				{
					destination = new PdfArray(destination);
				}
				PdfArray pdfArray = (PdfArray)parameters[PdfName.RECT];
				parameters.Remove(PdfName.RECT);
				llx = pdfArray.GetAsNumber(0).FloatValue;
				lly = pdfArray.GetAsNumber(1).FloatValue;
				urx = pdfArray.GetAsNumber(2).FloatValue;
				ury = pdfArray.GetAsNumber(3).FloatValue;
				rect = new PdfArray(pdfArray);
			}

			public virtual IDictionary<PdfName, PdfObject> GetParameters()
			{
				return new Dictionary<PdfName, PdfObject>(parameters);
			}

			public virtual PdfArray GetRect()
			{
				return new PdfArray(rect);
			}

			public virtual bool IsInternal()
			{
				return destination != null;
			}

			public virtual int GetDestinationPage()
			{
				if (!IsInternal())
				{
					return 0;
				}
				PdfIndirectReference asIndirectObject = destination.GetAsIndirectObject(0);
				PRIndirectReference pRIndirectReference = (PRIndirectReference)asIndirectObject;
				PdfReader reader = pRIndirectReference.Reader;
				for (int i = 1; i <= reader.NumberOfPages; i++)
				{
					PRIndirectReference pageOrigRef = reader.GetPageOrigRef(i);
					if (pageOrigRef.Generation == pRIndirectReference.Generation && pageOrigRef.Number == pRIndirectReference.Number)
					{
						return i;
					}
				}
				throw new ArgumentException(MessageLocalization.GetComposedMessage("page.not.found"));
			}

			public virtual void SetDestinationPage(int newPage)
			{
				if (!IsInternal())
				{
					throw new ArgumentException(MessageLocalization.GetComposedMessage("cannot.change.destination.of.external.link"));
				}
				this.newPage = newPage;
			}

			public virtual void TransformDestination(float a, float b, float c, float d, float e, float f)
			{
				if (!IsInternal())
				{
					throw new ArgumentException(MessageLocalization.GetComposedMessage("cannot.change.destination.of.external.link"));
				}
				if (destination.GetAsName(1).Equals(PdfName.XYZ))
				{
					float floatValue = destination.GetAsNumber(2).FloatValue;
					float floatValue2 = destination.GetAsNumber(3).FloatValue;
					float value = floatValue * a + floatValue2 * c + e;
					float value2 = floatValue * b + floatValue2 * d + f;
					destination.ArrayList[2] = new PdfNumber(value);
					destination.ArrayList[3] = new PdfNumber(value2);
				}
			}

			public virtual void TransformRect(float a, float b, float c, float d, float e, float f)
			{
				float num = llx * a + lly * c + e;
				float num2 = llx * b + lly * d + f;
				llx = num;
				lly = num2;
				num = urx * a + ury * c + e;
				num2 = urx * b + ury * d + f;
				urx = num;
				ury = num2;
			}

			public virtual PdfAnnotation CreateAnnotation(PdfWriter writer)
			{
				PdfAnnotation pdfAnnotation = writer.CreateAnnotation(new Rectangle(llx, lly, urx, ury), null);
				if (newPage != 0)
				{
					PdfIndirectReference pageReference = writer.GetPageReference(newPage);
					destination.Set(0, pageReference);
				}
				if (destination != null)
				{
					pdfAnnotation.Put(PdfName.DEST, destination);
				}
				foreach (PdfName key in parameters.Keys)
				{
					pdfAnnotation.hashMap[key] = parameters[key];
				}
				return pdfAnnotation;
			}

			public override string ToString()
			{
				StringBuilder stringBuilder = new StringBuilder("Imported link: location [");
				stringBuilder.Append(llx);
				stringBuilder.Append(' ');
				stringBuilder.Append(lly);
				stringBuilder.Append(' ');
				stringBuilder.Append(urx);
				stringBuilder.Append(' ');
				stringBuilder.Append(ury);
				stringBuilder.Append("] destination ");
				stringBuilder.Append(destination);
				stringBuilder.Append(" parameters ");
				stringBuilder.Append(parameters);
				return stringBuilder.ToString();
			}
		}

