		private void HelperRGB(float red, float green, float blue)
		{
			if (red < 0f)
			{
				red = 0f;
			}
			else if (red > 1f)
			{
				red = 1f;
			}
			if (green < 0f)
			{
				green = 0f;
			}
			else if (green > 1f)
			{
				green = 1f;
			}
			if (blue < 0f)
			{
				blue = 0f;
			}
			else if (blue > 1f)
			{
				blue = 1f;
			}
			content.Append(red).Append(' ').Append(green)
				.Append(' ')
				.Append(blue);
		}

