		public virtual void Circle(double x, double y, double r)
		{
			float num = 0.5523f;
			MoveTo(x + r, y);
			CurveTo(x + r, y + r * (double)num, x + r * (double)num, y + r, x, y + r);
			CurveTo(x - r * (double)num, y + r, x - r, y + r * (double)num, x - r, y);
			CurveTo(x - r, y - r * (double)num, x - r * (double)num, y - r, x, y - r);
			CurveTo(x + r * (double)num, y - r, x + r, y - r * (double)num, x + r, y);
		}

