		public static List<double[]> BezierArc(float x1, float y1, float x2, float y2, float startAng, float extent)
		{
			return BezierArc((double)x1, (double)y1, (double)x2, (double)y2, (double)startAng, (double)extent);
		}

		public static List<double[]> BezierArc(double x1, double y1, double x2, double y2, double startAng, double extent)
		{
			if (x1 > x2)
			{
				double num = x1;
				x1 = x2;
				x2 = num;
			}
			if (y2 > y1)
			{
				double num = y1;
				y1 = y2;
				y2 = num;
			}
			double num2;
			int num3;
			if (Math.Abs(extent) <= 90.0)
			{
				num2 = extent;
				num3 = 1;
			}
			else
			{
				num3 = (int)Math.Ceiling(Math.Abs(extent) / 90.0);
				num2 = extent / (double)num3;
			}
			double num4 = (x1 + x2) / 2.0;
			double num5 = (y1 + y2) / 2.0;
			double num6 = (x2 - x1) / 2.0;
			double num7 = (y2 - y1) / 2.0;
			double num8 = (float)(num2 * Math.PI / 360.0);
			double num9 = (float)Math.Abs(1.3333333333333333 * (1.0 - Math.Cos(num8)) / Math.Sin(num8));
			List<double[]> list = new List<double[]>();
			for (int i = 0; i < num3; i++)
			{
				float num10 = (float)((startAng + (double)i * num2) * Math.PI / 180.0);
				float num11 = (float)((startAng + (double)(i + 1) * num2) * Math.PI / 180.0);
				float num12 = (float)Math.Cos(num10);
				float num13 = (float)Math.Cos(num11);
				float num14 = (float)Math.Sin(num10);
				float num15 = (float)Math.Sin(num11);
				if (num2 > 0.0)
				{
					list.Add(new double[8]
					{
						num4 + num6 * (double)num12,
						num5 - num7 * (double)num14,
						num4 + num6 * ((double)num12 - num9 * (double)num14),
						num5 - num7 * ((double)num14 + num9 * (double)num12),
						num4 + num6 * ((double)num13 + num9 * (double)num15),
						num5 - num7 * ((double)num15 - num9 * (double)num13),
						num4 + num6 * (double)num13,
						num5 - num7 * (double)num15
					});
				}
				else
				{
					list.Add(new double[8]
					{
						num4 + num6 * (double)num12,
						num5 - num7 * (double)num14,
						num4 + num6 * ((double)num12 + num9 * (double)num14),
						num5 - num7 * ((double)num14 - num9 * (double)num12),
						num4 + num6 * ((double)num13 - num9 * (double)num15),
						num5 - num7 * ((double)num15 + num9 * (double)num13),
						num4 + num6 * (double)num13,
						num5 - num7 * (double)num15
					});
				}
			}
			return list;
		}

		public virtual void Arc(float x1, float y1, float x2, float y2, float startAng, float extent)
		{
			Arc((double)x1, (double)y1, (double)x2, (double)y2, (double)startAng, (double)extent);
		}

		public virtual void Arc(double x1, double y1, double x2, double y2, double startAng, double extent)
		{
			List<double[]> list = BezierArc(x1, y1, x2, y2, startAng, extent);
			if (list.Count != 0)
			{
				double[] array = list[0];
				MoveTo(array[0], array[1]);
				for (int i = 0; i < list.Count; i++)
				{
					array = list[i];
					CurveTo(array[2], array[3], array[4], array[5], array[6], array[7]);
				}
			}
		}

