		public virtual void RoundRectangle(float x, float y, float w, float h, float r)
		{
			RoundRectangle((double)x, (double)y, (double)w, (double)h, (double)r);
		}

		public virtual void RoundRectangle(double x, double y, double w, double h, double r)
		{
			if (w < 0.0)
			{
				x += w;
				w = 0.0 - w;
			}
			if (h < 0.0)
			{
				y += h;
				h = 0.0 - h;
			}
			if (r < 0.0)
			{
				r = 0.0 - r;
			}
			float num = 0.4477f;
			MoveTo(x + r, y);
			LineTo(x + w - r, y);
			CurveTo(x + w - r * (double)num, y, x + w, y + r * (double)num, x + w, y + r);
			LineTo(x + w, y + h - r);
			CurveTo(x + w, y + h - r * (double)num, x + w - r * (double)num, y + h, x + w - r, y + h);
			LineTo(x + r, y + h);
			CurveTo(x + r * (double)num, y + h, x, y + h - r * (double)num, x, y + h - r);
			LineTo(x, y + r);
			CurveTo(x, y + r * (double)num, x + r * (double)num, y, x + r, y);
		}

