		public virtual void DrawRadioField(float llx, float lly, float urx, float ury, bool on)
		{
			DrawRadioField((double)llx, (double)lly, (double)urx, (double)ury, on);
		}

		public virtual void DrawRadioField(double llx, double lly, double urx, double ury, bool on)
		{
			if (llx > urx)
			{
				double num = llx;
				llx = urx;
				urx = num;
			}
			if (lly > ury)
			{
				double num2 = lly;
				lly = ury;
				ury = num2;
			}
			SaveState();
			SetLineWidth(1f);
			SetLineCap(1);
			SetColorStroke(new BaseColor(192, 192, 192));
			Arc(llx + 1.0, lly + 1.0, urx - 1.0, ury - 1.0, 0.0, 360.0);
			Stroke();
			SetLineWidth(1f);
			SetLineCap(1);
			SetColorStroke(new BaseColor(160, 160, 160));
			Arc(llx + 0.5, lly + 0.5, urx - 0.5, ury - 0.5, 45.0, 180.0);
			Stroke();
			SetLineWidth(1f);
			SetLineCap(1);
			SetColorStroke(new BaseColor(0, 0, 0));
			Arc(llx + 1.5, lly + 1.5, urx - 1.5, ury - 1.5, 45.0, 180.0);
			Stroke();
			if (on)
			{
				SetLineWidth(1f);
				SetLineCap(1);
				SetColorFill(new BaseColor(0, 0, 0));
				Arc(llx + 4.0, lly + 4.0, urx - 4.0, ury - 4.0, 0.0, 360.0);
				Fill();
			}
			RestoreState();
		}

		public virtual void DrawTextField(float llx, float lly, float urx, float ury)
		{
			DrawTextField((double)llx, (double)lly, (double)urx, (double)ury);
