		public virtual void DrawTextField(double llx, double lly, double urx, double ury)
		{
			if (llx > urx)
			{
				double num = llx;
				llx = urx;
				urx = num;
			}
			if (lly > ury)
			{
				double num2 = lly;
				lly = ury;
				ury = num2;
			}
			SaveState();
			SetColorStroke(new BaseColor(192, 192, 192));
			SetLineWidth(1f);
			SetLineCap(0);
			Rectangle(llx, lly, urx - llx, ury - lly);
			Stroke();
			SetLineWidth(1f);
			SetLineCap(0);
			SetColorFill(new BaseColor(255, 255, 255));
			Rectangle(llx + 0.5, lly + 0.5, urx - llx - 1.0, ury - lly - 1.0);
			Fill();
			SetColorStroke(new BaseColor(192, 192, 192));
			SetLineWidth(1f);
			SetLineCap(0);
			MoveTo(llx + 1.0, lly + 1.5);
			LineTo(urx - 1.5, lly + 1.5);
			LineTo(urx - 1.5, ury - 1.0);
			Stroke();
			SetColorStroke(new BaseColor(160, 160, 160));
			SetLineWidth(1f);
			SetLineCap(0);
			MoveTo(llx + 1.0, lly + 1.0);
			LineTo(llx + 1.0, ury - 1.0);
			LineTo(urx - 1.0, ury - 1.0);
			Stroke();
			SetColorStroke(new BaseColor(0, 0, 0));
			SetLineWidth(1f);
			SetLineCap(0);
			MoveTo(llx + 2.0, lly + 2.0);
			LineTo(llx + 2.0, ury - 2.0);
			LineTo(urx - 2.0, ury - 2.0);
			Stroke();
			RestoreState();
		}

