			}
			SaveState();
			SetColorStroke(new BaseColor(0, 0, 0));
			SetLineWidth(1f);
			SetLineCap(0);
			Rectangle(llx, lly, urx - llx, ury - lly);
			Stroke();
			SetLineWidth(1f);
			SetLineCap(0);
			SetColorFill(new BaseColor(192, 192, 192));
			Rectangle(llx + 0.5, lly + 0.5, urx - llx - 1.0, ury - lly - 1.0);
			Fill();
			SetColorStroke(new BaseColor(255, 255, 255));
			SetLineWidth(1f);
			SetLineCap(0);
