	public class PdfContentParser
	{
		public const int COMMAND_TYPE = 200;

		private PRTokeniser tokeniser;

		public virtual PRTokeniser Tokeniser
		{
			get
			{
				return tokeniser;
			}
			set
			{
				tokeniser = value;
			}
		}

		public PdfContentParser(PRTokeniser tokeniser)
		{
			this.tokeniser = tokeniser;
		}

		public virtual List<PdfObject> Parse(List<PdfObject> ls)
		{
			if (ls == null)
			{
				ls = new List<PdfObject>();
			}
			else
			{
				ls.Clear();
			}
			PdfObject pdfObject = null;
			while ((pdfObject = ReadPRObject()) != null)
			{
				ls.Add(pdfObject);
				if (pdfObject.Type == 200)
				{
					break;
				}
			}
			return ls;
		}

		public virtual PRTokeniser GetTokeniser()
		{
			return tokeniser;
		}

		public virtual PdfDictionary ReadDictionary()
		{
			PdfDictionary pdfDictionary = new PdfDictionary();
			while (true)
			{
				if (!NextValidToken())
				{
					throw new IOException(MessageLocalization.GetComposedMessage("unexpected.end.of.file"));
				}
				if (tokeniser.TokenType == PRTokeniser.TokType.END_DIC)
				{
					break;
				}
				if (tokeniser.TokenType != PRTokeniser.TokType.OTHER || "def".CompareTo(tokeniser.StringValue) != 0)
				{
					if (tokeniser.TokenType != PRTokeniser.TokType.NAME)
					{
						throw new IOException(MessageLocalization.GetComposedMessage("dictionary.key.1.is.not.a.name", tokeniser.StringValue));
					}
					PdfName key = new PdfName(tokeniser.StringValue, lengthCheck: false);
					PdfObject pdfObject = ReadPRObject();
					int type = pdfObject.Type;
					if (-type == 8)
					{
						throw new IOException(MessageLocalization.GetComposedMessage("unexpected.gt.gt"));
					}
					if (-type == 6)
					{
						throw new IOException(MessageLocalization.GetComposedMessage("unexpected.close.bracket"));
					}
					pdfDictionary.Put(key, pdfObject);
				}
			}
			return pdfDictionary;
		}

		public virtual PdfArray ReadArray()
		{
			PdfArray pdfArray = new PdfArray();
			while (true)
			{
				PdfObject pdfObject = ReadPRObject();
				int type = pdfObject.Type;
				if (-type == 6)
				{
					break;
				}
				if (-type == 8)
				{
					throw new IOException(MessageLocalization.GetComposedMessage("unexpected.gt.gt"));
				}
				pdfArray.Add(pdfObject);
			}
			return pdfArray;
		}

		public virtual PdfObject ReadPRObject()
		{
			if (!NextValidToken())
			{
				return null;
			}
			PRTokeniser.TokType tokenType = tokeniser.TokenType;
			return tokenType switch
			{
				PRTokeniser.TokType.START_DIC => ReadDictionary(), 
				PRTokeniser.TokType.START_ARRAY => ReadArray(), 
				PRTokeniser.TokType.STRING => new PdfString(tokeniser.StringValue, null).SetHexWriting(tokeniser.IsHexString()), 
				PRTokeniser.TokType.NAME => new PdfName(tokeniser.StringValue, lengthCheck: false), 
				PRTokeniser.TokType.NUMBER => new PdfNumber(tokeniser.StringValue), 
				PRTokeniser.TokType.OTHER => new PdfLiteral(200, tokeniser.StringValue), 
				_ => new PdfLiteral(0 - tokenType, tokeniser.StringValue), 
			};
		}

		public virtual bool NextValidToken()
		{
			while (tokeniser.NextToken())
			{
				if (tokeniser.TokenType != PRTokeniser.TokType.COMMENT)
				{
					return true;
				}
			}
			return false;
		}
	}
	public class PdfContents : PdfStream
	{
		internal static byte[] SAVESTATE = DocWriter.GetISOBytes("q\n");

		internal static byte[] RESTORESTATE = DocWriter.GetISOBytes("Q\n");

		internal static byte[] ROTATE90 = DocWriter.GetISOBytes("0 1 -1 0 ");

		internal static byte[] ROTATE180 = DocWriter.GetISOBytes("-1 0 0 -1 ");

		internal static byte[] ROTATE270 = DocWriter.GetISOBytes("0 -1 1 0 ");

		internal static byte[] ROTATEFINAL = DocWriter.GetISOBytes(" cm\n");

		internal PdfContents(PdfContentByte under, PdfContentByte content, PdfContentByte text, PdfContentByte secondContent, Rectangle page)
		{
			Stream stream = null;
			streamBytes = new MemoryStream();
			if (Document.Compress)
			{
				compressed = true;
				stream = new ZDeflaterOutputStream(level: text?.PdfWriter.CompressionLevel ?? content.PdfWriter.CompressionLevel, outp: streamBytes);
			}
			else
			{
				stream = streamBytes;
			}
			switch (page.Rotation)
			{
			case 90:
			{
				stream.Write(ROTATE90, 0, ROTATE90.Length);
				byte[] iSOBytes = DocWriter.GetISOBytes(ByteBuffer.FormatDouble(page.Top));
				stream.Write(iSOBytes, 0, iSOBytes.Length);
				stream.WriteByte(32);
				stream.WriteByte(48);
				stream.Write(ROTATEFINAL, 0, ROTATEFINAL.Length);
				break;
			}
			case 180:
			{
				stream.Write(ROTATE180, 0, ROTATE180.Length);
				byte[] iSOBytes = DocWriter.GetISOBytes(ByteBuffer.FormatDouble(page.Right));
				stream.Write(iSOBytes, 0, iSOBytes.Length);
				stream.WriteByte(32);
				iSOBytes = DocWriter.GetISOBytes(ByteBuffer.FormatDouble(page.Top));
				stream.Write(iSOBytes, 0, iSOBytes.Length);
				stream.Write(ROTATEFINAL, 0, ROTATEFINAL.Length);
				break;
			}
			case 270:
			{
				stream.Write(ROTATE270, 0, ROTATE270.Length);
				stream.WriteByte(48);
				stream.WriteByte(32);
				byte[] iSOBytes = DocWriter.GetISOBytes(ByteBuffer.FormatDouble(page.Right));
				stream.Write(iSOBytes, 0, iSOBytes.Length);
				stream.Write(ROTATEFINAL, 0, ROTATEFINAL.Length);
				break;
			}
			}
			if (under.Size > 0)
			{
				stream.Write(SAVESTATE, 0, SAVESTATE.Length);
				under.InternalBuffer.WriteTo(stream);
				stream.Write(RESTORESTATE, 0, RESTORESTATE.Length);
			}
			if (content.Size > 0)
			{
				stream.Write(SAVESTATE, 0, SAVESTATE.Length);
				content.InternalBuffer.WriteTo(stream);
				stream.Write(RESTORESTATE, 0, RESTORESTATE.Length);
			}
			if (text != null)
			{
				stream.Write(SAVESTATE, 0, SAVESTATE.Length);
				text.InternalBuffer.WriteTo(stream);
				stream.Write(RESTORESTATE, 0, RESTORESTATE.Length);
			}
			if (secondContent.Size > 0)
			{
				secondContent.InternalBuffer.WriteTo(stream);
			}
			if (stream is ZDeflaterOutputStream)
			{
				((ZDeflaterOutputStream)stream).Finish();
			}
			Put(PdfName.LENGTH, new PdfNumber(streamBytes.Length));
			if (compressed)
			{
				Put(PdfName.FILTER, PdfName.FLATEDECODE);
			}
		}
	}
