							if (asName != null && asName3 != null && !asName3.Equals(GetOffStateName(pdfDictionary5)))
							{
								if (!mergedRadioButtons.ContainsKey(list))
								{
									mergedRadioButtons[list] = null;
									pdfDictionary5.Put(PdfName.AS, asName);
								}
								else
