	internal class PdfCopyFormsImp : PdfCopyFieldsImp
	{
		internal PdfCopyFormsImp(Stream os)
			: base(os)
		{
		}

		public virtual void CopyDocumentFields(PdfReader reader)
		{
			if (!reader.IsOpenedWithFullPermissions)
			{
				throw new BadPasswordException(MessageLocalization.GetComposedMessage("pdfreader.not.opened.with.owner.password"));
			}
			if (readers2intrefs.ContainsKey(reader))
			{
				reader = new PdfReader(reader);
			}
			else
			{
				if (reader.Tampered)
				{
					throw new DocumentException(MessageLocalization.GetComposedMessage("the.document.was.reused"));
				}
				reader.ConsolidateNamedDestinations();
				reader.Tampered = true;
			}
			reader.ShuffleSubsetNames();
			readers2intrefs[reader] = new IntHashtable();
			visited[reader] = new IntHashtable();
			fields.Add(reader.AcroFields);
			UpdateCalculationOrder(reader);
		}

		internal override void MergeFields()
		{
			for (int i = 0; i < fields.Count; i++)
			{
				IDictionary<string, AcroFields.Item> fd = fields[i].Fields;
				MergeWithMaster(fd);
			}
		}
	}
	public class PdfDashPattern : PdfArray
	{
		private float dash = -1f;

		private float gap = -1f;

		private float phase = -1f;

		public PdfDashPattern()
		{
		}

		public PdfDashPattern(float dash)
			: base(new PdfNumber(dash))
		{
			this.dash = dash;
		}

		public PdfDashPattern(float dash, float gap)
			: base(new PdfNumber(dash))
		{
			Add(new PdfNumber(gap));
			this.dash = dash;
			this.gap = gap;
		}

		public PdfDashPattern(float dash, float gap, float phase)
			: base(new PdfNumber(dash))
		{
			Add(new PdfNumber(gap));
			this.dash = dash;
			this.gap = gap;
			this.phase = phase;
		}

		public virtual void Add(float n)
		{
			Add(new PdfNumber(n));
		}

		public override void ToPdf(PdfWriter writer, Stream os)
		{
			os.WriteByte(91);
			if (dash >= 0f)
			{
				new PdfNumber(dash).ToPdf(writer, os);
				if (gap >= 0f)
				{
					os.WriteByte(32);
					new PdfNumber(gap).ToPdf(writer, os);
				}
			}
			os.WriteByte(93);
			if (phase >= 0f)
			{
				os.WriteByte(32);
				new PdfNumber(phase).ToPdf(writer, os);
			}
		}
	}
	public class PdfString : PdfObject
	{
		protected string value = "";

		protected string originalValue;

		protected string encoding = "PDF";

		protected int objNum;

		protected int objGen;

		protected bool hexWriting;

		public virtual string Encoding => encoding;

		public PdfString()
			: base(3)
		{
		}

		public PdfString(string value)
			: base(3)
		{
			this.value = value;
		}

		public PdfString(string value, string encoding)
			: base(3)
		{
			this.value = value;
			this.encoding = encoding;
		}

		public PdfString(byte[] bytes)
			: base(3)
		{
			value = PdfEncodings.ConvertToString(bytes, null);
			encoding = "";
		}

		public override void ToPdf(PdfWriter writer, Stream os)
		{
			PdfWriter.CheckPdfIsoConformance(writer, 11, this);
			byte[] array = GetBytes();
			PdfEncryption pdfEncryption = null;
			if (writer != null)
			{
				pdfEncryption = writer.Encryption;
			}
			if (pdfEncryption != null && !pdfEncryption.IsEmbeddedFilesOnly())
			{
				array = pdfEncryption.EncryptByteArray(array);
			}
			if (hexWriting)
			{
				ByteBuffer byteBuffer = new ByteBuffer();
				byteBuffer.Append('<');
				int num = array.Length;
				for (int i = 0; i < num; i++)
				{
					byteBuffer.AppendHex(array[i]);
				}
				byteBuffer.Append('>');
				os.Write(byteBuffer.ToByteArray(), 0, byteBuffer.Size);
			}
			else
			{
				array = StringUtils.EscapeString(array);
				os.Write(array, 0, array.Length);
			}
		}

		public override string ToString()
		{
			return value;
		}

		public virtual string ToUnicodeString()
		{
			if (encoding != null && encoding.Length != 0)
			{
				return value;
			}
			GetBytes();
			if (bytes.Length >= 2 && bytes[0] == 254 && bytes[1] == byte.MaxValue)
			{
				return PdfEncodings.ConvertToString(bytes, "UnicodeBig");
			}
			return PdfEncodings.ConvertToString(bytes, "PDF");
		}

		internal void SetObjNum(int objNum, int objGen)
		{
			this.objNum = objNum;
			this.objGen = objGen;
		}

		internal void Decrypt(PdfReader reader)
		{
			PdfEncryption decrypt = reader.Decrypt;
			if (decrypt != null)
			{
				originalValue = value;
				decrypt.SetHashKey(objNum, objGen);
				bytes = PdfEncodings.ConvertToBytes(value, null);
				bytes = decrypt.DecryptByteArray(bytes);
				value = PdfEncodings.ConvertToString(bytes, null);
			}
		}

		public override byte[] GetBytes()
		{
			if (bytes == null)
			{
				if (encoding != null && encoding.Equals("UnicodeBig") && PdfEncodings.IsPdfDocEncoding(value))
				{
					bytes = PdfEncodings.ConvertToBytes(value, "PDF");
				}
				else
				{
					bytes = PdfEncodings.ConvertToBytes(value, encoding);
				}
			}
			return bytes;
		}

		public virtual byte[] GetOriginalBytes()
		{
			if (originalValue == null)
			{
				return GetBytes();
			}
			return PdfEncodings.ConvertToBytes(originalValue, null);
		}

		public virtual PdfString SetHexWriting(bool hexWriting)
		{
			this.hexWriting = hexWriting;
			return this;
		}

		public virtual bool IsHexWriting()
		{
			return hexWriting;
		}
	}
	public class PdfDate : PdfString
	{
		public PdfDate(DateTime d)
		{
			value = d.ToString("\\D\\:yyyyMMddHHmmss", DateTimeFormatInfo.InvariantInfo);
			string text = d.ToString("zzz", DateTimeFormatInfo.InvariantInfo);
			text = text.Replace(":", "'");
			value = value + text + "'";
		}

		public PdfDate()
			: this(DateTime.Now)
		{
		}

		private static string SetLength(int i, int length)
		{
			return i.ToString().PadLeft(length, '0');
		}

		public virtual string GetW3CDate()
		{
			return GetW3CDate(value);
		}

		public static string GetW3CDate(string d)
		{
			if (d.StartsWith("D:"))
			{
				d = d.Substring(2);
			}
			StringBuilder stringBuilder = new StringBuilder();
			if (d.Length < 4)
			{
				return "0000";
			}
			stringBuilder.Append(d.Substring(0, 4));
			d = d.Substring(4);
			if (d.Length < 2)
			{
				return stringBuilder.ToString();
			}
			stringBuilder.Append('-').Append(d.Substring(0, 2));
			d = d.Substring(2);
			if (d.Length < 2)
			{
				return stringBuilder.ToString();
			}
			stringBuilder.Append('-').Append(d.Substring(0, 2));
			d = d.Substring(2);
			if (d.Length < 2)
			{
				return stringBuilder.ToString();
			}
			stringBuilder.Append('T').Append(d.Substring(0, 2));
			d = d.Substring(2);
			if (d.Length < 2)
			{
				stringBuilder.Append(":00Z");
				return stringBuilder.ToString();
			}
			stringBuilder.Append(':').Append(d.Substring(0, 2));
			d = d.Substring(2);
			if (d.Length < 2)
			{
				stringBuilder.Append('Z');
				return stringBuilder.ToString();
			}
			stringBuilder.Append(':').Append(d.Substring(0, 2));
			d = d.Substring(2);
			if (d.StartsWith("-") || d.StartsWith("+"))
			{
				string text = d.Substring(0, 1);
				d = d.Substring(1);
				string text2 = "00";
				string text3 = "00";
				if (d.Length >= 2)
				{
					text2 = d.Substring(0, 2);
					if (d.Length > 2)
					{
						d = d.Substring(3);
						if (d.Length >= 2)
						{
							text3 = d.Substring(0, 2);
						}
					}
					stringBuilder.Append(text).Append(text2).Append(':')
						.Append(text3);
					return stringBuilder.ToString();
				}
			}
			stringBuilder.Append('Z');
			return stringBuilder.ToString();
		}

		public static DateTime Decode(string date)
		{
			if (date.StartsWith("D:"))
			{
				date = date.Substring(2);
			}
			int month = 1;
			int day = 1;
			int hour = 0;
			int minute = 0;
			int second = 0;
			int hours = 0;
			int minutes = 0;
			char c = '\0';
			int year = int.Parse(date.Substring(0, 4));
			if (date.Length >= 6)
			{
				month = int.Parse(date.Substring(4, 2));
				if (date.Length >= 8)
				{
					day = int.Parse(date.Substring(6, 2));
					if (date.Length >= 10)
					{
						hour = int.Parse(date.Substring(8, 2));
						if (date.Length >= 12)
						{
							minute = int.Parse(date.Substring(10, 2));
							if (date.Length >= 14)
							{
								second = int.Parse(date.Substring(12, 2));
							}
						}
					}
				}
			}
			DateTime result = new DateTime(year, month, day, hour, minute, second);
			if (date.Length <= 14)
			{
				return result;
			}
			c = date[14];
			if (c == 'Z')
			{
				return result.ToLocalTime();
			}
			if (date.Length >= 17)
			{
				hours = int.Parse(date.Substring(15, 2));
				if (date.Length >= 20)
				{
					minutes = int.Parse(date.Substring(18, 2));
				}
			}
			TimeSpan timeSpan = new TimeSpan(hours, minutes, 0);
			if (c == '-')
			{
				result += timeSpan;
			}
			else
			{
				result -= timeSpan;
			}
			return result.ToLocalTime();
		}
	}
	public class PdfDestination : PdfArray
	{
		public const int XYZ = 0;

		public const int FIT = 1;

		public const int FITH = 2;

		public const int FITV = 3;

		public const int FITR = 4;

		public const int FITB = 5;

		public const int FITBH = 6;

		public const int FITBV = 7;

		private bool status;

		public PdfDestination(int type)
		{
			if (type == 5)
			{
				Add(PdfName.FITB);
			}
			else
			{
				Add(PdfName.FIT);
			}
		}

		public PdfDestination(int type, float parameter)
			: base(new PdfNumber(parameter))
		{
			switch (type)
			{
			default:
				AddFirst(PdfName.FITH);
				break;
			case 3:
				AddFirst(PdfName.FITV);
				break;
			case 6:
				AddFirst(PdfName.FITBH);
				break;
			case 7:
				AddFirst(PdfName.FITBV);
				break;
			}
		}

		public PdfDestination(int type, float left, float top, float zoom)
			: base(PdfName.XYZ)
		{
			if (left < 0f)
			{
				Add(PdfNull.PDFNULL);
			}
			else
			{
				Add(new PdfNumber(left));
			}
			if (top < 0f)
			{
				Add(PdfNull.PDFNULL);
			}
			else
			{
				Add(new PdfNumber(top));
			}
			Add(new PdfNumber(zoom));
		}

		public PdfDestination(int type, float left, float bottom, float right, float top)
			: base(PdfName.FITR)
		{
			Add(new PdfNumber(left));
			Add(new PdfNumber(bottom));
			Add(new PdfNumber(right));
			Add(new PdfNumber(top));
		}

		public PdfDestination(PdfDestination d)
			: base(d)
		{
			status = d.status;
		}

		public PdfDestination(string dest)
		{
			string[] array = dest.Trim().Split((char[]?)null);
			if (array.Length > 0)
			{
				Add(new PdfName(array[0]));
			}
			for (int i = 1; i < array.Length; i++)
			{
				if (array[i].Length == 0)
				{
					continue;
				}
				if ("null".Equals(array[i]))
				{
					Add(new PdfNull());
					continue;
				}
				try
				{
					Add(new PdfNumber(array[i]));
				}
				catch (Exception)
				{
					Add(new PdfNull());
				}
			}
		}

		public virtual bool HasPage()
		{
			return status;
		}

		public virtual bool AddPage(PdfIndirectReference page)
		{
			if (!status)
			{
				AddFirst(page);
				status = true;
				return true;
			}
			return false;
		}
	}
