						if (writer.DirectContent.GetSize(includeMarkedContentSize: false) == 0 && writer.DirectContentUnder.GetSize(includeMarkedContentSize: false) == 0 && text.GetSize(includeMarkedContentSize: false) - textEmptySize == 0)
