			public virtual byte[] CharToByte(char char1, string encoding)
			{
				if (char1 == ' ')
				{
					return new byte[1] { (byte)char1 };
				}
				if (char1 >= '✁' && char1 <= '➾')
				{
					byte b = table[char1 - 9984];
					if (b != 0)
					{
						return new byte[1] { b };
					}
				}
				return new byte[0];
