				embeddedFilesOnly = false;
				keyLength = 40;
				revision = 2;
				break;
			case 1:
				embeddedFilesOnly = false;
				if (kl > 0)
				{
					keyLength = kl;
				}
				else
				{
					keyLength = 128;
				}
				revision = 3;
				break;
			case 2:
				keyLength = 128;
				revision = 4;
				break;
			case 3:
				keyLength = 256;
				keySize = 32;
				revision = 5;
				break;
