				iV5[0] = (byte)permissions;
				iV5[1] = (byte)(permissions >> 8);
				iV5[2] = (byte)(permissions >> 16);
				iV5[3] = (byte)(permissions >> 24);
				iV5[4] = byte.MaxValue;
				iV5[5] = byte.MaxValue;
				iV5[6] = byte.MaxValue;
				iV5[7] = byte.MaxValue;
