	{
		protected PdfWriter writer;

		protected PdfIndirectReference refi;

		public virtual PdfIndirectReference Reference
		{
			get
			{
				if (refi != null)
				{
					return refi;
				}
				refi = writer.AddToBody(this).IndirectReference;
				return refi;
			}
		}

