		private static PdfName[] boxNames = new PdfName[4]
		{
			PdfName.CROPBOX,
			PdfName.TRIMBOX,
			PdfName.ARTBOX,
			PdfName.BLEEDBOX
		};

		public static PdfNumber PORTRAIT = new PdfNumber(0);

		public static PdfNumber LANDSCAPE = new PdfNumber(90);

