		{
			Put(PdfName.CONTENTS, contents);
		}

		internal PdfRectangle RotateMediaBox()
		{
			mediaBox = mediaBox.Rotate;
			Put(PdfName.MEDIABOX, mediaBox);
			return mediaBox;
		}
