	public class PdfPageLabels
	{
		public class PdfPageLabelFormat
		{
			public int physicalPage;

			public int numberStyle;

			public string prefix;

			public int logicalPage;

			public PdfPageLabelFormat(int physicalPage, int numberStyle, string prefix, int logicalPage)
			{
				this.physicalPage = physicalPage;
				this.numberStyle = numberStyle;
				this.prefix = prefix;
				this.logicalPage = logicalPage;
			}

			public override string ToString()
			{
				return $"Physical page {physicalPage}: style: {numberStyle}; prefix '{prefix}'; logical page: {logicalPage}";
			}
		}

		public const int DECIMAL_ARABIC_NUMERALS = 0;

		public const int UPPERCASE_ROMAN_NUMERALS = 1;

		public const int LOWERCASE_ROMAN_NUMERALS = 2;

		public const int UPPERCASE_LETTERS = 3;

		public const int LOWERCASE_LETTERS = 4;

		public const int EMPTY = 5;

		internal static PdfName[] numberingStyle = new PdfName[5]
		{
			PdfName.D,
			PdfName.R,
			new PdfName("r"),
			PdfName.A,
			new PdfName("a")
		};

		internal Dictionary<int, PdfDictionary> map;

		public PdfPageLabels()
		{
			map = new Dictionary<int, PdfDictionary>();
			AddPageLabel(1, 0, null, 1);
		}

		public virtual void AddPageLabel(int page, int numberStyle, string text, int firstPage)
		{
			if (page < 1 || firstPage < 1)
			{
				throw new ArgumentException(MessageLocalization.GetComposedMessage("in.a.page.label.the.page.numbers.must.be.greater.or.equal.to.1"));
			}
			PdfDictionary pdfDictionary = new PdfDictionary();
			if (numberStyle >= 0 && numberStyle < numberingStyle.Length)
			{
				pdfDictionary.Put(PdfName.S, numberingStyle[numberStyle]);
			}
			if (text != null)
			{
				pdfDictionary.Put(PdfName.P, new PdfString(text, "UnicodeBig"));
			}
			if (firstPage != 1)
			{
				pdfDictionary.Put(PdfName.ST, new PdfNumber(firstPage));
			}
			map[page - 1] = pdfDictionary;
		}

		public void AddPageLabel(int page, int numberStyle, string text, int firstPage, bool includeFirstPage)
		{
			if (page < 1 || firstPage < 1)
			{
				throw new ArgumentException(MessageLocalization.GetComposedMessage("in.a.page.label.the.page.numbers.must.be.greater.or.equal.to.1"));
			}
			PdfDictionary pdfDictionary = new PdfDictionary();
			if (numberStyle >= 0 && numberStyle < numberingStyle.Length)
			{
				pdfDictionary.Put(PdfName.S, numberingStyle[numberStyle]);
			}
			if (text != null)
			{
				pdfDictionary.Put(PdfName.P, new PdfString(text, "UnicodeBig"));
			}
			if (firstPage != 1 || includeFirstPage)
			{
				pdfDictionary.Put(PdfName.ST, new PdfNumber(firstPage));
			}
			map[page - 1] = pdfDictionary;
		}

		public virtual void AddPageLabel(int page, int numberStyle, string text)
		{
			AddPageLabel(page, numberStyle, text, 1);
		}

		public virtual void AddPageLabel(int page, int numberStyle)
		{
			AddPageLabel(page, numberStyle, null, 1);
		}

		public virtual void AddPageLabel(PdfPageLabelFormat format)
		{
			AddPageLabel(format.physicalPage, format.numberStyle, format.prefix, format.logicalPage);
		}

		public virtual void RemovePageLabel(int page)
		{
			if (page > 1)
			{
				map.Remove(page - 1);
			}
		}

		public virtual PdfDictionary GetDictionary(PdfWriter writer)
		{
			return PdfNumberTree.WriteTree(map, writer);
		}

		public static string[] GetPageLabels(PdfReader reader)
		{
			int numberOfPages = reader.NumberOfPages;
			PdfDictionary catalog = reader.Catalog;
			PdfDictionary pdfDictionary = (PdfDictionary)PdfReader.GetPdfObjectRelease(catalog.Get(PdfName.PAGELABELS));
			if (pdfDictionary == null)
			{
				return null;
			}
			string[] array = new string[numberOfPages];
			Dictionary<int, PdfObject> dictionary = PdfNumberTree.ReadTree(pdfDictionary);
			int num = 1;
			string text = "";
			char c = 'D';
			for (int i = 0; i < numberOfPages; i++)
			{
				if (dictionary.ContainsKey(i))
				{
					PdfDictionary pdfDictionary2 = (PdfDictionary)PdfReader.GetPdfObjectRelease(dictionary[i]);
					num = ((!pdfDictionary2.Contains(PdfName.ST)) ? 1 : ((PdfNumber)pdfDictionary2.Get(PdfName.ST)).IntValue);
					if (pdfDictionary2.Contains(PdfName.P))
					{
						text = ((PdfString)pdfDictionary2.Get(PdfName.P)).ToUnicodeString();
					}
					c = ((!pdfDictionary2.Contains(PdfName.S)) ? 'e' : ((PdfName)pdfDictionary2.Get(PdfName.S)).ToString()[1]);
				}
				switch (c)
				{
				default:
					array[i] = text + num;
					break;
				case 'R':
					array[i] = text + RomanNumberFactory.GetUpperCaseString(num);
					break;
				case 'r':
					array[i] = text + RomanNumberFactory.GetLowerCaseString(num);
					break;
				case 'A':
					array[i] = text + RomanAlphabetFactory.GetUpperCaseString(num);
					break;
				case 'a':
					array[i] = text + RomanAlphabetFactory.GetLowerCaseString(num);
					break;
				case 'e':
					array[i] = text;
					break;
				}
				num++;
			}
			return array;
		}

		public static PdfPageLabelFormat[] GetPageLabelFormats(PdfReader reader)
		{
			PdfDictionary catalog = reader.Catalog;
			PdfDictionary pdfDictionary = (PdfDictionary)PdfReader.GetPdfObjectRelease(catalog.Get(PdfName.PAGELABELS));
			if (pdfDictionary == null)
			{
				return null;
			}
			Dictionary<int, PdfObject> dictionary = PdfNumberTree.ReadTree(pdfDictionary);
			int[] array = new int[dictionary.Count];
			dictionary.Keys.CopyTo(array, 0);
			Array.Sort(array);
			PdfPageLabelFormat[] array2 = new PdfPageLabelFormat[dictionary.Count];
			for (int i = 0; i < array.Length; i++)
			{
				int num = array[i];
				PdfDictionary pdfDictionary2 = (PdfDictionary)PdfReader.GetPdfObjectRelease(dictionary[num]);
				int logicalPage = ((!pdfDictionary2.Contains(PdfName.ST)) ? 1 : ((PdfNumber)pdfDictionary2.Get(PdfName.ST)).IntValue);
				string prefix = ((!pdfDictionary2.Contains(PdfName.P)) ? "" : ((PdfString)pdfDictionary2.Get(PdfName.P)).ToUnicodeString());
				int numberStyle = ((!pdfDictionary2.Contains(PdfName.S)) ? 5 : (((PdfName)pdfDictionary2.Get(PdfName.S)).ToString()[1] switch
				{
					'R' => 1, 
					'r' => 2, 
					'A' => 3, 
					'a' => 4, 
					_ => 0, 
				}));
				array2[i] = new PdfPageLabelFormat(num + 1, numberStyle, prefix, logicalPage);
			}
			return array2;
		}
	}
	public class PdfPages
	{
		private List<PdfIndirectReference> pages = new List<PdfIndirectReference>();

		private List<PdfIndirectReference> parents = new List<PdfIndirectReference>();

		private int leafSize = 10;

		private PdfWriter writer;

		private PdfIndirectReference topParent;

		internal PdfIndirectReference TopParent => topParent;

		internal PdfPages(PdfWriter writer)
		{
			this.writer = writer;
		}

		internal void AddPage(PdfDictionary page)
		{
			if (pages.Count % leafSize == 0)
			{
				parents.Add(writer.PdfIndirectReference);
			}
			PdfIndirectReference value = parents[parents.Count - 1];
			page.Put(PdfName.PARENT, value);
			PdfIndirectReference currentPage = writer.CurrentPage;
			writer.AddToBody(page, currentPage);
			pages.Add(currentPage);
		}

		internal PdfIndirectReference AddPageRef(PdfIndirectReference pageRef)
		{
			if (pages.Count % leafSize == 0)
			{
				parents.Add(writer.PdfIndirectReference);
			}
			pages.Add(pageRef);
			return parents[parents.Count - 1];
		}

		internal PdfIndirectReference WritePageTree()
		{
			if (pages.Count == 0)
			{
				throw new IOException(MessageLocalization.GetComposedMessage("the.document.has.no.pages"));
			}
			int num = 1;
			List<PdfIndirectReference> list = parents;
			List<PdfIndirectReference> list2 = pages;
			List<PdfIndirectReference> list3 = new List<PdfIndirectReference>();
			while (true)
			{
				num *= leafSize;
				int num2 = leafSize;
				int num3 = list2.Count % leafSize;
				if (num3 == 0)
				{
					num3 = leafSize;
				}
				for (int i = 0; i < list.Count; i++)
				{
					int num4 = num;
					int count;
					if (i == list.Count - 1)
					{
						count = num3;
						num4 = pages.Count % num;
						if (num4 == 0)
						{
							num4 = num;
						}
					}
					else
					{
						count = num2;
					}
					PdfDictionary pdfDictionary = new PdfDictionary(PdfName.PAGES);
					pdfDictionary.Put(PdfName.COUNT, new PdfNumber(num4));
					PdfArray pdfArray = new PdfArray();
					List<PdfObject> arrayList = pdfArray.ArrayList;
					foreach (PdfIndirectReference item in list2.GetRange(i * num2, count))
					{
						arrayList.Add(item);
					}
					pdfDictionary.Put(PdfName.KIDS, pdfArray);
					if (list.Count > 1)
					{
						if (i % leafSize == 0)
						{
							list3.Add(writer.PdfIndirectReference);
						}
						pdfDictionary.Put(PdfName.PARENT, list3[i / leafSize]);
					}
					writer.AddToBody(pdfDictionary, list[i]);
				}
				if (list.Count == 1)
				{
					break;
				}
				list2 = list;
				list = list3;
				list3 = new List<PdfIndirectReference>();
			}
			topParent = list[0];
			return topParent;
		}

		internal void SetLinearMode(PdfIndirectReference topParent)
		{
			if (parents.Count > 1)
			{
				throw new Exception(MessageLocalization.GetComposedMessage("linear.page.mode.can.only.be.called.with.a.single.parent"));
			}
			if (topParent != null)
			{
				this.topParent = topParent;
				parents.Clear();
				parents.Add(topParent);
			}
			leafSize = 10000000;
		}

		internal void AddPage(PdfIndirectReference page)
		{
			pages.Add(page);
		}

		internal int ReorderPages(int[] order)
		{
			if (order == null)
			{
				return pages.Count;
			}
			if (parents.Count > 1)
			{
				throw new DocumentException(MessageLocalization.GetComposedMessage("page.reordering.requires.a.single.parent.in.the.page.tree.call.pdfwriter.setlinearmode.after.open"));
			}
			if (order.Length != pages.Count)
			{
				throw new DocumentException(MessageLocalization.GetComposedMessage("page.reordering.requires.an.array.with.the.same.size.as.the.number.of.pages"));
			}
			int count = pages.Count;
			bool[] array = new bool[count];
			for (int i = 0; i < count; i++)
			{
				int num = order[i];
				if (num < 1 || num > count)
				{
					throw new DocumentException(MessageLocalization.GetComposedMessage("page.reordering.requires.pages.between.1.and.1.found.2", count, num));
				}
				if (array[num - 1])
				{
					throw new DocumentException(MessageLocalization.GetComposedMessage("page.reordering.requires.no.page.repetition.page.1.is.repeated", num));
				}
				array[num - 1] = true;
			}
			PdfIndirectReference[] array2 = pages.ToArray();
			for (int j = 0; j < count; j++)
			{
				pages[j] = array2[order[j] - 1];
			}
			return count;
		}
	}
	public class PdfPattern : PdfStream
	{
		internal PdfPattern(PdfPatternPainter painter)
			: this(painter, -1)
		{
		}

		internal PdfPattern(PdfPatternPainter painter, int compressionLevel)
		{
			PdfNumber value = new PdfNumber(1);
			PdfArray matrix = painter.Matrix;
			if (matrix != null)
			{
				Put(PdfName.MATRIX, matrix);
			}
			Put(PdfName.TYPE, PdfName.PATTERN);
			Put(PdfName.BBOX, new PdfRectangle(painter.BoundingBox));
			Put(PdfName.RESOURCES, painter.Resources);
			Put(PdfName.TILINGTYPE, value);
			Put(PdfName.PATTERNTYPE, value);
			if (painter.IsStencil())
			{
				Put(PdfName.PAINTTYPE, new PdfNumber(2));
			}
			else
			{
				Put(PdfName.PAINTTYPE, value);
			}
			Put(PdfName.XSTEP, new PdfNumber(painter.XStep));
			Put(PdfName.YSTEP, new PdfNumber(painter.YStep));
			bytes = painter.ToPdf(null);
			Put(PdfName.LENGTH, new PdfNumber(bytes.Length));
			FlateCompress(compressionLevel);
		}
	}
	public sealed class PdfPatternPainter : PdfTemplate
	{
		internal float xstep;

		internal float ystep;

		internal bool stencil;

		internal BaseColor defaultColor;

		public float XStep
		{
			get
			{
				return xstep;
			}
			set
			{
				xstep = value;
			}
		}

		public float YStep
		{
			get
			{
				return ystep;
			}
			set
			{
				ystep = value;
			}
		}

		public override PdfContentByte Duplicate
		{
			get
			{
				PdfPatternPainter pdfPatternPainter = new PdfPatternPainter();
				pdfPatternPainter.writer = writer;
				pdfPatternPainter.pdf = pdf;
				pdfPatternPainter.thisReference = thisReference;
				pdfPatternPainter.pageResources = pageResources;
				pdfPatternPainter.bBox = new Rectangle(bBox);
				pdfPatternPainter.xstep = xstep;
				pdfPatternPainter.ystep = ystep;
				pdfPatternPainter.matrix = matrix;
				pdfPatternPainter.stencil = stencil;
				pdfPatternPainter.defaultColor = defaultColor;
				return pdfPatternPainter;
			}
		}

		public BaseColor DefaultColor => defaultColor;

		private PdfPatternPainter()
		{
			type = 3;
		}

		internal PdfPatternPainter(PdfWriter wr)
			: base(wr)
		{
			type = 3;
		}

		internal PdfPatternPainter(PdfWriter wr, BaseColor defaultColor)
