			: base(0f, 0f, 0f, 0f)
		{
			borderWidth = 0.5f;
			border = 15;
			column.SetLeading(0f, 1f);
			if (fit)
			{
				this.image = image;
				Padding = borderWidth / 2f;
			}
			else
			{
				image.ScaleToFitLineWhenOverflow = false;
				column.AddText(phrase = new Phrase(new Chunk(image, 0f, 0f, changeLeading: true)));
