					continue;
				}
				row.calculated = false;
				PdfPCell[] cells = row.GetCells();
				foreach (PdfPCell pdfPCell in cells)
				{
					if (pdfPCell != null)
					{
						pdfPCell.CalculatedHeight = 0f;
					}
				}
			}
		}

