		}

		public virtual byte[] GetEncodedRecipient(int index)
		{
			PdfPublicKeyRecipient pdfPublicKeyRecipient = recipients[index];
			byte[] cms = pdfPublicKeyRecipient.Cms;
			if (cms != null)
			{
				return cms;
			}
			Org.BouncyCastle.X509.X509Certificate certificate = pdfPublicKeyRecipient.Certificate;
			int permission = pdfPublicKeyRecipient.Permission;
			int num = 3;
			permission |= ((num == 3) ? (-3904) : (-64));
			permission &= -4;
			permission++;
			byte[] array = new byte[24];
			byte b = (byte)permission;
			byte b2 = (byte)(permission >> 8);
			byte b3 = (byte)(permission >> 16);
			byte b4 = (byte)(permission >> 24);
			Array.Copy(seed, 0, array, 0, 20);
			array[20] = b4;
			array[21] = b3;
			array[22] = b2;
			array[23] = b;
			Asn1Object obj = CreateDERForRecipient(array, certificate);
			MemoryStream memoryStream = new MemoryStream();
			DerOutputStream derOutputStream = new DerOutputStream(memoryStream);
			derOutputStream.WriteObject(obj);
			return pdfPublicKeyRecipient.Cms = memoryStream.ToArray();
		}

		public virtual PdfArray GetEncodedRecipients()
		{
			PdfArray pdfArray = new PdfArray();
			byte[] array = null;
			for (int i = 0; i < recipients.Count; i++)
			{
				try
				{
					array = GetEncodedRecipient(i);
					pdfArray.Add(new PdfLiteral(StringUtils.EscapeString(array)));
				}
				catch
				{
					pdfArray = null;
				}
			}
			return pdfArray;
		}

		private Asn1Object CreateDERForRecipient(byte[] inp, Org.BouncyCastle.X509.X509Certificate cert)
		{
			string identifier = "1.2.840.113549.3.2";
			byte[] array = new byte[100];
			DerObjectIdentifier derObjectIdentifier = new DerObjectIdentifier(identifier);
			byte[] iV = IVGenerator.GetIV(16);
			IBufferedCipher cipher = CipherUtilities.GetCipher(derObjectIdentifier);
			KeyParameter parameters = new KeyParameter(iV);
			byte[] iV2 = IVGenerator.GetIV(cipher.GetBlockSize());
			ParametersWithIV parameters2 = new ParametersWithIV(parameters, iV2);
			cipher.Init(forEncryption: true, parameters2);
			int num = cipher.DoFinal(inp, array, 0);
			byte[] array2 = new byte[num];
			Array.Copy(array, 0, array2, 0, num);
			DerOctetString encryptedContent = new DerOctetString(array2);
			KeyTransRecipientInfo info = ComputeRecipientInfo(cert, iV);
			DerSet recipientInfos = new DerSet(new RecipientInfo(info));
			Asn1EncodableVector asn1EncodableVector = new Asn1EncodableVector();
			asn1EncodableVector.Add(new DerInteger(58));
			asn1EncodableVector.Add(new DerOctetString(iV2));
			DerSequence parameters3 = new DerSequence(asn1EncodableVector);
			AlgorithmIdentifier contentEncryptionAlgorithm = new AlgorithmIdentifier(derObjectIdentifier, parameters3);
			EncryptedContentInfo encryptedContentInfo = new EncryptedContentInfo(PkcsObjectIdentifiers.Data, contentEncryptionAlgorithm, encryptedContent);
			Asn1Set unprotectedAttrs = null;
			EnvelopedData content = new EnvelopedData(null, recipientInfos, encryptedContentInfo, unprotectedAttrs);
			Org.BouncyCastle.Asn1.Cms.ContentInfo contentInfo = new Org.BouncyCastle.Asn1.Cms.ContentInfo(PkcsObjectIdentifiers.EnvelopedData, content);
			return contentInfo.ToAsn1Object();
		}

		private KeyTransRecipientInfo ComputeRecipientInfo(Org.BouncyCastle.X509.X509Certificate x509certificate, byte[] abyte0)
		{
			Asn1InputStream asn1InputStream = new Asn1InputStream(new MemoryStream(x509certificate.GetTbsCertificate()));
			TbsCertificateStructure instance = TbsCertificateStructure.GetInstance(asn1InputStream.ReadObject());
			AlgorithmIdentifier algorithmID = instance.SubjectPublicKeyInfo.AlgorithmID;
			Org.BouncyCastle.Asn1.Cms.IssuerAndSerialNumber id = new Org.BouncyCastle.Asn1.Cms.IssuerAndSerialNumber(instance.Issuer, instance.SerialNumber.Value);
			IBufferedCipher cipher = CipherUtilities.GetCipher(algorithmID.ObjectID);
			cipher.Init(forEncryption: true, x509certificate.GetPublicKey());
			byte[] array = new byte[10000];
			int num = cipher.DoFinal(abyte0, array, 0);
			byte[] array2 = new byte[num];
			Array.Copy(array, 0, array2, 0, num);
			DerOctetString encryptedKey = new DerOctetString(array2);
			RecipientIdentifier rid = new RecipientIdentifier(id);
			return new KeyTransRecipientInfo(rid, algorithmID, encryptedKey);
		}
	}
	public class PdfReaderInstance
	{
		internal static PdfLiteral IDENTITYMATRIX = new PdfLiteral("[1 0 0 1 0 0]");

		internal static PdfNumber ONE = new PdfNumber(1);

		internal int[] myXref;

		internal PdfReader reader;

		internal RandomAccessFileOrArray file;

		internal Dictionary<int, PdfImportedPage> importedPages = new Dictionary<int, PdfImportedPage>();

		internal PdfWriter writer;

		internal Dictionary<int, object> visited = new Dictionary<int, object>();

		internal List<int> nextRound = new List<int>();

		internal PdfReader Reader => reader;

		internal RandomAccessFileOrArray ReaderFile => file;

		internal PdfReaderInstance(PdfReader reader, PdfWriter writer)
		{
			this.reader = reader;
			this.writer = writer;
			file = reader.SafeFile;
			myXref = new int[reader.XrefSize];
		}

		internal PdfImportedPage GetImportedPage(int pageNumber)
		{
			if (!reader.IsOpenedWithFullPermissions)
			{
				throw new ArgumentException(MessageLocalization.GetComposedMessage("pdfreader.not.opened.with.owner.password"));
			}
			if (pageNumber < 1 || pageNumber > reader.NumberOfPages)
			{
				throw new ArgumentException(MessageLocalization.GetComposedMessage("invalid.page.number.1", pageNumber));
			}
			if (!importedPages.TryGetValue(pageNumber, out var value))
			{
				value = new PdfImportedPage(this, writer, pageNumber);
				importedPages[pageNumber] = value;
			}
			return value;
		}

		internal int GetNewObjectNumber(int number, int generation)
		{
			if (myXref[number] == 0)
			{
				myXref[number] = writer.IndirectReferenceNumber;
				nextRound.Add(number);
			}
			return myXref[number];
		}

		internal PdfObject GetResources(int pageNumber)
		{
			return PdfReader.GetPdfObjectRelease(reader.GetPageNRelease(pageNumber).Get(PdfName.RESOURCES));
		}

		internal PdfStream GetFormXObject(int pageNumber, int compressionLevel)
		{
			PdfDictionary pageNRelease = reader.GetPageNRelease(pageNumber);
			PdfObject pdfObjectRelease = PdfReader.GetPdfObjectRelease(pageNRelease.Get(PdfName.CONTENTS));
			PdfDictionary pdfDictionary = new PdfDictionary();
			byte[] array = null;
			if (pdfObjectRelease != null)
			{
				if (pdfObjectRelease.IsStream())
				{
					pdfDictionary.Merge((PRStream)pdfObjectRelease);
				}
				else
				{
					array = reader.GetPageContent(pageNumber, file);
				}
			}
			else
			{
				array = new byte[0];
			}
			pdfDictionary.Put(PdfName.RESOURCES, PdfReader.GetPdfObjectRelease(pageNRelease.Get(PdfName.RESOURCES)));
			pdfDictionary.Put(PdfName.TYPE, PdfName.XOBJECT);
			pdfDictionary.Put(PdfName.SUBTYPE, PdfName.FORM);
			PdfImportedPage pdfImportedPage = importedPages[pageNumber];
			pdfDictionary.Put(PdfName.BBOX, new PdfRectangle(pdfImportedPage.BoundingBox));
			PdfArray matrix = pdfImportedPage.Matrix;
			if (matrix == null)
			{
				pdfDictionary.Put(PdfName.MATRIX, IDENTITYMATRIX);
			}
			else
			{
				pdfDictionary.Put(PdfName.MATRIX, matrix);
			}
			pdfDictionary.Put(PdfName.FORMTYPE, ONE);
			PRStream pRStream;
			if (array == null)
			{
				pRStream = new PRStream((PRStream)pdfObjectRelease, pdfDictionary);
			}
			else
			{
				pRStream = new PRStream(reader, array);
				pRStream.Merge(pdfDictionary);
			}
			return pRStream;
		}

		internal void WriteAllVisited()
		{
			while (nextRound.Count > 0)
			{
				List<int> list = nextRound;
				nextRound = new List<int>();
				foreach (int item in list)
				{
					if (!visited.ContainsKey(item))
					{
						visited[item] = null;
						writer.AddToBody(reader.GetPdfObjectRelease(item), myXref[item]);
					}
				}
			}
		}

		public virtual void WriteAllPages()
		{
			try
			{
				file.ReOpen();
				foreach (PdfImportedPage value in importedPages.Values)
				{
					if (value.IsToCopy())
					{
						writer.AddToBody(value.GetFormXObject(writer.CompressionLevel), value.IndirectReference);
						value.SetCopied();
					}
				}
				WriteAllVisited();
			}
			finally
			{
				try
				{
					file.Close();
				}
				catch
				{
				}
			}
		}
	}
