		{
			PdfStamper pdfStamper = new PdfStamper(reader, os);
			pdfStamper.sigXmlApp = new XmlSignatureAppearance(pdfStamper.stamper);
			pdfStamper.sigXmlApp.SetStamper(pdfStamper);
			return pdfStamper;
		}

