		internal PdfContentByte GetOverContent(int pageNum)
		{
			if (pageNum < 1 || pageNum > reader.NumberOfPages)
			{
				return null;
			}
			PageStamp pageStamp = GetPageStamp(pageNum);
			if (pageStamp.over == null)
			{
