		internal AffineTransform CalculateTemplateTransformationMatrix(AffineTransform currentMatrix, double fieldRotation, Rectangle box)
		{
			AffineTransform affineTransform = new AffineTransform(currentMatrix);
			double num = box.Left;
			double num2 = box.Bottom;
			if (fieldRotation % (Math.PI / 2.0) == 0.0 && fieldRotation % 4.71238898038469 != 0.0 && fieldRotation != 0.0)
			{
				num += (double)box.Width;
			}
			if ((fieldRotation % 4.71238898038469 == 0.0 || fieldRotation % Math.PI == 0.0) && fieldRotation != 0.0)
			{
				num2 += (double)box.Height;
			}
			affineTransform.Translate(num, num2);
			affineTransform.Rotate(fieldRotation);
			return affineTransform;
		}

		internal void SweepKids(PdfObject obj)
		{
			PdfObject pdfObject = PdfReader.KillIndirect(obj);
			if (pdfObject == null || !pdfObject.IsDictionary())
			{
