			}
			PdfDictionary pdfDictionary = (PdfDictionary)pdfObject;
			PdfArray pdfArray = (PdfArray)PdfReader.KillIndirect(pdfDictionary.Get(PdfName.KIDS));
			if (pdfArray != null)
			{
				for (int i = 0; i < pdfArray.Size; i++)
				{
					SweepKids(pdfArray.GetPdfObject(i));
				}
			}
		}

