								IRandomAccessSource byteSource = new RandomAccessSourceFactory().CreateSource(asString.GetBytes());
								PdfContentParser pdfContentParser = new PdfContentParser(new PRTokeniser(new RandomAccessFileOrArray(byteSource)));
								List<PdfObject> list = new List<PdfObject>();
								while (pdfContentParser.Parse(list).Count > 0)
								{
									PdfLiteral pdfLiteral = (PdfLiteral)list[list.Count - 1];
									if (!pdfLiteral.ToString().Equals("Tf"))
									{
										continue;
									}
									pdfName = (PdfName)list[0];
									string text = pdfName.ToString().Substring(1);
									if (!fromShortToFullAnnotationFontNames.TryGetValue(text, out var value2))
									{
										value2 = text;
									}
									if (!builtInAnnotationFonts.TryGetValue(value2, out value))
									{
										PdfDictionary pdfDictionary3 = BaseFont.createBuiltInFontDictionary(value2);
										if (pdfDictionary3 != null)
										{
											value = AddToBody(pdfDictionary3).IndirectReference;
											builtInAnnotationFonts[value2] = value;
										}
									}
								}
							}
							catch (Exception)
							{
								logger.Warn(MessageLocalization.GetComposedMessage("error.resolving.freetext.font"));
								break;
							}
							pdfAppearance = new PdfAppearance(this);
							if (value != null)
							{
								pdfAppearance.PageResources.AddFont(pdfName, value);
							}
							pdfAppearance.SaveState();
							pdfAppearance.BeginText();
							pdfAppearance.SetLiteral(literal);
							pdfAppearance.SetLiteral("(" + asString2.ToString() + ") Tj\n");
							pdfAppearance.EndText();
							pdfAppearance.RestoreState();
						}
						else
						{
							logger.Warn(MessageLocalization.GetComposedMessage("freetext.annotation.doesnt.contain.da"));
						}
					}
					else
					{
						logger.Warn(MessageLocalization.GetComposedMessage("annotation.type.not.supported.flattening"));
					}
					if (pdfAppearance != null)
					{
						Rectangle normalizedRectangle = PdfReader.GetNormalizedRectangle(pdfDictionary.GetAsArray(PdfName.RECT));
						Rectangle rectangle = null;
						rectangle = ((asStream != null) ? PdfReader.GetNormalizedRectangle(asStream.GetAsArray(PdfName.BBOX)) : (pdfAppearance.BoundingBox = new Rectangle(0f, 0f, normalizedRectangle.Width, normalizedRectangle.Height)));
						PdfContentByte overContent = GetOverContent(i);
						overContent.SetLiteral("Q ");
						if (asStream != null && asStream.GetAsArray(PdfName.MATRIX) != null && !Util.ArraysAreEqual(DEFAULT_MATRIX, asStream.GetAsArray(PdfName.MATRIX).AsDoubleArray()))
						{
							double[] matrix = asStream.GetAsArray(PdfName.MATRIX).AsDoubleArray();
							Rectangle rectangle3 = TransformBBoxByMatrix(rectangle, matrix);
							overContent.AddTemplate(pdfAppearance, normalizedRectangle.Width / rectangle3.Width, 0f, 0f, normalizedRectangle.Height / rectangle3.Height, normalizedRectangle.Left, normalizedRectangle.Bottom);
						}
						else
						{
							float num2 = 0f - rectangle.Bottom;
							float num3 = 0f - rectangle.Left;
							overContent.AddTemplate(pdfAppearance, normalizedRectangle.Width / rectangle.Width, 0f, 0f, normalizedRectangle.Height / rectangle.Height, normalizedRectangle.Left + num3, normalizedRectangle.Bottom + num2);
						}
						overContent.SetLiteral("q ");
						asArray.Remove(j);
						j--;
					}
				}
				if (asArray.IsEmpty())
				{
					PdfReader.KillIndirect(pageN.Get(PdfName.ANNOTS));
					pageN.Remove(PdfName.ANNOTS);
				}
			}
		}

		private Rectangle TransformBBoxByMatrix(Rectangle bBox, double[] matrix)
		{
			float[] array = new float[4];
			float[] array2 = new float[4];
			iTextSharp.awt.geom.Point point = TransformPoint(bBox.Left, bBox.Bottom, matrix);
			array[0] = (float)point.x;
			array2[0] = (float)point.y;
			iTextSharp.awt.geom.Point point2 = TransformPoint(bBox.Right, bBox.Top, matrix);
			array[1] = (float)point2.x;
			array2[1] = (float)point2.y;
			iTextSharp.awt.geom.Point point3 = TransformPoint(bBox.Left, bBox.Top, matrix);
			array[2] = (float)point3.x;
			array2[2] = (float)point3.y;
			iTextSharp.awt.geom.Point point4 = TransformPoint(bBox.Right, bBox.Bottom, matrix);
			array[3] = (float)point4.x;
			array2[3] = (float)point4.y;
			return new Rectangle(Utilities.Min(array), Utilities.Min(array2), Utilities.Max(array), Utilities.Max(array2));
		}

		private iTextSharp.awt.geom.Point TransformPoint(double x, double y, double[] matrix)
		{
			iTextSharp.awt.geom.Point point = new iTextSharp.awt.geom.Point();
			point.x = matrix[0] * x + matrix[2] * y + matrix[4];
			point.y = matrix[1] * x + matrix[3] * y + matrix[5];
			return point;
		}

