		private Pfm2afm(RandomAccessFileOrArray inp, Stream outp)
		{
			this.inp = inp;
			encoding = Encoding.GetEncoding(1252);
			this.outp = new StreamWriter(outp, encoding);
		}

		public static void Convert(RandomAccessFileOrArray inp, Stream outp)
		{
			Pfm2afm pfm2afm = new Pfm2afm(inp, outp);
			pfm2afm.Openpfm();
			pfm2afm.Putheader();
			pfm2afm.Putchartab();
			pfm2afm.Putkerntab();
			pfm2afm.Puttrailer();
			pfm2afm.outp.Flush();
		}

		private string ReadString(int n)
		{
			byte[] array = new byte[n];
			inp.ReadFully(array);
			int i;
			for (i = 0; i < array.Length && array[i] != 0; i++)
			{
			}
			return encoding.GetString(array, 0, i);
		}

		private string ReadString()
		{
			StringBuilder stringBuilder = new StringBuilder();
			while (true)
			{
				int num = inp.Read();
				if (num <= 0)
				{
					break;
				}
				stringBuilder.Append((char)num);
			}
			return stringBuilder.ToString();
		}

		private void Outval(int n)
		{
			outp.Write(' ');
			outp.Write(n);
		}

		private void Outchar(int code, int width, string name)
		{
			outp.Write("C ");
			Outval(code);
			outp.Write(" ; WX ");
			Outval(width);
			if (name != null)
			{
				outp.Write(" ; N ");
				outp.Write(name);
			}
			outp.Write(" ;\n");
		}

		private void Openpfm()
		{
			inp.Seek(0);
			vers = inp.ReadShortLE();
			h_len = inp.ReadIntLE();
			copyright = ReadString(60);
			type = inp.ReadShortLE();
			points = inp.ReadShortLE();
			verres = inp.ReadShortLE();
			horres = inp.ReadShortLE();
			ascent = inp.ReadShortLE();
			intleading = inp.ReadShortLE();
			extleading = inp.ReadShortLE();
			italic = (byte)inp.Read();
			uline = (byte)inp.Read();
			overs = (byte)inp.Read();
			weight = inp.ReadShortLE();
			charset = (byte)inp.Read();
			pixwidth = inp.ReadShortLE();
			pixheight = inp.ReadShortLE();
			kind = (byte)inp.Read();
			avgwidth = inp.ReadShortLE();
			maxwidth = inp.ReadShortLE();
			firstchar = inp.Read();
			lastchar = inp.Read();
			defchar = (byte)inp.Read();
			brkchar = (byte)inp.Read();
			widthby = inp.ReadShortLE();
			device = inp.ReadIntLE();
			face = inp.ReadIntLE();
			bits = inp.ReadIntLE();
			bitoff = inp.ReadIntLE();
			extlen = inp.ReadShortLE();
			psext = inp.ReadIntLE();
			chartab = inp.ReadIntLE();
			res1 = inp.ReadIntLE();
			kernpairs = inp.ReadIntLE();
			res2 = inp.ReadIntLE();
			fontname = inp.ReadIntLE();
			if (h_len != inp.Length || extlen != 30 || fontname < 75 || fontname > 512)
			{
				throw new IOException(MessageLocalization.GetComposedMessage("not.a.valid.pfm.file"));
			}
			inp.Seek(psext + 14);
			capheight = inp.ReadShortLE();
			xheight = inp.ReadShortLE();
			ascender = inp.ReadShortLE();
			descender = inp.ReadShortLE();
		}

		private void Putheader()
		{
			outp.Write("StartFontMetrics 2.0\n");
			if (copyright.Length > 0)
			{
				outp.Write("Comment " + copyright + '\n');
			}
			outp.Write("FontName ");
			inp.Seek(fontname);
			string text = ReadString();
			outp.Write(text);
			outp.Write("\nEncodingScheme ");
			if (charset != 0)
			{
				outp.Write("FontSpecific\n");
			}
			else
			{
				outp.Write("AdobeStandardEncoding\n");
			}
			outp.Write("FullName " + text.Replace('-', ' '));
			if (face != 0)
			{
				inp.Seek(face);
				outp.Write("\nFamilyName " + ReadString());
			}
			outp.Write("\nWeight ");
			if (weight > 475 || text.ToLower(CultureInfo.InvariantCulture).IndexOf("bold") >= 0)
			{
				outp.Write("Bold");
			}
			else if ((weight < 325 && weight != 0) || text.ToLower(CultureInfo.InvariantCulture).IndexOf("light") >= 0)
			{
				outp.Write("Light");
			}
			else if (text.ToLower(CultureInfo.InvariantCulture).IndexOf("black") >= 0)
			{
				outp.Write("Black");
			}
			else
			{
				outp.Write("Medium");
			}
			outp.Write("\nItalicAngle ");
			if (italic != 0 || text.ToLower(CultureInfo.InvariantCulture).IndexOf("italic") >= 0)
			{
				outp.Write("-12.00");
			}
			else
			{
				outp.Write("0");
			}
			outp.Write("\nIsFixedPitch ");
			if ((kind & 1) == 0 || avgwidth == maxwidth)
			{
				outp.Write("true");
				isMono = true;
			}
			else
			{
				outp.Write("false");
				isMono = false;
			}
			outp.Write("\nFontBBox");
			if (isMono)
			{
				Outval(-20);
			}
			else
			{
				Outval(-100);
			}
			Outval(-(descender + 5));
			Outval(maxwidth + 10);
			Outval(ascent + 5);
			outp.Write("\nCapHeight");
			Outval(capheight);
			outp.Write("\nXHeight");
			Outval(xheight);
			outp.Write("\nDescender");
			Outval(-descender);
			outp.Write("\nAscender");
			Outval(ascender);
			outp.Write('\n');
		}

		private void Putchartab()
		{
			int num = lastchar - firstchar + 1;
			int[] array = new int[num];
			inp.Seek(chartab);
			for (int i = 0; i < num; i++)
			{
				array[i] = inp.ReadUnsignedShortLE();
			}
			int[] array2 = new int[256];
			if (charset == 0)
			{
				for (int j = firstchar; j <= lastchar; j++)
				{
					if (Win2PSStd[j] != 0)
					{
						array2[Win2PSStd[j]] = j;
					}
				}
			}
			outp.Write("StartCharMetrics");
			Outval(num);
			outp.Write('\n');
			if (charset != 0)
			{
				for (int k = firstchar; k <= lastchar; k++)
				{
					if (array[k - firstchar] != 0)
					{
						Outchar(k, array[k - firstchar], null);
					}
				}
			}
			else
			{
				for (int l = 0; l < 256; l++)
				{
					int num2 = array2[l];
					if (num2 != 0)
					{
						Outchar(l, array[num2 - firstchar], WinChars[num2]);
						array[num2 - firstchar] = 0;
					}
				}
				for (int m = firstchar; m <= lastchar; m++)
				{
					if (array[m - firstchar] != 0)
					{
						Outchar(-1, array[m - firstchar], WinChars[m]);
					}
				}
			}
			outp.Write("EndCharMetrics\n");
		}

		private void Putkerntab()
		{
			if (kernpairs == 0)
			{
				return;
			}
			inp.Seek(kernpairs);
			int num = inp.ReadUnsignedShortLE();
			int num2 = 0;
			int[] array = new int[num * 3];
			int num3 = 0;
			while (num3 < array.Length)
			{
				array[num3++] = inp.Read();
				array[num3++] = inp.Read();
				if ((array[num3++] = inp.ReadShortLE()) != 0)
				{
					num2++;
				}
			}
			if (num2 == 0)
			{
				return;
			}
			outp.Write("StartKernData\nStartKernPairs");
			Outval(num2);
			outp.Write('\n');
			for (int i = 0; i < array.Length; i += 3)
			{
				if (array[i + 2] != 0)
				{
					outp.Write("KPX ");
					outp.Write(WinChars[array[i]]);
					outp.Write(' ');
					outp.Write(WinChars[array[i + 1]]);
					Outval(array[i + 2]);
					outp.Write('\n');
				}
			}
			outp.Write("EndKernPairs\nEndKernData\n");
		}

		private void Puttrailer()
		{
			outp.Write("EndFontMetrics\n");
		}
	}
	public class PRAcroForm : PdfDictionary
	{
		public class FieldInformation
		{
			internal string fieldName;

			internal PdfDictionary info;

			internal PRIndirectReference refi;

			public virtual string WidgetName => info.Get(PdfName.NM)?.ToString();

			public virtual string Name => fieldName;

			public virtual PdfDictionary Info => info;

			public virtual PRIndirectReference Ref => refi;

			internal FieldInformation(string fieldName, PdfDictionary info, PRIndirectReference refi)
			{
				this.fieldName = fieldName;
				this.info = info;
				this.refi = refi;
			}
		}

		internal List<FieldInformation> fields;

		internal List<PdfDictionary> stack;

		internal Dictionary<string, FieldInformation> fieldByName;

		internal PdfReader reader;

		public new int Size => fields.Count;

		public virtual List<FieldInformation> Fields => fields;

		public PRAcroForm(PdfReader reader)
		{
			this.reader = reader;
			fields = new List<FieldInformation>();
			fieldByName = new Dictionary<string, FieldInformation>();
			stack = new List<PdfDictionary>();
		}

		public virtual FieldInformation GetField(string name)
		{
			fieldByName.TryGetValue(name, out var value);
			return value;
		}

		public virtual PRIndirectReference GetRefByName(string name)
		{
			return GetField(name)?.Ref;
		}

		public virtual void ReadAcroForm(PdfDictionary root)
		{
			if (root != null)
			{
				hashMap = root.hashMap;
				PushAttrib(root);
				PdfArray pdfArray = (PdfArray)PdfReader.GetPdfObjectRelease(root.Get(PdfName.FIELDS));
				if (pdfArray != null)
				{
					IterateFields(pdfArray, null, null);
				}
			}
		}

		protected virtual void IterateFields(PdfArray fieldlist, PRIndirectReference fieldDict, string parentPath)
		{
			foreach (PRIndirectReference array in fieldlist.ArrayList)
			{
				PdfDictionary pdfDictionary = (PdfDictionary)PdfReader.GetPdfObjectRelease(array);
				PRIndirectReference pRIndirectReference2 = fieldDict;
				string text = parentPath;
				PdfString pdfString = (PdfString)pdfDictionary.Get(PdfName.T);
				bool flag = pdfString != null;
				if (flag)
				{
					pRIndirectReference2 = array;
					text = ((parentPath != null) ? (parentPath + '.' + pdfString.ToString()) : pdfString.ToString());
				}
				PdfArray pdfArray = (PdfArray)pdfDictionary.Get(PdfName.KIDS);
				if (pdfArray != null)
				{
					PushAttrib(pdfDictionary);
					IterateFields(pdfArray, pRIndirectReference2, text);
					stack.RemoveAt(stack.Count - 1);
				}
				else if (pRIndirectReference2 != null)
				{
					PdfDictionary pdfDictionary2 = stack[stack.Count - 1];
					if (flag)
					{
						pdfDictionary2 = MergeAttrib(pdfDictionary2, pdfDictionary);
					}
					pdfDictionary2.Put(PdfName.T, new PdfString(text));
					FieldInformation fieldInformation = new FieldInformation(text, pdfDictionary2, pRIndirectReference2);
					fields.Add(fieldInformation);
					fieldByName[text] = fieldInformation;
				}
			}
		}

		protected virtual PdfDictionary MergeAttrib(PdfDictionary parent, PdfDictionary child)
		{
			PdfDictionary pdfDictionary = new PdfDictionary();
			if (parent != null)
			{
				pdfDictionary.Merge(parent);
			}
			foreach (PdfName key in child.Keys)
			{
				if (key.Equals(PdfName.DR) || key.Equals(PdfName.DA) || key.Equals(PdfName.Q) || key.Equals(PdfName.FF) || key.Equals(PdfName.DV) || key.Equals(PdfName.V) || key.Equals(PdfName.FT) || key.Equals(PdfName.NM) || key.Equals(PdfName.F))
				{
					pdfDictionary.Put(key, child.Get(key));
				}
			}
			return pdfDictionary;
		}

		protected virtual void PushAttrib(PdfDictionary dict)
		{
			PdfDictionary parent = null;
			if (stack.Count != 0)
			{
				parent = stack[stack.Count - 1];
			}
			parent = MergeAttrib(parent, dict);
			stack.Add(parent);
		}
	}
	public class PRIndirectReference : PdfIndirectReference
	{
		protected PdfReader reader;

		public virtual PdfReader Reader => reader;

		public PRIndirectReference(PdfReader reader, int number, int generation)
		{
			type = 10;
			base.number = number;
			base.generation = generation;
			this.reader = reader;
		}

		public PRIndirectReference(PdfReader reader, int number)
			: this(reader, number, 0)
		{
		}

		public override void ToPdf(PdfWriter writer, Stream os)
		{
			if (writer != null)
			{
				int newObjectNumber = writer.GetNewObjectNumber(reader, number, generation);
				byte[] array = PdfEncodings.ConvertToBytes(new StringBuilder().Append(newObjectNumber).Append(" ").Append(reader.Appendable ? generation : 0)
					.Append(" R")
					.ToString(), null);
				os.Write(array, 0, array.Length);
			}
			else
			{
				base.ToPdf(null, os);
			}
		}

		public virtual void SetNumber(int number, int generation)
		{
			base.number = number;
			base.generation = generation;
		}
	}
	public class PRStream : PdfStream
	{
		protected PdfReader reader;

		protected long offset;

		protected int length;

		protected int objNum;

		protected int objGen;

		public new int Length
		{
			get
			{
				return length;
			}
			set
			{
				length = value;
				Put(PdfName.LENGTH, new PdfNumber(length));
			}
		}

		public virtual long Offset => offset;

		public virtual PdfReader Reader => reader;

		public virtual int ObjNum
		{
			get
			{
				return objNum;
			}
			set
			{
				objNum = value;
			}
		}

		public virtual int ObjGen
		{
			get
			{
				return objGen;
			}
			set
			{
				objGen = value;
			}
		}

		public PRStream(PRStream stream, PdfDictionary newDic)
		{
			reader = stream.reader;
			offset = stream.offset;
			length = stream.Length;
			compressed = stream.compressed;
			compressionLevel = stream.compressionLevel;
			streamBytes = stream.streamBytes;
			bytes = stream.bytes;
			objNum = stream.objNum;
			objGen = stream.objGen;
			if (newDic != null)
			{
				Merge(newDic);
			}
			else
			{
				Merge(stream);
			}
		}

		public PRStream(PRStream stream, PdfDictionary newDic, PdfReader reader)
			: this(stream, newDic)
		{
			this.reader = reader;
		}

		public PRStream(PdfReader reader, long offset)
		{
			this.reader = reader;
			this.offset = offset;
		}

		public PRStream(PdfReader reader, byte[] conts)
			: this(reader, conts, -1)
		{
		}

		public PRStream(PdfReader reader, byte[] conts, int compressionLevel)
		{
			this.reader = reader;
			offset = -1L;
			if (Document.Compress)
			{
				MemoryStream memoryStream = new MemoryStream();
				ZDeflaterOutputStream zDeflaterOutputStream = new ZDeflaterOutputStream(memoryStream, compressionLevel);
				zDeflaterOutputStream.Write(conts, 0, conts.Length);
				zDeflaterOutputStream.Close();
				bytes = memoryStream.ToArray();
				Put(PdfName.FILTER, PdfName.FLATEDECODE);
			}
			else
			{
				bytes = conts;
			}
			Length = bytes.Length;
		}

		public virtual void SetData(byte[] data, bool compress)
		{
			SetData(data, compress, -1);
		}

		public virtual void SetData(byte[] data, bool compress, int compressionLevel)
		{
			Remove(PdfName.FILTER);
			offset = -1L;
			if (Document.Compress && compress)
			{
				MemoryStream memoryStream = new MemoryStream();
				ZDeflaterOutputStream zDeflaterOutputStream = new ZDeflaterOutputStream(memoryStream, compressionLevel);
				zDeflaterOutputStream.Write(data, 0, data.Length);
				zDeflaterOutputStream.Close();
				bytes = memoryStream.ToArray();
				base.compressionLevel = compressionLevel;
				Put(PdfName.FILTER, PdfName.FLATEDECODE);
			}
			else
			{
				bytes = data;
			}
			Length = bytes.Length;
		}

		public virtual void SetDataRaw(byte[] data)
		{
			offset = -1L;
			bytes = data;
			Length = bytes.Length;
		}

		public virtual void SetData(byte[] data)
		{
			SetData(data, compress: true);
		}

		public new byte[] GetBytes()
		{
			return bytes;
		}

		public override void ToPdf(PdfWriter writer, Stream os)
		{
			byte[] array = PdfReader.GetStreamBytesRaw(this);
			PdfEncryption pdfEncryption = null;
			if (writer != null)
			{
				pdfEncryption = writer.Encryption;
			}
			PdfObject value = Get(PdfName.LENGTH);
			int num = array.Length;
			if (pdfEncryption != null)
			{
				num = pdfEncryption.CalculateStreamSize(num);
			}
			Put(PdfName.LENGTH, new PdfNumber(num));
			SuperToPdf(writer, os);
			Put(PdfName.LENGTH, value);
			os.Write(PdfStream.STARTSTREAM, 0, PdfStream.STARTSTREAM.Length);
			if (length > 0)
			{
				if (pdfEncryption != null && !pdfEncryption.IsEmbeddedFilesOnly())
				{
					array = pdfEncryption.EncryptByteArray(array);
				}
				os.Write(array, 0, array.Length);
			}
			os.Write(PdfStream.ENDSTREAM, 0, PdfStream.ENDSTREAM.Length);
		}
	}
	public class PRTokeniser
	{
		public enum TokType
		{
			NUMBER = 1,
			STRING,
			NAME,
			COMMENT,
			START_ARRAY,
			END_ARRAY,
			START_DIC,
			END_DIC,
			REF,
			OTHER,
			ENDOFFILE
		}

		internal const string EMPTY = "";

		private readonly RandomAccessFileOrArray file;

		protected TokType type;

		protected string stringValue;

		protected int reference;

		protected int generation;

		protected bool hexString;

		private StringBuilder outBuf;

