	public sealed class BitArray
	{
		public int[] bits;

		public int size;

		public BitArray(int size)
		{
			if (size < 1)
			{
				throw new ArgumentException("size must be at least 1");
			}
			this.size = size;
			bits = MakeArray(size);
		}

		public int GetSize()
		{
			return size;
		}

		public bool Get(int i)
		{
			return (bits[i >> 5] & (1 << (i & 0x1F))) != 0;
		}

		public void Set(int i)
		{
			bits[i >> 5] |= 1 << i;
		}

		public void Flip(int i)
		{
			bits[i >> 5] ^= 1 << i;
		}

		public void SetBulk(int i, int newBits)
		{
			bits[i >> 5] = newBits;
		}

		public void Clear()
		{
			int num = bits.Length;
			for (int i = 0; i < num; i++)
			{
				bits[i] = 0;
			}
		}

		public bool IsRange(int start, int end, bool value)
		{
			if (end < start)
			{
				throw new ArgumentException();
			}
			if (end == start)
			{
				return true;
			}
			end--;
			int num = start >> 5;
			int num2 = end >> 5;
			for (int i = num; i <= num2; i++)
			{
				int num3 = ((i <= num) ? (start & 0x1F) : 0);
				int num4 = ((i < num2) ? 31 : (end & 0x1F));
				int num5;
				if (num3 == 0 && num4 == 31)
				{
					num5 = -1;
				}
				else
				{
					num5 = 0;
					for (int j = num3; j <= num4; j++)
					{
						num5 |= 1 << j;
					}
				}
				if ((bits[i] & num5) != (value ? num5 : 0))
				{
					return false;
				}
			}
			return true;
		}

		public int[] GetBitArray()
		{
			return bits;
		}

		public void Reverse()
		{
			int[] array = new int[bits.Length];
			int num = size;
			for (int i = 0; i < num; i++)
			{
				if (Get(num - i - 1))
				{
					array[i >> 5] |= 1 << i;
				}
			}
			bits = array;
		}

		private static int[] MakeArray(int size)
		{
			int num = size >> 5;
			if (((uint)size & 0x1Fu) != 0)
			{
				num++;
			}
			return new int[num];
		}

		public override string ToString()
		{
			StringBuilder stringBuilder = new StringBuilder(size);
			for (int i = 0; i < size; i++)
			{
				if ((i & 7) == 0)
				{
					stringBuilder.Append(' ');
				}
				stringBuilder.Append(Get(i) ? 'X' : '.');
			}
			return stringBuilder.ToString();
		}
	}
	public sealed class BitMatrix
	{
		public int width;

		public int height;

		public int rowSize;

		public int[] bits;

		public BitMatrix(int dimension)
			: this(dimension, dimension)
		{
		}

		public BitMatrix(int width, int height)
		{
			if (width < 1 || height < 1)
			{
				throw new ArgumentException("Both dimensions must be greater than 0");
			}
			this.width = width;
			this.height = height;
			int num = width >> 5;
			if (((uint)width & 0x1Fu) != 0)
			{
				num++;
			}
			rowSize = num;
			bits = new int[num * height];
		}

		public bool Get(int x, int y)
		{
			int num = y * rowSize + (x >> 5);
			return ((bits[num] >> (x & 0x1F)) & 1) != 0;
		}

		public void Set(int x, int y)
		{
			int num = y * rowSize + (x >> 5);
			bits[num] |= 1 << x;
		}

		public void Flip(int x, int y)
		{
			int num = y * rowSize + (x >> 5);
			bits[num] ^= 1 << x;
		}

		public void Clear()
		{
			int num = bits.Length;
			for (int i = 0; i < num; i++)
			{
				bits[i] = 0;
			}
		}

		public void SetRegion(int left, int top, int width, int height)
		{
			if (top < 0 || left < 0)
			{
				throw new ArgumentException("Left and top must be nonnegative");
			}
			if (height < 1 || width < 1)
			{
				throw new ArgumentException("Height and width must be at least 1");
			}
			int num = left + width;
			int num2 = top + height;
			if (num2 > this.height || num > this.width)
			{
				throw new ArgumentException("The region must fit inside the matrix");
			}
			for (int i = top; i < num2; i++)
			{
				int num3 = i * rowSize;
				for (int j = left; j < num; j++)
				{
					bits[num3 + (j >> 5)] |= 1 << j;
				}
			}
		}

		public BitArray GetRow(int y, BitArray row)
		{
			if (row == null || row.GetSize() < width)
			{
				row = new BitArray(width);
			}
			int num = y * rowSize;
			for (int i = 0; i < rowSize; i++)
			{
				row.SetBulk(i << 5, bits[num + i]);
			}
			return row;
		}

		public int GetWidth()
		{
			return width;
		}

		public int GetHeight()
		{
			return height;
		}

		public int GetDimension()
		{
			if (width != height)
			{
				throw new InvalidOperationException("Can't call GetDimension() on a non-square matrix");
			}
			return width;
		}

		public override string ToString()
		{
			StringBuilder stringBuilder = new StringBuilder(height * (width + 1));
			for (int i = 0; i < height; i++)
			{
				for (int j = 0; j < width; j++)
				{
					stringBuilder.Append(Get(j, i) ? "X " : "  ");
				}
				stringBuilder.Append('\n');
			}
			return stringBuilder.ToString();
		}
	}
	public sealed class BitVector
	{
		private const int DEFAULT_SIZE_IN_BYTES = 32;

		private int sizeInBits;

		private byte[] array;

		public BitVector()
		{
			sizeInBits = 0;
			array = new byte[32];
		}

		public int At(int index)
		{
			if (index < 0 || index >= sizeInBits)
			{
				throw new IndexOutOfRangeException("Bad index: " + index);
			}
			int num = array[index >> 3] & 0xFF;
			return (num >> 7 - (index & 7)) & 1;
		}

		public int Size()
		{
			return sizeInBits;
		}

		public int SizeInBytes()
		{
			return sizeInBits + 7 >> 3;
		}

		public void AppendBit(int bit)
		{
			if (bit != 0 && bit != 1)
			{
				throw new ArgumentException("Bad bit");
			}
			int num = sizeInBits & 7;
			if (num == 0)
			{
				AppendByte(0);
				sizeInBits -= 8;
			}
			array[sizeInBits >> 3] |= (byte)(bit << 7 - num);
			sizeInBits++;
		}

		public void AppendBits(int value, int numBits)
		{
			if (numBits < 0 || numBits > 32)
			{
				throw new ArgumentException("Num bits must be between 0 and 32");
			}
			int num = numBits;
			while (num > 0)
			{
				if ((sizeInBits & 7) == 0 && num >= 8)
				{
					int value2 = (value >> num - 8) & 0xFF;
					AppendByte(value2);
					num -= 8;
				}
				else
				{
					int bit = (value >> num - 1) & 1;
					AppendBit(bit);
					num--;
				}
			}
		}

		public void AppendBitVector(BitVector bits)
		{
			int num = bits.Size();
			for (int i = 0; i < num; i++)
			{
				AppendBit(bits.At(i));
			}
		}

		public void Xor(BitVector other)
		{
			if (sizeInBits != other.Size())
			{
				throw new ArgumentException("BitVector sizes don't match");
			}
			int num = sizeInBits + 7 >> 3;
			for (int i = 0; i < num; i++)
			{
				array[i] ^= other.array[i];
			}
		}

		public override string ToString()
		{
			StringBuilder stringBuilder = new StringBuilder(sizeInBits);
			for (int i = 0; i < sizeInBits; i++)
			{
				if (At(i) == 0)
				{
					stringBuilder.Append('0');
					continue;
				}
				if (At(i) == 1)
				{
					stringBuilder.Append('1');
					continue;
				}
				throw new ArgumentException("Byte isn't 0 or 1");
			}
			return stringBuilder.ToString();
		}

		public byte[] GetArray()
		{
			return array;
		}

		private void AppendByte(int value)
		{
			if (sizeInBits >> 3 == array.Length)
			{
				byte[] destinationArray = new byte[array.Length << 1];
				Array.Copy(array, 0, destinationArray, 0, array.Length);
				array = destinationArray;
			}
			array[sizeInBits >> 3] = (byte)value;
			sizeInBits += 8;
		}
	}
