		public ByteMatrix(int width, int height)
		{
			bytes = new sbyte[height][];
			for (int i = 0; i < height; i++)
			{
				bytes[i] = new sbyte[width];
			}
			this.width = width;
			this.height = height;
		}

		public int GetHeight()
		{
			return height;
		}

		public int GetWidth()
		{
			return width;
		}

		public sbyte Get(int x, int y)
		{
			return bytes[y][x];
		}

		public sbyte[][] GetArray()
		{
			return bytes;
		}

		public void Set(int x, int y, sbyte value)
		{
			bytes[y][x] = value;
		}

		public void Set(int x, int y, int value)
		{
			bytes[y][x] = (sbyte)value;
		}

		public void Clear(sbyte value)
		{
			for (int i = 0; i < height; i++)
			{
				for (int j = 0; j < width; j++)
				{
					bytes[i][j] = value;
				}
			}
		}

		public override string ToString()
		{
			StringBuilder stringBuilder = new StringBuilder(2 * width * height + 2);
			for (int i = 0; i < height; i++)
			{
				for (int j = 0; j < width; j++)
				{
					switch (bytes[i][j])
					{
					case 0:
						stringBuilder.Append(" 0");
						break;
					case 1:
						stringBuilder.Append(" 1");
						break;
					default:
						stringBuilder.Append("  ");
						break;
					}
				}
				stringBuilder.Append('\n');
			}
			return stringBuilder.ToString();
		}
	}
	public class CharacterSetECI
	{
