	public sealed class Mode
	{
		public static readonly Mode TERMINATOR;

		public static readonly Mode NUMERIC;

		public static readonly Mode ALPHANUMERIC;

		public static readonly Mode STRUCTURED_APPEND;

		public static readonly Mode BYTE;

		public static readonly Mode ECI;

		public static readonly Mode KANJI;

		public static readonly Mode FNC1_FIRST_POSITION;

		public static readonly Mode FNC1_SECOND_POSITION;

		private int[] characterCountBitsForVersions;

		private int bits;

		private string name;

		private Mode(int[] characterCountBitsForVersions, int bits, string name)
		{
			this.characterCountBitsForVersions = characterCountBitsForVersions;
			this.bits = bits;
			this.name = name;
		}

		public static Mode ForBits(int bits)
		{
			return bits switch
			{
				0 => TERMINATOR, 
				1 => NUMERIC, 
				2 => ALPHANUMERIC, 
				3 => STRUCTURED_APPEND, 
				4 => BYTE, 
				5 => FNC1_FIRST_POSITION, 
				7 => ECI, 
				8 => KANJI, 
				9 => FNC1_SECOND_POSITION, 
				_ => throw new ArgumentException(), 
			};
		}

		public int GetCharacterCountBits(Version version)
		{
			if (characterCountBitsForVersions == null)
			{
				throw new ArgumentException("Character count doesn't apply to this mode");
			}
			int versionNumber = version.GetVersionNumber();
			int num = ((versionNumber > 9) ? ((versionNumber <= 26) ? 1 : 2) : 0);
			return characterCountBitsForVersions[num];
		}

		public int GetBits()
		{
			return bits;
		}

		public string GetName()
		{
			return name;
		}

		public override string ToString()
		{
			return name;
		}

		static Mode()
		{
			int[] array = new int[3];
			TERMINATOR = new Mode(array, 0, "TERMINATOR");
			NUMERIC = new Mode(new int[3] { 10, 12, 14 }, 1, "NUMERIC");
			ALPHANUMERIC = new Mode(new int[3] { 9, 11, 13 }, 2, "ALPHANUMERIC");
			int[] array2 = new int[3];
			STRUCTURED_APPEND = new Mode(array2, 3, "STRUCTURED_APPEND");
			BYTE = new Mode(new int[3] { 8, 16, 16 }, 4, "BYTE");
			ECI = new Mode(null, 7, "ECI");
			KANJI = new Mode(new int[3] { 8, 10, 12 }, 8, "KANJI");
			FNC1_FIRST_POSITION = new Mode(null, 5, "FNC1_FIRST_POSITION");
			FNC1_SECOND_POSITION = new Mode(null, 9, "FNC1_SECOND_POSITION");
		}
	}
	public sealed class QRCode
	{
		public const int NUM_MASK_PATTERNS = 8;

