		private int numDataBytes;

		private int numECBytes;

		private int numRSBlocks;

		private ByteMatrix matrix;

		public QRCode()
		{
			mode = null;
			ecLevel = null;
			version = -1;
			matrixWidth = -1;
			maskPattern = -1;
			numTotalBytes = -1;
			numDataBytes = -1;
			numECBytes = -1;
			numRSBlocks = -1;
			matrix = null;
		}

		public Mode GetMode()
		{
			return mode;
		}

		public ErrorCorrectionLevel GetECLevel()
		{
			return ecLevel;
		}

		public int GetVersion()
		{
			return version;
		}

		public int GetMatrixWidth()
		{
			return matrixWidth;
		}

