		{
			return maskPattern;
		}

		public int GetNumTotalBytes()
		{
			return numTotalBytes;
		}

		public int GetNumDataBytes()
		{
			return numDataBytes;
		}

		public int GetNumECBytes()
		{
			return numECBytes;
		}

		public int GetNumRSBlocks()
		{
			return numRSBlocks;
		}

		public ByteMatrix GetMatrix()
		{
			return matrix;
		}

		public int At(int x, int y)
		{
			int num = matrix.Get(x, y);
			if (num != 0 && num != 1)
			{
				throw new ArgumentException("Bad value");
			}
			return num;
		}

		public bool IsValid()
		{
			if (mode != null && ecLevel != null && version != -1 && matrixWidth != -1 && maskPattern != -1 && numTotalBytes != -1 && numDataBytes != -1 && numECBytes != -1 && numRSBlocks != -1 && IsValidMaskPattern(maskPattern) && numTotalBytes == numDataBytes + numECBytes && matrix != null && matrixWidth == matrix.GetWidth())
			{
				return matrix.GetWidth() == matrix.GetHeight();
			}
			return false;
		}

		public override string ToString()
		{
			StringBuilder stringBuilder = new StringBuilder(200);
			stringBuilder.Append("<<\n");
			stringBuilder.Append(" mode: ");
			stringBuilder.Append(mode);
			stringBuilder.Append("\n ecLevel: ");
			stringBuilder.Append(ecLevel);
			stringBuilder.Append("\n version: ");
			stringBuilder.Append(version);
			stringBuilder.Append("\n matrixWidth: ");
			stringBuilder.Append(matrixWidth);
			stringBuilder.Append("\n maskPattern: ");
			stringBuilder.Append(maskPattern);
			stringBuilder.Append("\n numTotalBytes: ");
			stringBuilder.Append(numTotalBytes);
			stringBuilder.Append("\n numDataBytes: ");
			stringBuilder.Append(numDataBytes);
			stringBuilder.Append("\n numECBytes: ");
			stringBuilder.Append(numECBytes);
			stringBuilder.Append("\n numRSBlocks: ");
			stringBuilder.Append(numRSBlocks);
			if (matrix == null)
			{
				stringBuilder.Append("\n matrix: null\n");
			}
			else
			{
				stringBuilder.Append("\n matrix:\n");
				stringBuilder.Append(matrix.ToString());
			}
			stringBuilder.Append(">>\n");
			return stringBuilder.ToString();
		}

		public void SetMode(Mode value)
		{
			mode = value;
		}

		public void SetECLevel(ErrorCorrectionLevel value)
		{
			ecLevel = value;
		}

		public void SetVersion(int value)
		{
			version = value;
		}

		public void SetMatrixWidth(int value)
		{
			matrixWidth = value;
		}

		public void SetMaskPattern(int value)
		{
			maskPattern = value;
		}

		public void SetNumTotalBytes(int value)
		{
			numTotalBytes = value;
		}

		public void SetNumDataBytes(int value)
		{
			numDataBytes = value;
		}

		public void SetNumECBytes(int value)
		{
			numECBytes = value;
		}

		public void SetNumRSBlocks(int value)
		{
			numRSBlocks = value;
		}

		public void SetMatrix(ByteMatrix value)
		{
			matrix = value;
		}

		public static bool IsValidMaskPattern(int maskPattern)
		{
			if (maskPattern >= 0)
			{
				return maskPattern < 8;
			}
			return false;
		}
	}
	public sealed class QRCodeWriter
	{
		private const int QUIET_ZONE_SIZE = 4;

		public ByteMatrix Encode(string contents, int width, int height)
		{
			return Encode(contents, width, height, null);
		}

		public ByteMatrix Encode(string contents, int width, int height, IDictionary<EncodeHintType, object> hints)
		{
			if (contents == null || contents.Length == 0)
			{
				throw new ArgumentException("Found empty contents");
			}
			if (width < 0 || height < 0)
			{
				throw new ArgumentException("Requested dimensions are too small: " + width + 'x' + height);
			}
			ErrorCorrectionLevel ecLevel = ErrorCorrectionLevel.L;
			if (hints != null && hints.ContainsKey(EncodeHintType.ERROR_CORRECTION))
			{
				ecLevel = (ErrorCorrectionLevel)hints[EncodeHintType.ERROR_CORRECTION];
			}
			QRCode qRCode = new QRCode();
			Encoder.Encode(contents, ecLevel, hints, qRCode);
			return RenderResult(qRCode, width, height);
		}

		private static ByteMatrix RenderResult(QRCode code, int width, int height)
		{
			ByteMatrix matrix = code.GetMatrix();
			int width2 = matrix.GetWidth();
			int height2 = matrix.GetHeight();
			int num = width2 + 8;
			int num2 = height2 + 8;
			int num3 = Math.Max(width, num);
			int num4 = Math.Max(height, num2);
			int num5 = Math.Min(num3 / num, num4 / num2);
			int num6 = (num3 - width2 * num5) / 2;
			int num7 = (num4 - height2 * num5) / 2;
			ByteMatrix byteMatrix = new ByteMatrix(num3, num4);
			sbyte[][] array = byteMatrix.GetArray();
			sbyte[] array2 = new sbyte[num3];
			for (int i = 0; i < num7; i++)
			{
				SetRowColor(array[i], -1);
			}
			sbyte[][] array3 = matrix.GetArray();
			for (int j = 0; j < height2; j++)
			{
				for (int k = 0; k < num6; k++)
				{
					array2[k] = -1;
				}
				int num8 = num6;
				for (int l = 0; l < width2; l++)
				{
					sbyte b = (sbyte)((array3[j][l] != 1) ? (-1) : 0);
					for (int m = 0; m < num5; m++)
					{
						array2[num8 + m] = b;
					}
					num8 += num5;
				}
				num8 = num6 + width2 * num5;
				for (int n = num8; n < num3; n++)
				{
					array2[n] = -1;
				}
				num8 = num7 + j * num5;
				for (int num9 = 0; num9 < num5; num9++)
				{
					Array.Copy(array2, 0, array[num8 + num9], 0, num3);
				}
			}
			int num10 = num7 + height2 * num5;
			for (int num11 = num10; num11 < num4; num11++)
			{
				SetRowColor(array[num11], -1);
			}
			return byteMatrix;
		}

		private static void SetRowColor(sbyte[] row, sbyte value)
		{
			for (int i = 0; i < row.Length; i++)
			{
				row[i] = value;
			}
		}
	}
	public sealed class ReedSolomonEncoder
	{
		private GF256 field;

		private List<GF256Poly> cachedGenerators;

		public ReedSolomonEncoder(GF256 field)
		{
			if (!GF256.QR_CODE_FIELD.Equals(field))
			{
				throw new ArgumentException("Only QR Code is supported at this time");
			}
			this.field = field;
			cachedGenerators = new List<GF256Poly>();
			cachedGenerators.Add(new GF256Poly(field, new int[1] { 1 }));
		}

		private GF256Poly BuildGenerator(int degree)
		{
			if (degree >= cachedGenerators.Count)
			{
				GF256Poly gF256Poly = cachedGenerators[cachedGenerators.Count - 1];
				for (int i = cachedGenerators.Count; i <= degree; i++)
				{
					GF256Poly gF256Poly2 = gF256Poly.Multiply(new GF256Poly(field, new int[2]
					{
						1,
						field.Exp(i - 1)
					}));
					cachedGenerators.Add(gF256Poly2);
					gF256Poly = gF256Poly2;
				}
			}
			return cachedGenerators[degree];
		}

		public void Encode(int[] toEncode, int ecBytes)
		{
			if (ecBytes == 0)
			{
				throw new ArgumentException("No error correction bytes");
			}
			int num = toEncode.Length - ecBytes;
			if (num <= 0)
			{
				throw new ArgumentException("No data bytes provided");
			}
			GF256Poly other = BuildGenerator(ecBytes);
			int[] array = new int[num];
			Array.Copy(toEncode, 0, array, 0, num);
			GF256Poly gF256Poly = new GF256Poly(field, array);
			gF256Poly = gF256Poly.MultiplyByMonomial(ecBytes, 1);
			GF256Poly gF256Poly2 = gF256Poly.Divide(other)[1];
			int[] coefficients = gF256Poly2.GetCoefficients();
			int num2 = ecBytes - coefficients.Length;
			for (int i = 0; i < num2; i++)
			{
				toEncode[num + i] = 0;
			}
			Array.Copy(coefficients, 0, toEncode, num + num2, coefficients.Length);
		}
	}
	[Serializable]
	public sealed class ReedSolomonException : Exception
	{
		public ReedSolomonException(string message)
			: base(message)
		{
		}

		protected ReedSolomonException(SerializationInfo info, StreamingContext context)
			: base(info, context)
		{
		}
	}
	public sealed class Version
	{
		public sealed class ECBlocks
		{
			private int ecCodewordsPerBlock;

			private ECB[] ecBlocks;

			public ECBlocks(int ecCodewordsPerBlock, ECB ecBlocks)
			{
				this.ecCodewordsPerBlock = ecCodewordsPerBlock;
				this.ecBlocks = new ECB[1] { ecBlocks };
			}

			public ECBlocks(int ecCodewordsPerBlock, ECB ecBlocks1, ECB ecBlocks2)
			{
				this.ecCodewordsPerBlock = ecCodewordsPerBlock;
				ecBlocks = new ECB[2] { ecBlocks1, ecBlocks2 };
			}

			public int GetECCodewordsPerBlock()
			{
				return ecCodewordsPerBlock;
			}

			public int GetNumBlocks()
			{
				int num = 0;
				for (int i = 0; i < ecBlocks.Length; i++)
				{
					num += ecBlocks[i].GetCount();
				}
				return num;
			}

			public int GetTotalECCodewords()
			{
				return ecCodewordsPerBlock * GetNumBlocks();
			}

			public ECB[] GetECBlocks()
			{
				return ecBlocks;
			}
		}

