namespace iTextSharp.text.pdf.security
{
	public interface IExternalSignature
	{
		string GetHashAlgorithm();

		string GetEncryptionAlgorithm();

		byte[] Sign(byte[] message);
	}
	public class AsymmetricAlgorithmSignature : IExternalSignature
	{
		private AsymmetricAlgorithm algorithm;

		private string hashAlgorithm;

		private string encryptionAlgorithm;

		private AsymmetricAlgorithmSignature(AsymmetricAlgorithm algorithm, string hashAlgorithm)
		{
			this.algorithm = algorithm;
			this.hashAlgorithm = DigestAlgorithms.GetDigest(DigestAlgorithms.GetAllowedDigests(hashAlgorithm));
			if (algorithm is RSACryptoServiceProvider)
			{
				encryptionAlgorithm = "RSA";
				return;
			}
			if (algorithm is DSACryptoServiceProvider)
			{
				encryptionAlgorithm = "DSA";
				return;
			}
			throw new ArgumentException("Not supported encryption algorithm " + algorithm);
		}

		public AsymmetricAlgorithmSignature(RSACryptoServiceProvider algorithm, string hashAlgorithm)
			: this((AsymmetricAlgorithm)algorithm, hashAlgorithm)
		{
		}

		public AsymmetricAlgorithmSignature(DSACryptoServiceProvider algorithm)
			: this(algorithm, null)
		{
		}

		public byte[] Sign(byte[] message)
		{
			if (algorithm is RSACryptoServiceProvider)
			{
				RSACryptoServiceProvider rSACryptoServiceProvider = (RSACryptoServiceProvider)algorithm;
				return rSACryptoServiceProvider.SignData(message, hashAlgorithm);
			}
			DSACryptoServiceProvider dSACryptoServiceProvider = (DSACryptoServiceProvider)algorithm;
			return dSACryptoServiceProvider.SignData(message);
		}

		public string GetHashAlgorithm()
		{
			return hashAlgorithm;
		}

		public string GetEncryptionAlgorithm()
		{
			return encryptionAlgorithm;
		}
	}
	public interface IExternalSignatureContainer
	{
		byte[] Sign(Stream data);

		void ModifySigningDictionary(PdfDictionary signDic);
	}
}
namespace com.itextpdf.text.pdf.security
{
	public class ExternalBlankSignatureContainer : IExternalSignatureContainer
	{
		private PdfDictionary sigDic;

		public ExternalBlankSignatureContainer(PdfDictionary sigDic)
		{
			this.sigDic = sigDic;
		}

		public ExternalBlankSignatureContainer(PdfName filter, PdfName subFilter)
		{
			sigDic = new PdfDictionary();
			sigDic.Put(PdfName.FILTER, filter);
			sigDic.Put(PdfName.SUBFILTER, subFilter);
		}

		public virtual byte[] Sign(Stream data)
		{
			return new byte[0];
		}

		public virtual void ModifySigningDictionary(PdfDictionary signDic)
		{
			signDic.PutAll(sigDic);
		}
	}
}
