		public static void SignXmlDSig(XmlSignatureAppearance sap, IExternalSignature externalSignature, KeyInfoClause keyInfo)
		{
			VerifyArguments(sap, externalSignature);
			List<XmlElement> list = new List<XmlElement>(1);
			list.Add(GenerateContentReference(sap.GetXmlLocator().GetDocument(), sap, null));
			XmlElement signature = GenerateSignatureElement(sap.GetXmlLocator(), null, isXades: false);
			Sign(signature, sap.GetXmlLocator(), externalSignature, list, null, keyInfo);
			sap.Close();
		}

		public static void SignXades(XmlSignatureAppearance sap, IExternalSignature externalSignature, Org.BouncyCastle.X509.X509Certificate[] chain, bool includeSignaturePolicy)
		{
			VerifyArguments(sap, externalSignature);
			string text = "Reference-" + GetRandomId();
			string text2 = "SignedProperties-" + GetRandomId();
			string signatureId = "Signature-" + GetRandomId();
			XmlDocument document = sap.GetXmlLocator().GetDocument();
			document.XmlResolver = null;
			KeyInfoClause keyInfo = GenerateKeyInfo(chain, sap);
			List<XmlElement> list = new List<XmlElement>(2);
			XmlElement signature = GenerateSignatureElement(sap.GetXmlLocator(), signatureId, isXades: true);
			string[] array = null;
			if (includeSignaturePolicy)
			{
				array = new string[2];
				if (externalSignature.GetEncryptionAlgorithm().Equals("RSA"))
				{
					array[0] = "urn:oid:1.2.840.113549.1.1.5";
					array[1] = "RSA (PKCS #1 v1.5) with SHA-1 signature";
				}
				else
				{
					array[0] = "urn:oid:1.2.840.10040.4.3";
					array[1] = "ANSI X9.57 DSA signature generated with SHA-1 hash (DSA x9.30)";
				}
			}
			XmlElement signedProperty;
			XmlElement dsObject = GenerateXadesObject(sap, signatureId, text, text2, array, out signedProperty);
			list.Add(GenerateCustomReference(document, signedProperty, "#" + text2, "http://uri.etsi.org/01903#SignedProperties", null));
			list.Add(GenerateContentReference(document, sap, text));
			Sign(signature, sap.GetXmlLocator(), externalSignature, list, dsObject, keyInfo);
			sap.Close();
		}

		public static void SignXadesBes(XmlSignatureAppearance sap, IExternalSignature externalSignature, Org.BouncyCastle.X509.X509Certificate[] chain)
		{
			SignXades(sap, externalSignature, chain, includeSignaturePolicy: false);
		}

		public static void SignXadesEpes(XmlSignatureAppearance sap, IExternalSignature externalSignature, Org.BouncyCastle.X509.X509Certificate[] chain)
		{
			SignXades(sap, externalSignature, chain, includeSignaturePolicy: true);
		}

		public static void SignXmlDSig(XmlSignatureAppearance sap, IExternalSignature externalSignature, Org.BouncyCastle.X509.X509Certificate[] chain)
		{
			//IL_000a: Unknown result type (might be due to invalid IL or missing references)
			//IL_0014: Expected O, but got Unknown
			SignXmlDSig(sap, externalSignature, (KeyInfoClause)new KeyInfoX509Data(chain[0].GetEncoded()));
		}

		public static void SignXmlDSig(XmlSignatureAppearance sap, IExternalSignature externalSignature, AsymmetricAlgorithm publicKey)
		{
			SignXmlDSig(sap, externalSignature, GenerateKeyInfo(publicKey));
		}

		private static void VerifyArguments(XmlSignatureAppearance sap, IExternalSignature externalSignature)
		{
			if (sap.GetXmlLocator() == null)
			{
				throw new DocumentException(MessageLocalization.GetComposedMessage("xmllocator.cannot.be.null"));
			}
			if (!externalSignature.GetHashAlgorithm().Equals("SHA1"))
			{
				throw new UnsupportedPdfException(MessageLocalization.GetComposedMessage("support.only.sha1.hash.algorithm"));
			}
			if (!externalSignature.GetEncryptionAlgorithm().Equals("RSA") && !externalSignature.GetEncryptionAlgorithm().Equals("DSA"))
			{
				throw new UnsupportedPdfException(MessageLocalization.GetComposedMessage("support.only.rsa.and.dsa.algorithms"));
			}
		}

		private static void NormalizeNamespaces(XPathNavigator src, XPathNavigator dest)
		{
			IDictionary<string, string> namespacesInScope = src.GetNamespacesInScope(XmlNamespaceScope.ExcludeXml);
			IDictionary<string, string> namespacesInScope2 = dest.GetNamespacesInScope(XmlNamespaceScope.Local);
			foreach (KeyValuePair<string, string> item in namespacesInScope)
			{
				if (!namespacesInScope2.ContainsKey(item.Key))
				{
					dest.CreateAttribute("xmlns", item.Key, "http://www.w3.org/2000/xmlns/", item.Value);
				}
			}
		}

		private static byte[] CalculateC14nByteRange(XmlDocument doc)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			//IL_0006: Expected O, but got Unknown
			XmlDsigC14NTransform val = new XmlDsigC14NTransform();
			((Transform)val).LoadInput((object)doc);
			return ((MemoryStream)((Transform)val).GetOutput()).ToArray();
		}

		private static byte[] CalculateC14nDigest(XmlDocument doc, HashAlgorithm hash)
		{
			return hash.ComputeHash(CalculateC14nByteRange(doc));
		}

		private static XmlElement GenerateSignatureElement(IXmlLocator locator, string signatureId, bool isXades)
		{
			XmlElement xmlElement = locator.GetDocument().CreateElement("Signature", "http://www.w3.org/2000/09/xmldsig#");
			if (signatureId != null)
			{
				xmlElement.SetAttribute("Id", signatureId);
			}
			if (isXades)
			{
				xmlElement.CreateNavigator().CreateAttribute("xmlns", "xades", "http://www.w3.org/2000/xmlns/", "http://uri.etsi.org/01903/v1.3.2#");
			}
			return xmlElement;
		}

		private static KeyInfoClause GenerateKeyInfo(Org.BouncyCastle.X509.X509Certificate[] chain, XmlSignatureAppearance sap)
		{
			//IL_0013: Unknown result type (might be due to invalid IL or missing references)
			//IL_0019: Expected O, but got Unknown
			Org.BouncyCastle.X509.X509Certificate certificate = chain[0];
			sap.SetCertificate(certificate);
			return (KeyInfoClause)new KeyInfoX509Data(chain[0].GetEncoded());
		}

		private static KeyInfoClause GenerateKeyInfo(AsymmetricAlgorithm publicKey)
		{
			//IL_000e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0014: Expected O, but got Unknown
			//IL_0022: Unknown result type (might be due to invalid IL or missing references)
			//IL_0028: Expected O, but got Unknown
			if (publicKey is DSA)
			{
				return (KeyInfoClause)new DSAKeyValue((DSA)publicKey);
			}
			if (publicKey is RSA)
			{
				return (KeyInfoClause)new RSAKeyValue((RSA)publicKey);
			}
			throw new UnsupportedPdfException(MessageLocalization.GetComposedMessage("support.only.rsa.and.dsa.algorithms"));
		}

