		private static XmlElement GenerateXadesObject(XmlSignatureAppearance sap, string signatureId, string contentReferenceId, string signedPropertiesId, string[] signaturePolicy, out XmlElement signedProperty)
		{
			HashAlgorithm hashAlgorithm = new SHA1Managed();
			Org.BouncyCastle.X509.X509Certificate certificate = sap.GetCertificate();
			XmlDocument document = sap.GetXmlLocator().GetDocument();
			document.XmlResolver = null;
