			XmlElement xmlElement2 = document.CreateElement("xades:QualifyingProperties", "http://uri.etsi.org/01903/v1.3.2#");
			xmlElement2.SetAttribute("Target", "#" + signatureId);
			XmlElement xmlElement3 = document.CreateElement("xades:SignedProperties", "http://uri.etsi.org/01903/v1.3.2#");
			xmlElement3.SetAttribute("Id", signedPropertiesId);
			XmlElement xmlElement4 = document.CreateElement("xades:SignedSignatureProperties", "http://uri.etsi.org/01903/v1.3.2#");
			XmlElement xmlElement5 = document.CreateElement("xades:SigningTime", "http://uri.etsi.org/01903/v1.3.2#");
			string text = sap.GetSignDate().ToString("yyyy-MM-dd'T'HH:mm:sszzz");
			xmlElement5.AppendChild(document.CreateTextNode(text));
			xmlElement4.AppendChild(xmlElement5);
			XmlElement xmlElement6 = document.CreateElement("xades:SigningCertificate", "http://uri.etsi.org/01903/v1.3.2#");
			XmlElement xmlElement7 = document.CreateElement("xades:Cert", "http://uri.etsi.org/01903/v1.3.2#");
			XmlElement xmlElement8 = document.CreateElement("xades:CertDigest", "http://uri.etsi.org/01903/v1.3.2#");
			XmlElement xmlElement9 = document.CreateElement("DigestMethod", "http://www.w3.org/2000/09/xmldsig#");
			xmlElement9.SetAttribute("Algorithm", "http://www.w3.org/2000/09/xmldsig#sha1");
			xmlElement8.AppendChild(xmlElement9);
			XmlElement xmlElement10 = document.CreateElement("DigestValue", "http://www.w3.org/2000/09/xmldsig#");
			xmlElement10.AppendChild(document.CreateTextNode(Convert.ToBase64String(hashAlgorithm.ComputeHash(certificate.GetEncoded()))));
			xmlElement8.AppendChild(xmlElement10);
			xmlElement7.AppendChild(xmlElement8);
			XmlElement xmlElement11 = document.CreateElement("xades:IssuerSerial", "http://uri.etsi.org/01903/v1.3.2#");
			XmlElement xmlElement12 = document.CreateElement("X509IssuerName", "http://www.w3.org/2000/09/xmldsig#");
			xmlElement12.AppendChild(document.CreateTextNode(GetX509IssuerName(certificate)));
			xmlElement11.AppendChild(xmlElement12);
			XmlElement xmlElement13 = document.CreateElement("X509SerialNumber", "http://www.w3.org/2000/09/xmldsig#");
			xmlElement13.AppendChild(document.CreateTextNode(GetX509SerialNumber(certificate)));
			xmlElement11.AppendChild(xmlElement13);
			xmlElement7.AppendChild(xmlElement11);
			xmlElement6.AppendChild(xmlElement7);
			xmlElement4.AppendChild(xmlElement6);
			if (signaturePolicy != null)
			{
				XmlElement xmlElement14 = document.CreateElement("xades:SignaturePolicyIdentifier", "http://uri.etsi.org/01903/v1.3.2#");
				XmlElement xmlElement15 = document.CreateElement("xades:SignaturePolicyId", "http://uri.etsi.org/01903/v1.3.2#");
				XmlElement xmlElement16 = document.CreateElement("xades:SigPolicyId", "http://uri.etsi.org/01903/v1.3.2#");
				XmlElement xmlElement17 = document.CreateElement("xades:Identifier", "http://uri.etsi.org/01903/v1.3.2#");
				xmlElement17.AppendChild(document.CreateTextNode(signaturePolicy[0]));
				xmlElement17.SetAttribute("Qualifier", "OIDAsURN");
				xmlElement16.AppendChild(xmlElement17);
				XmlElement xmlElement18 = document.CreateElement("xades:Description", "http://uri.etsi.org/01903/v1.3.2#");
				xmlElement18.AppendChild(document.CreateTextNode(signaturePolicy[1]));
				xmlElement16.AppendChild(xmlElement18);
				xmlElement15.AppendChild(xmlElement16);
				XmlElement xmlElement19 = document.CreateElement("xades:SigPolicyHash", "http://uri.etsi.org/01903/v1.3.2#");
				xmlElement9 = document.CreateElement("DigestMethod", "http://www.w3.org/2000/09/xmldsig#");
				xmlElement9.SetAttribute("Algorithm", "http://www.w3.org/2000/09/xmldsig#sha1");
				xmlElement19.AppendChild(xmlElement9);
				xmlElement10 = document.CreateElement("DigestValue", "http://www.w3.org/2000/09/xmldsig#");
				byte[] bytes = Encoding.UTF8.GetBytes(xmlElement16.OuterXml);
				xmlElement10.AppendChild(document.CreateTextNode(Convert.ToBase64String(hashAlgorithm.ComputeHash(bytes))));
				xmlElement19.AppendChild(xmlElement10);
				xmlElement15.AppendChild(xmlElement19);
				xmlElement14.AppendChild(xmlElement15);
				xmlElement4.AppendChild(xmlElement14);
			}
			xmlElement3.AppendChild(xmlElement4);
			XmlElement xmlElement20 = document.CreateElement("xades:SignedDataObjectProperties", "http://uri.etsi.org/01903/v1.3.2#");
			XmlElement xmlElement21 = document.CreateElement("xades:DataObjectFormat", "http://uri.etsi.org/01903/v1.3.2#");
			xmlElement21.SetAttribute("ObjectReference", "#" + contentReferenceId);
			string description = sap.GetDescription();
			if (description != null)
			{
				XmlElement xmlElement22 = document.CreateElement("xades:Description", "http://uri.etsi.org/01903/v1.3.2#");
				xmlElement22.AppendChild(document.CreateTextNode(description));
				xmlElement21.AppendChild(xmlElement22);
			}
			XmlElement xmlElement23 = document.CreateElement("xades:MimeType", "http://uri.etsi.org/01903/v1.3.2#");
			xmlElement23.AppendChild(document.CreateTextNode(sap.GetMimeType()));
			xmlElement21.AppendChild(xmlElement23);
			string encoding = sap.GetXmlLocator().GetEncoding();
			if (encoding != null)
			{
