			}
			xmlElement20.AppendChild(xmlElement21);
			xmlElement3.AppendChild(xmlElement20);
			xmlElement2.AppendChild(xmlElement3);
			xmlElement.AppendChild(xmlElement2);
			signedProperty = xmlElement3;
			return xmlElement;
		}

