		private static XmlElement GenerateContentReference(XmlDocument doc, XmlSignatureAppearance sap, string referenceId)
		{
			IXpathConstructor xpathConstructor = sap.GetXpathConstructor();
			XmlElement xmlElement = doc.CreateElement("Reference", "http://www.w3.org/2000/09/xmldsig#");
			xmlElement.SetAttribute("URI", "");
			if (referenceId != null)
			{
				xmlElement.SetAttribute("Id", referenceId);
			}
			XmlElement xmlElement2 = doc.CreateElement("Transforms", "http://www.w3.org/2000/09/xmldsig#");
			XmlElement xmlElement3 = doc.CreateElement("Transform", "http://www.w3.org/2000/09/xmldsig#");
			xmlElement3.SetAttribute("Algorithm", "http://www.w3.org/2000/09/xmldsig#enveloped-signature");
			xmlElement2.AppendChild(xmlElement3);
			byte[] array = null;
			if (xpathConstructor != null && xpathConstructor.GetXpathExpression().Length > 0)
			{
				XmlNodeList xmlNodeList = doc.SelectNodes(xpathConstructor.GetXpathExpression(), xpathConstructor.GetNamespaceManager());
				if (xmlNodeList.Count == 1 && xmlNodeList[0].NodeType == XmlNodeType.Element)
				{
					XmlElement xmlElement4 = (XmlElement)xmlNodeList[0].CloneNode(deep: true);
					NormalizeNamespaces(xmlNodeList[0].CreateNavigator(), xmlElement4.CreateNavigator());
					XmlDocument xmlDocument = new XmlDocument(doc.NameTable);
					xmlDocument.XmlResolver = null;
					xmlDocument.LoadXml(xmlElement4.OuterXml);
					array = CalculateC14nDigest(xmlDocument, new SHA1Managed());
					xmlElement3 = doc.CreateElement("Transform", "http://www.w3.org/2000/09/xmldsig#");
					xmlElement3.SetAttribute("Algorithm", "http://www.w3.org/2002/06/xmldsig-filter2");
					XmlElement xmlElement5 = doc.CreateElement("XPath", "http://www.w3.org/2000/09/xmldsig#");
					xmlElement5.SetAttribute("xmlns", "http://www.w3.org/2002/06/xmldsig-filter2");
					xmlElement5.SetAttribute("Filter", "intersect");
					XmlNode newChild = doc.CreateTextNode(xpathConstructor.GetXpathExpression());
					xmlElement5.AppendChild(newChild);
					xmlElement3.AppendChild(xmlElement5);
					xmlElement2.AppendChild(xmlElement3);
				}
			}
			if (array == null)
			{
				array = CalculateC14nDigest(doc, new SHA1Managed());
			}
			xmlElement.AppendChild(xmlElement2);
			XmlElement xmlElement6 = doc.CreateElement("DigestMethod", "http://www.w3.org/2000/09/xmldsig#");
			xmlElement6.SetAttribute("Algorithm", "http://www.w3.org/2000/09/xmldsig#sha1");
			xmlElement.AppendChild(xmlElement6);
			XmlElement xmlElement7 = doc.CreateElement("DigestValue", "http://www.w3.org/2000/09/xmldsig#");
			xmlElement7.AppendChild(doc.CreateTextNode(Convert.ToBase64String(array)));
			xmlElement.AppendChild(xmlElement7);
			return xmlElement;
		}

		private static XmlElement GenerateCustomReference(XmlDocument doc, XmlElement signedElement, string uri, string type, string id)
		{
			XmlElement xmlElement = doc.CreateElement("Reference", "http://www.w3.org/2000/09/xmldsig#");
			if (uri == null)
			{
				uri = string.Empty;
			}
			xmlElement.SetAttribute("URI", uri);
			if (type != null)
			{
				xmlElement.SetAttribute("Type", type);
			}
			if (id != null)
			{
				xmlElement.SetAttribute("Id", id);
			}
			XmlElement xmlElement2 = (XmlElement)signedElement.CloneNode(deep: true);
			XPathNavigator xPathNavigator = xmlElement2.CreateNavigator();
			NormalizeNamespaces(doc.DocumentElement.CreateNavigator(), xPathNavigator);
			xPathNavigator.CreateAttribute("xmlns", "xades", "http://www.w3.org/2000/xmlns/", "http://uri.etsi.org/01903/v1.3.2#");
			xPathNavigator.CreateAttribute("xmlns", "", "http://www.w3.org/2000/xmlns/", "http://www.w3.org/2000/09/xmldsig#");
			XmlDocument xmlDocument = new XmlDocument(doc.NameTable);
			xmlDocument.XmlResolver = null;
			xmlDocument.LoadXml(xmlElement2.OuterXml);
			byte[] inArray = CalculateC14nDigest(xmlDocument, new SHA1Managed());
			XmlElement xmlElement3 = doc.CreateElement("DigestMethod", "http://www.w3.org/2000/09/xmldsig#");
			xmlElement3.SetAttribute("Algorithm", "http://www.w3.org/2000/09/xmldsig#sha1");
			xmlElement.AppendChild(xmlElement3);
			XmlElement xmlElement4 = doc.CreateElement("DigestValue", "http://www.w3.org/2000/09/xmldsig#");
			xmlElement4.AppendChild(doc.CreateTextNode(Convert.ToBase64String(inArray)));
			xmlElement.AppendChild(xmlElement4);
			return xmlElement;
		}

		private static void Sign(XmlElement signature, IXmlLocator xmlLocator, IExternalSignature externalSignature, List<XmlElement> references, XmlElement dsObject, KeyInfoClause keyInfo)
		{
			XmlDocument document = xmlLocator.GetDocument();
			document.XmlResolver = null;
			if (signature == null)
			{
				throw new InvalidOperationException();
			}
			XmlElement xmlElement = document.CreateElement("SignedInfo", "http://www.w3.org/2000/09/xmldsig#");
			signature.AppendChild(xmlElement);
			XmlElement xmlElement2 = document.CreateElement("CanonicalizationMethod", "http://www.w3.org/2000/09/xmldsig#");
			xmlElement2.SetAttribute("Algorithm", "http://www.w3.org/TR/2001/REC-xml-c14n-20010315");
			xmlElement.AppendChild(xmlElement2);
			XmlElement xmlElement3 = document.CreateElement("SignatureMethod", "http://www.w3.org/2000/09/xmldsig#");
			if (externalSignature.GetEncryptionAlgorithm().Equals("RSA"))
			{
				xmlElement3.SetAttribute("Algorithm", "http://www.w3.org/2000/09/xmldsig#rsa-sha1");
			}
			else if (externalSignature.GetEncryptionAlgorithm().Equals("DSA"))
			{
				xmlElement3.SetAttribute("Algorithm", "http://www.w3.org/2000/09/xmldsig#dsa-sha1");
			}
			xmlElement.AppendChild(xmlElement3);
			foreach (XmlElement reference in references)
			{
				xmlElement.AppendChild(reference);
			}
			document.DocumentElement.AppendChild(signature);
			XmlElement xmlElement4 = (XmlElement)xmlElement.CloneNode(deep: true);
			NormalizeNamespaces(xmlElement.CreateNavigator(), xmlElement4.CreateNavigator());
			XmlDocument xmlDocument = new XmlDocument(document.NameTable);
			xmlDocument.XmlResolver = null;
			xmlDocument.LoadXml(xmlElement4.OuterXml);
			byte[] message = CalculateC14nByteRange(xmlDocument);
			string text = Convert.ToBase64String(externalSignature.Sign(message));
			XmlElement xmlElement5 = document.CreateElement("SignatureValue", "http://www.w3.org/2000/09/xmldsig#");
			xmlElement5.AppendChild(document.CreateTextNode(text));
			signature.AppendChild(xmlElement5);
			if (keyInfo != null)
			{
				XmlElement xmlElement6 = document.CreateElement("KeyInfo", "http://www.w3.org/2000/09/xmldsig#");
				xmlElement6.AppendChild(document.ImportNode(keyInfo.GetXml(), deep: true));
				signature.AppendChild(xmlElement6);
			}
			if (dsObject != null)
			{
				signature.AppendChild(dsObject);
			}
			xmlLocator.SetDocument(document);
		}
	}
