	public class SignaturePolicyInfo
	{
		private string policyIdentifier;

		private byte[] policyHash;

		private string policyDigestAlgorithm;

		private string policyUri;

		public string PolicyIdentifier => policyIdentifier;

		public byte[] PolicyHash => policyHash;

		public string PolicyDigestAlgorithm => policyDigestAlgorithm;

		public string PolicyUri => policyUri;

		public SignaturePolicyInfo(string policyIdentifier, byte[] policyHash, string policyDigestAlgorithm, string policyUri)
		{
			if (string.IsNullOrEmpty(policyIdentifier))
			{
				throw new ArgumentException("Policy identifier cannot be null");
			}
			if (policyHash == null)
			{
				throw new ArgumentException("Policy hash cannot be null");
			}
			if (string.IsNullOrEmpty(policyDigestAlgorithm))
			{
				throw new ArgumentException("Policy digest algorithm cannot be null");
			}
			this.policyIdentifier = policyIdentifier;
			this.policyHash = policyHash;
			this.policyDigestAlgorithm = policyDigestAlgorithm;
			this.policyUri = policyUri;
		}

		public SignaturePolicyInfo(string policyIdentifier, string policyHashBase64, string policyDigestAlgorithm, string policyUri)
			: this(policyIdentifier, (policyHashBase64 != null) ? Convert.FromBase64String(policyHashBase64) : null, policyDigestAlgorithm, policyUri)
		{
		}

		protected internal SignaturePolicyIdentifier ToSignaturePolicyIdentifier()
		{
			string allowedDigests = DigestAlgorithms.GetAllowedDigests(PolicyDigestAlgorithm);
			if (string.IsNullOrEmpty(allowedDigests))
			{
				throw new ArgumentException("Invalid policy hash algorithm");
			}
			SignaturePolicyIdentifier signaturePolicyIdentifier = null;
			SigPolicyQualifierInfo sigPolicyQualifierInfo = null;
			if (!string.IsNullOrEmpty(PolicyUri))
			{
				sigPolicyQualifierInfo = new SigPolicyQualifierInfo(PkcsObjectIdentifiers.IdSpqEtsUri, new DerIA5String(PolicyUri));
			}
			return new SignaturePolicyIdentifier(new SignaturePolicyId(DerObjectIdentifier.GetInstance(new DerObjectIdentifier(PolicyIdentifier.Replace("urn:oid:", ""))), new OtherHashAlgAndValue(new AlgorithmIdentifier(allowedDigests), new DerOctetString(PolicyHash)), sigPolicyQualifierInfo));
		}
	}
