		public static string EscapeBinaryString(string s)
		{
			StringBuilder stringBuilder = new StringBuilder();
			char[] array = s.ToCharArray();
			int num = array.Length;
			for (int i = 0; i < num; i++)
			{
				char c = array[i];
				if (c < ' ')
				{
					stringBuilder.Append('\\');
					int num2 = c;
					string text = "";
					do
					{
						text = num2 % 8 + text;
						num2 /= 8;
					}
					while (num2 > 0);
					stringBuilder.Append(text.PadLeft(3, '0'));
				}
				else if (c == '\\')
				{
					stringBuilder.Append("\\\\");
				}
				else
				{
					stringBuilder.Append(c);
				}
			}
			return stringBuilder.ToString();
		}

		public static string UnEscapeBinaryString(string s)
		{
			StringBuilder stringBuilder = new StringBuilder();
			char[] array = s.ToCharArray();
			int num = array.Length;
			for (int i = 0; i < num; i++)
			{
				char c = array[i];
				if (c == '\\')
				{
					if (++i >= num)
					{
						stringBuilder.Append('\\');
						break;
					}
					c = array[i];
					if (c >= '0' && c <= '7')
					{
						int num2 = c - 48;
						i++;
						for (int j = 0; j < 2; j++)
						{
							if (i >= num)
							{
								break;
							}
							c = array[i];
							if (c < '0' || c > '7')
							{
								break;
							}
							i++;
							num2 = num2 * 8 + c - 48;
						}
						i--;
						stringBuilder.Append((char)num2);
					}
					else
					{
						stringBuilder.Append(c);
					}
				}
				else
				{
					stringBuilder.Append(c);
				}
			}
			return stringBuilder.ToString();
		}

		public void EndDocument()
		{
		}

		public void EndElement(string tag)
		{
			if (tag.Equals("Bookmark"))
			{
				if (attr.Count != 0)
				{
					throw new Exception(MessageLocalization.GetComposedMessage("bookmark.end.tag.out.of.place"));
				}
				return;
			}
			if (!tag.Equals("Title"))
			{
				throw new Exception(MessageLocalization.GetComposedMessage("invalid.end.tag.1", tag));
			}
			Dictionary<string, object> dictionary = attr.Pop();
			string text = (string)dictionary["Title"];
			dictionary["Title"] = text.Trim();
			string val = GetVal(dictionary, "Named");
			if (val != null)
			{
				dictionary["Named"] = UnEscapeBinaryString(val);
			}
			val = GetVal(dictionary, "NamedN");
			if (val != null)
			{
				dictionary["NamedN"] = UnEscapeBinaryString(val);
			}
			if (attr.Count == 0)
			{
				topList.Add(dictionary);
				return;
			}
			Dictionary<string, object> dictionary2 = attr.Peek();
			IList<Dictionary<string, object>> list = null;
			if (dictionary2.ContainsKey("Kids"))
			{
				list = (IList<Dictionary<string, object>>)dictionary2["Kids"];
			}
			if (list == null)
			{
				list = (IList<Dictionary<string, object>>)(dictionary2["Kids"] = new List<Dictionary<string, object>>());
			}
			list.Add(dictionary);
		}

		public void StartDocument()
		{
		}

		public void StartElement(string tag, IDictionary<string, string> h)
		{
			if (topList == null)
			{
				if (tag.Equals("Bookmark"))
				{
					topList = new List<Dictionary<string, object>>();
					return;
				}
				throw new Exception(MessageLocalization.GetComposedMessage("root.element.is.not.bookmark.1", tag));
			}
			if (!tag.Equals("Title"))
			{
				throw new Exception(MessageLocalization.GetComposedMessage("tag.1.not.allowed", tag));
			}
			Dictionary<string, object> dictionary = new Dictionary<string, object>();
			foreach (KeyValuePair<string, string> item in h)
			{
				dictionary[item.Key] = item.Value;
			}
			dictionary["Title"] = "";
			dictionary.Remove("Kids");
			attr.Push(dictionary);
		}

		public void Text(string str)
		{
			if (attr.Count != 0)
			{
				Dictionary<string, object> dictionary = attr.Peek();
				string text = (string)dictionary["Title"];
				text += str;
				dictionary["Title"] = text;
			}
		}
	}
	public sealed class SimpleNamedDestination : ISimpleXMLDocHandler
	{
		private Dictionary<string, string> xmlNames;

		private Dictionary<string, string> xmlLast;

		private SimpleNamedDestination()
		{
		}

		public static Dictionary<string, string> GetNamedDestination(PdfReader reader, bool fromNames)
		{
			IntHashtable intHashtable = new IntHashtable();
			int numberOfPages = reader.NumberOfPages;
			for (int i = 1; i <= numberOfPages; i++)
			{
				intHashtable[reader.GetPageOrigRef(i).Number] = i;
			}
			Dictionary<string, PdfObject> dictionary = (fromNames ? reader.GetNamedDestinationFromNames() : reader.GetNamedDestinationFromStrings());
			Dictionary<string, string> dictionary2 = new Dictionary<string, string>(dictionary.Count);
			string[] array = new string[dictionary.Count];
			dictionary.Keys.CopyTo(array, 0);
			string[] array2 = array;
			foreach (string key in array2)
			{
				PdfArray pdfArray = (PdfArray)dictionary[key];
				StringBuilder stringBuilder = new StringBuilder();
				try
				{
					stringBuilder.Append(intHashtable[pdfArray.GetAsIndirectObject(0).Number]);
					stringBuilder.Append(' ').Append(pdfArray[1].ToString().Substring(1));
					for (int k = 2; k < pdfArray.Size; k++)
					{
						stringBuilder.Append(' ').Append(pdfArray[k].ToString());
					}
					dictionary2[key] = stringBuilder.ToString();
				}
				catch
				{
				}
			}
			return dictionary2;
		}

		public static void ExportToXML(Dictionary<string, string> names, Stream outp, string encoding, bool onlyASCII)
		{
			StreamWriter wrt = new StreamWriter(outp, IanaEncodings.GetEncodingEncoding(encoding));
			ExportToXML(names, wrt, encoding, onlyASCII);
		}

		public static void ExportToXML(Dictionary<string, string> names, TextWriter wrt, string encoding, bool onlyASCII)
		{
			wrt.Write("<?xml version=\"1.0\" encoding=\"");
			wrt.Write(XMLUtil.EscapeXML(encoding, onlyASCII));
			wrt.Write("\"?>\n<Destination>\n");
			foreach (string key in names.Keys)
			{
				string s = names[key];
				wrt.Write("  <Name Page=\"");
				wrt.Write(XMLUtil.EscapeXML(s, onlyASCII));
				wrt.Write("\">");
				wrt.Write(XMLUtil.EscapeXML(EscapeBinaryString(key), onlyASCII));
				wrt.Write("</Name>\n");
			}
			wrt.Write("</Destination>\n");
			wrt.Flush();
		}

