		internal static PdfArray CreateDestinationArray(string value, PdfWriter writer)
		{
			PdfArray pdfArray = new PdfArray();
			StringTokenizer stringTokenizer = new StringTokenizer(value);
			int page = int.Parse(stringTokenizer.NextToken());
			pdfArray.Add(writer.GetPageReference(page));
			if (!stringTokenizer.HasMoreTokens())
			{
				pdfArray.Add(PdfName.XYZ);
				pdfArray.Add(new float[3] { 0f, 10000f, 0f });
			}
			else
			{
				string text = stringTokenizer.NextToken();
				if (text.StartsWith("/"))
				{
					text = text.Substring(1);
				}
				pdfArray.Add(new PdfName(text));
				for (int i = 0; i < 4; i++)
				{
					if (!stringTokenizer.HasMoreTokens())
					{
						break;
					}
					text = stringTokenizer.NextToken();
					if (text.Equals("null"))
					{
						pdfArray.Add(PdfNull.PDFNULL);
					}
					else
					{
						pdfArray.Add(new PdfNumber(text));
					}
				}
			}
			return pdfArray;
		}

		public static PdfDictionary OutputNamedDestinationAsNames(Dictionary<string, string> names, PdfWriter writer)
		{
			PdfDictionary pdfDictionary = new PdfDictionary();
			foreach (string key2 in names.Keys)
			{
				try
				{
					string value = names[key2];
					PdfArray value2 = CreateDestinationArray(value, writer);
					PdfName key = new PdfName(key2);
					pdfDictionary.Put(key, value2);
				}
				catch
				{
				}
			}
			return pdfDictionary;
		}

		public static PdfDictionary OutputNamedDestinationAsStrings(Dictionary<string, string> names, PdfWriter writer)
		{
			Dictionary<string, PdfObject> dictionary = new Dictionary<string, PdfObject>(names.Count);
			foreach (string key in names.Keys)
			{
				try
				{
					string value = names[key];
					PdfArray objecta = CreateDestinationArray(value, writer);
					dictionary[key] = writer.AddToBody(objecta).IndirectReference;
				}
				catch
				{
				}
			}
			return PdfNameTree.WriteTree(dictionary, writer);
		}

		public static string EscapeBinaryString(string s)
		{
			StringBuilder stringBuilder = new StringBuilder();
			char[] array = s.ToCharArray();
			int num = array.Length;
			for (int i = 0; i < num; i++)
			{
				char c = array[i];
				if (c < ' ')
				{
					stringBuilder.Append('\\');
					int num2 = c;
					num2.ToString("", CultureInfo.InvariantCulture);
					string text = "00" + Convert.ToString(c, 8);
					stringBuilder.Append(text.Substring(text.Length - 3));
				}
				else if (c == '\\')
				{
					stringBuilder.Append("\\\\");
				}
				else
				{
					stringBuilder.Append(c);
				}
			}
			return stringBuilder.ToString();
		}

		public static string UnEscapeBinaryString(string s)
		{
			StringBuilder stringBuilder = new StringBuilder();
			char[] array = s.ToCharArray();
			int num = array.Length;
			for (int i = 0; i < num; i++)
			{
				char c = array[i];
				if (c == '\\')
				{
					if (++i >= num)
					{
						stringBuilder.Append('\\');
						break;
					}
					c = array[i];
					if (c >= '0' && c <= '7')
					{
						int num2 = c - 48;
						i++;
						for (int j = 0; j < 2; j++)
						{
							if (i >= num)
							{
								break;
							}
							c = array[i];
							if (c < '0' || c > '7')
							{
								break;
							}
							i++;
							num2 = num2 * 8 + c - 48;
						}
						i--;
						stringBuilder.Append((char)num2);
					}
					else
					{
						stringBuilder.Append(c);
					}
				}
				else
				{
					stringBuilder.Append(c);
				}
			}
			return stringBuilder.ToString();
		}

		public void EndDocument()
		{
		}

		public void EndElement(string tag)
		{
			if (tag.Equals("Destination"))
			{
				if (xmlLast != null || xmlNames == null)
				{
					throw new ArgumentException(MessageLocalization.GetComposedMessage("destination.end.tag.out.of.place"));
				}
				return;
			}
			if (!tag.Equals("Name"))
			{
				throw new ArgumentException(MessageLocalization.GetComposedMessage("invalid.end.tag.1", tag));
			}
			if (xmlLast == null || xmlNames == null)
			{
				throw new ArgumentException(MessageLocalization.GetComposedMessage("name.end.tag.out.of.place"));
			}
			if (!xmlLast.ContainsKey("Page"))
			{
				throw new ArgumentException(MessageLocalization.GetComposedMessage("page.attribute.missing"));
			}
			xmlNames[UnEscapeBinaryString(xmlLast["Name"])] = xmlLast["Page"];
			xmlLast = null;
		}

		public void StartDocument()
		{
		}

		public void StartElement(string tag, IDictionary<string, string> h)
		{
			if (xmlNames == null)
			{
				if (tag.Equals("Destination"))
				{
					xmlNames = new Dictionary<string, string>();
					return;
				}
				throw new ArgumentException(MessageLocalization.GetComposedMessage("root.element.is.not.destination"));
			}
			if (!tag.Equals("Name"))
			{
				throw new ArgumentException(MessageLocalization.GetComposedMessage("tag.1.not.allowed", tag));
			}
			if (xmlLast != null)
			{
				throw new ArgumentException(MessageLocalization.GetComposedMessage("nested.tags.are.not.allowed"));
			}
			xmlLast = new Dictionary<string, string>(h);
			xmlLast["Name"] = "";
		}

		public void Text(string str)
		{
			if (xmlLast != null)
			{
				string text = xmlLast["Name"];
				text += str;
				xmlLast["Name"] = text;
			}
		}
	}
	public class SpotColor : ExtendedColor
	{
		private PdfSpotColor spot;

		private float tint;

		public virtual PdfSpotColor PdfSpotColor => spot;

		public virtual float Tint => tint;

		public SpotColor(PdfSpotColor spot, float tint)
			: base(3, ((float)spot.AlternativeCS.R / 255f - 1f) * tint + 1f, ((float)spot.AlternativeCS.G / 255f - 1f) * tint + 1f, ((float)spot.AlternativeCS.B / 255f - 1f) * tint + 1f)
		{
			this.spot = spot;
			this.tint = tint;
		}

		public override bool Equals(object obj)
		{
			if (obj is SpotColor && ((SpotColor)obj).spot.Equals(spot))
			{
				return ((SpotColor)obj).tint == tint;
			}
			return false;
		}

		public override int GetHashCode()
		{
			return spot.GetHashCode() ^ tint.GetHashCode();
		}
	}
