namespace iTextSharp.text.pdf.crypto
{
	public class StandardDecryption
	{
		private const int AES_128 = 4;

		private const int AES_256 = 5;

		protected ARCFOUREncryption arcfour;

		protected AESCipher cipher;

		private byte[] key;

		private bool aes;

		private bool initiated;

		private byte[] iv = new byte[16];

		private int ivptr;

		public StandardDecryption(byte[] key, int off, int len, int revision)
		{
			aes = revision == 4 || revision == 5;
			if (aes)
			{
				this.key = new byte[len];
				Array.Copy(key, off, this.key, 0, len);
			}
			else
			{
				arcfour = new ARCFOUREncryption();
				arcfour.PrepareARCFOURKey(key, off, len);
			}
		}

		public virtual byte[] Update(byte[] b, int off, int len)
		{
			if (aes)
			{
				if (initiated)
				{
					return cipher.Update(b, off, len);
				}
				int num = Math.Min(iv.Length - ivptr, len);
				Array.Copy(b, off, iv, ivptr, num);
				off += num;
				len -= num;
				ivptr += num;
				if (ivptr == iv.Length)
				{
					cipher = new AESCipher(forEncryption: false, key, iv);
					initiated = true;
					if (len > 0)
					{
						return cipher.Update(b, off, len);
					}
				}
				return null;
			}
			byte[] array = new byte[len];
			arcfour.EncryptARCFOUR(b, off, len, array, 0);
			return array;
		}

		public virtual byte[] Finish()
		{
			if (cipher != null && aes)
			{
				return cipher.DoFinal();
			}
			return null;
		}
	}
}
namespace iTextSharp.text.pdf
{
	public class StringUtils
	{
		private static readonly byte[] r = DocWriter.GetISOBytes("\\r");

		private static readonly byte[] n = DocWriter.GetISOBytes("\\n");

		private static readonly byte[] t = DocWriter.GetISOBytes("\\t");

		private static readonly byte[] b = DocWriter.GetISOBytes("\\b");

		private static readonly byte[] f = DocWriter.GetISOBytes("\\f");

		private StringUtils()
		{
		}

		public static byte[] EscapeString(byte[] b)
		{
			ByteBuffer byteBuffer = new ByteBuffer();
			EscapeString(b, byteBuffer);
			return byteBuffer.ToByteArray();
		}

		public static void EscapeString(byte[] bytes, ByteBuffer content)
		{
			content.Append_i(40);
			foreach (byte b in bytes)
			{
				switch (b)
				{
				case 13:
					content.Append(r);
					break;
				case 10:
					content.Append(n);
					break;
				case 9:
					content.Append(t);
					break;
				case 8:
					content.Append(StringUtils.b);
					break;
				case 12:
					content.Append(f);
					break;
				case 40:
				case 41:
				case 92:
					content.Append_i(92).Append_i(b);
					break;
				default:
					content.Append_i(b);
					break;
				}
			}
			content.Append(')');
		}

		public static byte[] ConvertCharsToBytes(char[] chars)
		{
			byte[] array = new byte[chars.Length * 2];
			for (int i = 0; i < chars.Length; i++)
			{
				array[2 * i] = (byte)(chars[i] / 256);
				array[2 * i + 1] = (byte)(chars[i] % 256);
			}
			return array;
		}
	}
