			}
			pdfDictionary.Put(PdfName.ENCODING, new PdfName(encoding));
			pdfDictionary.Put(PdfName.DESCENDANTFONTS, new PdfArray(descendant));
			if (toUnicode != null)
			{
				pdfDictionary.Put(PdfName.TOUNICODE, toUnicode);
			}
			return pdfDictionary;
		}

