					this.urx = urx;
					this.ury = ury;
				}
				else
				{
					this.llx = Math.Min(this.llx, llx);
					this.lly = Math.Min(this.lly, lly);
					this.urx = Math.Max(this.urx, urx);
					this.ury = Math.Max(this.ury, ury);
				}
			}
			value = new Type3Glyph(writer, pageResources, wx, llx, lly, urx, ury, colorized);
