		internal override void WriteFont(PdfWriter writer, PdfIndirectReference piRef, object[] oParams)
		{
			if (this.writer != writer)
			{
				throw new ArgumentException(MessageLocalization.GetComposedMessage("type3.font.used.with.the.wrong.pdfwriter"));
			}
			int i;
			for (i = 0; i < usedSlot.Length && !usedSlot[i]; i++)
			{
			}
			if (i == usedSlot.Length)
			{
				throw new DocumentException(MessageLocalization.GetComposedMessage("no.glyphs.defined.for.type3.font"));
			}
			int num = usedSlot.Length - 1;
			while (num >= i && !usedSlot[num])
			{
				num--;
			}
			int[] array = new int[num - i + 1];
			int[] array2 = new int[num - i + 1];
			int num2 = 0;
			int num3 = 0;
			int num4 = i;
			while (num4 <= num)
			{
				if (usedSlot[num4])
				{
					array2[num2++] = num4;
					array[num3] = widths3[num4];
				}
				num4++;
				num3++;
			}
			PdfArray pdfArray = new PdfArray();
			PdfDictionary pdfDictionary = new PdfDictionary();
			int num5 = -1;
			for (int j = 0; j < num2; j++)
			{
				int num6 = array2[j];
				if (num6 > num5)
				{
					num5 = num6;
					pdfArray.Add(new PdfNumber(num5));
				}
				num5++;
				int num7 = array2[j];
				string text = GlyphList.UnicodeToName(num7);
				if (text == null)
				{
					text = "a" + num7;
				}
				PdfName pdfName = new PdfName(text);
				pdfArray.Add(pdfName);
				char2glyph.TryGetValue((char)num7, out var value);
				PdfStream pdfStream = new PdfStream(value.ToPdf(null));
				pdfStream.FlateCompress(compressionLevel);
				PdfIndirectReference indirectReference = writer.AddToBody(pdfStream).IndirectReference;
				pdfDictionary.Put(pdfName, indirectReference);
			}
			PdfDictionary pdfDictionary2 = new PdfDictionary(PdfName.FONT);
			pdfDictionary2.Put(PdfName.SUBTYPE, PdfName.TYPE3);
			if (colorized)
			{
				pdfDictionary2.Put(PdfName.FONTBBOX, new PdfRectangle(0f, 0f, 0f, 0f));
			}
			else
			{
				pdfDictionary2.Put(PdfName.FONTBBOX, new PdfRectangle(llx, lly, urx, ury));
			}
			pdfDictionary2.Put(PdfName.FONTMATRIX, new PdfArray(new float[6] { 0.001f, 0f, 0f, 0.001f, 0f, 0f }));
			pdfDictionary2.Put(PdfName.CHARPROCS, writer.AddToBody(pdfDictionary).IndirectReference);
			PdfDictionary pdfDictionary3 = new PdfDictionary();
			pdfDictionary3.Put(PdfName.DIFFERENCES, pdfArray);
			pdfDictionary2.Put(PdfName.ENCODING, writer.AddToBody(pdfDictionary3).IndirectReference);
			pdfDictionary2.Put(PdfName.FIRSTCHAR, new PdfNumber(i));
			pdfDictionary2.Put(PdfName.LASTCHAR, new PdfNumber(num));
			pdfDictionary2.Put(PdfName.WIDTHS, writer.AddToBody(new PdfArray(array)).IndirectReference);
			if (pageResources.HasResources())
			{
				pdfDictionary2.Put(PdfName.RESOURCES, writer.AddToBody(pageResources.Resources).IndirectReference);
