	public class RomanList : List
	{
		public RomanList()
			: base(numbered: true)
		{
		}

		public RomanList(int symbolIndent)
			: base(numbered: true, symbolIndent)
		{
		}

		public RomanList(bool romanlower, int symbolIndent)
			: base(numbered: true, symbolIndent)
		{
			lowercase = romanlower;
		}

		public override bool Add(IElement o)
		{
			if (o is ListItem)
			{
				ListItem listItem = (ListItem)o;
				Chunk chunk = new Chunk(preSymbol, symbol.Font);
				chunk.Attributes = symbol.Attributes;
				chunk.Append(RomanNumberFactory.GetString(first + base.list.Count, lowercase));
				chunk.Append(postSymbol);
				listItem.ListSymbol = chunk;
				listItem.SetIndentationLeft(symbolIndent, autoindent);
				listItem.IndentationRight = 0f;
				base.list.Add(listItem);
				return true;
			}
			if (o is List)
			{
				List list = (List)o;
				list.IndentationLeft += symbolIndent;
				first--;
				base.list.Add(list);
				return true;
			}
			return false;
		}

		public override List CloneShallow()
		{
			RomanList romanList = new RomanList();
			PopulateProperties(romanList);
			return romanList;
		}
	}
	public class SpecialSymbol
	{
		public static int Index(string str)
		{
			int length = str.Length;
			for (int i = 0; i < length; i++)
			{
				if (GetCorrespondingSymbol(str[i]) != ' ')
				{
					return i;
				}
			}
			return -1;
		}

		public static Chunk Get(char c, Font font)
		{
			char correspondingSymbol = GetCorrespondingSymbol(c);
			if (correspondingSymbol == ' ')
			{
				return new Chunk(c.ToString(), font);
			}
			Font font2 = new Font(Font.FontFamily.SYMBOL, font.Size, font.Style, font.Color);
			return new Chunk(correspondingSymbol.ToString(), font2);
		}

		public static char GetCorrespondingSymbol(char c)
		{
			return c switch
