	public class TabStop
	{
		public enum Alignment
		{
			LEFT,
			RIGHT,
			CENTER,
			ANCHOR
		}

		protected float position;

		protected Alignment alignment;

		protected IDrawInterface leader;

		protected char anchorChar = '.';

		public virtual float Position
		{
			get
			{
				return position;
			}
			set
			{
				position = value;
			}
		}

		public virtual Alignment Align
		{
			get
			{
				return alignment;
			}
			set
			{
				alignment = value;
			}
		}

		public virtual IDrawInterface Leader
		{
			get
			{
				return leader;
			}
			set
			{
				leader = value;
			}
		}

		public virtual char AnchorChar
		{
			get
			{
				return anchorChar;
			}
			set
			{
				anchorChar = value;
			}
		}

		public static TabStop NewInstance(float currentPosition, float tabInterval)
		{
			currentPosition = (float)Math.Round(currentPosition * 1000f) / 1000f;
			tabInterval = (float)Math.Round(tabInterval * 1000f) / 1000f;
			return new TabStop(currentPosition + tabInterval - currentPosition % tabInterval);
		}

		public TabStop(float position)
			: this(position, Alignment.LEFT)
		{
		}

		public TabStop(float position, IDrawInterface leader)
			: this(position, leader, Alignment.LEFT)
		{
		}

		public TabStop(float position, Alignment alignment)
			: this(position, null, alignment)
		{
		}

		public TabStop(float position, Alignment alignment, char anchorChar)
			: this(position, null, alignment, anchorChar)
		{
		}

		public TabStop(float position, IDrawInterface leader, Alignment alignment)
			: this(position, leader, alignment, '.')
		{
		}

		public TabStop(float position, IDrawInterface leader, Alignment alignment, char anchorChar)
		{
			this.position = position;
			this.leader = leader;
			this.alignment = alignment;
			this.anchorChar = anchorChar;
		}

		public TabStop(TabStop tabStop)
			: this(tabStop.Position, tabStop.Leader, tabStop.Align, tabStop.AnchorChar)
		{
		}

		public virtual float GetPosition(float tabPosition, float currentPosition, float anchorPosition)
		{
			float result = position;
			float num = currentPosition - tabPosition;
			switch (alignment)
			{
			case Alignment.RIGHT:
				result = ((!(tabPosition + num < position)) ? tabPosition : (position - num));
				break;
			case Alignment.CENTER:
				result = ((!(tabPosition + num / 2f < position)) ? tabPosition : (position - num / 2f));
				break;
			case Alignment.ANCHOR:
				result = (float.IsNaN(anchorPosition) ? ((!(tabPosition + num < position)) ? tabPosition : (position - num)) : ((!(anchorPosition < position)) ? tabPosition : (position - (anchorPosition - tabPosition))));
				break;
			}
			return result;
		}
	}
	public class Utilities
	{
		private static byte[] skipBuffer = new byte[4096];

		public static ICollection<K> GetKeySet<K, V>(Dictionary<K, V> table)
		{
			if (table != null)
			{
				return table.Keys;
			}
			return new List<K>();
		}

		public static object[][] AddToArray(object[][] original, object[] item)
		{
			if (original == null)
			{
				original = new object[1][] { item };
				return original;
			}
			object[][] array = new object[original.Length + 1][];
			Array.Copy(original, 0, array, 0, original.Length);
			array[original.Length] = item;
			return array;
		}

		public static bool CheckTrueOrFalse(Properties attributes, string key)
		{
			return Util.EqualsIgnoreCase("true", attributes[key]);
		}

		public static Uri ToURL(string filename)
		{
			try
			{
				return new Uri(filename);
			}
			catch
			{
				return new Uri(System.IO.Path.GetFullPath(filename));
			}
		}

		public static string UnEscapeURL(string src)
		{
			StringBuilder stringBuilder = new StringBuilder();
			char[] array = src.ToCharArray();
			for (int i = 0; i < array.Length; i++)
			{
				char c = array[i];
				if (c == '%')
				{
					if (i + 2 >= array.Length)
					{
						stringBuilder.Append(c);
						continue;
					}
					int hex = PRTokeniser.GetHex(array[i + 1]);
					int hex2 = PRTokeniser.GetHex(array[i + 2]);
					if (hex < 0 || hex2 < 0)
					{
						stringBuilder.Append(c);
						continue;
					}
					stringBuilder.Append((char)(hex * 16 + hex2));
					i += 2;
				}
				else
				{
					stringBuilder.Append(c);
				}
			}
			return stringBuilder.ToString();
		}

		public static void Skip(Stream istr, int size)
		{
			while (size > 0)
			{
				int num = istr.Read(skipBuffer, 0, Math.Min(skipBuffer.Length, size));
				if (num <= 0)
				{
					break;
				}
				size -= num;
			}
		}

		public static float MillimetersToPoints(float value)
		{
			return InchesToPoints(MillimetersToInches(value));
		}

		public static float MillimetersToInches(float value)
		{
			return value / 25.4f;
		}

		public static float PointsToMillimeters(float value)
		{
			return InchesToMillimeters(PointsToInches(value));
		}

		public static float PointsToInches(float value)
		{
			return value / 72f;
		}

		public static float InchesToMillimeters(float value)
		{
			return value * 25.4f;
		}

		public static float InchesToPoints(float value)
		{
			return value * 72f;
		}

		public static bool IsSurrogateHigh(char c)
		{
			if (c >= '\ud800')
			{
				return c <= '\udbff';
			}
			return false;
		}

		public static bool IsSurrogateLow(char c)
		{
			if (c >= '\udc00')
			{
				return c <= '\udfff';
			}
			return false;
		}

		public static bool IsSurrogatePair(string text, int idx)
		{
			if (idx < 0 || idx > text.Length - 2)
			{
				return false;
			}
			if (IsSurrogateHigh(text[idx]))
			{
				return IsSurrogateLow(text[idx + 1]);
			}
			return false;
		}

		public static bool IsSurrogatePair(char[] text, int idx)
		{
			if (idx < 0 || idx > text.Length - 2)
			{
				return false;
			}
			if (IsSurrogateHigh(text[idx]))
			{
				return IsSurrogateLow(text[idx + 1]);
			}
			return false;
		}

		public static int ConvertToUtf32(char highSurrogate, char lowSurrogate)
		{
			return (highSurrogate - 55296) * 1024 + (lowSurrogate - 56320) + 65536;
		}

		public static int ConvertToUtf32(char[] text, int idx)
		{
			return (text[idx] - 55296) * 1024 + (text[idx + 1] - 56320) + 65536;
		}

		public static int ConvertToUtf32(string text, int idx)
		{
			return (text[idx] - 55296) * 1024 + (text[idx + 1] - 56320) + 65536;
		}

		public static string ConvertFromUtf32(int codePoint)
		{
			if (codePoint < 65536)
			{
				return char.ToString((char)codePoint);
			}
			codePoint -= 65536;
			return new string(new char[2]
			{
				(char)(codePoint / 1024 + 55296),
				(char)(codePoint % 1024 + 56320)
			});
		}

		public static string ReadFileToString(string path)
		{
			using StreamReader streamReader = new StreamReader(path, Encoding.Default);
			return streamReader.ReadToEnd();
		}

		public static string ConvertToHex(byte[] bytes)
		{
			iTextSharp.text.pdf.ByteBuffer byteBuffer = new iTextSharp.text.pdf.ByteBuffer();
			foreach (byte b in bytes)
			{
				byteBuffer.AppendHex(b);
			}
			return PdfEncodings.ConvertToString(byteBuffer.ToByteArray(), null).ToUpper();
		}

		public static float ComputeTabSpace(float lx, float rx, float tab)
		{
			return ComputeTabSpace(rx - lx, tab);
		}

		public static float ComputeTabSpace(float width, float tab)
		{
			width = (float)Math.Round(width, 3);
			tab = (float)Math.Round(tab, 3);
			return tab - width % tab;
		}

		public static float Max(float[] array)
		{
			float num = array[0];
			for (int i = 1; i < array.Length; i++)
			{
				if (array[i] > num)
				{
					num = array[i];
				}
			}
			return num;
		}

		public static float Min(float[] array)
		{
			float num = array[0];
			for (int i = 1; i < array.Length; i++)
			{
				if (array[i] < num)
				{
					num = array[i];
				}
			}
			return num;
		}
	}
}
namespace iTextSharp.text.xml
{
	public abstract class ParserBase
	{
		public virtual void Parse(XmlDocument xDoc)
		{
			string outerXml = xDoc.OuterXml;
			StringReader input = new StringReader(outerXml);
			XmlTextReader xmlTextReader = new XmlTextReader(input);
			xmlTextReader.XmlResolver = null;
			xmlTextReader.ProhibitDtd = true;
			Parse(xmlTextReader);
		}

		public virtual void Parse(XmlTextReader reader)
		{
			reader.XmlResolver = null;
			reader.ProhibitDtd = true;
			try
			{
				while (reader.Read())
				{
					switch (reader.NodeType)
					{
					case XmlNodeType.Element:
					{
						string namespaceURI = reader.NamespaceURI;
						string name = reader.Name;
						bool isEmptyElement = reader.IsEmptyElement;
						Hashtable hashtable = new Hashtable();
						if (reader.HasAttributes)
						{
							for (int i = 0; i < reader.AttributeCount; i++)
							{
								reader.MoveToAttribute(i);
								hashtable.Add(reader.Name, reader.Value);
							}
						}
						StartElement(namespaceURI, name, name, hashtable);
						if (isEmptyElement)
						{
							EndElement(namespaceURI, name, name);
						}
						break;
					}
					case XmlNodeType.EndElement:
						EndElement(reader.NamespaceURI, reader.Name, reader.Name);
						break;
					case XmlNodeType.Text:
						Characters(reader.Value, 0, reader.Value.Length);
						break;
					case XmlNodeType.Whitespace:
						Characters(reader.Value, 0, reader.Value.Length);
						break;
					}
				}
			}
			catch (XmlException ex)
			{
				Console.Out.WriteLine(ex.Message);
			}
			finally
			{
				reader?.Close();
			}
		}

		public virtual void Parse(string url)
		{
			XmlTextReader xmlTextReader = null;
			xmlTextReader = new XmlTextReader(url);
			xmlTextReader.XmlResolver = null;
			xmlTextReader.ProhibitDtd = true;
			Parse(xmlTextReader);
		}

		public abstract void StartElement(string uri, string lname, string name, Hashtable attrs);

		public abstract void EndElement(string uri, string lname, string name);

		public abstract void Characters(string content, int start, int length);
	}
}
