		public static int GetEncodingNumber(string name)
		{
			name = name.ToUpper(CultureInfo.InvariantCulture);
			if (map.ContainsKey(name))
			{
				return map[name];
			}
			return 0;
		}

		public static Encoding GetEncodingEncoding(string name)
		{
			string text = name.ToUpper(CultureInfo.InvariantCulture);
			if (text.Equals("UNICODEBIGUNMARKED"))
			{
				return new UnicodeEncoding(bigEndian: true, byteOrderMark: false);
			}
			if (text.Equals("UNICODEBIG"))
			{
				return new UnicodeEncoding(bigEndian: true, byteOrderMark: true);
			}
			if (text.Equals("UNICODELITTLEUNMARKED"))
			{
				return new UnicodeEncoding(bigEndian: false, byteOrderMark: false);
			}
			if (text.Equals("UNICODELITTLE"))
			{
				return new UnicodeEncoding(bigEndian: false, byteOrderMark: true);
			}
			if (map.ContainsKey(text))
			{
				return Encoding.GetEncoding(map[text], new EncoderReplacementFallback(""), new DecoderReplacementFallback());
			}
			return Encoding.GetEncoding(name, new EncoderReplacementFallback(""), new DecoderReplacementFallback());
		}
