		{
			XmlNodeList elementsByTagName = domDocument.GetElementsByTagName(localName, namespaceURI);
			if (elementsByTagName.Count == 0)
			{
				return false;
			}
			for (int i = 0; i < elementsByTagName.Count; i++)
			{
				XmlNode n = elementsByTagName[i];
				SetNodeText(domDocument, n, value);
			}
			return true;
		}

		public virtual bool ReplaceDescriptionAttribute(string namespaceURI, string localName, string value)
		{
			XmlNodeList elementsByTagName = domDocument.GetElementsByTagName("Description", "http://www.w3.org/1999/02/22-rdf-syntax-ns#");
			if (elementsByTagName.Count == 0)
			{
				return false;
			}
			for (int i = 0; i < elementsByTagName.Count; i++)
			{
				XmlNode xmlNode = elementsByTagName.Item(i);
				XmlNode namedItem = xmlNode.Attributes.GetNamedItem(localName, namespaceURI);
				if (namedItem != null)
				{
					namedItem.Value = value;
					return true;
				}
			}
			return false;
		}

		public virtual bool Add(string parent, string namespaceURI, string localName, string value)
		{
			XmlNodeList elementsByTagName = domDocument.GetElementsByTagName(parent);
			if (elementsByTagName.Count == 0)
			{
				return false;
			}
			for (int i = 0; i < elementsByTagName.Count; i++)
			{
				XmlNode xmlNode = elementsByTagName[i];
				XmlAttributeCollection attributes = xmlNode.Attributes;
				for (int j = 0; j < attributes.Count; j++)
				{
					XmlNode xmlNode2 = attributes[j];
					if (namespaceURI.Equals(xmlNode2.Value))
					{
						string localName2 = xmlNode2.LocalName;
						xmlNode2 = domDocument.CreateElement(localName, namespaceURI);
						xmlNode2.Prefix = localName2;
						xmlNode2.AppendChild(domDocument.CreateTextNode(value));
						xmlNode.AppendChild(xmlNode2);
						return true;
					}
				}
			}
			return false;
		}

		public virtual bool SetNodeText(XmlDocument domDocument, XmlNode n, string value)
		{
			if (n == null)
			{
				return false;
			}
			XmlNode xmlNode = null;
			while ((xmlNode = n.FirstChild) != null)
			{
				n.RemoveChild(xmlNode);
			}
			domDocument.XmlResolver = null;
			n.AppendChild(domDocument.CreateTextNode(value));
			return true;
		}

		public virtual byte[] SerializeDoc()
		{
			XmlDomWriter xmlDomWriter = new XmlDomWriter();
			MemoryStream memoryStream = new MemoryStream();
			xmlDomWriter.SetOutput(memoryStream, null);
			byte[] bytes = new UTF8Encoding(encoderShouldEmitUTF8Identifier: false).GetBytes("<?xpacket begin=\"\ufeff\" id=\"W5M0MpCehiHzreSzNTczkc9d\"?>\n");
			memoryStream.Write(bytes, 0, bytes.Length);
			memoryStream.Flush();
			XmlNodeList elementsByTagName = domDocument.GetElementsByTagName("x:xmpmeta");
			xmlDomWriter.Write(elementsByTagName[0]);
			memoryStream.Flush();
			bytes = new UTF8Encoding(encoderShouldEmitUTF8Identifier: false).GetBytes("                                                                                                   \n");
			for (int i = 0; i < 20; i++)
			{
				memoryStream.Write(bytes, 0, bytes.Length);
			}
			bytes = new UTF8Encoding(encoderShouldEmitUTF8Identifier: false).GetBytes("<?xpacket end=\"w\"?>");
			memoryStream.Write(bytes, 0, bytes.Length);
			memoryStream.Close();
