	public abstract class FilterReader : TextReader
	{
		protected TextReader inp;

		protected FilterReader(TextReader inp)
		{
			this.inp = TextReader.Synchronized(inp);
		}

		public override int Read()
		{
			return inp.Read();
		}

		public override int Read(char[] cbuf, int off, int len)
		{
			return inp.Read(cbuf, off, len);
		}

		public override void Close()
		{
			inp.Close();
		}
	}
	public class PushbackReader : FilterReader
	{
		private char[] _buf;

		private int _pos;

		public PushbackReader(TextReader inp, int size)
			: base(inp)
		{
			if (size <= 0)
			{
				throw new ArgumentException("size <= 0");
			}
			_buf = new char[size];
			_pos = size;
		}

		public PushbackReader(TextReader inp)
			: this(inp, 1)
		{
		}

		private void EnsureOpen()
		{
			if (_buf == null)
			{
				throw new IOException("Stream closed");
			}
		}

		public override int Read()
		{
			EnsureOpen();
			if (_pos < _buf.Length)
			{
				return _buf[_pos++];
			}
			return base.Read();
		}

		public override int Read(char[] cbuf, int off, int len)
		{
			EnsureOpen();
			try
			{
				if (len <= 0)
				{
					if (len < 0)
					{
						throw new IndexOutOfRangeException();
					}
					if (off < 0 || off > cbuf.Length)
					{
						throw new IndexOutOfRangeException();
					}
					return 0;
				}
				int num = _buf.Length - _pos;
				if (num > 0)
				{
					if (len < num)
					{
						num = len;
					}
					Array.Copy(_buf, _pos, cbuf, off, num);
					_pos += num;
					off += num;
					len -= num;
				}
				if (len > 0)
				{
					len = base.Read(cbuf, off, len);
					if (len == -1)
					{
						return (num == 0) ? (-1) : num;
					}
					return num + len;
				}
				return num;
			}
			catch (IndexOutOfRangeException)
			{
				throw new IndexOutOfRangeException();
			}
		}

		public virtual void Unread(int c)
		{
			EnsureOpen();
			if (_pos == 0)
			{
				throw new IOException("Pushback buffer overflow");
			}
			_buf[--_pos] = (char)c;
		}

		public virtual void Unread(char[] cbuf, int off, int len)
		{
			EnsureOpen();
			if (len > _pos)
			{
				throw new IOException("Pushback buffer overflow");
			}
			_pos -= len;
			Array.Copy(cbuf, off, _buf, _pos, len);
		}

		public virtual void Unread(char[] cbuf)
		{
			Unread(cbuf, 0, cbuf.Length);
		}

		public override void Close()
		{
			base.Close();
			_buf = null;
		}
	}
	public class FixAsciiControlsReader : PushbackReader
	{
		private const int STATE_START = 0;

		private const int STATE_AMP = 1;

		private const int STATE_HASH = 2;

		private const int STATE_HEX = 3;

		private const int STATE_DIG1 = 4;

		private const int STATE_ERROR = 5;

		private const int BUFFER_SIZE = 8;

		private int _control;

		private int _digits;

		private int _state;

		public FixAsciiControlsReader(TextReader inp)
			: base(inp, 8)
		{
		}

		public override int Read(char[] cbuf, int off, int len)
		{
			int num = 0;
			int num2 = 0;
			int num3 = off;
			char[] array = new char[8];
			bool flag = true;
			while (flag && num2 < len)
			{
				flag = base.Read(array, num, 1) == 1;
				if (flag)
				{
					char c = ProcessChar(array[num]);
					if (_state == 0)
					{
						if (Utils.IsControlChar(c))
						{
							c = ' ';
						}
						cbuf[num3++] = c;
						num = 0;
						num2++;
					}
					else if (_state == 5)
					{
						Unread(array, 0, num + 1);
						num = 0;
					}
					else
					{
						num++;
					}
				}
				else if (num > 0)
				{
					Unread(array, 0, num);
					_state = 5;
					num = 0;
					flag = true;
				}
			}
			if (num2 <= 0 && !flag)
			{
				return -1;
			}
			return num2;
		}

		private char ProcessChar(char ch)
		{
			switch (_state)
			{
			case 0:
				if (ch == '&')
				{
					_state = 1;
				}
				return ch;
			case 1:
				_state = ((ch == '#') ? 2 : 5);
				return ch;
			case 2:
				if (ch == 'x')
				{
					_control = 0;
					_digits = 0;
					_state = 3;
				}
				else if ('0' <= ch && ch <= '9')
				{
					_control = Convert.ToInt32(ch.ToString(CultureInfo.InvariantCulture), 10);
					_digits = 1;
					_state = 4;
				}
				else
				{
					_state = 5;
				}
				return ch;
			case 4:
				if ('0' <= ch && ch <= '9')
				{
					_control = _control * 10 + Convert.ToInt32(ch.ToString(CultureInfo.InvariantCulture), 10);
					_digits++;
					_state = ((_digits <= 5) ? 4 : 5);
				}
				else
				{
					if (ch == ';' && Utils.IsControlChar((char)_control))
					{
						_state = 0;
						return (char)_control;
					}
					_state = 5;
				}
				return ch;
			case 3:
				if (('0' <= ch && ch <= '9') || ('a' <= ch && ch <= 'f') || ('A' <= ch && ch <= 'F'))
				{
					_control = _control * 16 + Convert.ToInt32(ch.ToString(CultureInfo.InvariantCulture), 16);
					_digits++;
					_state = ((_digits <= 4) ? 3 : 5);
				}
				else
				{
					if (ch == ';' && Utils.IsControlChar((char)_control))
					{
						_state = 0;
						return (char)_control;
					}
					_state = 5;
				}
				return ch;
			case 5:
				_state = 0;
				return ch;
			default:
				return ch;
			}
		}
	}
	public static class Iso8601Converter
	{
		public static IXmpDateTime Parse(string iso8601String)
		{
			return Parse(iso8601String, new XmpDateTimeImpl());
		}

		public static IXmpDateTime Parse(string iso8601String, IXmpDateTime binValue)
		{
			if (iso8601String == null)
			{
				throw new XmpException("Parameter must not be null", 4);
			}
			if (iso8601String.Length == 0)
			{
				return binValue;
			}
			ParseState parseState = new ParseState(iso8601String);
			if (parseState.Ch(0) == '-')
			{
				parseState.Skip();
			}
			int num = parseState.GatherInt("Invalid year in date string", 9999);
			if (parseState.HasNext() && parseState.Ch() != '-')
			{
				throw new XmpException("Invalid date string, after year", 5);
			}
			if (parseState.Ch(0) == '-')
			{
				num = -num;
			}
			binValue.Year = num;
			if (!parseState.HasNext())
			{
				return binValue;
			}
			parseState.Skip();
			num = parseState.GatherInt("Invalid month in date string", 12);
			if (parseState.HasNext() && parseState.Ch() != '-')
			{
				throw new XmpException("Invalid date string, after month", 5);
			}
			binValue.Month = num;
			if (!parseState.HasNext())
			{
				return binValue;
			}
			parseState.Skip();
			num = parseState.GatherInt("Invalid day in date string", 31);
			if (parseState.HasNext() && parseState.Ch() != 'T')
			{
				throw new XmpException("Invalid date string, after day", 5);
			}
			binValue.Day = num;
			if (!parseState.HasNext())
			{
				return binValue;
			}
			parseState.Skip();
			num = parseState.GatherInt("Invalid hour in date string", 23);
			binValue.Hour = num;
			if (!parseState.HasNext())
			{
				return binValue;
			}
			if (parseState.Ch() == ':')
			{
				parseState.Skip();
				num = parseState.GatherInt("Invalid minute in date string", 59);
				if (parseState.HasNext() && parseState.Ch() != ':' && parseState.Ch() != 'Z' && parseState.Ch() != '+' && parseState.Ch() != '-')
				{
					throw new XmpException("Invalid date string, after minute", 5);
				}
				binValue.Minute = num;
			}
			if (!parseState.HasNext())
			{
				return binValue;
			}
			if (parseState.HasNext() && parseState.Ch() == ':')
			{
				parseState.Skip();
				num = parseState.GatherInt("Invalid whole seconds in date string", 59);
				if (parseState.HasNext() && parseState.Ch() != '.' && parseState.Ch() != 'Z' && parseState.Ch() != '+' && parseState.Ch() != '-')
				{
					throw new XmpException("Invalid date string, after whole seconds", 5);
				}
				binValue.Second = num;
				if (parseState.Ch() == '.')
				{
					parseState.Skip();
					int num2 = parseState.Pos();
					num = parseState.GatherInt("Invalid fractional seconds in date string", 999999999);
					if (parseState.HasNext() && parseState.Ch() != 'Z' && parseState.Ch() != '+' && parseState.Ch() != '-')
					{
						throw new XmpException("Invalid date string, after fractional second", 5);
					}
					for (num2 = parseState.Pos() - num2; num2 > 9; num2--)
					{
						num /= 10;
					}
					for (; num2 < 9; num2++)
					{
						num *= 10;
					}
					binValue.NanoSecond = num;
				}
			}
			else if (parseState.Ch() != 'Z' && parseState.Ch() != '+' && parseState.Ch() != '-')
			{
				throw new XmpException("Invalid date string, after time", 5);
			}
			if (!parseState.HasNext())
			{
				return binValue;
			}
			if (parseState.Ch() == 'Z')
			{
				parseState.Skip();
			}
			else if (parseState.HasNext())
			{
				if (parseState.Ch() != '+' && parseState.Ch() != '-')
				{
					throw new XmpException("Time zone must begin with 'Z', '+', or '-'", 5);
				}
				parseState.Skip();
				if (parseState.HasNext())
				{
					if (parseState.Ch() != ':')
					{
						throw new XmpException("Invalid date string, after time zone hour", 5);
					}
					parseState.Skip();
				}
			}
			binValue.TimeZone = TimeZone.CurrentTimeZone;
			if (parseState.HasNext())
			{
				throw new XmpException("Invalid date string, extra chars at end", 5);
			}
			return binValue;
		}

		public static string Render(IXmpDateTime dateTime)
		{
			return dateTime.Calendar.DateTime.ToString("s");
		}
	}
	internal class ParseState
	{
		private readonly string _str;

		private int _pos;

		public ParseState(string str)
		{
			_str = str;
		}

		public virtual int Length()
		{
			return _str.Length;
		}

		public virtual bool HasNext()
		{
			return _pos < _str.Length;
		}

		public virtual char Ch(int index)
		{
			if (index >= _str.Length)
			{
				return '\0';
			}
			return _str[index];
		}

		public virtual char Ch()
		{
			if (_pos >= _str.Length)
			{
				return '\0';
			}
			return _str[_pos];
		}

		public virtual void Skip()
		{
			_pos++;
		}

		public virtual int Pos()
		{
			return _pos;
		}

		public virtual int GatherInt(string errorMsg, int maxValue)
		{
			int num = 0;
			bool flag = false;
			char c = Ch(_pos);
			while ('0' <= c && c <= '9')
			{
				num = num * 10 + (c - 48);
				flag = true;
				_pos++;
				c = Ch(_pos);
			}
			if (flag)
			{
				if (num > maxValue)
				{
					return maxValue;
				}
				if (num < 0)
				{
					return 0;
				}
				return num;
			}
			throw new XmpException(errorMsg, 5);
		}
	}
	public class Latin1Converter
	{
		private const int STATE_START = 0;

		private const int STATE_UTF8CHAR = 11;

		private Latin1Converter()
		{
		}

		public static ByteBuffer Convert(ByteBuffer buffer)
		{
			if ("UTF-8".Equals(buffer.Encoding))
			{
				byte[] array = new byte[8];
				int num = 0;
				int num2 = 0;
				ByteBuffer byteBuffer = new ByteBuffer(buffer.Length * 4 / 3);
				int num3 = 0;
				for (int i = 0; i < buffer.Length; i++)
				{
					int num4 = buffer.ByteAt(i);
					int num5 = num3;
					if (num5 == 0 || num5 != 11)
					{
						if (num4 < 127)
						{
							byteBuffer.Append((byte)num4);
						}
						else if (num4 >= 192)
						{
							num2 = -1;
							int num6 = num4;
							while (num2 < 8 && (num6 & 0x80) == 128)
							{
								num2++;
								num6 <<= 1;
							}
							array[num++] = (byte)num4;
							num3 = 11;
						}
						else
						{
							byte[] bytes = ConvertToUtf8((byte)num4);
							byteBuffer.Append(bytes);
						}
					}
					else if (num2 > 0 && (num4 & 0xC0) == 128)
					{
						array[num++] = (byte)num4;
						num2--;
						if (num2 == 0)
						{
							byteBuffer.Append(array, 0, num);
							num = 0;
							num3 = 0;
						}
					}
					else
					{
						byte[] bytes2 = ConvertToUtf8(array[0]);
						byteBuffer.Append(bytes2);
						i -= num;
						num = 0;
						num3 = 0;
					}
				}
				if (num3 == 11)
				{
					for (int j = 0; j < num; j++)
					{
						byte ch = array[j];
						byte[] bytes3 = ConvertToUtf8(ch);
						byteBuffer.Append(bytes3);
					}
				}
				return byteBuffer;
			}
			return buffer;
		}

		private static byte[] ConvertToUtf8(byte ch)
		{
			int num = ch & 0xFF;
			try
			{
				if (num >= 128)
				{
					if (num == 129 || num == 141 || num == 143 || num == 144 || num == 157)
					{
						return new byte[1] { 32 };
					}
					string @string = Encoding.Default.GetString(new byte[1] { ch });
					return Encoding.UTF8.GetBytes(@string);
				}
			}
			catch (Exception)
			{
			}
			return new byte[1] { ch };
		}
	}
