			}
			StringBuilder stringBuilder = new StringBuilder(value.Length * 4 / 3);
			foreach (char c2 in value)
			{
				if (!escapeWhitespaces || (c2 != '\t' && c2 != '\n' && c2 != '\r'))
				{
