				if (string.IsNullOrEmpty(parentPath))
				{
					return text2;
				}
				if (_outerInstance.Options.JustLeafname)
				{
					if (text2.StartsWith("?"))
					{
						return text2.Substring(1);
					}
					return text2;
				}
				return parentPath + text + text2;
