		public XmpNode(string name, string value, PropertyOptions options)
		{
			_name = name;
			_value = value;
			_options = options;
		}

		public XmpNode(string name, PropertyOptions options)
			: this(name, null, options)
		{
		}

		public virtual object Clone()
		{
			PropertyOptions options;
			try
			{
				options = new PropertyOptions(Options.Options);
			}
			catch (XmpException)
			{
				options = new PropertyOptions();
			}
			XmpNode xmpNode = new XmpNode(_name, _value, options);
			CloneSubtree(xmpNode);
			return xmpNode;
		}

		public virtual int CompareTo(object xmpNode)
		{
			if (Options.SchemaNode)
			{
				return _value.CompareTo(((XmpNode)xmpNode).Value);
			}
			return _name.CompareTo(((XmpNode)xmpNode).Name);
		}

		public virtual void Clear()
		{
			_options = null;
			_name = null;
			_value = null;
			_children = null;
			_qualifier = null;
		}

		public virtual XmpNode GetChild(int index)
		{
			return (XmpNode)Children[index - 1];
		}

		public virtual void AddChild(XmpNode node)
		{
			AssertChildNotExisting(node.Name);
			node.Parent = this;
			Children.Add(node);
		}

		public virtual void AddChild(int index, XmpNode node)
		{
			AssertChildNotExisting(node.Name);
			node.Parent = this;
			Children.Insert(index - 1, node);
		}

		public virtual void ReplaceChild(int index, XmpNode node)
		{
			node.Parent = this;
			Children[index - 1] = node;
		}

		public virtual void RemoveChild(int itemIndex)
		{
			Children.RemoveAt(itemIndex - 1);
			CleanupChildren();
		}

		public virtual void RemoveChild(XmpNode node)
		{
			Children.Remove(node);
			CleanupChildren();
		}

		protected internal virtual void CleanupChildren()
		{
			if (_children.Count == 0)
			{
				_children = null;
			}
		}

		public virtual void RemoveChildren()
		{
			_children = null;
		}

		public virtual XmpNode FindChildByName(string expr)
		{
			return find(Children, expr);
		}

		public virtual XmpNode GetQualifier(int index)
		{
			return (XmpNode)Qualifier[index - 1];
		}

		public virtual void AddQualifier(XmpNode qualNode)
		{
			AssertQualifierNotExisting(qualNode.Name);
			qualNode.Parent = this;
			qualNode.Options.Qualifier = true;
			Options.HasQualifiers = true;
			if (qualNode.LanguageNode)
			{
				_options.HasLanguage = true;
				Qualifier.Insert(0, qualNode);
			}
			else if (qualNode.TypeNode)
			{
				_options.HasType = true;
				Qualifier.Insert(_options.HasLanguage ? 1 : 0, qualNode);
			}
			else
			{
				Qualifier.Add(qualNode);
			}
		}

		public virtual void RemoveQualifier(XmpNode qualNode)
		{
			PropertyOptions options = Options;
			if (qualNode.LanguageNode)
			{
				options.HasLanguage = false;
			}
			else if (qualNode.TypeNode)
			{
				options.HasType = false;
			}
			Qualifier.Remove(qualNode);
			if (_qualifier.Count == 0)
			{
				options.HasQualifiers = false;
				_qualifier = null;
			}
		}

		public virtual void RemoveQualifiers()
		{
			PropertyOptions options = Options;
			options.HasQualifiers = false;
			options.HasLanguage = false;
			options.HasType = false;
			_qualifier = null;
		}

		public virtual XmpNode FindQualifierByName(string expr)
		{
			return find(_qualifier, expr);
		}

		public virtual bool HasChildren()
		{
			if (_children != null)
			{
				return _children.Count > 0;
			}
			return false;
		}

		public virtual IEnumerator IterateChildren()
		{
			if (_children != null)
			{
				return Children.GetEnumerator();
			}
			return EmptyList.GetEnumerator();
		}

		public virtual bool HasQualifier()
		{
			if (_qualifier != null)
			{
				return _qualifier.Count > 0;
			}
			return false;
		}

		public virtual IEnumerator IterateQualifier()
		{
			if (_qualifier != null)
			{
				return Qualifier.GetEnumerator();
			}
			return EmptyList.GetEnumerator();
		}

		public virtual void CloneSubtree(XmpNode destination)
		{
			try
			{
				foreach (XmpNode child in Children)
				{
					destination.AddChild((XmpNode)child.Clone());
				}
				foreach (XmpNode item in Qualifier)
				{
					destination.AddQualifier((XmpNode)item.Clone());
				}
			}
			catch (XmpException)
			{
			}
		}

		public virtual string DumpNode(bool recursive)
		{
			StringBuilder stringBuilder = new StringBuilder(512);
			DumpNode(stringBuilder, recursive, 0, 0);
			return stringBuilder.ToString();
		}

		public virtual void Sort()
		{
			if (HasQualifier())
			{
				XmpNode[] array = new XmpNode[Qualifier.Count];
				Qualifier.CopyTo(array, 0);
				int i;
				for (i = 0; array.Length > i && ("xml:lang".Equals(array[i].Name) || "rdf:type".Equals(array[i].Name)); i++)
				{
					array[i].Sort();
				}
				Array.Sort(array, i, array.Length - i);
				for (int j = 0; j < array.Length; j++)
				{
					_qualifier[j] = array[j];
					array[j].Sort();
				}
			}
			if (!HasChildren())
			{
				return;
			}
			if (!Options.Array)
			{
				ArrayList.Adapter(_children).Sort();
			}
			IEnumerator enumerator = IterateChildren();
			while (enumerator.MoveNext())
			{
				if (enumerator.Current != null)
				{
					((XmpNode)enumerator.Current).Sort();
				}
			}
		}

		private void DumpNode(StringBuilder result, bool recursive, int indent, int index)
		{
			for (int i = 0; i < indent; i++)
			{
				result.Append('\t');
			}
			if (_parent != null)
			{
				if (Options.Qualifier)
				{
					result.Append('?');
					result.Append(_name);
				}
				else if (Parent.Options.Array)
				{
					result.Append('[');
					result.Append(index);
					result.Append(']');
				}
				else
				{
					result.Append(_name);
				}
			}
			else
			{
				result.Append("ROOT NODE");
				if (!string.IsNullOrEmpty(_name))
				{
					result.Append(" (");
					result.Append(_name);
					result.Append(')');
				}
			}
			if (!string.IsNullOrEmpty(_value))
			{
				result.Append(" = \"");
				result.Append(_value);
				result.Append('"');
			}
			if (Options.ContainsOneOf(uint.MaxValue))
			{
				result.Append("\t(");
				result.Append(Options.ToString());
				result.Append(" : ");
				result.Append(Options.OptionsString);
				result.Append(')');
			}
			result.Append('\n');
			if (recursive && HasQualifier())
			{
				XmpNode[] array = new XmpNode[Qualifier.Count];
				Qualifier.CopyTo(array, 0);
				int j;
				for (j = 0; array.Length > j && ("xml:lang".Equals(array[j].Name) || "rdf:type".Equals(array[j].Name)); j++)
				{
				}
				Array.Sort(array, j, array.Length - j);
				for (j = 0; j < array.Length; j++)
				{
					XmpNode xmpNode = array[j];
					xmpNode.DumpNode(result, recursive, indent + 2, j + 1);
				}
			}
			if (recursive && HasChildren())
			{
				XmpNode[] array2 = new XmpNode[Children.Count];
				Children.CopyTo(array2, 0);
				if (!Options.Array)
				{
					Array.Sort(array2);
				}
				for (int k = 0; k < array2.Length; k++)
				{
					XmpNode xmpNode2 = array2[k];
					xmpNode2.DumpNode(result, recursive, indent + 1, k + 1);
				}
			}
		}

		private XmpNode find(IList list, string expr)
		{
			if (list != null)
			{
				foreach (XmpNode item in list)
				{
					if (item.Name.Equals(expr))
					{
						return item;
					}
				}
			}
			return null;
		}

		private void AssertChildNotExisting(string childName)
		{
			if (!"[]".Equals(childName) && FindChildByName(childName) != null)
			{
				throw new XmpException("Duplicate property or field node '" + childName + "'", 203);
			}
		}

		private void AssertQualifierNotExisting(string qualifierName)
		{
			if (!"[]".Equals(qualifierName) && FindQualifierByName(qualifierName) != null)
			{
				throw new XmpException("Duplicate '" + qualifierName + "' qualifier", 203);
			}
		}
	}
	public class XmpNodeUtils : XmpConst
	{
		internal const int CLT_NO_VALUES = 0;

		internal const int CLT_SPECIFIC_MATCH = 1;

		internal const int CLT_SINGLE_GENERIC = 2;

		internal const int CLT_MULTIPLE_GENERIC = 3;

		internal const int CLT_XDEFAULT = 4;

		internal const int CLT_FIRST_ITEM = 5;

		private XmpNodeUtils()
		{
		}

		internal static XmpNode FindSchemaNode(XmpNode tree, string namespaceUri, bool createNodes)
		{
			return FindSchemaNode(tree, namespaceUri, null, createNodes);
		}

		internal static XmpNode FindSchemaNode(XmpNode tree, string namespaceUri, string suggestedPrefix, bool createNodes)
		{
			XmpNode xmpNode = tree.FindChildByName(namespaceUri);
			if (xmpNode == null && createNodes)
			{
				PropertyOptions propertyOptions = new PropertyOptions();
				propertyOptions.SchemaNode = true;
				xmpNode = new XmpNode(namespaceUri, propertyOptions);
				xmpNode.Implicit = true;
				string text = XmpMetaFactory.SchemaRegistry.GetNamespacePrefix(namespaceUri);
				if (text == null)
				{
					if (string.IsNullOrEmpty(suggestedPrefix))
					{
						throw new XmpException("Unregistered schema namespace URI", 101);
					}
					text = XmpMetaFactory.SchemaRegistry.RegisterNamespace(namespaceUri, suggestedPrefix);
				}
				xmpNode.Value = text;
				tree.AddChild(xmpNode);
			}
			return xmpNode;
		}

		internal static XmpNode FindChildNode(XmpNode parent, string childName, bool createNodes)
		{
			if (!parent.Options.SchemaNode && !parent.Options.Struct)
			{
				if (!parent.Implicit)
				{
					throw new XmpException("Named children only allowed for schemas and structs", 102);
				}
				if (parent.Options.Array)
				{
					throw new XmpException("Named children not allowed for arrays", 102);
				}
				if (createNodes)
				{
					parent.Options.Struct = true;
				}
			}
			XmpNode xmpNode = parent.FindChildByName(childName);
			if (xmpNode == null && createNodes)
			{
				PropertyOptions options = new PropertyOptions();
				xmpNode = new XmpNode(childName, options);
				xmpNode.Implicit = true;
				parent.AddChild(xmpNode);
			}
			return xmpNode;
		}

		internal static XmpNode FindNode(XmpNode xmpTree, XmpPath xpath, bool createNodes, PropertyOptions leafOptions)
		{
			if (xpath == null || xpath.Size() == 0)
			{
				throw new XmpException("Empty XmpPath", 102);
			}
			XmpNode xmpNode = null;
			XmpNode xmpNode2 = FindSchemaNode(xmpTree, xpath.GetSegment(0).Name, createNodes);
			if (xmpNode2 == null)
			{
				return null;
			}
			if (xmpNode2.Implicit)
			{
				xmpNode2.Implicit = false;
				xmpNode = xmpNode2;
			}
			try
			{
				for (int i = 1; i < xpath.Size(); i++)
				{
					xmpNode2 = FollowXPathStep(xmpNode2, xpath.GetSegment(i), createNodes);
					if (xmpNode2 == null)
					{
						if (createNodes)
						{
							DeleteNode(xmpNode);
						}
						return null;
					}
					if (xmpNode2.Implicit)
					{
						xmpNode2.Implicit = false;
						if (i == 1 && xpath.GetSegment(i).Alias && xpath.GetSegment(i).AliasForm != 0)
						{
							xmpNode2.Options.SetOption(xpath.GetSegment(i).AliasForm, value: true);
						}
						else if (i < xpath.Size() - 1 && xpath.GetSegment(i).Kind == 1 && !xmpNode2.Options.CompositeProperty)
						{
							xmpNode2.Options.Struct = true;
						}
						if (xmpNode == null)
						{
							xmpNode = xmpNode2;
						}
					}
				}
			}
			catch (XmpException ex)
			{
				if (xmpNode != null)
				{
					DeleteNode(xmpNode);
				}
				throw ex;
			}
			if (xmpNode != null)
			{
				xmpNode2.Options.MergeWith(leafOptions);
				xmpNode2.Options = xmpNode2.Options;
			}
			return xmpNode2;
		}

		internal static void DeleteNode(XmpNode node)
		{
			XmpNode parent = node.Parent;
			if (node.Options.Qualifier)
			{
				parent.RemoveQualifier(node);
			}
			else
			{
				parent.RemoveChild(node);
			}
			if (!parent.HasChildren() && parent.Options.SchemaNode)
			{
				parent.Parent.RemoveChild(parent);
			}
		}

		internal static void SetNodeValue(XmpNode node, object value)
		{
			string value2 = SerializeNodeValue(value);
			if (!node.Options.Qualifier || !"xml:lang".Equals(node.Name))
			{
				node.Value = value2;
			}
			else
			{
				node.Value = Utils.NormalizeLangValue(value2);
			}
		}

		internal static PropertyOptions VerifySetOptions(PropertyOptions options, object itemValue)
		{
			if (options == null)
			{
				options = new PropertyOptions();
			}
			if (options.ArrayAltText)
			{
				options.ArrayAlternate = true;
			}
			if (options.ArrayAlternate)
			{
				options.ArrayOrdered = true;
			}
			if (options.ArrayOrdered)
			{
				options.Array = true;
			}
			if (options.CompositeProperty && itemValue != null && itemValue.ToString().Length > 0)
			{
				throw new XmpException("Structs and arrays can't have values", 103);
			}
			options.AssertConsistency(options.Options);
			return options;
		}

		internal static string SerializeNodeValue(object value)
		{
			string text;
			if (value == null)
			{
				text = null;
			}
			else if (value is bool? flag)
			{
				text = XmpUtils.ConvertFromBoolean(flag.Value);
			}
			else if (value is int? num)
			{
				text = XmpUtils.ConvertFromInteger(num.Value);
			}
			else if (value is long? num2)
			{
				text = XmpUtils.ConvertFromLong(num2.Value);
			}
			else if (value is double? num3)
			{
				text = XmpUtils.ConvertFromDouble(num3.Value);
			}
			else if (value is IXmpDateTime)
			{
				text = XmpUtils.ConvertFromDate((IXmpDateTime)value);
			}
			else if (!(value is XmpCalendar))
			{
				text = ((!(value is byte[])) ? value.ToString() : XmpUtils.EncodeBase64((byte[])value));
			}
			else
			{
				IXmpDateTime value2 = XmpDateTimeFactory.CreateFromCalendar((XmpCalendar)value);
				text = XmpUtils.ConvertFromDate(value2);
			}
			if (text == null)
			{
				return null;
			}
			return Utils.RemoveControlChars(text);
		}

		private static XmpNode FollowXPathStep(XmpNode parentNode, XmpPathSegment nextStep, bool createNodes)
		{
			XmpNode result = null;
			uint kind = nextStep.Kind;
			switch (kind)
			{
			case 1u:
				result = FindChildNode(parentNode, nextStep.Name, createNodes);
				break;
			case 2u:
				result = FindQualifierNode(parentNode, nextStep.Name.Substring(1), createNodes);
				break;
			default:
			{
				if (!parentNode.Options.Array)
				{
					throw new XmpException("Indexing applied to non-array", 102);
				}
				int num;
				switch (kind)
				{
				case 3u:
					num = FindIndexedItem(parentNode, nextStep.Name, createNodes);
					break;
				case 4u:
					num = parentNode.ChildrenLength;
					break;
				case 6u:
				{
					string[] array2 = Utils.SplitNameAndValue(nextStep.Name);
					string fieldName = array2[0];
					string fieldValue = array2[1];
					num = LookupFieldSelector(parentNode, fieldName, fieldValue);
					break;
				}
				case 5u:
				{
					string[] array = Utils.SplitNameAndValue(nextStep.Name);
					string qualName = array[0];
					string qualValue = array[1];
					num = LookupQualSelector(parentNode, qualName, qualValue, nextStep.AliasForm);
					break;
				}
				default:
					throw new XmpException("Unknown array indexing step in FollowXPathStep", 9);
				}
				if (1 <= num && num <= parentNode.ChildrenLength)
				{
					result = parentNode.GetChild(num);
				}
				break;
			}
			}
			return result;
		}

		private static XmpNode FindQualifierNode(XmpNode parent, string qualName, bool createNodes)
		{
			XmpNode xmpNode = parent.FindQualifierByName(qualName);
			if (xmpNode == null && createNodes)
			{
				xmpNode = new XmpNode(qualName, null);
				xmpNode.Implicit = true;
				parent.AddQualifier(xmpNode);
			}
			return xmpNode;
		}

		private static int FindIndexedItem(XmpNode arrayNode, string segment, bool createNodes)
		{
			int num;
			try
			{
				segment = segment.Substring(1, segment.Length - 1 - 1);
				num = Convert.ToInt32(segment);
				if (num < 1)
				{
					throw new XmpException("Array index must be larger than zero", 102);
				}
			}
			catch (FormatException)
			{
				throw new XmpException("Array index not digits.", 102);
			}
			if (createNodes && num == arrayNode.ChildrenLength + 1)
			{
				XmpNode xmpNode = new XmpNode("[]", null);
				xmpNode.Implicit = true;
				arrayNode.AddChild(xmpNode);
			}
			return num;
		}

		private static int LookupFieldSelector(XmpNode arrayNode, string fieldName, string fieldValue)
		{
			int num = -1;
			for (int i = 1; i <= arrayNode.ChildrenLength; i++)
			{
				if (num >= 0)
				{
					break;
				}
				XmpNode child = arrayNode.GetChild(i);
				if (!child.Options.Struct)
				{
					throw new XmpException("Field selector must be used on array of struct", 102);
				}
				for (int j = 1; j <= child.ChildrenLength; j++)
				{
					XmpNode child2 = child.GetChild(j);
					if (fieldName.Equals(child2.Name) && fieldValue.Equals(child2.Value))
					{
						num = i;
						break;
					}
				}
			}
			return num;
		}

		private static int LookupQualSelector(XmpNode arrayNode, string qualName, string qualValue, uint aliasForm)
		{
			if ("xml:lang".Equals(qualName))
			{
				qualValue = Utils.NormalizeLangValue(qualValue);
				int num = LookupLanguageItem(arrayNode, qualValue);
				if (num < 0 && (aliasForm & 0x1000u) != 0)
				{
					XmpNode xmpNode = new XmpNode("[]", null);
					XmpNode qualNode = new XmpNode("xml:lang", "x-default", null);
					xmpNode.AddQualifier(qualNode);
					arrayNode.AddChild(1, xmpNode);
					return 1;
				}
				return num;
			}
			for (int i = 1; i < arrayNode.ChildrenLength; i++)
			{
				XmpNode child = arrayNode.GetChild(i);
				IEnumerator enumerator = child.IterateQualifier();
				while (enumerator.MoveNext())
				{
					XmpNode xmpNode2 = (XmpNode)enumerator.Current;
					if (xmpNode2 != null && qualName.Equals(xmpNode2.Name) && qualValue.Equals(xmpNode2.Value))
					{
						return i;
					}
				}
			}
			return -1;
		}

		internal static void NormalizeLangArray(XmpNode arrayNode)
		{
			if (!arrayNode.Options.ArrayAltText)
			{
				return;
			}
			for (int i = 2; i <= arrayNode.ChildrenLength; i++)
			{
				XmpNode child = arrayNode.GetChild(i);
				if (child.HasQualifier() && "x-default".Equals(child.GetQualifier(1).Value))
				{
					try
					{
						arrayNode.RemoveChild(i);
						arrayNode.AddChild(1, child);
					}
					catch (XmpException)
					{
					}
					if (i == 2)
					{
						arrayNode.GetChild(2).Value = child.Value;
					}
					break;
				}
			}
		}

		internal static void DetectAltText(XmpNode arrayNode)
		{
			if (!arrayNode.Options.ArrayAlternate || !arrayNode.HasChildren())
			{
				return;
			}
			bool flag = false;
			IEnumerator enumerator = arrayNode.IterateChildren();
			while (enumerator.MoveNext())
			{
				XmpNode xmpNode = (XmpNode)enumerator.Current;
				if (xmpNode != null && xmpNode.Options != null && xmpNode.Options.HasLanguage)
				{
					flag = true;
					break;
				}
			}
			if (flag)
			{
				arrayNode.Options.ArrayAltText = true;
				NormalizeLangArray(arrayNode);
			}
		}

		internal static void AppendLangItem(XmpNode arrayNode, string itemLang, string itemValue)
		{
			XmpNode xmpNode = new XmpNode("[]", itemValue, null);
			XmpNode xmpNode2 = new XmpNode("xml:lang", itemLang, null);
			xmpNode.AddQualifier(xmpNode2);
			if (!"x-default".Equals(xmpNode2.Value))
			{
				arrayNode.AddChild(xmpNode);
			}
			else
			{
				arrayNode.AddChild(1, xmpNode);
			}
		}

		internal static object[] ChooseLocalizedText(XmpNode arrayNode, string genericLang, string specificLang)
		{
			if (!arrayNode.Options.ArrayAltText)
			{
				throw new XmpException("Localized text array is not alt-text", 102);
			}
			if (!arrayNode.HasChildren())
			{
				return new object[2] { 0, null };
			}
			int num = 0;
			XmpNode xmpNode = null;
			XmpNode xmpNode2 = null;
			IEnumerator enumerator = arrayNode.IterateChildren();
			while (enumerator.MoveNext())
			{
				XmpNode xmpNode3 = (XmpNode)enumerator.Current;
				if (xmpNode3 == null || xmpNode3.Options == null || xmpNode3.Options.CompositeProperty)
				{
					throw new XmpException("Alt-text array item is not simple", 102);
				}
				if (!xmpNode3.HasQualifier() || !"xml:lang".Equals(xmpNode3.GetQualifier(1).Name))
				{
					throw new XmpException("Alt-text array item has no language qualifier", 102);
				}
				string value = xmpNode3.GetQualifier(1).Value;
				if (specificLang.Equals(value))
				{
					return new object[2] { 1, xmpNode3 };
				}
				if (genericLang != null && value.StartsWith(genericLang))
				{
					if (xmpNode == null)
					{
						xmpNode = xmpNode3;
					}
					num++;
				}
				else if ("x-default".Equals(value))
				{
					xmpNode2 = xmpNode3;
				}
			}
			if (num == 1)
			{
				return new object[2] { 2, xmpNode };
			}
			if (num > 1)
			{
				return new object[2] { 3, xmpNode };
			}
			if (xmpNode2 != null)
			{
				return new object[2] { 4, xmpNode2 };
			}
			return new object[2]
			{
				5,
				arrayNode.GetChild(1)
			};
		}

		internal static int LookupLanguageItem(XmpNode arrayNode, string language)
		{
			if (!arrayNode.Options.Array)
			{
				throw new XmpException("Language item must be used on array", 102);
			}
			for (int i = 1; i <= arrayNode.ChildrenLength; i++)
			{
				XmpNode child = arrayNode.GetChild(i);
				if (child.HasQualifier() && "xml:lang".Equals(child.GetQualifier(1).Name) && language.Equals(child.GetQualifier(1).Value))
				{
					return i;
				}
			}
			return -1;
		}
	}
	public class XmpNormalizer
	{
		private static IDictionary _dcArrayForms;

		static XmpNormalizer()
		{
			InitDcArrays();
		}

		private XmpNormalizer()
		{
		}

		internal static IXmpMeta Process(XmpMetaImpl xmp, ParseOptions options)
		{
			XmpNode root = xmp.Root;
			TouchUpDataModel(xmp);
			MoveExplicitAliases(root, options);
			TweakOldXmp(root);
			DeleteEmptySchemas(root);
			return xmp;
		}

		private static void TweakOldXmp(XmpNode tree)
		{
			if (tree.Name == null || tree.Name.Length < Utils.UUID_LENGTH)
			{
				return;
			}
			string text = tree.Name.ToLower();
			if (text.StartsWith("uuid:"))
			{
				text = text.Substring(5);
			}
			if (Utils.CheckUuidFormat(text))
			{
				XmpPath xpath = XmpPathParser.ExpandXPath("http://ns.adobe.com/xap/1.0/mm/", "InstanceID");
				XmpNode xmpNode = XmpNodeUtils.FindNode(tree, xpath, createNodes: true, null);
				if (xmpNode == null)
				{
					throw new XmpException("Failure creating xmpMM:InstanceID", 9);
				}
				xmpNode.Options = null;
				xmpNode.Value = "uuid:" + text;
				xmpNode.RemoveChildren();
				xmpNode.RemoveQualifiers();
				tree.Name = null;
			}
		}

		private static void TouchUpDataModel(XmpMetaImpl xmp)
		{
			XmpNodeUtils.FindSchemaNode(xmp.Root, "http://purl.org/dc/elements/1.1/", createNodes: true);
			IEnumerator enumerator = xmp.Root.IterateChildren();
			while (enumerator.MoveNext())
			{
				XmpNode xmpNode = (XmpNode)enumerator.Current;
				if (xmpNode != null && "http://purl.org/dc/elements/1.1/".Equals(xmpNode.Name))
				{
					NormalizeDcArrays(xmpNode);
				}
				else if (xmpNode != null && "http://ns.adobe.com/exif/1.0/".Equals(xmpNode.Name))
				{
					FixGpsTimeStamp(xmpNode);
					XmpNode xmpNode2 = XmpNodeUtils.FindChildNode(xmpNode, "exif:UserComment", createNodes: false);
					if (xmpNode2 != null)
					{
						RepairAltText(xmpNode2);
					}
				}
				else if (xmpNode != null && "http://ns.adobe.com/xmp/1.0/DynamicMedia/".Equals(xmpNode.Name))
				{
					XmpNode xmpNode3 = XmpNodeUtils.FindChildNode(xmpNode, "xmpDM:copyright", createNodes: false);
					if (xmpNode3 != null)
					{
						MigrateAudioCopyright(xmp, xmpNode3);
					}
				}
				else if (xmpNode != null && "http://ns.adobe.com/xap/1.0/rights/".Equals(xmpNode.Name))
				{
					XmpNode xmpNode4 = XmpNodeUtils.FindChildNode(xmpNode, "xmpRights:UsageTerms", createNodes: false);
					if (xmpNode4 != null)
					{
						RepairAltText(xmpNode4);
					}
				}
			}
		}

		private static void NormalizeDcArrays(XmpNode dcSchema)
		{
			for (int i = 1; i <= dcSchema.ChildrenLength; i++)
			{
				XmpNode child = dcSchema.GetChild(i);
				PropertyOptions propertyOptions = (PropertyOptions)_dcArrayForms[child.Name];
				if (propertyOptions == null)
				{
					continue;
				}
				if (child.Options.Simple)
				{
					XmpNode xmpNode = new XmpNode(child.Name, propertyOptions);
					child.Name = "[]";
					xmpNode.AddChild(child);
					dcSchema.ReplaceChild(i, xmpNode);
					if (propertyOptions.ArrayAltText && !child.Options.HasLanguage)
					{
						XmpNode qualNode = new XmpNode("xml:lang", "x-default", null);
						child.AddQualifier(qualNode);
					}
				}
				else
				{
					child.Options.SetOption(7680u, value: false);
					child.Options.MergeWith(propertyOptions);
					if (propertyOptions.ArrayAltText)
					{
						RepairAltText(child);
					}
				}
			}
		}

		private static void RepairAltText(XmpNode arrayNode)
		{
			if (arrayNode == null || !arrayNode.Options.Array)
			{
				return;
			}
			arrayNode.Options.ArrayOrdered = true;
			arrayNode.Options.ArrayAlternate = true;
			arrayNode.Options.ArrayAltText = true;
			ArrayList arrayList = new ArrayList();
			IEnumerator enumerator = arrayNode.IterateChildren();
			while (enumerator.MoveNext())
			{
				XmpNode xmpNode = (XmpNode)enumerator.Current;
				if (xmpNode == null)
				{
					continue;
				}
				if (xmpNode.Options.CompositeProperty)
				{
					arrayList.Add(xmpNode);
				}
				else if (!xmpNode.Options.HasLanguage)
				{
					string value = xmpNode.Value;
					if (string.IsNullOrEmpty(value))
					{
						arrayList.Add(xmpNode);
						continue;
					}
					XmpNode qualNode = new XmpNode("xml:lang", "x-repair", null);
					xmpNode.AddQualifier(qualNode);
				}
			}
			foreach (object item in arrayList)
			{
				arrayNode.Children.Remove(item);
			}
		}

		private static void MoveExplicitAliases(XmpNode tree, ParseOptions options)
		{
			if (!tree.HasAliases)
			{
				return;
			}
			tree.HasAliases = false;
			bool strictAliasing = options.StrictAliasing;
			IEnumerator enumerator = tree.UnmodifiableChildren.GetEnumerator();
			while (enumerator.MoveNext())
			{
				XmpNode xmpNode = (XmpNode)enumerator.Current;
				if (xmpNode == null || !xmpNode.HasAliases)
				{
					continue;
				}
				ArrayList arrayList = new ArrayList();
				IEnumerator enumerator2 = xmpNode.IterateChildren();
				while (enumerator2.MoveNext())
				{
					XmpNode xmpNode2 = (XmpNode)enumerator2.Current;
					if (xmpNode2 == null || !xmpNode2.Alias)
					{
						continue;
					}
					xmpNode2.Alias = false;
					IXmpAliasInfo xmpAliasInfo = XmpMetaFactory.SchemaRegistry.FindAlias(xmpNode2.Name);
					if (xmpAliasInfo == null)
					{
						continue;
					}
					XmpNode xmpNode3 = XmpNodeUtils.FindSchemaNode(tree, xmpAliasInfo.Namespace, null, createNodes: true);
					xmpNode3.Implicit = false;
					XmpNode xmpNode4 = XmpNodeUtils.FindChildNode(xmpNode3, xmpAliasInfo.Prefix + xmpAliasInfo.PropName, createNodes: false);
					if (xmpNode4 == null)
					{
						if (xmpAliasInfo.AliasForm.Simple)
						{
							string name = xmpAliasInfo.Prefix + xmpAliasInfo.PropName;
							xmpNode2.Name = name;
							xmpNode3.AddChild(xmpNode2);
						}
						else
						{
							xmpNode4 = new XmpNode(xmpAliasInfo.Prefix + xmpAliasInfo.PropName, xmpAliasInfo.AliasForm.ToPropertyOptions());
							xmpNode3.AddChild(xmpNode4);
							TransplantArrayItemAlias(xmpNode2, xmpNode4);
						}
						arrayList.Add(xmpNode2);
						continue;
					}
					if (xmpAliasInfo.AliasForm.Simple)
					{
						if (strictAliasing)
						{
							CompareAliasedSubtrees(xmpNode2, xmpNode4, outerCall: true);
						}
						arrayList.Add(xmpNode2);
						continue;
					}
					XmpNode xmpNode5 = null;
					if (xmpAliasInfo.AliasForm.ArrayAltText)
					{
						int num = XmpNodeUtils.LookupLanguageItem(xmpNode4, "x-default");
						if (num != -1)
						{
							xmpNode5 = xmpNode4.GetChild(num);
						}
					}
					else if (xmpNode4.HasChildren())
					{
						xmpNode5 = xmpNode4.GetChild(1);
					}
					if (xmpNode5 == null)
					{
						TransplantArrayItemAlias(xmpNode2, xmpNode4);
					}
					else if (strictAliasing)
					{
						CompareAliasedSubtrees(xmpNode2, xmpNode5, outerCall: true);
					}
					arrayList.Add(xmpNode2);
				}
				foreach (object item in arrayList)
				{
					xmpNode.Children.Remove(item);
				}
				arrayList.Clear();
				xmpNode.HasAliases = false;
			}
		}

		private static void TransplantArrayItemAlias(XmpNode childNode, XmpNode baseArray)
		{
			if (baseArray.Options.ArrayAltText)
			{
				if (childNode.Options.HasLanguage)
				{
					throw new XmpException("Alias to x-default already has a language qualifier", 203);
				}
				XmpNode qualNode = new XmpNode("xml:lang", "x-default", null);
				childNode.AddQualifier(qualNode);
			}
			childNode.Name = "[]";
			baseArray.AddChild(childNode);
		}

		private static void FixGpsTimeStamp(XmpNode exifSchema)
		{
			XmpNode xmpNode = XmpNodeUtils.FindChildNode(exifSchema, "exif:GPSTimeStamp", createNodes: false);
			if (xmpNode == null)
			{
				return;
			}
			try
			{
				IXmpDateTime xmpDateTime = XmpUtils.ConvertToDate(xmpNode.Value);
				if (xmpDateTime.Year == 0 && xmpDateTime.Month == 0 && xmpDateTime.Day == 0)
				{
					XmpNode xmpNode2 = XmpNodeUtils.FindChildNode(exifSchema, "exif:DateTimeOriginal", createNodes: false);
					xmpNode2 = xmpNode2 ?? XmpNodeUtils.FindChildNode(exifSchema, "exif:DateTimeDigitized", createNodes: false);
					IXmpDateTime xmpDateTime2 = XmpUtils.ConvertToDate(xmpNode2.Value);
					XmpCalendar calendar = xmpDateTime.Calendar;
					DateTime dateTime = new DateTime(xmpDateTime2.Year, xmpDateTime2.Month, xmpDateTime2.Day, calendar.DateTime.Hour, calendar.DateTime.Minute, calendar.DateTime.Second, calendar.DateTime.Millisecond);
					calendar.DateTime = dateTime;
					xmpDateTime = new XmpDateTimeImpl(calendar);
					xmpNode.Value = XmpUtils.ConvertFromDate(xmpDateTime);
				}
			}
			catch (XmpException)
			{
			}
		}

		private static void DeleteEmptySchemas(XmpNode tree)
		{
			ArrayList arrayList = new ArrayList();
			foreach (XmpNode child in tree.Children)
			{
				if (!child.HasChildren())
				{
					arrayList.Add(child);
				}
			}
			foreach (XmpNode item in arrayList)
			{
				tree.Children.Remove(item);
			}
		}

		private static void CompareAliasedSubtrees(XmpNode aliasNode, XmpNode baseNode, bool outerCall)
		{
			if (!aliasNode.Value.Equals(baseNode.Value) || aliasNode.ChildrenLength != baseNode.ChildrenLength)
			{
				throw new XmpException("Mismatch between alias and base nodes", 203);
			}
			if (!outerCall && (!aliasNode.Name.Equals(baseNode.Name) || !aliasNode.Options.Equals(baseNode.Options) || aliasNode.QualifierLength != baseNode.QualifierLength))
			{
				throw new XmpException("Mismatch between alias and base nodes", 203);
			}
			IEnumerator enumerator = aliasNode.IterateChildren();
			IEnumerator enumerator2 = baseNode.IterateChildren();
			while (enumerator.MoveNext() && enumerator2.MoveNext())
			{
				XmpNode aliasNode2 = (XmpNode)enumerator.Current;
				XmpNode baseNode2 = (XmpNode)enumerator2.Current;
				CompareAliasedSubtrees(aliasNode2, baseNode2, outerCall: false);
			}
			IEnumerator enumerator3 = aliasNode.IterateQualifier();
			IEnumerator enumerator4 = baseNode.IterateQualifier();
			while (enumerator3.MoveNext() && enumerator4.MoveNext())
			{
				XmpNode aliasNode3 = (XmpNode)enumerator3.Current;
				XmpNode baseNode3 = (XmpNode)enumerator4.Current;
				CompareAliasedSubtrees(aliasNode3, baseNode3, outerCall: false);
			}
		}

		private static void MigrateAudioCopyright(IXmpMeta xmp, XmpNode dmCopyright)
		{
			try
			{
				XmpNode parent = XmpNodeUtils.FindSchemaNode(((XmpMetaImpl)xmp).Root, "http://purl.org/dc/elements/1.1/", createNodes: true);
				string value = dmCopyright.Value;
				XmpNode xmpNode = XmpNodeUtils.FindChildNode(parent, "dc:rights", createNodes: false);
				if (xmpNode == null || !xmpNode.HasChildren())
				{
					value = "\n\n" + value;
					xmp.SetLocalizedText("http://purl.org/dc/elements/1.1/", "rights", "", "x-default", value, null);
				}
				else
				{
					int num = XmpNodeUtils.LookupLanguageItem(xmpNode, "x-default");
					if (num < 0)
					{
						string value2 = xmpNode.GetChild(1).Value;
						xmp.SetLocalizedText("http://purl.org/dc/elements/1.1/", "rights", "", "x-default", value2, null);
						num = XmpNodeUtils.LookupLanguageItem(xmpNode, "x-default");
					}
					XmpNode child = xmpNode.GetChild(num);
					string value3 = child.Value;
					int num2 = value3.IndexOf("\n\n");
					if (num2 < 0)
					{
						if (!value.Equals(value3))
						{
							child.Value = value3 + "\n\n" + value;
						}
					}
					else if (!value3.Substring(num2 + 2).Equals(value))
					{
						child.Value = value3.Substring(0, num2 + 2) + value;
					}
				}
				dmCopyright.Parent.RemoveChild(dmCopyright);
			}
			catch (XmpException)
			{
			}
		}

		private static void InitDcArrays()
		{
			_dcArrayForms = new Hashtable();
			PropertyOptions propertyOptions = new PropertyOptions();
			propertyOptions.Array = true;
			_dcArrayForms["dc:contributor"] = propertyOptions;
			_dcArrayForms["dc:language"] = propertyOptions;
			_dcArrayForms["dc:publisher"] = propertyOptions;
			_dcArrayForms["dc:relation"] = propertyOptions;
			_dcArrayForms["dc:subject"] = propertyOptions;
			_dcArrayForms["dc:type"] = propertyOptions;
			PropertyOptions propertyOptions2 = new PropertyOptions();
			propertyOptions2.Array = true;
			propertyOptions2.ArrayOrdered = true;
			_dcArrayForms["dc:creator"] = propertyOptions2;
			_dcArrayForms["dc:date"] = propertyOptions2;
			PropertyOptions propertyOptions3 = new PropertyOptions();
			propertyOptions3.Array = true;
			propertyOptions3.ArrayOrdered = true;
			propertyOptions3.ArrayAlternate = true;
			propertyOptions3.ArrayAltText = true;
			_dcArrayForms["dc:description"] = propertyOptions3;
			_dcArrayForms["dc:rights"] = propertyOptions3;
			_dcArrayForms["dc:title"] = propertyOptions3;
		}
	}
}
namespace iTextSharp.xmp
{
	public interface IXmpSchemaRegistry
	{
		string RegisterNamespace(string namespaceUri, string suggestedPrefix);

		string GetNamespacePrefix(string namespaceUri);

		string GetNamespaceUri(string namespacePrefix);

		IDictionary GetNamespaces();

		IDictionary GetPrefixes();

		void DeleteNamespace(string namespaceUri);

		IXmpAliasInfo ResolveAlias(string aliasNs, string aliasProp);

		IXmpAliasInfo[] FindAliases(string aliasNs);

		IXmpAliasInfo FindAlias(string qname);

		IDictionary GetAliases();
	}
}
namespace iTextSharp.xmp.impl
{
	public sealed class XmpSchemaRegistryImpl : XmpConst, IXmpSchemaRegistry
	{
		private class XmpAliasInfoImpl : IXmpAliasInfo
		{
			private readonly AliasOptions _aliasForm;

			private readonly string _namespace;

			private readonly string _prefix;

			private readonly string _propName;

			public string Namespace => _namespace;

			public string Prefix => _prefix;

			public string PropName => _propName;

			public AliasOptions AliasForm => _aliasForm;

			public XmpAliasInfoImpl(string @namespace, string prefix, string propName, AliasOptions aliasForm)
			{
				_namespace = @namespace;
				_prefix = prefix;
				_propName = propName;
				_aliasForm = aliasForm;
			}

			public override string ToString()
			{
				return string.Concat(Prefix, PropName, " NS(", Namespace, "), FORM (", AliasForm, ")");
			}
		}

		private readonly IDictionary _aliasMap = new Hashtable();

		private readonly IDictionary _namespaceToPrefixMap = new Hashtable();

		private readonly IDictionary _prefixToNamespaceMap = new Hashtable();

		private readonly Regex _regex = new Regex("[/*?\\[\\]]");

		public XmpSchemaRegistryImpl()
		{
			try
			{
				RegisterStandardNamespaces();
				RegisterStandardAliases();
			}
			catch (XmpException)
			{
				throw new Exception("The XMPSchemaRegistry cannot be initialized!");
			}
		}

		[MethodImpl(MethodImplOptions.Synchronized)]
		public string RegisterNamespace(string namespaceUri, string suggestedPrefix)
		{
			ParameterAsserts.AssertSchemaNs(namespaceUri);
			ParameterAsserts.AssertPrefix(suggestedPrefix);
			if (suggestedPrefix[suggestedPrefix.Length - 1] != ':')
			{
				suggestedPrefix += ':';
			}
			if (!Utils.IsXmlNameNs(suggestedPrefix.Substring(0, suggestedPrefix.Length - 1)))
			{
				throw new XmpException("The prefix is a bad XML name", 201);
			}
			string text = (string)_namespaceToPrefixMap[namespaceUri];
			string text2 = (string)_prefixToNamespaceMap[suggestedPrefix];
			if (text != null)
			{
				return text;
			}
			if (text2 != null)
			{
				string text3 = suggestedPrefix;
				int num = 1;
				while (_prefixToNamespaceMap.Contains(text3))
				{
					text3 = suggestedPrefix.Substring(0, suggestedPrefix.Length - 1) + "_" + num + "_:";
					num++;
				}
				suggestedPrefix = text3;
			}
			_prefixToNamespaceMap[suggestedPrefix] = namespaceUri;
			_namespaceToPrefixMap[namespaceUri] = suggestedPrefix;
			return suggestedPrefix;
		}

		[MethodImpl(MethodImplOptions.Synchronized)]
		public void DeleteNamespace(string namespaceUri)
		{
			string namespacePrefix = GetNamespacePrefix(namespaceUri);
			if (namespacePrefix != null)
			{
				_namespaceToPrefixMap.Remove(namespaceUri);
				_prefixToNamespaceMap.Remove(namespacePrefix);
			}
		}

		[MethodImpl(MethodImplOptions.Synchronized)]
		public string GetNamespacePrefix(string namespaceUri)
		{
			return (string)_namespaceToPrefixMap[namespaceUri];
		}

		[MethodImpl(MethodImplOptions.Synchronized)]
		public string GetNamespaceUri(string namespacePrefix)
		{
			if (namespacePrefix != null && !namespacePrefix.EndsWith(":"))
			{
				namespacePrefix += ":";
			}
			return (string)_prefixToNamespaceMap[namespacePrefix];
		}

		[MethodImpl(MethodImplOptions.Synchronized)]
		public IXmpAliasInfo ResolveAlias(string aliasNs, string aliasProp)
		{
			string namespacePrefix = GetNamespacePrefix(aliasNs);
			if (namespacePrefix == null)
			{
				return null;
			}
			return (IXmpAliasInfo)_aliasMap[namespacePrefix + aliasProp];
		}

		[MethodImpl(MethodImplOptions.Synchronized)]
		public IXmpAliasInfo FindAlias(string qname)
		{
			return (IXmpAliasInfo)_aliasMap[qname];
		}

		[MethodImpl(MethodImplOptions.Synchronized)]
		public IXmpAliasInfo[] FindAliases(string aliasNs)
		{
			string namespacePrefix = GetNamespacePrefix(aliasNs);
			IList list = new ArrayList();
			if (namespacePrefix != null)
			{
				IEnumerator enumerator = _aliasMap.Keys.GetEnumerator();
				while (enumerator.MoveNext())
				{
					string text = (string)enumerator.Current;
					if (text != null && text.StartsWith(namespacePrefix))
					{
						list.Add(FindAlias(text));
					}
				}
			}
			IXmpAliasInfo[] array = new IXmpAliasInfo[list.Count];
			list.CopyTo(array, 0);
			return array;
		}

		[MethodImpl(MethodImplOptions.Synchronized)]
		public IDictionary GetNamespaces()
		{
			return ReadOnlyDictionary.ReadOnly(new Hashtable(_namespaceToPrefixMap));
		}

		[MethodImpl(MethodImplOptions.Synchronized)]
		public IDictionary GetPrefixes()
		{
			return ReadOnlyDictionary.ReadOnly(new Hashtable(_prefixToNamespaceMap));
		}

		[MethodImpl(MethodImplOptions.Synchronized)]
		public IDictionary GetAliases()
		{
			return ReadOnlyDictionary.ReadOnly(new Hashtable(_aliasMap));
		}

