					xmpNode2 = new XmpNode(xmpNode.Name, xmpNode.Value, propertyOptions);
					xmpMetaImpl2.Root.AddChild(xmpNode2);
					flag = true;
				}
				IEnumerator enumerator2 = xmpNode.IterateChildren();
				while (enumerator2.MoveNext())
				{
					XmpNode xmpNode3 = (XmpNode)enumerator2.Current;
					if (xmpNode3 != null && (doAllProperties || !Utils.IsInternalProperty(xmpNode.Name, xmpNode3.Name)))
					{
						AppendSubtree(xmpMetaImpl2, xmpNode3, xmpNode2, replaceOldValues, deleteEmptyValues);
					}
				}
				if (!xmpNode2.HasChildren() && (flag || deleteEmptyValues))
				{
					xmpMetaImpl2.Root.RemoveChild(xmpNode2);
				}
			}
		}

		private static bool RemoveSchemaChildren(XmpNode schemaNode, bool doAllProperties)
		{
			ArrayList arrayList = new ArrayList();
			IEnumerator enumerator = schemaNode.IterateChildren();
			while (enumerator.MoveNext())
			{
				XmpNode xmpNode = (XmpNode)enumerator.Current;
				if (xmpNode != null && (doAllProperties || !Utils.IsInternalProperty(schemaNode.Name, xmpNode.Name)))
				{
					arrayList.Add(xmpNode);
				}
			}
			foreach (XmpNode item in arrayList)
			{
				schemaNode.Children.Remove(item);
			}
			arrayList.Clear();
			return !schemaNode.HasChildren();
		}

		private static void AppendSubtree(XmpMetaImpl destXmp, XmpNode sourceNode, XmpNode destParent, bool replaceOldValues, bool deleteEmptyValues)
		{
			XmpNode xmpNode = XmpNodeUtils.FindChildNode(destParent, sourceNode.Name, createNodes: false);
			bool flag = false;
			if (deleteEmptyValues)
			{
				flag = (sourceNode.Options.Simple ? string.IsNullOrEmpty(sourceNode.Value) : (!sourceNode.HasChildren()));
			}
			if (deleteEmptyValues && flag)
			{
				if (xmpNode != null)
				{
					destParent.RemoveChild(xmpNode);
				}
				return;
			}
			if (xmpNode == null)
			{
				destParent.AddChild((XmpNode)sourceNode.Clone());
				return;
			}
			if (replaceOldValues)
			{
				destXmp.SetNode(xmpNode, sourceNode.Value, sourceNode.Options, deleteExisting: true);
				destParent.RemoveChild(xmpNode);
				xmpNode = (XmpNode)sourceNode.Clone();
				destParent.AddChild(xmpNode);
				return;
			}
			PropertyOptions options = sourceNode.Options;
			PropertyOptions options2 = xmpNode.Options;
			if (options != options2)
			{
				return;
			}
			if (options.Struct)
			{
				IEnumerator enumerator = sourceNode.IterateChildren();
				while (enumerator.MoveNext())
				{
					XmpNode xmpNode2 = (XmpNode)enumerator.Current;
					if (xmpNode2 != null)
					{
						AppendSubtree(destXmp, xmpNode2, xmpNode, replaceOldValues, deleteEmptyValues);
						if (deleteEmptyValues && !xmpNode.HasChildren())
						{
							destParent.RemoveChild(xmpNode);
						}
					}
				}
			}
			else if (options.ArrayAltText)
			{
				IEnumerator enumerator2 = sourceNode.IterateChildren();
				while (enumerator2.MoveNext())
				{
					XmpNode xmpNode3 = (XmpNode)enumerator2.Current;
					if (xmpNode3 == null || !xmpNode3.HasQualifier() || !"xml:lang".Equals(xmpNode3.GetQualifier(1).Name))
					{
						continue;
					}
					int num = XmpNodeUtils.LookupLanguageItem(xmpNode, xmpNode3.GetQualifier(1).Value);
					if (deleteEmptyValues && string.IsNullOrEmpty(xmpNode3.Value))
					{
						if (num != -1)
						{
							xmpNode.RemoveChild(num);
							if (!xmpNode.HasChildren())
							{
								destParent.RemoveChild(xmpNode);
							}
						}
					}
					else if (num == -1)
					{
						if (!"x-default".Equals(xmpNode3.GetQualifier(1).Value) || !xmpNode.HasChildren())
						{
							xmpNode3.CloneSubtree(xmpNode);
							continue;
						}
						XmpNode xmpNode4 = new XmpNode(xmpNode3.Name, xmpNode3.Value, xmpNode3.Options);
						xmpNode3.CloneSubtree(xmpNode4);
						xmpNode.AddChild(1, xmpNode4);
					}
				}
			}
			else
			{
				if (!options.Array)
				{
					return;
				}
				IEnumerator enumerator3 = sourceNode.IterateChildren();
				while (enumerator3.MoveNext())
				{
					XmpNode xmpNode5 = (XmpNode)enumerator3.Current;
					if (xmpNode5 == null)
					{
						continue;
					}
					bool flag2 = false;
					IEnumerator enumerator4 = xmpNode.IterateChildren();
					while (enumerator4.MoveNext())
					{
						XmpNode xmpNode6 = (XmpNode)enumerator4.Current;
						if (xmpNode6 != null && ItemValuesMatch(xmpNode5, xmpNode6))
						{
							flag2 = true;
						}
					}
					if (!flag2)
					{
						xmpNode = (XmpNode)xmpNode5.Clone();
						destParent.AddChild(xmpNode);
					}
				}
			}
		}

		private static bool ItemValuesMatch(XmpNode leftNode, XmpNode rightNode)
		{
			PropertyOptions options = leftNode.Options;
			PropertyOptions options2 = rightNode.Options;
			if (options.Equals(options2))
			{
				return false;
			}
			if (options.Options == 0)
			{
				if (!leftNode.Value.Equals(rightNode.Value))
				{
					return false;
				}
				if (leftNode.Options.HasLanguage != rightNode.Options.HasLanguage)
				{
					return false;
				}
				if (leftNode.Options.HasLanguage && !leftNode.GetQualifier(1).Value.Equals(rightNode.GetQualifier(1).Value))
				{
					return false;
				}
			}
			else if (options.Struct)
			{
				if (leftNode.ChildrenLength != rightNode.ChildrenLength)
				{
					return false;
				}
				IEnumerator enumerator = leftNode.IterateChildren();
				while (enumerator.MoveNext())
				{
					XmpNode xmpNode = (XmpNode)enumerator.Current;
					if (xmpNode != null)
					{
						XmpNode xmpNode2 = XmpNodeUtils.FindChildNode(rightNode, xmpNode.Name, createNodes: false);
						if (xmpNode2 == null || !ItemValuesMatch(xmpNode, xmpNode2))
						{
							return false;
						}
					}
				}
			}
			else
			{
				IEnumerator enumerator2 = leftNode.IterateChildren();
				while (enumerator2.MoveNext())
				{
					XmpNode xmpNode3 = (XmpNode)enumerator2.Current;
					if (xmpNode3 == null)
					{
						continue;
					}
					bool flag = false;
					IEnumerator enumerator3 = rightNode.IterateChildren();
					while (enumerator3.MoveNext())
					{
						XmpNode xmpNode4 = (XmpNode)enumerator3.Current;
						if (xmpNode4 != null && ItemValuesMatch(xmpNode3, xmpNode4))
						{
							flag = true;
							break;
						}
					}
					if (!flag)
					{
						return false;
					}
				}
			}
			return true;
		}

		private static void CheckSeparator(string separator)
		{
			bool flag = false;
			for (int i = 0; i < separator.Length; i++)
			{
				switch (ClassifyCharacter(separator[i]))
				{
				case 3:
					if (flag)
					{
						throw new XmpException("Separator can have only one semicolon", 4);
					}
					flag = true;
					break;
				default:
					throw new XmpException("Separator can have only spaces and one semicolon", 4);
				case 1:
					break;
				}
			}
			if (!flag)
			{
				throw new XmpException("Separator must have one semicolon", 4);
			}
		}

		private static char CheckQuotes(string quotes, char openQuote)
		{
			int num = ClassifyCharacter(openQuote);
			if (num != 4)
			{
				throw new XmpException("Invalid quoting character", 4);
			}
			char c;
			if (quotes.Length == 1)
			{
				c = openQuote;
			}
			else
			{
				c = quotes[1];
				num = ClassifyCharacter(c);
				if (num != 4)
				{
					throw new XmpException("Invalid quoting character", 4);
				}
			}
			if (c != GetClosingQuote(openQuote))
			{
				throw new XmpException("Mismatched quote pair", 4);
			}
			return c;
		}

		private static int ClassifyCharacter(char ch)
		{
			if (" \u3000〿".IndexOf(ch) >= 0 || ('\u2000' <= ch && ch <= '\u200b'))
			{
				return 1;
			}
			if (",，､﹐﹑、،՝".IndexOf(ch) >= 0)
			{
				return 2;
			}
			if (";；﹔؛;".IndexOf(ch) >= 0)
			{
				return 3;
			}
			if ("\"«»〝〞〟―‹›".IndexOf(ch) >= 0 || ('〈' <= ch && ch <= '』') || ('‘' <= ch && ch <= '‟'))
			{
				return 4;
			}
			if (ch < ' ' || "\u2028\u2029".IndexOf(ch) >= 0)
			{
				return 5;
			}
			return 0;
		}

		private static char GetClosingQuote(char openQuote)
		{
			return openQuote switch
			{
				'"' => '"', 
				'«' => '»', 
				'»' => '«', 
				'―' => '―', 
				'‘' => '’', 
				'‚' => '‛', 
				'“' => '”', 
				'„' => '‟', 
				'‹' => '›', 
				'›' => '‹', 
				'〈' => '〉', 
				'《' => '》', 
				'「' => '」', 
				'『' => '』', 
				'〝' => '〟', 
				_ => '\0', 
			};
		}

		private static string ApplyQuotes(string item, char openQuote, char closeQuote, bool allowCommas)
		{
			if (item == null)
			{
				item = "";
			}
			bool flag = false;
			int i;
			for (i = 0; i < item.Length; i++)
			{
				char ch = item[i];
				int num = ClassifyCharacter(ch);
				if (i == 0 && num == 4)
				{
					break;
				}
				if (num == 1)
				{
					if (flag)
					{
						break;
					}
					flag = true;
					continue;
				}
				flag = false;
				switch (num)
				{
				case 2:
					if (allowCommas)
					{
						continue;
					}
					break;
				default:
					continue;
				case 3:
				case 5:
					break;
				}
				break;
			}
			if (i < item.Length)
			{
				StringBuilder stringBuilder = new StringBuilder(item.Length + 2);
				int j;
				for (j = 0; j <= i; j++)
				{
					if (ClassifyCharacter(item[i]) == 4)
					{
						break;
					}
				}
				stringBuilder.Append(openQuote).Append(item.Substring(0, j));
				for (int k = j; k < item.Length; k++)
				{
					stringBuilder.Append(item[k]);
					if (ClassifyCharacter(item[k]) == 4 && IsSurroundingQuote(item[k], openQuote, closeQuote))
					{
						stringBuilder.Append(item[k]);
					}
				}
				stringBuilder.Append(closeQuote);
				item = stringBuilder.ToString();
			}
			return item;
		}

		private static bool IsSurroundingQuote(char ch, char openQuote, char closeQuote)
		{
			if (ch != openQuote)
			{
				return IsClosingingQuote(ch, openQuote, closeQuote);
			}
			return true;
		}

		private static bool IsClosingingQuote(char ch, char openQuote, char closeQuote)
		{
			if (ch != closeQuote)
			{
				if (openQuote != '〝' || ch != '〞')
				{
					return ch == '〟';
				}
				return true;
			}
			return true;
		}
	}
}
namespace iTextSharp.xmp.impl.xpath
{
	public class XmpPath
	{
		public const uint STRUCT_FIELD_STEP = 1u;

		public const uint QUALIFIER_STEP = 2u;

		public const uint ARRAY_INDEX_STEP = 3u;

		public const uint ARRAY_LAST_STEP = 4u;

		public const uint QUAL_SELECTOR_STEP = 5u;

		public const uint FIELD_SELECTOR_STEP = 6u;

		public const uint SCHEMA_NODE = 2147483648u;

		public const uint STEP_SCHEMA = 0u;

		public const uint STEP_ROOT_PROP = 1u;

		private readonly IList _segments = new ArrayList(5);

		public virtual void Add(XmpPathSegment segment)
		{
			_segments.Add(segment);
		}

		public virtual XmpPathSegment GetSegment(int index)
		{
			return (XmpPathSegment)_segments[index];
		}

		public virtual int Size()
		{
			return _segments.Count;
		}

		public override string ToString()
		{
			StringBuilder stringBuilder = new StringBuilder();
			for (int i = 1; i < Size(); i++)
			{
				stringBuilder.Append(GetSegment(i));
				if (i < Size() - 1)
				{
					uint kind = GetSegment(i + 1).Kind;
					if (kind == 1 || kind == 2)
					{
						stringBuilder.Append('/');
					}
				}
			}
			return stringBuilder.ToString();
		}
	}
	public sealed class XmpPathParser
	{
		internal XmpPathParser()
		{
		}

		public static XmpPath ExpandXPath(string schemaNs, string path)
		{
			if (schemaNs == null || path == null)
			{
				throw new XmpException("Parameter must not be null", 4);
			}
			XmpPath xmpPath = new XmpPath();
			PathPosition pathPosition = new PathPosition();
			pathPosition.Path = path;
			ParseRootNode(schemaNs, pathPosition, xmpPath);
			while (pathPosition.StepEnd < path.Length)
			{
				pathPosition.StepBegin = pathPosition.StepEnd;
				SkipPathDelimiter(path, pathPosition);
				pathPosition.StepEnd = pathPosition.StepBegin;
				XmpPathSegment xmpPathSegment = ((path[pathPosition.StepBegin] != '[') ? ParseStructSegment(pathPosition) : ParseIndexSegment(pathPosition));
				if (xmpPathSegment.Kind == 1)
				{
					if (xmpPathSegment.Name[0] == '@')
					{
						xmpPathSegment.Name = "?" + xmpPathSegment.Name.Substring(1);
						if (!"?xml:lang".Equals(xmpPathSegment.Name))
						{
							throw new XmpException("Only xml:lang allowed with '@'", 102);
						}
					}
					if (xmpPathSegment.Name[0] == '?')
					{
						pathPosition.NameStart++;
						xmpPathSegment.Kind = 2u;
					}
					VerifyQualName(pathPosition.Path.Substring(pathPosition.NameStart, pathPosition.NameEnd - pathPosition.NameStart));
				}
				else if (xmpPathSegment.Kind == 6)
				{
					if (xmpPathSegment.Name[1] == '@')
					{
						xmpPathSegment.Name = "[?" + xmpPathSegment.Name.Substring(2);
						if (!xmpPathSegment.Name.StartsWith("[?xml:lang="))
						{
							throw new XmpException("Only xml:lang allowed with '@'", 102);
						}
					}
					if (xmpPathSegment.Name[1] == '?')
					{
						pathPosition.NameStart++;
						xmpPathSegment.Kind = 5u;
						VerifyQualName(pathPosition.Path.Substring(pathPosition.NameStart, pathPosition.NameEnd - pathPosition.NameStart));
					}
				}
				xmpPath.Add(xmpPathSegment);
			}
			return xmpPath;
		}

		internal static void SkipPathDelimiter(string path, PathPosition pos)
		{
			if (path[pos.StepBegin] == '/')
			{
				pos.StepBegin++;
				if (pos.StepBegin >= path.Length)
				{
					throw new XmpException("Empty XmpPath segment", 102);
				}
			}
			if (path[pos.StepBegin] == '*')
			{
				pos.StepBegin++;
				if (pos.StepBegin >= path.Length || path[pos.StepBegin] != '[')
				{
					throw new XmpException("Missing '[' after '*'", 102);
				}
			}
		}

		internal static XmpPathSegment ParseStructSegment(PathPosition pos)
		{
			pos.NameStart = pos.StepBegin;
			while (pos.StepEnd < pos.Path.Length && "/[*".IndexOf(pos.Path[pos.StepEnd]) < 0)
			{
				pos.StepEnd++;
			}
			pos.NameEnd = pos.StepEnd;
			if (pos.StepEnd == pos.StepBegin)
			{
				throw new XmpException("Empty XmpPath segment", 102);
			}
			return new XmpPathSegment(pos.Path.Substring(pos.StepBegin, pos.StepEnd - pos.StepBegin), 1u);
		}

		internal static XmpPathSegment ParseIndexSegment(PathPosition pos)
		{
			pos.StepEnd++;
			XmpPathSegment xmpPathSegment;
			if ('0' <= pos.Path[pos.StepEnd] && pos.Path[pos.StepEnd] <= '9')
			{
				while (pos.StepEnd < pos.Path.Length && '0' <= pos.Path[pos.StepEnd] && pos.Path[pos.StepEnd] <= '9')
				{
					pos.StepEnd++;
				}
				xmpPathSegment = new XmpPathSegment(null, 3u);
			}
			else
			{
				while (pos.StepEnd < pos.Path.Length && pos.Path[pos.StepEnd] != ']' && pos.Path[pos.StepEnd] != '=')
				{
					pos.StepEnd++;
				}
				if (pos.StepEnd >= pos.Path.Length)
				{
					throw new XmpException("Missing ']' or '=' for array index", 102);
				}
				if (pos.Path[pos.StepEnd] == ']')
				{
					if (!"[last()".Equals(pos.Path.Substring(pos.StepBegin, pos.StepEnd - pos.StepBegin)))
					{
						throw new XmpException("Invalid non-numeric array index", 102);
					}
					xmpPathSegment = new XmpPathSegment(null, 4u);
				}
				else
				{
					pos.NameStart = pos.StepBegin + 1;
					pos.NameEnd = pos.StepEnd;
					pos.StepEnd++;
					char c = pos.Path[pos.StepEnd];
					if (c != '\'' && c != '"')
					{
						throw new XmpException("Invalid quote in array selector", 102);
					}
					pos.StepEnd++;
					while (pos.StepEnd < pos.Path.Length)
					{
						if (pos.Path[pos.StepEnd] == c)
						{
							if (pos.StepEnd + 1 >= pos.Path.Length || pos.Path[pos.StepEnd + 1] != c)
							{
								break;
							}
							pos.StepEnd++;
						}
						pos.StepEnd++;
					}
					if (pos.StepEnd >= pos.Path.Length)
					{
						throw new XmpException("No terminating quote for array selector", 102);
					}
					pos.StepEnd++;
					xmpPathSegment = new XmpPathSegment(null, 6u);
				}
			}
			if (pos.StepEnd >= pos.Path.Length || pos.Path[pos.StepEnd] != ']')
			{
				throw new XmpException("Missing ']' for array index", 102);
			}
			pos.StepEnd++;
			xmpPathSegment.Name = pos.Path.Substring(pos.StepBegin, pos.StepEnd - pos.StepBegin);
			return xmpPathSegment;
		}

		internal static void ParseRootNode(string schemaNs, PathPosition pos, XmpPath expandedXPath)
		{
			while (pos.StepEnd < pos.Path.Length && "/[*".IndexOf(pos.Path[pos.StepEnd]) < 0)
			{
				pos.StepEnd++;
			}
			if (pos.StepEnd == pos.StepBegin)
			{
				throw new XmpException("Empty initial XmpPath step", 102);
			}
			string text = VerifyXPathRoot(schemaNs, pos.Path.Substring(pos.StepBegin, pos.StepEnd - pos.StepBegin));
			IXmpAliasInfo xmpAliasInfo = XmpMetaFactory.SchemaRegistry.FindAlias(text);
			if (xmpAliasInfo == null)
			{
				expandedXPath.Add(new XmpPathSegment(schemaNs, 2147483648u));
				XmpPathSegment segment = new XmpPathSegment(text, 1u);
				expandedXPath.Add(segment);
				return;
			}
			expandedXPath.Add(new XmpPathSegment(xmpAliasInfo.Namespace, 2147483648u));
			XmpPathSegment xmpPathSegment = new XmpPathSegment(VerifyXPathRoot(xmpAliasInfo.Namespace, xmpAliasInfo.PropName), 1u);
			xmpPathSegment.Alias = true;
			xmpPathSegment.AliasForm = xmpAliasInfo.AliasForm.Options;
			expandedXPath.Add(xmpPathSegment);
			if (xmpAliasInfo.AliasForm.ArrayAltText)
			{
				XmpPathSegment xmpPathSegment2 = new XmpPathSegment("[?xml:lang='x-default']", 5u);
				xmpPathSegment2.Alias = true;
				xmpPathSegment2.AliasForm = xmpAliasInfo.AliasForm.Options;
				expandedXPath.Add(xmpPathSegment2);
			}
			else if (xmpAliasInfo.AliasForm.Array)
			{
				XmpPathSegment xmpPathSegment3 = new XmpPathSegment("[1]", 3u);
				xmpPathSegment3.Alias = true;
				xmpPathSegment3.AliasForm = xmpAliasInfo.AliasForm.Options;
				expandedXPath.Add(xmpPathSegment3);
			}
		}

		internal static void VerifyQualName(string qualName)
		{
			int num = qualName.IndexOf(':');
			if (num > 0)
			{
				string text = qualName.Substring(0, num);
				if (Utils.IsXmlNameNs(text))
				{
					string namespaceUri = XmpMetaFactory.SchemaRegistry.GetNamespaceUri(text);
					if (namespaceUri != null)
					{
						return;
					}
					throw new XmpException("Unknown namespace prefix for qualified name", 102);
				}
			}
			throw new XmpException("Ill-formed qualified name", 102);
		}

		internal static void VerifySimpleXmlName(string name)
		{
			if (!Utils.IsXmlName(name))
			{
				throw new XmpException("Bad XML name", 102);
			}
		}

		internal static string VerifyXPathRoot(string schemaNs, string rootProp)
		{
			if (string.IsNullOrEmpty(schemaNs))
			{
				throw new XmpException("Schema namespace URI is required", 101);
			}
			if (rootProp[0] == '?' || rootProp[0] == '@')
			{
				throw new XmpException("Top level name must not be a qualifier", 102);
			}
			if (rootProp.IndexOf('/') >= 0 || rootProp.IndexOf('[') >= 0)
			{
				throw new XmpException("Top level name must be simple", 102);
			}
			string namespacePrefix = XmpMetaFactory.SchemaRegistry.GetNamespacePrefix(schemaNs);
			if (namespacePrefix == null)
			{
				throw new XmpException("Unregistered schema namespace URI", 101);
			}
			int num = rootProp.IndexOf(':');
			if (num < 0)
			{
				VerifySimpleXmlName(rootProp);
				return namespacePrefix + rootProp;
			}
			VerifySimpleXmlName(rootProp.Substring(0, num));
			VerifySimpleXmlName(rootProp.Substring(num));
			namespacePrefix = rootProp.Substring(0, num + 1);
			string namespacePrefix2 = XmpMetaFactory.SchemaRegistry.GetNamespacePrefix(schemaNs);
			if (namespacePrefix2 == null)
			{
				throw new XmpException("Unknown schema namespace prefix", 101);
			}
			if (!namespacePrefix.Equals(namespacePrefix2))
			{
				throw new XmpException("Schema namespace URI and prefix mismatch", 101);
			}
			return rootProp;
		}
	}
	public class PathPosition
	{
		internal int NameEnd;

		internal int NameStart;

		internal string Path;

		internal int StepBegin;

		internal int StepEnd;
	}
	public class XmpPathSegment
