				orderedTreeNode2 = z.Right;
				while (orderedTreeNode2.Left != sentinelNode)
				{
					orderedTreeNode2 = orderedTreeNode2.Left;
				}
			}
			orderedTreeNode = ((orderedTreeNode2.Left == sentinelNode) ? orderedTreeNode2.Right : orderedTreeNode2.Left);
			orderedTreeNode.Parent = orderedTreeNode2.Parent;
			if (orderedTreeNode2.Parent != null)
			{
				if (orderedTreeNode2 == orderedTreeNode2.Parent.Left)
				{
					orderedTreeNode2.Parent.Left = orderedTreeNode;
				}
				else
				{
					orderedTreeNode2.Parent.Right = orderedTreeNode;
				}
			}
			else
			{
				rbTree = orderedTreeNode;
			}
			if (orderedTreeNode2 != z)
			{
				z.Key = orderedTreeNode2.Key;
				z.Data = orderedTreeNode2.Data;
			}
			if (orderedTreeNode2.Color)
			{
				RestoreAfterDelete(orderedTreeNode);
			}
			lastNodeFound = sentinelNode;
		}

		private void RestoreAfterDelete(OrderedTreeNode x)
		{
			while (x != rbTree && x.Color)
			{
				OrderedTreeNode right;
				if (x == x.Parent.Left)
				{
					right = x.Parent.Right;
					if (!right.Color)
					{
						right.Color = true;
						x.Parent.Color = false;
						RotateLeft(x.Parent);
						right = x.Parent.Right;
					}
					if (right.Left.Color && right.Right.Color)
					{
						right.Color = false;
						x = x.Parent;
						continue;
					}
					if (right.Right.Color)
					{
						right.Left.Color = true;
						right.Color = false;
						RotateRight(right);
						right = x.Parent.Right;
					}
					right.Color = x.Parent.Color;
					x.Parent.Color = true;
					right.Right.Color = true;
					RotateLeft(x.Parent);
					x = rbTree;
					continue;
				}
				right = x.Parent.Left;
				if (!right.Color)
				{
					right.Color = true;
					x.Parent.Color = false;
					RotateRight(x.Parent);
					right = x.Parent.Left;
				}
				if (right.Right.Color && right.Left.Color)
				{
					right.Color = false;
					x = x.Parent;
					continue;
				}
				if (right.Left.Color)
				{
					right.Right.Color = true;
					right.Color = false;
					RotateLeft(right);
					right = x.Parent.Left;
				}
				right.Color = x.Parent.Color;
				x.Parent.Color = true;
				right.Left.Color = true;
				RotateRight(x.Parent);
				x = rbTree;
			}
			x.Color = true;
		}

		public virtual void RemoveMin()
		{
			if (rbTree != null && rbTree != sentinelNode)
			{
				Remove(GetMinKey());
			}
		}

		public virtual void RemoveMax()
		{
			if (rbTree != null && rbTree != sentinelNode)
			{
				Remove(GetMaxKey());
			}
		}

		public virtual void Clear()
		{
			rbTree = sentinelNode;
			intCount = 0;
		}
	}
	public class OrderedTreeEnumerator : IEnumerator
	{
		private Stack stack;

		private bool keys;

		private bool ascending;

		private OrderedTreeNode tnode;

		private OrderedTreeNode sentinelNode;

		private bool pre = true;

		private IComparable ordKey;

		private object objValue;

		public virtual IComparable Key
		{
			get
			{
				return ordKey;
			}
			set
			{
				ordKey = value;
			}
		}

		public virtual object Value
		{
			get
			{
				return objValue;
			}
			set
			{
				objValue = value;
			}
		}

		public virtual object Current
		{
			get
			{
				if (pre)
				{
					throw new InvalidOperationException("Current");
				}
				if (!keys)
				{
					return Value;
				}
				return Key;
			}
		}

		private OrderedTreeEnumerator()
		{
		}

		public OrderedTreeEnumerator(OrderedTreeNode tnode, bool keys, bool ascending, OrderedTreeNode sentinelNode)
		{
			this.sentinelNode = sentinelNode;
			stack = new Stack();
			this.keys = keys;
			this.ascending = ascending;
			this.tnode = tnode;
			Reset();
		}

		public virtual void Reset()
		{
			pre = true;
			stack.Clear();
			if (ascending)
			{
				while (tnode != sentinelNode)
				{
					stack.Push(tnode);
					tnode = tnode.Left;
				}
			}
			else
			{
				while (tnode != sentinelNode)
				{
					stack.Push(tnode);
					tnode = tnode.Right;
				}
			}
		}

		public virtual bool HasMoreElements()
		{
			return stack.Count > 0;
		}

		public virtual object NextElement()
		{
			if (stack.Count == 0)
			{
				throw new InvalidOperationException("Element not found");
			}
			OrderedTreeNode orderedTreeNode = (OrderedTreeNode)stack.Peek();
			if (ascending)
			{
				if (orderedTreeNode.Right == sentinelNode)
				{
					OrderedTreeNode orderedTreeNode2 = (OrderedTreeNode)stack.Pop();
					while (HasMoreElements() && ((OrderedTreeNode)stack.Peek()).Right == orderedTreeNode2)
					{
						orderedTreeNode2 = (OrderedTreeNode)stack.Pop();
					}
				}
				else
				{
					for (OrderedTreeNode orderedTreeNode3 = orderedTreeNode.Right; orderedTreeNode3 != sentinelNode; orderedTreeNode3 = orderedTreeNode3.Left)
					{
						stack.Push(orderedTreeNode3);
					}
				}
			}
			else if (orderedTreeNode.Left == sentinelNode)
			{
				OrderedTreeNode orderedTreeNode4 = (OrderedTreeNode)stack.Pop();
				while (HasMoreElements() && ((OrderedTreeNode)stack.Peek()).Left == orderedTreeNode4)
				{
					orderedTreeNode4 = (OrderedTreeNode)stack.Pop();
				}
			}
			else
			{
				for (OrderedTreeNode orderedTreeNode5 = orderedTreeNode.Left; orderedTreeNode5 != sentinelNode; orderedTreeNode5 = orderedTreeNode5.Right)
				{
					stack.Push(orderedTreeNode5);
				}
			}
			Key = orderedTreeNode.Key;
			Value = orderedTreeNode.Data;
			if (!keys)
			{
				return orderedTreeNode.Data;
			}
			return orderedTreeNode.Key;
		}

		public virtual bool MoveNext()
		{
			if (HasMoreElements())
			{
				NextElement();
				pre = false;
				return true;
			}
			pre = true;
			return false;
		}

		public virtual OrderedTreeEnumerator GetEnumerator()
		{
			return this;
		}
	}
