	public class ListIterator<T>
	{
		private IList<T> col;

		private int cursor;

		private int lastRet = -1;

		public ListIterator(IList<T> col)
		{
			this.col = col;
		}

		public virtual bool HasNext()
		{
			return cursor != col.Count;
		}

		public virtual T Next()
		{
			T result = col[cursor];
			lastRet = cursor++;
			return result;
		}

		public virtual T Previous()
		{
			int index = cursor - 1;
			T result = col[index];
			lastRet = (cursor = index);
			return result;
		}

		public virtual void Remove()
		{
			if (lastRet == -1)
			{
				throw new InvalidOperationException();
			}
			col.RemoveAt(lastRet);
			if (lastRet < cursor)
			{
				cursor--;
			}
			lastRet = -1;
		}
	}
	public class PushbackStream : FilterStream
	{
		private int buf = -1;

		public PushbackStream(Stream s)
			: base(s)
		{
		}

		public override int ReadByte()
		{
			if (buf != -1)
			{
				int result = buf;
				buf = -1;
				return result;
			}
			return base.ReadByte();
		}

		public override int Read(byte[] buffer, int offset, int count)
		{
			if (buf != -1 && count > 0)
			{
				buffer[offset] = (byte)buf;
				buf = -1;
				return 1;
			}
			return base.Read(buffer, offset, count);
		}

		public virtual void Unread(int b)
		{
			if (buf != -1)
			{
				throw new InvalidOperationException("Can only push back one byte");
			}
			buf = b & 0xFF;
		}
	}
	public class RectangleJ
	{
		public const int OUT_LEFT = 1;

		public const int OUT_TOP = 2;

		public const int OUT_RIGHT = 4;

		public const int OUT_BOTTOM = 8;

		private float x;

		private float y;

		private float width;

		private float height;

		public virtual float X
		{
			get
			{
				return x;
			}
			set
			{
				x = value;
			}
		}

		public virtual float Y
		{
			get
			{
				return y;
			}
			set
			{
				y = value;
			}
		}

		public virtual float Width
		{
			get
			{
				return width;
			}
			set
			{
				width = value;
			}
		}

		public virtual float Height
		{
			get
			{
				return height;
			}
			set
			{
				height = value;
			}
		}

		public RectangleJ(float x, float y, float width, float height)
		{
			this.x = x;
			this.y = y;
			this.width = width;
			this.height = height;
		}

		public RectangleJ(iTextSharp.text.Rectangle rect)
		{
			rect.Normalize();
			x = rect.Left;
			y = rect.Bottom;
			width = rect.Width;
			height = rect.Height;
		}

		public virtual void Add(RectangleJ rect)
		{
			float num = Math.Min(Math.Min(x, x + width), Math.Min(rect.x, rect.x + rect.width));
			float num2 = Math.Max(Math.Max(x, x + width), Math.Max(rect.x, rect.x + rect.width));
			float num3 = Math.Min(Math.Min(y, y + height), Math.Min(rect.y, rect.y + rect.height));
			float num4 = Math.Max(Math.Max(y, y + height), Math.Max(rect.y, rect.y + rect.height));
			x = num;
			y = num3;
			width = num2 - num;
			height = num4 - num3;
		}

		public virtual int Outcode(double x, double y)
		{
			int num = 0;
			if (width <= 0f)
			{
				num |= 5;
			}
			else if (x < (double)this.x)
			{
				num |= 1;
			}
			else if (x > (double)this.x + (double)width)
			{
				num |= 4;
			}
			if (height <= 0f)
			{
				num |= 0xA;
			}
			else if (y < (double)this.y)
			{
				num |= 2;
			}
			else if (y > (double)this.y + (double)height)
			{
				num |= 8;
			}
			return num;
		}

		public virtual bool IntersectsLine(double x1, double y1, double x2, double y2)
		{
			int num;
			if ((num = Outcode(x2, y2)) == 0)
			{
				return true;
			}
			int num2;
			while ((num2 = Outcode(x1, y1)) != 0)
			{
				if ((num2 & num) != 0)
				{
					return false;
				}
				if (((uint)num2 & 5u) != 0)
				{
					float num3 = X;
					if (((uint)num2 & 4u) != 0)
					{
						num3 += Width;
					}
					y1 += ((double)num3 - x1) * (y2 - y1) / (x2 - x1);
					x1 = num3;
				}
				else
				{
					float num4 = Y;
					if (((uint)num2 & 8u) != 0)
					{
						num4 += Height;
					}
					x1 += ((double)num4 - y1) * (x2 - x1) / (y2 - y1);
					y1 = num4;
				}
			}
			return true;
		}

		public virtual RectangleJ Intersection(RectangleJ r)
		{
			float num = Math.Max(x, r.x);
			float num2 = Math.Max(y, r.y);
			float num3 = Math.Min(x + width, r.x + r.width);
			float num4 = Math.Min(y + height, r.y + r.height);
			return new RectangleJ(num, num2, num3 - num, num4 - num2);
		}

		public virtual bool IsEmpty()
		{
			if (!(width <= 0f))
			{
				return height <= 0f;
			}
			return true;
		}

		public virtual bool Contains(Point2D point)
		{
			return Contains(point.GetX(), point.GetY());
		}

		public virtual bool Contains(double x, double y)
		{
			if (IsEmpty())
			{
				return false;
			}
			if (x < (double)this.x || y < (double)this.y)
			{
				return false;
			}
			x -= (double)this.x;
			y -= (double)this.y;
			if (x < (double)width)
			{
				return y < (double)height;
			}
			return false;
		}
	}
	public class StringTokenizer
	{
		private int pos;

		private string str;

		private int len;

		private string delim;

		private bool retDelims;

		public StringTokenizer(string str)
			: this(str, " \t\n\r\f", retDelims: false)
		{
		}

		public StringTokenizer(string str, string delim)
			: this(str, delim, retDelims: false)
		{
		}

		public StringTokenizer(string str, string delim, bool retDelims)
		{
			len = str.Length;
			this.str = str;
			this.delim = delim;
			this.retDelims = retDelims;
			pos = 0;
		}

		public virtual bool HasMoreTokens()
		{
			if (!retDelims)
			{
				while (pos < len && delim.IndexOf(str[pos]) >= 0)
				{
					pos++;
				}
			}
			return pos < len;
		}

		public virtual string NextToken(string delim)
		{
			this.delim = delim;
			return NextToken();
		}

		public virtual string NextToken()
		{
			if (pos < len && delim.IndexOf(str[pos]) >= 0)
			{
				if (retDelims)
				{
					return str.Substring(pos++, 1);
				}
				while (++pos < len && delim.IndexOf(str[pos]) >= 0)
				{
				}
			}
			if (pos < len)
			{
				int num = pos;
				while (++pos < len && delim.IndexOf(str[pos]) < 0)
				{
				}
				return str.Substring(num, pos - num);
			}
			throw new IndexOutOfRangeException();
		}

		public virtual int CountTokens()
		{
			int num = 0;
			int num2 = 0;
			bool flag = false;
			int i = pos;
			while (i < len)
			{
				if (delim.IndexOf(str[i++]) >= 0)
				{
					if (flag)
					{
						num++;
						flag = false;
					}
					num2++;
				}
				else
				{
					flag = true;
					for (; i < len && delim.IndexOf(str[i]) < 0; i++)
					{
					}
				}
			}
			if (flag)
			{
				num++;
			}
			if (!retDelims)
			{
				return num;
			}
			return num + num2;
		}
	}
	public static class Util
	{
		public static int USR(int op1, int op2)
		{
			if (op2 < 1)
			{
				return op1;
			}
			return op1 >>> op2;
		}

		public static bool EqualsIgnoreCase(string s1, string s2)
		{
			return CultureInfo.InvariantCulture.CompareInfo.Compare(s1, s2, CompareOptions.IgnoreCase) == 0;
		}

		public static int CompareToIgnoreCase(string s1, string s2)
		{
			return CultureInfo.InvariantCulture.CompareInfo.Compare(s1, s2, CompareOptions.IgnoreCase);
		}

		public static CultureInfo GetStandartEnUSLocale()
		{
			CultureInfo cultureInfo = (CultureInfo)CultureInfo.InvariantCulture.Clone();
			cultureInfo.NumberFormat.CurrencySymbol = "$";
			cultureInfo.DateTimeFormat.ShortDatePattern = "M/d/yyyy";
			cultureInfo.DateTimeFormat.ShortTimePattern = "h:mm tt";
			cultureInfo.DateTimeFormat.LongDatePattern = "dddd, MMMM dd, yyyy";
			cultureInfo.DateTimeFormat.YearMonthPattern = "MMMM, yyyy";
			return cultureInfo;
		}

		public static int GetArrayHashCode<T>(T[] a)
		{
			if (a == null)
			{
				return 0;
			}
			int num = 1;
			for (int i = 0; i < a.Length; i++)
			{
				T val = a[i];
				num = 31 * num + (val?.GetHashCode() ?? 0);
			}
			return num;
		}

		public static int Compare(float f1, float f2)
		{
			if (f1 < f2)
			{
				return -1;
			}
			if (f1 > f2)
			{
				return 1;
			}
			int num = BitConverter.ToInt32(BitConverter.GetBytes(f1), 0);
			int num2 = BitConverter.ToInt32(BitConverter.GetBytes(f2), 0);
			if (num != num2)
			{
				if (num >= num2)
				{
					return 1;
				}
				return -1;
			}
			return 0;
		}

		public static bool ArraysAreEqual<T>(T[] a, T[] b)
		{
			if (a == b)
			{
				return true;
			}
			if (a == null || b == null)
			{
				return false;
			}
			int num = a.Length;
			if (b.Length != num)
			{
				return false;
			}
			for (int i = 0; i < num; i++)
			{
				object obj = a[i];
				object obj2 = b[i];
				if (!(obj?.Equals(obj2) ?? (obj2 == null)))
				{
					return false;
				}
			}
			return true;
		}

		public static bool AreEqual<T>(Stack<T> s1, Stack<T> s2)
		{
			if (s1.Count != s2.Count)
			{
				return false;
			}
			IEnumerator<T> enumerator = s1.GetEnumerator();
			IEnumerator<T> enumerator2 = s2.GetEnumerator();
			while (enumerator.MoveNext() && enumerator2.MoveNext())
			{
				if ((enumerator.Current != null || enumerator2.Current != null) && (enumerator == null || !enumerator.Current.Equals(enumerator2.Current)))
				{
					return false;
				}
			}
			return true;
		}

		public static T Min<T>(T[] array)
		{
			if (array.Length == 0)
			{
				throw new InvalidOperationException();
			}
			T val = array[0];
			for (int i = 1; i < array.Length; i++)
			{
				if (Comparer<T>.Default.Compare(val, array[i]) > 0)
				{
					val = array[i];
				}
			}
			return val;
		}

		public static T Max<T>(T[] array)
		{
			if (array.Length == 0)
			{
				throw new InvalidOperationException();
			}
			T val = array[0];
			for (int i = 1; i < array.Length; i++)
			{
				if (Comparer<T>.Default.Compare(val, array[i]) < 0)
				{
					val = array[i];
				}
			}
			return val;
		}

		public static void AddAll<T>(ICollection<T> dest, IEnumerable<T> source, int srcStartFrom)
		{
			IEnumerator<T> enumerator = source.GetEnumerator();
			while (srcStartFrom != 0 && enumerator.MoveNext())
			{
				srcStartFrom--;
			}
