	public class LocalizedResource
	{
		private static readonly char[] splt = new char[1] { '_' };

		private Properties msgs = new Properties();

		public LocalizedResource(string resourceRoot, CultureInfo culture, Assembly assembly)
		{
			Stream stream = null;
			string text = culture.Name.Replace('-', '_');
			if (text != "")
			{
				try
				{
					stream = assembly.GetManifestResourceStream(resourceRoot + "_" + text + ".properties");
				}
				catch
				{
				}
				if (stream == null)
				{
					string[] array = text.Split(splt, 2);
					if (array.Length == 2)
					{
						try
						{
							stream = assembly.GetManifestResourceStream(resourceRoot + "_" + array[0] + ".properties");
						}
						catch
						{
						}
					}
				}
			}
			if (stream == null)
			{
				try
				{
					stream = assembly.GetManifestResourceStream(resourceRoot + ".properties");
				}
				catch
				{
				}
			}
			if (stream != null)
			{
				msgs.Load(stream);
			}
			List<string> list = new List<string>(msgs.Keys);
			foreach (string item in list)
			{
				string text2 = msgs[item];
				StringBuilder stringBuilder = new StringBuilder();
				int num = 0;
				int num2 = 0;
				string text3 = text2;
				foreach (char c in text3)
				{
					switch (num2)
					{
					case 0:
						switch (c)
						{
						case '%':
							num2 = 1;
							goto end_IL_010b;
						case '{':
						case '}':
							stringBuilder.Append(c);
							break;
						}
						stringBuilder.Append(c);
						break;
					case 1:
						{
							if (c == '%')
							{
								stringBuilder.Append(c);
								num2 = 0;
							}
							else if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
							{
								num2 = 0;
							}
							stringBuilder.Append('{').Append(num++).Append('}');
							break;
						}
						end_IL_010b:
						break;
					}
				}
				msgs[item] = stringBuilder.ToString();
			}
		}

		public virtual string GetMessage(string key)
		{
			string text = msgs[key];
			if (text == null)
			{
				return key;
			}
			return text;
		}
	}
