namespace iTextSharp.text.html
{
	[Obsolete]
	public class HtmlUtilities
	{
		public const float DEFAULT_FONT_SIZE = 12f;

		private static Dictionary<string, float> sizes;

		public static readonly int[] FONTSIZES;

		static HtmlUtilities()
		{
			sizes = new Dictionary<string, float>();
			FONTSIZES = new int[7] { 8, 10, 12, 14, 18, 24, 36 };
			sizes["xx-small"] = 4f;
			sizes["x-small"] = 6f;
			sizes["small"] = 8f;
			sizes["medium"] = 10f;
			sizes["large"] = 13f;
			sizes["x-large"] = 18f;
			sizes["xx-large"] = 26f;
		}

		public static float ParseLength(string str)
		{
			return ParseLength(str, 12f);
		}

		public static float ParseLength(string str, float actualFontSize)
		{
			if (str == null)
			{
				return 0f;
			}
			if (sizes.ContainsKey(str))
			{
				return sizes[str];
			}
			int num = 0;
			int length = str.Length;
			bool flag = true;
			while (flag && num < length)
			{
				switch (str[num])
				{
				case '+':
				case '-':
				case '.':
				case '0':
				case '1':
				case '2':
				case '3':
				case '4':
				case '5':
				case '6':
				case '7':
				case '8':
				case '9':
					num++;
					break;
				default:
					flag = false;
					break;
				}
			}
			if (num == 0)
			{
				return 0f;
			}
			if (num == length)
			{
				return float.Parse(str, CultureInfo.InvariantCulture);
			}
			float num2 = float.Parse(str.Substring(0, num), CultureInfo.InvariantCulture);
			str = str.Substring(num);
			if (str.StartsWith("in"))
			{
				return num2 * 72f;
			}
			if (str.StartsWith("cm"))
			{
				return num2 / 2.54f * 72f;
			}
			if (str.StartsWith("mm"))
			{
				return num2 / 25.4f * 72f;
			}
			if (str.StartsWith("pc"))
			{
				return num2 * 12f;
			}
			if (str.StartsWith("em"))
			{
				return num2 * actualFontSize;
			}
			if (str.StartsWith("ex"))
			{
				return num2 * actualFontSize / 2f;
			}
			return num2;
		}

		public static BaseColor DecodeColor(string s)
		{
			if (s == null)
			{
				return null;
			}
			s = s.ToLowerInvariant().Trim();
			try
			{
				return WebColors.GetRGBColor(s);
			}
			catch
			{
				return null;
			}
		}

		public static Properties ParseAttributes(string str)
		{
			Properties properties = new Properties();
			if (str == null)
			{
				return properties;
			}
			StringTokenizer stringTokenizer = new StringTokenizer(str, ";");
			while (stringTokenizer.HasMoreTokens())
			{
				StringTokenizer stringTokenizer2 = new StringTokenizer(stringTokenizer.NextToken(), ":");
				if (!stringTokenizer2.HasMoreTokens())
				{
					continue;
				}
				string text = stringTokenizer2.NextToken().Trim();
				if (stringTokenizer2.HasMoreTokens())
				{
					string text2 = stringTokenizer2.NextToken().Trim();
					if (text2.StartsWith("\""))
					{
						text2 = text2.Substring(1);
					}
					if (text2.EndsWith("\""))
					{
						text2 = text2.Substring(0, text2.Length - 1);
					}
					properties[text.ToLowerInvariant()] = text2;
				}
			}
			return properties;
		}

		public static string RemoveComment(string str, string startComment, string endComment)
		{
			StringBuilder stringBuilder = new StringBuilder();
			int num = 0;
			int length = endComment.Length;
			for (int num2 = str.IndexOf(startComment, num); num2 > -1; num2 = str.IndexOf(startComment, num))
			{
				stringBuilder.Append(str.Substring(num, num2 - num));
				num = str.IndexOf(endComment, num2) + length;
			}
			stringBuilder.Append(str.Substring(num));
			return stringBuilder.ToString();
		}

		public static string EliminateWhiteSpace(string content)
		{
			StringBuilder stringBuilder = new StringBuilder();
			int length = content.Length;
			bool flag = false;
			for (int i = 0; i < length; i++)
			{
				char value;
				switch (value = content[i])
				{
				case ' ':
					if (!flag)
					{
						stringBuilder.Append(value);
					}
					break;
				case '\n':
					if (i > 0)
					{
						flag = true;
						stringBuilder.Append(' ');
					}
					break;
				default:
					flag = false;
					stringBuilder.Append(value);
					break;
				case '\t':
				case '\r':
					break;
				}
			}
			return stringBuilder.ToString();
		}

		public static int GetIndexedFontSize(string value, string previous)
		{
			int num = 0;
			if (value.StartsWith("+") || value.StartsWith("-"))
			{
				if (previous == null)
				{
					previous = "12";
				}
				int num2 = (int)float.Parse(previous, CultureInfo.InvariantCulture);
				for (int num3 = FONTSIZES.Length - 1; num3 >= 0; num3--)
				{
					if (num2 >= FONTSIZES[num3])
					{
						num = num3;
						break;
					}
				}
				int num4 = int.Parse(value.StartsWith("+") ? value.Substring(1) : value);
				num += num4;
			}
			else
			{
				try
				{
					num = int.Parse(value) - 1;
				}
				catch
				{
					num = 0;
				}
			}
			if (num < 0)
			{
				num = 0;
			}
			else if (num >= FONTSIZES.Length)
			{
				num = FONTSIZES.Length - 1;
			}
			return FONTSIZES[num];
		}

		public static int AlignmentValue(string alignment)
		{
			if (alignment == null)
			{
				return -1;
			}
			if (Util.EqualsIgnoreCase("center", alignment))
			{
				return 1;
			}
			if (Util.EqualsIgnoreCase("left", alignment))
			{
				return 0;
			}
			if (Util.EqualsIgnoreCase("right", alignment))
			{
				return 2;
			}
			if (Util.EqualsIgnoreCase("justify", alignment))
			{
				return 3;
			}
			if (Util.EqualsIgnoreCase("JustifyAll", alignment))
			{
				return 8;
			}
			if (Util.EqualsIgnoreCase("top", alignment))
			{
				return 4;
			}
			if (Util.EqualsIgnoreCase("middle", alignment))
			{
				return 5;
			}
			if (Util.EqualsIgnoreCase("bottom", alignment))
			{
				return 6;
			}
			if (Util.EqualsIgnoreCase("baseline", alignment))
			{
				return 7;
			}
			return -1;
		}
	}
