		public virtual bool IsPercentage => percentage;

		public CellWrapper(string tag, ChainedProperties chain)
		{
			cell = CreatePdfPCell(tag, chain);
			string text = chain["width"];
			if (text != null)
			{
				text = text.Trim();
				if (text.EndsWith("%"))
				{
