		public virtual PdfPCell CreatePdfPCell(string tag, ChainedProperties chain)
		{
			PdfPCell pdfPCell = new PdfPCell((Phrase)null);
			string text = chain["colspan"];
			if (text != null)
			{
				pdfPCell.Colspan = int.Parse(text);
			}
			text = chain["rowspan"];
			if (text != null)
			{
				pdfPCell.Rowspan = int.Parse(text);
			}
			if (tag.Equals("th"))
			{
				pdfPCell.HorizontalAlignment = 1;
			}
			text = chain["align"];
			if (text != null)
			{
				pdfPCell.HorizontalAlignment = HtmlUtilities.AlignmentValue(text);
			}
			text = chain["valign"];
			pdfPCell.VerticalAlignment = 5;
			if (text != null)
			{
				pdfPCell.VerticalAlignment = HtmlUtilities.AlignmentValue(text);
			}
			text = chain["border"];
			float borderWidth = 0f;
			if (text != null)
			{
				borderWidth = float.Parse(text, CultureInfo.InvariantCulture);
			}
			pdfPCell.BorderWidth = borderWidth;
			text = chain["cellpadding"];
			if (text != null)
			{
				pdfPCell.Padding = float.Parse(text, CultureInfo.InvariantCulture);
			}
			pdfPCell.UseDescender = true;
			text = chain["bgcolor"];
			pdfPCell.BackgroundColor = HtmlUtilities.DecodeColor(text);
