	[Obsolete]
	public class ElementFactory
	{
		private IFontProvider provider = FontFactory.FontImp;

		public virtual IFontProvider FontProvider
		{
			get
			{
				return provider;
			}
			set
			{
				provider = value;
			}
		}

		public virtual Font GetFont(ChainedProperties chain)
		{
			string text = chain["face"];
			if (text == null || text.Trim().Length == 0)
			{
				text = chain["font-family"];
			}
			if (text != null)
			{
				StringTokenizer stringTokenizer = new StringTokenizer(text, ",");
				while (stringTokenizer.HasMoreTokens())
				{
					text = stringTokenizer.NextToken().Trim();
					if (text.StartsWith("\""))
					{
						text = text.Substring(1);
					}
					if (text.EndsWith("\""))
					{
						text = text.Substring(0, text.Length - 1);
					}
					if (provider.IsRegistered(text))
					{
						break;
					}
				}
			}
			string text2 = chain["encoding"];
			if (text2 == null)
			{
				text2 = "Cp1252";
			}
			string text3 = chain["size"];
			float size = 12f;
			if (text3 != null)
			{
				size = float.Parse(text3, CultureInfo.InvariantCulture);
			}
			int num = 0;
			string text4 = chain["text-decoration"];
			if (text4 != null && text4.Trim().Length != 0)
			{
				if ("underline".Equals(text4))
				{
					num |= 4;
				}
				else if ("line-through".Equals(text4))
				{
					num |= 8;
				}
			}
			if (chain.HasProperty("i"))
			{
				num |= 2;
			}
			if (chain.HasProperty("b"))
			{
				num |= 1;
			}
			if (chain.HasProperty("u"))
			{
				num |= 4;
			}
			if (chain.HasProperty("s"))
			{
				num |= 8;
			}
			BaseColor color = HtmlUtilities.DecodeColor(chain["color"]);
			return provider.GetFont(text, text2, embedded: true, size, num, color);
		}

		public virtual Chunk CreateChunk(string content, ChainedProperties chain)
		{
			Font font = GetFont(chain);
			Chunk chunk = new Chunk(content, font);
			if (chain.HasProperty("sub"))
			{
				chunk.SetTextRise((0f - font.Size) / 2f);
			}
			else if (chain.HasProperty("sup"))
			{
				chunk.SetTextRise(font.Size / 2f);
			}
			chunk.SetHyphenation(GetHyphenation(chain));
			return chunk;
		}

		public virtual Paragraph CreateParagraph(ChainedProperties chain)
		{
			Paragraph paragraph = new Paragraph();
			UpdateElement(paragraph, chain);
			return paragraph;
		}

		public virtual ListItem CreateListItem(ChainedProperties chain)
		{
			ListItem listItem = new ListItem();
			UpdateElement(listItem, chain);
			return listItem;
		}

		protected virtual void UpdateElement(Paragraph paragraph, ChainedProperties chain)
		{
			string alignment = chain["align"];
			paragraph.Alignment = HtmlUtilities.AlignmentValue(alignment);
			paragraph.Hyphenation = GetHyphenation(chain);
			SetParagraphLeading(paragraph, chain["leading"]);
			alignment = chain["after"];
			if (alignment != null)
			{
				try
				{
					paragraph.SpacingBefore = float.Parse(alignment, CultureInfo.InvariantCulture);
				}
				catch
				{
				}
			}
			alignment = chain["after"];
			if (alignment != null)
			{
				try
				{
					paragraph.SpacingAfter = float.Parse(alignment, CultureInfo.InvariantCulture);
				}
				catch
				{
				}
			}
			alignment = chain["extraparaspace"];
			if (alignment != null)
			{
				try
				{
					paragraph.ExtraParagraphSpace = float.Parse(alignment, CultureInfo.InvariantCulture);
				}
				catch
				{
				}
			}
			alignment = chain["indent"];
			if (alignment != null)
			{
				try
				{
					paragraph.IndentationLeft = float.Parse(alignment, CultureInfo.InvariantCulture);
				}
				catch
				{
				}
			}
		}

		protected static void SetParagraphLeading(Paragraph paragraph, string leading)
		{
			if (leading == null)
			{
				paragraph.SetLeading(0f, 1.5f);
				return;
			}
			try
			{
				StringTokenizer stringTokenizer = new StringTokenizer(leading, " ,");
				string s = stringTokenizer.NextToken();
				float fixedLeading = float.Parse(s, CultureInfo.InvariantCulture);
				if (!stringTokenizer.HasMoreTokens())
				{
					paragraph.SetLeading(fixedLeading, 0f);
					return;
				}
				s = stringTokenizer.NextToken();
				float multipliedLeading = float.Parse(s, CultureInfo.InvariantCulture);
				paragraph.SetLeading(fixedLeading, multipliedLeading);
			}
			catch
			{
				paragraph.SetLeading(0f, 1.5f);
			}
		}

		public virtual IHyphenationEvent GetHyphenation(ChainedProperties chain)
		{
			string text = chain["hyphenation"];
			if (text == null || text.Length == 0)
			{
				return null;
			}
			int num = text.IndexOf('_');
			if (num == -1)
			{
				return new HyphenationAuto(text, null, 2, 2);
			}
			string lang = text.Substring(0, num);
			string text2 = text.Substring(num + 1);
			num = text2.IndexOf(',');
			if (num == -1)
			{
				return new HyphenationAuto(lang, text2, 2, 2);
			}
			int rightMin = 2;
			text = text2.Substring(num + 1);
			text2 = text2.Substring(0, num);
			num = text.IndexOf(',');
			int leftMin;
			if (num == -1)
			{
				leftMin = int.Parse(text);
			}
			else
			{
				leftMin = int.Parse(text.Substring(0, num));
				rightMin = int.Parse(text.Substring(num + 1));
			}
			return new HyphenationAuto(lang, text2, leftMin, rightMin);
		}

		public virtual LineSeparator CreateLineSeparator(IDictionary<string, string> attrs, float offset)
		{
			float lineWidth = 1f;
			attrs.TryGetValue("size", out var value);
			if (value != null)
			{
				float num = HtmlUtilities.ParseLength(value, 12f);
				if (num > 0f)
				{
					lineWidth = num;
				}
			}
			attrs.TryGetValue("width", out var value2);
			float percentage = 100f;
			if (value2 != null)
			{
				float num2 = HtmlUtilities.ParseLength(value2, 12f);
				if (num2 > 0f)
				{
					percentage = num2;
				}
				if (!value2.EndsWith("%"))
				{
					percentage = 100f;
				}
			}
			BaseColor lineColor = null;
			attrs.TryGetValue("align", out var value3);
			int align = HtmlUtilities.AlignmentValue(value3);
			return new LineSeparator(lineWidth, percentage, lineColor, align, offset);
		}

		public virtual Image CreateImage(string src, IDictionary<string, string> attrs, ChainedProperties chain, IDocListener document, IImageProvider img_provider, Dictionary<string, Image> img_store, string img_baseurl)
		{
			Image image = null;
			if (img_provider != null)
			{
				image = img_provider.GetImage(src, attrs, chain, document);
			}
			if (image == null && img_store != null)
			{
				img_store.TryGetValue(src, out var value);
				if (value != null)
				{
					image = Image.GetInstance(value);
				}
			}
			if (image != null)
			{
				return image;
			}
			if (!src.StartsWith("http") && img_baseurl != null)
			{
				src = img_baseurl + src;
			}
			else if (image == null && !src.StartsWith("http"))
			{
				string text = chain["image_path"];
				if (text == null)
				{
					text = "";
				}
				src = System.IO.Path.Combine(text, src);
			}
			image = Image.GetInstance(src);
			if (image == null)
			{
				return null;
			}
			float num = HtmlUtilities.ParseLength(chain["size"], 12f);
			if (num <= 0f)
			{
				num = 12f;
			}
			attrs.TryGetValue("width", out var value2);
			float num2 = HtmlUtilities.ParseLength(value2, num);
			attrs.TryGetValue("height", out var value3);
			float num3 = HtmlUtilities.ParseLength(value3, num);
			if (num2 > 0f && num3 > 0f)
			{
				image.ScaleAbsolute(num2, num3);
			}
			else if (num2 > 0f)
			{
				num3 = image.Height * num2 / image.Width;
				image.ScaleAbsolute(num2, num3);
			}
			else if (num3 > 0f)
			{
				num2 = image.Width * num3 / image.Height;
				image.ScaleAbsolute(num2, num3);
			}
			string text2 = chain["before"];
			if (text2 != null)
			{
				image.SpacingBefore = float.Parse(text2, CultureInfo.InvariantCulture);
			}
			string text3 = chain["after"];
			if (text3 != null)
			{
				image.SpacingAfter = float.Parse(text3, CultureInfo.InvariantCulture);
			}
			image.WidthPercentage = 0f;
			return image;
		}

		public virtual List CreateList(string tag, ChainedProperties chain)
		{
			List list;
			if (Util.EqualsIgnoreCase("ul", tag))
			{
				list = new List(numbered: false);
				list.SetListSymbol("• ");
			}
			else
			{
				list = new List(numbered: true);
			}
			try
			{
				list.IndentationLeft = float.Parse(chain["indent"], CultureInfo.InvariantCulture);
			}
			catch
			{
				list.Autoindent = true;
			}
			return list;
		}
	}
