	[Obsolete]
	public class TableWrapper : IElement
	{
		private IDictionary<string, string> styles = new Dictionary<string, string>();

		private IList<IList<PdfPCell>> rows = new List<IList<PdfPCell>>();

		private float[] colWidths;

		public virtual float[] ColWidths
		{
			set
			{
				colWidths = value;
			}
		}

		public virtual int Type => 0;

		public virtual IList<Chunk> Chunks => null;

		public TableWrapper(IDictionary<string, string> attrs)
		{
			foreach (KeyValuePair<string, string> attr in attrs)
			{
				styles[attr.Key] = attr.Value;
			}
		}

		public virtual void AddRow(IList<PdfPCell> row)
		{
			if (row != null)
			{
				List<PdfPCell> list = new List<PdfPCell>(row);
				list.Reverse();
				rows.Add(list);
			}
		}

		public virtual PdfPTable CreateTable()
		{
			if (rows.Count == 0)
			{
				return new PdfPTable(1);
			}
			int num = 0;
			foreach (PdfPCell item in rows[0])
			{
				num += item.Colspan;
			}
			PdfPTable pdfPTable = new PdfPTable(num);
			styles.TryGetValue("width", out var value);
			if (value == null)
			{
				pdfPTable.WidthPercentage = 100f;
			}
			else if (value.EndsWith("%"))
			{
				pdfPTable.WidthPercentage = float.Parse(value.Substring(0, value.Length - 1), CultureInfo.InvariantCulture);
			}
			else
			{
				pdfPTable.TotalWidth = float.Parse(value, CultureInfo.InvariantCulture);
				pdfPTable.LockedWidth = true;
			}
			styles.TryGetValue("align", out var value2);
			int horizontalAlignment = 0;
			if (value2 != null)
			{
				horizontalAlignment = HtmlUtilities.AlignmentValue(value2);
			}
			pdfPTable.HorizontalAlignment = horizontalAlignment;
			try
			{
				if (colWidths != null)
				{
					pdfPTable.SetWidths(colWidths);
				}
			}
			catch
			{
			}
			foreach (IList<PdfPCell> row in rows)
			{
				foreach (PdfPCell item2 in row)
				{
					pdfPTable.AddCell(item2);
				}
			}
			return pdfPTable;
		}

		public virtual bool Process(IElementListener listener)
		{
			return false;
		}

		public virtual bool IsContent()
		{
			return false;
		}

		public virtual bool IsNestable()
		{
			return false;
		}
	}
