namespace iTextSharp.text.log
{
	public interface ILogger
	{
		ILogger GetLogger(Type klass);

		ILogger GetLogger(string name);

		bool IsLogging(Level level);

		void Warn(string message);

		void Trace(string message);

		void Debug(string message);

		void Info(string message);

		void Error(string message);

		void Error(string message, Exception e);
	}
	public enum Level
	{
		ERROR,
		WARN,
		INFO,
		DEBUG,
		TRACE
	}
	public class LoggerFactory
	{
		private static LoggerFactory myself;

		private ILogger logger = new NoOpLogger();

		static LoggerFactory()
		{
			myself = new LoggerFactory();
		}

		public static ILogger GetLogger(Type klass)
		{
			return myself.logger.GetLogger(klass);
		}

		public static ILogger GetLogger(string name)
		{
			return myself.logger.GetLogger(name);
		}

		public static LoggerFactory GetInstance()
		{
			return myself;
		}

		private LoggerFactory()
		{
		}

		public virtual void SetLogger(ILogger logger)
		{
			this.logger = logger;
		}

		public virtual ILogger Logger()
		{
			return logger;
		}
	}
	public sealed class NoOpLogger : ILogger
	{
		public ILogger GetLogger(Type name)
		{
			return this;
		}

		public void Warn(string message)
		{
		}

		public void Trace(string message)
		{
		}

		public void Debug(string message)
		{
		}

		public void Info(string message)
		{
		}

		public void Error(string message, Exception e)
		{
		}

		public bool IsLogging(Level level)
		{
			return false;
		}

		public void Error(string message)
		{
		}

		public ILogger GetLogger(string name)
		{
			return this;
		}
	}
	public class SysoLogger : ILogger
	{
		private string name;

		private int shorten;

		public SysoLogger()
			: this(1)
		{
		}

		public SysoLogger(int packageReduce)
		{
			shorten = packageReduce;
		}

		protected SysoLogger(string klass, int shorten)
		{
			this.shorten = shorten;
			name = klass;
		}

		public virtual ILogger GetLogger(Type klass)
		{
			return new SysoLogger(klass.FullName, shorten);
		}

		public virtual ILogger GetLogger(string name)
		{
			return new SysoLogger("[itext]", 0);
		}

		public virtual bool IsLogging(Level level)
		{
			return true;
		}

		public virtual void Warn(string message)
		{
			Console.Out.WriteLine("{0} WARN  {1}", Shorten(name), message);
		}

		private string Shorten(string className)
		{
			if (shorten != 0)
			{
				StringBuilder stringBuilder = new StringBuilder();
				string text = className;
				for (int num = className.IndexOf('.'); num != -1; num = text.IndexOf('.'))
				{
					stringBuilder.Append(text[..((num < shorten) ? num : shorten)]);
					stringBuilder.Append('.');
					text = text.Substring(num + 1);
				}
				stringBuilder.Append(className.Substring(className.LastIndexOf('.') + 1));
				return stringBuilder.ToString();
			}
			return className;
		}

		public virtual void Trace(string message)
		{
			Console.Out.WriteLine("{0} TRACE {1}", Shorten(name), message);
		}

		public virtual void Debug(string message)
		{
			Console.Out.WriteLine("{0} DEBUG {1}", Shorten(name), message);
		}

		public virtual void Info(string message)
		{
			Console.Out.WriteLine("{0} INFO  {1}", Shorten(name), message);
		}

		public virtual void Error(string message)
		{
			Console.Out.WriteLine("{0} ERROR {1}", name, message);
		}

		public virtual void Error(string message, Exception e)
		{
			Console.Out.WriteLine("{0} ERROR {1}", name, message);
			Console.Out.WriteLine(e.StackTrace);
		}
	}
}
namespace iTextSharp.text.pdf.codec
{
	public class LZWCompressor
	{
		private int codeSize_;

		private int clearCode_;

		private int endOfInfo_;

		private int numBits_;

		private int limit_;

		private short prefix_;

		private BitFile bf_;

		private LZWStringTable lzss_;

		private bool tiffFudge_;

		public LZWCompressor(Stream outp, int codeSize, bool TIFF)
		{
			bf_ = new BitFile(outp, !TIFF);
			codeSize_ = codeSize;
			tiffFudge_ = TIFF;
			clearCode_ = 1 << codeSize_;
			endOfInfo_ = clearCode_ + 1;
			numBits_ = codeSize_ + 1;
			limit_ = (1 << numBits_) - 1;
			if (tiffFudge_)
			{
				limit_--;
			}
			prefix_ = -1;
			lzss_ = new LZWStringTable();
			lzss_.ClearTable(codeSize_);
			bf_.WriteBits(clearCode_, numBits_);
		}

		public virtual void Compress(byte[] buf, int offset, int length)
		{
			int num = offset + length;
			for (int i = offset; i < num; i++)
			{
				byte b = buf[i];
				short num2;
				if ((num2 = lzss_.FindCharString(prefix_, b)) != -1)
				{
					prefix_ = num2;
					continue;
				}
				bf_.WriteBits(prefix_, numBits_);
				if (lzss_.AddCharString(prefix_, b) > limit_)
				{
					if (numBits_ == 12)
					{
						bf_.WriteBits(clearCode_, numBits_);
						lzss_.ClearTable(codeSize_);
						numBits_ = codeSize_ + 1;
					}
					else
					{
						numBits_++;
					}
					limit_ = (1 << numBits_) - 1;
					if (tiffFudge_)
					{
						limit_--;
					}
				}
				prefix_ = (short)(b & 0xFF);
			}
		}

		public virtual void Flush()
		{
			if (prefix_ != -1)
			{
				bf_.WriteBits(prefix_, numBits_);
			}
			bf_.WriteBits(endOfInfo_, numBits_);
			bf_.Flush();
		}
	}
	public class LZWStringTable
	{
		private const int RES_CODES = 2;

		private const short HASH_FREE = -1;

		private const short NEXT_FIRST = -1;

		private const int MAXBITS = 12;

		private const int MAXSTR = 4096;

		private const short HASHSIZE = 9973;

		private const short HASHSTEP = 2039;

		private byte[] strChr_;

		private short[] strNxt_;

		private short[] strHsh_;

		private short numStrings_;

		private int[] strLen_;

		public LZWStringTable()
		{
			strChr_ = new byte[4096];
			strNxt_ = new short[4096];
			strLen_ = new int[4096];
			strHsh_ = new short[9973];
		}

		public virtual int AddCharString(short index, byte b)
		{
			if (numStrings_ >= 4096)
			{
				return 65535;
			}
			int num = Hash(index, b);
			while (strHsh_[num] != -1)
			{
				num = (num + 2039) % 9973;
			}
			strHsh_[num] = numStrings_;
			strChr_[numStrings_] = b;
			if (index == -1)
			{
				strNxt_[numStrings_] = -1;
				strLen_[numStrings_] = 1;
			}
			else
			{
				strNxt_[numStrings_] = index;
				strLen_[numStrings_] = strLen_[index] + 1;
			}
			return numStrings_++;
		}

		public virtual short FindCharString(short index, byte b)
		{
			if (index == -1)
			{
				return (short)(b & 0xFF);
			}
			int num = Hash(index, b);
			int num2;
			while ((num2 = strHsh_[num]) != -1)
			{
				if (strNxt_[num2] == index && strChr_[num2] == b)
				{
					return (short)num2;
				}
				num = (num + 2039) % 9973;
			}
			return -1;
		}

		public virtual void ClearTable(int codesize)
		{
			numStrings_ = 0;
			for (int i = 0; i < 9973; i++)
			{
				strHsh_[i] = -1;
			}
			int num = (1 << codesize) + 2;
			for (int j = 0; j < num; j++)
			{
				AddCharString(-1, (byte)j);
			}
		}

		public static int Hash(short index, byte lastbyte)
		{
			return (((short)(lastbyte << 8) ^ index) & 0xFFFF) % 9973;
		}

		public virtual int ExpandCode(byte[] buf, int offset, short code, int skipHead)
		{
			if (offset == -2 && skipHead == 1)
			{
				skipHead = 0;
			}
			if (code == -1 || skipHead == strLen_[code])
			{
				return 0;
			}
			int num = strLen_[code] - skipHead;
			int num2 = buf.Length - offset;
			int num3 = ((num2 <= num) ? num2 : num);
			int num4 = num - num3;
			int num5 = offset + num3;
			while (num5 > offset && code != -1)
			{
				if (--num4 < 0)
				{
					buf[--num5] = strChr_[code];
				}
				code = strNxt_[code];
			}
			if (num > num3)
			{
				return -num3;
			}
			return num3;
		}
	}
