namespace iTextSharp.testutils
{
	public class CompareTool
	{
		protected class ObjectPath
		{
			protected class Pair<T>
			{
				private T first;

				private T second;

				public Pair(T first, T second)
				{
					this.first = first;
					this.second = second;
				}

				public override bool Equals(object obj)
				{
					if (obj is Pair<T> && first.Equals(((Pair<T>)obj).first))
					{
						return second.Equals(((Pair<T>)obj).second);
					}
					return false;
				}

				public override int GetHashCode()
				{
					return first.GetHashCode() * 31 + second.GetHashCode();
				}
			}

			protected abstract class PathItem
			{
				public abstract XmlNode ToXmlNode(XmlDocument document);
			}

			private class DictPathItem : PathItem
			{
				private string key;

				public DictPathItem(string key)
				{
					this.key = key;
				}

				public override string ToString()
				{
					return "Dict key: " + key;
				}

				public override int GetHashCode()
				{
					return key.GetHashCode();
				}

				public override bool Equals(object obj)
				{
					if (obj is DictPathItem)
					{
						return key.Equals(((DictPathItem)obj).key);
					}
					return false;
				}

				public override XmlNode ToXmlNode(XmlDocument document)
				{
					XmlNode xmlNode = document.CreateElement("dictKey");
					xmlNode.AppendChild(document.CreateTextNode(key));
					return xmlNode;
				}
			}

			private class ArrayPathItem : PathItem
			{
				private int index;

				public ArrayPathItem(int index)
				{
					this.index = index;
				}

				public override string ToString()
				{
					return "Array index: " + index;
				}

				public override int GetHashCode()
				{
					return index;
				}

				public override bool Equals(object obj)
				{
					if (obj is ArrayPathItem)
					{
						return index == ((ArrayPathItem)obj).index;
					}
					return false;
				}

				public override XmlNode ToXmlNode(XmlDocument document)
				{
					XmlNode xmlNode = document.CreateElement("arrayIndex");
					xmlNode.AppendChild(document.CreateTextNode(index.ToString()));
					return xmlNode;
				}
			}

			private class OffsetPathItem : PathItem
			{
				private int offset;

				public OffsetPathItem(int offset)
				{
					this.offset = offset;
				}

				public override string ToString()
				{
					return "Offset: " + offset;
				}

				public override int GetHashCode()
				{
					return offset;
				}

				public override bool Equals(object obj)
				{
					if (obj is OffsetPathItem)
					{
						return offset == ((OffsetPathItem)obj).offset;
					}
					return false;
				}

				public override XmlNode ToXmlNode(XmlDocument document)
				{
					XmlNode xmlNode = document.CreateElement("offset");
					xmlNode.AppendChild(document.CreateTextNode(offset.ToString()));
					return xmlNode;
				}
			}

			protected RefKey baseCmpObject;

			protected RefKey baseOutObject;

			protected Stack<PathItem> path = new Stack<PathItem>();

			protected Stack<Pair<RefKey>> indirects = new Stack<Pair<RefKey>>();

			public ObjectPath()
			{
			}

			public ObjectPath(RefKey baseCmpObject, RefKey baseOutObject)
			{
				this.baseCmpObject = baseCmpObject;
				this.baseOutObject = baseOutObject;
			}

			private ObjectPath(RefKey baseCmpObject, RefKey baseOutObject, Stack<PathItem> path)
			{
				this.baseCmpObject = baseCmpObject;
				this.baseOutObject = baseOutObject;
				this.path = path;
			}

			public ObjectPath ResetDirectPath(RefKey baseCmpObject, RefKey baseOutObject)
			{
				ObjectPath objectPath = new ObjectPath(baseCmpObject, baseOutObject);
				objectPath.indirects = new Stack<Pair<RefKey>>(new Stack<Pair<RefKey>>(indirects));
				objectPath.indirects.Push(new Pair<RefKey>(baseCmpObject, baseOutObject));
				return objectPath;
			}

			public bool IsComparing(RefKey baseCmpObject, RefKey baseOutObject)
			{
				return indirects.Contains(new Pair<RefKey>(baseCmpObject, baseOutObject));
			}

			public void PushArrayItemToPath(int index)
			{
				path.Push(new ArrayPathItem(index));
			}

			public void PushDictItemToPath(string key)
			{
				path.Push(new DictPathItem(key));
			}

			public void PushOffsetToPath(int offset)
			{
				path.Push(new OffsetPathItem(offset));
			}

			public void Pop()
			{
				path.Pop();
			}

			public override string ToString()
			{
				StringBuilder stringBuilder = new StringBuilder();
				foreach (PathItem item in path)
				{
					stringBuilder.Insert(0, "\n" + item.ToString());
				}
				stringBuilder.Insert(0, $"Base cmp object: {baseCmpObject} obj. Base out object: {baseOutObject} obj");
				return stringBuilder.ToString();
			}

			public override int GetHashCode()
			{
				int num = ((baseCmpObject == null) ? 1 : baseCmpObject.GetHashCode());
				int num2 = ((baseOutObject == null) ? 1 : baseOutObject.GetHashCode());
				int num3 = num * 31 + num2;
				foreach (PathItem item in path)
				{
					num3 *= 31;
					num3 += item.GetHashCode();
				}
				return num3;
			}

			public override bool Equals(object obj)
			{
				if (obj is ObjectPath && baseCmpObject.Equals(((ObjectPath)obj).baseCmpObject) && baseOutObject.Equals(((ObjectPath)obj).baseOutObject))
				{
					return Util.AreEqual(path, ((ObjectPath)obj).path);
				}
				return false;
			}

			public object Clone()
			{
				return new ObjectPath(baseCmpObject, baseOutObject, new Stack<PathItem>(new Stack<PathItem>(path)));
			}

			public XmlNode ToXmlNode(XmlDocument document)
			{
				XmlElement xmlElement = document.CreateElement("base");
				xmlElement.SetAttribute("cmp", baseCmpObject.ToString() + " obj");
				xmlElement.SetAttribute("out", baseOutObject.ToString() + " obj");
				XmlElement xmlElement2 = document.CreateElement("path");
				foreach (PathItem item in path)
				{
					xmlElement2.PrependChild(item.ToXmlNode(document));
				}
				xmlElement2.PrependChild(xmlElement);
				return xmlElement2;
			}
		}

		protected class CompareResult
		{
			protected Dictionary<ObjectPath, string> differences = new Dictionary<ObjectPath, string>();

			protected int messageLimit = 1;

			public CompareResult(int messageLimit)
			{
				this.messageLimit = messageLimit;
			}

			public bool isOk()
			{
				return differences.Count == 0;
			}

			public int GetErrorCount()
			{
				return differences.Count;
			}

			public bool IsMessageLimitReached()
			{
				return differences.Count >= messageLimit;
			}

			public string GetReport()
			{
				StringBuilder stringBuilder = new StringBuilder();
				bool flag = true;
				foreach (KeyValuePair<ObjectPath, string> difference in differences)
				{
					if (!flag)
					{
						stringBuilder.Append("-----------------------------").Append("\n");
					}
					ObjectPath key = difference.Key;
					stringBuilder.Append(difference.Value).Append("\n").Append(key.ToString())
						.Append("\n");
					flag = false;
				}
				return stringBuilder.ToString();
			}

			public void AddError(ObjectPath path, string message)
			{
				if (differences.Count < messageLimit && !differences.ContainsKey(path))
				{
					differences[(ObjectPath)path.Clone()] = message;
				}
			}

			public void WriteReportToXml(Stream stream)
			{
				XmlDocument xmlDocument = new XmlDocument();
				XmlElement xmlElement = xmlDocument.CreateElement("errors");
				xmlElement.SetAttribute("count", differences.Count.ToString());
				XmlElement xmlElement2 = xmlDocument.CreateElement("report");
				xmlElement2.AppendChild(xmlElement);
				foreach (KeyValuePair<ObjectPath, string> difference in differences)
				{
					XmlNode xmlNode = xmlDocument.CreateElement("error");
					XmlNode xmlNode2 = xmlDocument.CreateElement("message");
					xmlNode2.AppendChild(xmlDocument.CreateTextNode(difference.Value));
					XmlNode newChild = difference.Key.ToXmlNode(xmlDocument);
					xmlNode.AppendChild(xmlNode2);
					xmlNode.AppendChild(newChild);
					xmlElement.AppendChild(xmlNode);
				}
				xmlDocument.AppendChild(xmlElement2);
				xmlDocument.PreserveWhitespace = true;
				using XmlTextWriter xmlTextWriter = new XmlTextWriter(stream, null);
				xmlTextWriter.Formatting = Formatting.Indented;
				xmlDocument.Save(xmlTextWriter);
			}
		}

		private class ImageNameComparator : IComparer<FileSystemInfo>
