		private string Compare(string outPath, string differenceImagePrefix, IDictionary<int, IList<iTextSharp.text.Rectangle>> ignoredAreas)
		{
			return Compare(outPath, differenceImagePrefix, ignoredAreas, null);
		}

		private string Compare(string outPath, string differenceImagePrefix, IDictionary<int, IList<iTextSharp.text.Rectangle>> ignoredAreas, IList<int> equalPages)
		{
			if (gsExec == null)
			{
				return "Path to GhostScript is not specified. Please use -DgsExec=<path_to_ghostscript> (e.g. -DgsExec=\"C:/Program Files/gs/gs9.14/bin/gswin32c.exe\")";
			}
			if (!File.Exists(gsExec))
			{
				return gsExec + " does not exist";
			}
			try
			{
				DirectoryInfo directoryInfo;
				FileSystemInfo[] fileSystemInfos;
				FileSystemInfo[] array;
				FileSystemInfo[] array3;
				if (Directory.Exists(outPath))
				{
					directoryInfo = new DirectoryInfo(outPath);
					fileSystemInfos = directoryInfo.GetFileSystemInfos("*.png");
					array = Array.FindAll(fileSystemInfos, PngPredicate);
					FileSystemInfo[] array2 = array;
					foreach (FileSystemInfo fileSystemInfo in array2)
					{
						fileSystemInfo.Delete();
					}
					array3 = Array.FindAll(fileSystemInfos, CmpPngPredicate);
					FileSystemInfo[] array4 = array3;
					foreach (FileSystemInfo fileSystemInfo2 in array4)
					{
						fileSystemInfo2.Delete();
					}
				}
				else
				{
					directoryInfo = Directory.CreateDirectory(outPath);
				}
				if (File.Exists(outPath + differenceImagePrefix))
				{
					File.Delete(outPath + differenceImagePrefix);
				}
				if (ignoredAreas != null && ignoredAreas.Count > 0)
				{
					PdfReader pdfReader = new PdfReader(cmpPdf);
					PdfReader pdfReader2 = new PdfReader(outPdf);
					PdfStamper pdfStamper = new PdfStamper(pdfReader2, new FileStream(outPath + "ignored_areas_" + outPdfName, FileMode.Create));
					PdfStamper pdfStamper2 = new PdfStamper(pdfReader, new FileStream(outPath + "ignored_areas_" + cmpPdfName, FileMode.Create));
					foreach (KeyValuePair<int, IList<iTextSharp.text.Rectangle>> ignoredArea in ignoredAreas)
					{
						int key = ignoredArea.Key;
						IList<iTextSharp.text.Rectangle> value = ignoredArea.Value;
						if (value == null || value.Count <= 0)
						{
							continue;
						}
						PdfContentByte overContent = pdfStamper.GetOverContent(key);
						PdfContentByte overContent2 = pdfStamper2.GetOverContent(key);
						foreach (iTextSharp.text.Rectangle item in value)
						{
							item.BackgroundColor = BaseColor.BLACK;
							overContent.Rectangle(item);
							overContent2.Rectangle(item);
						}
					}
					pdfStamper.Close();
					pdfStamper2.Close();
					pdfReader2.Close();
					pdfReader.Close();
					Init(outPath + "ignored_areas_" + outPdfName, outPath + "ignored_areas_" + cmpPdfName);
				}
				string arguments = " -dNOPAUSE -dBATCH -sDEVICE=png16m -r150 -sOutputFile=<outputfile> <inputfile>".Replace("<outputfile>", outPath + cmpImage).Replace("<inputfile>", cmpPdf);
				Process process = new Process();
				process.StartInfo.FileName = gsExec;
				process.StartInfo.Arguments = arguments;
				process.StartInfo.UseShellExecute = false;
				process.StartInfo.RedirectStandardError = true;
				process.StartInfo.RedirectStandardOutput = true;
				process.StartInfo.CreateNoWindow = true;
				process.Start();
				string value2;
				while ((value2 = process.StandardOutput.ReadLine()) != null)
				{
					Console.Out.WriteLine(value2);
				}
				process.StandardOutput.Close();
				while ((value2 = process.StandardError.ReadLine()) != null)
				{
					Console.Out.WriteLine(value2);
				}
				process.StandardError.Close();
				process.WaitForExit();
				if (process.ExitCode != 0)
				{
					return "GhostScript failed for <filename>.".Replace("<filename>", cmpPdf);
				}
				arguments = " -dNOPAUSE -dBATCH -sDEVICE=png16m -r150 -sOutputFile=<outputfile> <inputfile>".Replace("<outputfile>", outPath + outImage).Replace("<inputfile>", outPdf);
				process = new Process();
				process.StartInfo.FileName = gsExec;
				process.StartInfo.Arguments = arguments;
				process.StartInfo.UseShellExecute = false;
				process.StartInfo.RedirectStandardError = true;
				process.StartInfo.RedirectStandardOutput = true;
				process.StartInfo.CreateNoWindow = true;
				process.Start();
				while ((value2 = process.StandardOutput.ReadLine()) != null)
				{
					Console.Out.WriteLine(value2);
				}
				process.StandardOutput.Close();
				while ((value2 = process.StandardError.ReadLine()) != null)
				{
					Console.Out.WriteLine(value2);
				}
				process.StandardError.Close();
				process.WaitForExit();
				if (process.ExitCode != 0)
				{
					return "GhostScript failed for <filename>.".Replace("<filename>", outPdf);
				}
				fileSystemInfos = directoryInfo.GetFileSystemInfos("*.png");
				array = Array.FindAll(fileSystemInfos, PngPredicate);
				array3 = Array.FindAll(fileSystemInfos, CmpPngPredicate);
				bool flag = array.Length != array3.Length;
				int num = Math.Min(array.Length, array3.Length);
				if (num < 1)
				{
					return "No files for comparing!!!\nThe result or sample pdf file is not processed by GhostScript.";
				}
				Array.Sort(array, new ImageNameComparator());
				Array.Sort(array3, new ImageNameComparator());
				string text = null;
				for (int k = 0; k < num; k++)
				{
					if (equalPages != null && equalPages.Contains(k))
					{
						continue;
					}
					Console.Out.WriteLine("Comparing page " + (k + 1) + " (" + array[k].FullName + ")...");
					FileStream fileStream = new FileStream(array[k].FullName, FileMode.Open);
					FileStream fileStream2 = new FileStream(array3[k].FullName, FileMode.Open);
					bool flag2 = CompareStreams(fileStream, fileStream2);
					fileStream.Close();
					fileStream2.Close();
					if (!flag2)
					{
						if (!File.Exists(compareExec))
						{
							text = "File <filename> differs on page <pagenumber>.".Replace("<filename>", outPdf).Replace("<pagenumber>", (k + 1).ToString());
							text += "\nYou can optionally specify path to ImageMagick compare tool (e.g. -DcompareExec=\"C:/Program Files/ImageMagick-6.5.4-2/compare.exe\") to visualize differences.";
							break;
						}
						string arguments2 = " \"<image1>\" \"<image2>\" \"<difference>\"".Replace("<image1>", array[k].FullName).Replace("<image2>", array3[k].FullName).Replace("<difference>", outPath + differenceImagePrefix + (k + 1) + ".png");
						process = new Process();
						process.StartInfo.FileName = compareExec;
						process.StartInfo.Arguments = arguments2;
						process.StartInfo.UseShellExecute = false;
						process.StartInfo.RedirectStandardError = true;
						process.StartInfo.CreateNoWindow = true;
						process.Start();
						while ((value2 = process.StandardError.ReadLine()) != null)
						{
							Console.Out.WriteLine(value2);
						}
						process.StandardError.Close();
						process.WaitForExit();
						if (process.ExitCode == 0)
						{
							if (text == null)
							{
								text = "File <filename> differs on page <pagenumber>.".Replace("<filename>", outPdf).Replace("<pagenumber>", (k + 1).ToString());
								string text2 = text;
								text = text2 + "\nPlease, examine " + outPath + differenceImagePrefix + (k + 1) + ".png for more details.";
							}
							else
							{
								text = "File " + outPdf + " differs.\nPlease, examine difference images for more details.";
							}
						}
						else
						{
							text = "File <filename> differs on page <pagenumber>.".Replace("<filename>", outPdf).Replace("<pagenumber>", (k + 1).ToString());
							Console.Out.WriteLine("Invalid compareExec variable.");
						}
					}
					else
					{
						Console.Out.WriteLine("done.");
					}
				}
				if (text != null)
				{
					return text;
				}
				if (flag)
				{
					return "Unexpected number of pages for <filename>.".Replace("<filename>", outPdf);
				}
			}
			catch (Exception)
			{
				return "Cannot open tarGet directory for <filename>.".Replace("<filename>", outPdf);
			}
			return null;
		}

		public virtual string Compare(string outPdf, string cmpPdf, string outPath, string differenceImagePrefix, IDictionary<int, IList<iTextSharp.text.Rectangle>> ignoredAreas)
		{
			Init(outPdf, cmpPdf);
			return Compare(outPath, differenceImagePrefix, ignoredAreas);
		}

		public virtual string Compare(string outPdf, string cmpPdf, string outPath, string differenceImagePrefix)
		{
			Init(outPdf, cmpPdf);
			return Compare(outPath, differenceImagePrefix, null);
		}

		public virtual CompareTool SetCompareByContentErrorsLimit(int compareByContentMaxErrorCount)
		{
			compareByContentErrorsLimit = compareByContentMaxErrorCount;
			return this;
		}

