		private string CompareByContent(string outPath, string differenceImagePrefix, IDictionary<int, IList<iTextSharp.text.Rectangle>> ignoredAreas)
		{
			Console.Write("[itext] INFO  Comparing by content..........");
			PdfReader pdfReader = new PdfReader(outPdf);
			outPages = new List<PdfDictionary>();
			outPagesRef = new List<RefKey>();
			LoadPagesFromReader(pdfReader, outPages, outPagesRef);
			PdfReader pdfReader2 = new PdfReader(cmpPdf);
			cmpPages = new List<PdfDictionary>();
			cmpPagesRef = new List<RefKey>();
			LoadPagesFromReader(pdfReader2, cmpPages, cmpPagesRef);
			if (outPages.Count != cmpPages.Count)
			{
				return Compare(outPath, differenceImagePrefix, ignoredAreas);
			}
			CompareResult compareResult = new CompareResult(compareByContentErrorsLimit);
			IList<int> list = new List<int>(cmpPages.Count);
			for (int i = 0; i < cmpPages.Count; i++)
			{
				ObjectPath currentPath = new ObjectPath(cmpPagesRef[i], outPagesRef[i]);
				if (CompareDictionariesExtended(outPages[i], cmpPages[i], currentPath, compareResult))
				{
					list.Add(i);
				}
			}
			PdfObject pdfObject = pdfReader.Catalog.Get(PdfName.STRUCTTREEROOT);
			PdfObject pdfObject2 = pdfReader2.Catalog.Get(PdfName.STRUCTTREEROOT);
			RefKey baseCmpObject = ((pdfObject == null) ? null : new RefKey((PdfIndirectReference)pdfObject));
			RefKey baseOutObject = ((pdfObject2 == null) ? null : new RefKey((PdfIndirectReference)pdfObject2));
			CompareObjects(pdfObject, pdfObject2, new ObjectPath(baseCmpObject, baseOutObject), compareResult);
			PdfObject pdfObject3 = pdfReader.Catalog.Get(PdfName.OCPROPERTIES);
			PdfObject pdfObject4 = pdfReader2.Catalog.Get(PdfName.OCPROPERTIES);
			RefKey baseCmpObject2 = ((pdfObject3 is PdfIndirectReference) ? new RefKey((PdfIndirectReference)pdfObject3) : null);
			RefKey baseOutObject2 = ((pdfObject4 is PdfIndirectReference) ? new RefKey((PdfIndirectReference)pdfObject4) : null);
			CompareObjects(pdfObject3, pdfObject4, new ObjectPath(baseCmpObject2, baseOutObject2), compareResult);
			pdfReader.Close();
			pdfReader2.Close();
			if (generateCompareByContentXmlReport)
			{
				try
				{
					compareResult.WriteReportToXml(new FileStream(outPath + "/" + xmlReportName + ".xml", FileMode.Create));
				}
				catch (Exception)
				{
				}
			}
			if (list.Count == cmpPages.Count && compareResult.isOk())
			{
				Console.WriteLine("OK");
				Console.Out.Flush();
				return null;
			}
			Console.WriteLine("Fail");
			Console.Out.Flush();
			string value = "Compare by content report:\n" + compareResult.GetReport();
			Console.WriteLine(value);
			Console.Out.Flush();
			string text = Compare(outPath, differenceImagePrefix, ignoredAreas, list);
			if (text == null || text.Length == 0)
			{
				return "Compare by content fails. No visual differences";
			}
			return text;
		}

		public virtual string CompareByContent(string outPdf, string cmpPdf, string outPath, string differenceImagePrefix, IDictionary<int, IList<iTextSharp.text.Rectangle>> ignoredAreas)
		{
			Init(outPdf, cmpPdf);
			return CompareByContent(outPath, differenceImagePrefix, ignoredAreas);
		}

		public virtual string CompareByContent(string outPdf, string cmpPdf, string outPath, string differenceImagePrefix)
		{
			return CompareByContent(outPdf, cmpPdf, outPath, differenceImagePrefix, null);
		}

		private void LoadPagesFromReader(PdfReader reader, IList<PdfDictionary> pages, IList<RefKey> pagesRef)
		{
			PdfObject dictRef = reader.Catalog.Get(PdfName.PAGES);
			AddPagesFromDict(dictRef, pages, pagesRef);
		}

		private void AddPagesFromDict(PdfObject dictRef, IList<PdfDictionary> pages, IList<RefKey> pagesRef)
		{
			PdfDictionary pdfDictionary = (PdfDictionary)PdfReader.GetPdfObject(dictRef);
			if (pdfDictionary.IsPages())
			{
				PdfArray asArray = pdfDictionary.GetAsArray(PdfName.KIDS);
				if (asArray == null)
				{
					return;
				}
				{
					foreach (PdfObject item in asArray)
					{
						AddPagesFromDict(item, pages, pagesRef);
					}
					return;
				}
			}
			if (pdfDictionary.IsPage())
			{
				pages.Add(pdfDictionary);
				pagesRef.Add(new RefKey((PRIndirectReference)dictRef));
			}
		}

		private bool CompareObjects(PdfObject outObj, PdfObject cmpObj, ObjectPath currentPath, CompareResult compareResult)
		{
			PdfObject pdfObject = PdfReader.GetPdfObject(outObj);
			PdfObject pdfObject2 = PdfReader.GetPdfObject(cmpObj);
			if (pdfObject2 == null && pdfObject == null)
			{
				return true;
			}
			if (pdfObject == null)
			{
				compareResult.AddError(currentPath, "Expected object was not found.");
				return false;
			}
			if (pdfObject2 == null)
			{
				compareResult.AddError(currentPath, "Found object which was not expected to be found.");
				return false;
			}
			if (pdfObject2.Type != pdfObject.Type)
			{
				compareResult.AddError(currentPath, $"Types do not match. Expected: {pdfObject2.GetType().Name}. Found: {pdfObject.GetType().Name}.");
				return false;
			}
			if (cmpObj.IsIndirect() && outObj.IsIndirect())
			{
				if (currentPath.IsComparing(new RefKey((PdfIndirectReference)cmpObj), new RefKey((PdfIndirectReference)outObj)))
				{
					return true;
				}
				currentPath = currentPath.ResetDirectPath(new RefKey((PdfIndirectReference)cmpObj), new RefKey((PdfIndirectReference)outObj));
			}
			if (pdfObject2.IsDictionary() && ((PdfDictionary)pdfObject2).IsPage())
			{
				if (!pdfObject.IsDictionary() || !((PdfDictionary)pdfObject).IsPage())
				{
					if (compareResult != null && currentPath != null)
					{
						compareResult.AddError(currentPath, "Expected a page. Found not a page.");
					}
					return false;
				}
				RefKey item = new RefKey((PRIndirectReference)cmpObj);
				RefKey item2 = new RefKey((PRIndirectReference)outObj);
				if (cmpPagesRef.Contains(item) && cmpPagesRef.IndexOf(item) == outPagesRef.IndexOf(item2))
				{
					return true;
				}
				if (compareResult != null && currentPath != null)
				{
					compareResult.AddError(currentPath, $"The dictionaries refer to different pages. Expected page number: {cmpPagesRef.IndexOf(item)}. Found: {outPagesRef.IndexOf(item2)}");
				}
				return false;
			}
			if (pdfObject2.IsDictionary())
			{
				if (!CompareDictionariesExtended((PdfDictionary)pdfObject, (PdfDictionary)pdfObject2, currentPath, compareResult))
				{
					return false;
				}
			}
			else if (pdfObject2.IsStream())
			{
				if (!CompareStreamsExtended((PRStream)pdfObject, (PRStream)pdfObject2, currentPath, compareResult))
				{
					return false;
				}
			}
			else if (pdfObject2.IsArray())
			{
				if (!CompareArraysExtended((PdfArray)pdfObject, (PdfArray)pdfObject2, currentPath, compareResult))
				{
					return false;
				}
			}
			else if (pdfObject2.IsName())
			{
				if (!CompareNamesExtended((PdfName)pdfObject, (PdfName)pdfObject2, currentPath, compareResult))
				{
					return false;
				}
			}
			else if (pdfObject2.IsNumber())
			{
				if (!CompareNumbersExtended((PdfNumber)pdfObject, (PdfNumber)pdfObject2, currentPath, compareResult))
				{
					return false;
				}
			}
			else if (pdfObject2.IsString())
			{
				if (!CompareStringsExtended((PdfString)pdfObject, (PdfString)pdfObject2, currentPath, compareResult))
				{
					return false;
				}
			}
			else if (pdfObject2.IsBoolean())
			{
				if (!CompareBooleansExtended((PdfBoolean)pdfObject, (PdfBoolean)pdfObject2, currentPath, compareResult))
				{
					return false;
				}
			}
			else if (pdfObject2 is PdfLiteral)
			{
				if (!CompareLiteralsExtended((PdfLiteral)pdfObject, (PdfLiteral)pdfObject2, currentPath, compareResult))
				{
					return false;
				}
			}
			else if (!pdfObject.IsNull() || !pdfObject2.IsNull())
			{
				throw new InvalidOperationException();
			}
			return true;
		}

		public bool CompareDictionaries(PdfDictionary outDict, PdfDictionary cmpDict)
		{
			return CompareDictionariesExtended(outDict, cmpDict, null, null);
		}

		private bool CompareDictionariesExtended(PdfDictionary outDict, PdfDictionary cmpDict, ObjectPath currentPath, CompareResult compareResult)
		{
			if ((cmpDict != null && outDict == null) || (outDict != null && cmpDict == null))
			{
				compareResult.AddError(currentPath, "One of the dictionaries is null, the other is not.");
				return false;
			}
			bool flag = true;
			HashSet2<PdfName> hashSet = new HashSet2<PdfName>(cmpDict.Keys);
			hashSet.AddAll(outDict.Keys);
			foreach (PdfName item in hashSet)
			{
				if (item.CompareTo(PdfName.PARENT) == 0 || item.CompareTo(PdfName.P) == 0 || (outDict.IsStream() && cmpDict.IsStream() && (item.Equals(PdfName.FILTER) || item.Equals(PdfName.LENGTH))))
				{
					continue;
				}
				if (item.CompareTo(PdfName.BASEFONT) == 0 || item.CompareTo(PdfName.FONTNAME) == 0)
				{
					PdfObject directObject = cmpDict.GetDirectObject(item);
					if (directObject.IsName() && directObject.ToString().IndexOf('+') > 0)
					{
						PdfObject directObject2 = outDict.GetDirectObject(item);
						if (!directObject2.IsName() || directObject2.ToString().IndexOf('+') == -1)
						{
							if (compareResult != null && currentPath != null)
							{
								compareResult.AddError(currentPath, $"PdfDictionary {item.ToString()} entry: Expected: {directObject.ToString()}. Found: {directObject2.ToString()}");
							}
							flag = false;
							continue;
						}
						string text = directObject.ToString().Substring(directObject.ToString().IndexOf('+'));
						string value = directObject2.ToString().Substring(directObject2.ToString().IndexOf('+'));
						if (!text.Equals(value))
						{
							if (compareResult != null && currentPath != null)
							{
								compareResult.AddError(currentPath, $"PdfDictionary {item.ToString()} entry: Expected: {directObject.ToString()}. Found: {directObject2.ToString()}");
							}
							flag = false;
						}
						continue;
					}
				}
				if (floatComparisonError != 0.0 && cmpDict.IsPage() && outDict.IsPage() && item.Equals(PdfName.CONTENTS))
				{
					if (!CompareContentStreamsByParsingExtended(outDict.GetDirectObject(item), cmpDict.GetDirectObject(item), (PdfDictionary)outDict.GetDirectObject(PdfName.RESOURCES), (PdfDictionary)cmpDict.GetDirectObject(PdfName.RESOURCES), currentPath, compareResult))
					{
						flag = false;
					}
					continue;
				}
				currentPath?.PushDictItemToPath(item.ToString());
				flag = CompareObjects(outDict.Get(item), cmpDict.Get(item), currentPath, compareResult) && flag;
				currentPath?.Pop();
				if (!flag && (currentPath == null || compareResult == null || compareResult.IsMessageLimitReached()))
				{
					return false;
				}
			}
			return flag;
		}

		public bool CompareContentStreamsByParsing(PdfObject outObj, PdfObject cmpObj)
		{
			return CompareContentStreamsByParsingExtended(outObj, cmpObj, null, null, null, null);
		}

		public bool CompareContentStreamsByParsing(PdfObject outObj, PdfObject cmpObj, PdfDictionary outResources, PdfDictionary cmpResources)
		{
			return CompareContentStreamsByParsingExtended(outObj, cmpObj, outResources, cmpResources, null, null);
		}

		private bool CompareContentStreamsByParsingExtended(PdfObject outObj, PdfObject cmpObj, PdfDictionary outResources, PdfDictionary cmpResources, ObjectPath currentPath, CompareResult compareResult)
		{
			if (outObj.Type != outObj.Type)
			{
				compareResult.AddError(currentPath, $"PdfObject. Types are different. Expected: {cmpObj.Type}. Found: {outObj.Type}");
				return false;
			}
			if (outObj.IsArray())
			{
				PdfArray pdfArray = (PdfArray)outObj;
				PdfArray pdfArray2 = (PdfArray)cmpObj;
				if (pdfArray2.Size != pdfArray.Size)
				{
					compareResult.AddError(currentPath, $"PdfArray. Sizes are different. Expected: {pdfArray2.Size}. Found: {pdfArray.Size}");
					return false;
				}
				for (int i = 0; i < pdfArray2.Size; i++)
				{
					if (!CompareContentStreamsByParsingExtended(pdfArray.GetPdfObject(i), pdfArray2.GetPdfObject(i), outResources, cmpResources, currentPath, compareResult))
					{
						return false;
					}
				}
			}
			PRTokeniser tokeniser = new PRTokeniser(new RandomAccessFileOrArray(new RandomAccessSourceFactory().CreateSource(ContentByteUtils.GetContentBytesFromContentObject(cmpObj))));
			PRTokeniser tokeniser2 = new PRTokeniser(new RandomAccessFileOrArray(new RandomAccessSourceFactory().CreateSource(ContentByteUtils.GetContentBytesFromContentObject(outObj))));
			PdfContentParser pdfContentParser = new PdfContentParser(tokeniser);
			PdfContentParser pdfContentParser2 = new PdfContentParser(tokeniser2);
			List<PdfObject> list = new List<PdfObject>();
			List<PdfObject> list2 = new List<PdfObject>();
			while (pdfContentParser.Parse(list).Count > 0)
			{
				pdfContentParser2.Parse(list2);
				if (list.Count != list2.Count)
				{
					compareResult.AddError(currentPath, $"PdfObject. Different commands lengths. Expected: {list.Count}. Found: {list2.Count}");
					return false;
				}
				if (list.Count == 1 && CompareLiterals((PdfLiteral)list[0], new PdfLiteral("BI")) && CompareLiterals((PdfLiteral)list2[0], new PdfLiteral("BI")))
				{
					PRStream pRStream = (PRStream)cmpObj;
					PRStream pRStream2 = (PRStream)outObj;
					if (pRStream2.GetDirectObject(PdfName.RESOURCES) != null && pRStream.GetDirectObject(PdfName.RESOURCES) != null)
					{
						outResources = (PdfDictionary)pRStream2.GetDirectObject(PdfName.RESOURCES);
						cmpResources = (PdfDictionary)pRStream.GetDirectObject(PdfName.RESOURCES);
					}
					if (!CompareInlineImagesExtended(pdfContentParser2, pdfContentParser, outResources, cmpResources, currentPath, compareResult))
					{
						return false;
					}
					continue;
				}
				for (int j = 0; j < list.Count; j++)
				{
					if (!CompareObjects(list2[j], list[j], currentPath, compareResult))
					{
						return false;
					}
				}
			}
			return true;
		}

		private bool CompareInlineImagesExtended(PdfContentParser outPs, PdfContentParser cmpPs, PdfDictionary outDict, PdfDictionary cmpDict, ObjectPath currentPath, CompareResult compareResult)
		{
			InlineImageInfo inlineImageInfo = InlineImageUtils.ParseInlineImage(cmpPs, cmpDict);
			InlineImageInfo inlineImageInfo2 = InlineImageUtils.ParseInlineImage(outPs, outDict);
			if (CompareObjects(inlineImageInfo2.ImageDictionary, inlineImageInfo.ImageDictionary, currentPath, compareResult))
			{
				return Util.ArraysAreEqual(inlineImageInfo2.Samples, inlineImageInfo.Samples);
			}
			return false;
		}

		public bool CompareStreams(PRStream outStream, PRStream cmpStream)
		{
			return CompareStreamsExtended(outStream, cmpStream, null, null);
		}

		private bool CompareStreamsExtended(PRStream outStream, PRStream cmpStream, ObjectPath currentPath, CompareResult compareResult)
		{
			bool flag = PdfName.FLATEDECODE.Equals(outStream.Get(PdfName.FILTER));
			byte[] array = PdfReader.GetStreamBytesRaw(outStream);
			byte[] array2 = PdfReader.GetStreamBytesRaw(cmpStream);
			if (flag)
			{
				array = PdfReader.DecodeBytes(array, outStream);
				array2 = PdfReader.DecodeBytes(array2, cmpStream);
			}
			if (floatComparisonError != 0.0 && PdfName.XOBJECT.Equals(cmpStream.GetDirectObject(PdfName.TYPE)) && PdfName.XOBJECT.Equals(outStream.GetDirectObject(PdfName.TYPE)) && PdfName.FORM.Equals(cmpStream.GetDirectObject(PdfName.SUBTYPE)) && PdfName.FORM.Equals(outStream.GetDirectObject(PdfName.SUBTYPE)))
			{
				if (CompareContentStreamsByParsingExtended(outStream, cmpStream, outStream.GetAsDict(PdfName.RESOURCES), cmpStream.GetAsDict(PdfName.RESOURCES), currentPath, compareResult))
				{
					return CompareDictionariesExtended(outStream, cmpStream, currentPath, compareResult);
				}
				return false;
			}
			if (Util.ArraysAreEqual(array, array2))
			{
				return CompareDictionariesExtended(outStream, cmpStream, currentPath, compareResult);
			}
			if (array2.Length != array.Length)
			{
				if (compareResult != null && currentPath != null)
				{
					compareResult.AddError(currentPath, $"PRStream. Lengths are different. Expected: {array2.Length}. Found: {array.Length}");
				}
			}
			else
			{
				for (int i = 0; i < array2.Length; i++)
				{
					if (array2[i] != array[i])
					{
						int num = Math.Max(0, i - 10);
						int num2 = Math.Min(array2.Length, i + 10);
						if (compareResult != null && currentPath != null)
						{
							currentPath.PushOffsetToPath(i);
							compareResult.AddError(currentPath, string.Format("PRStream. The bytes differ at index {0}. Expected: {1} ({2}). Found: {3} ({4})", i, Encoding.UTF8.GetString(new byte[1] { array2[i] }), Encoding.UTF8.GetString(array2, num, num2 - num).Replace("\n", "\\n"), Encoding.UTF8.GetString(new byte[1] { array[i] }), Encoding.UTF8.GetString(array, num, num2 - num).Replace("\n", "\\n")));
							currentPath.Pop();
						}
					}
				}
			}
			return false;
		}

		public bool CompareArrays(PdfArray outArray, PdfArray cmpArray)
		{
			return CompareArraysExtended(outArray, cmpArray, null, null);
		}

		private bool CompareArraysExtended(PdfArray outArray, PdfArray cmpArray, ObjectPath currentPath, CompareResult compareResult)
		{
			if (outArray == null)
			{
				if (compareResult != null && currentPath != null)
				{
					compareResult.AddError(currentPath, "Found null. Expected PdfArray.");
				}
				return false;
			}
			if (outArray.Size != cmpArray.Size)
			{
				if (compareResult != null && currentPath != null)
				{
					compareResult.AddError(currentPath, $"PdfArrays. Lengths are different. Expected: {cmpArray.Size}. Found: {outArray.Size}.");
				}
				return false;
			}
			bool flag = true;
			for (int i = 0; i < cmpArray.Size; i++)
			{
				currentPath?.PushArrayItemToPath(i);
				flag = CompareObjects(outArray.GetPdfObject(i), cmpArray.GetPdfObject(i), currentPath, compareResult) && flag;
				currentPath?.Pop();
				if (!flag && (currentPath == null || compareResult == null || compareResult.IsMessageLimitReached()))
				{
					return false;
				}
			}
			return flag;
		}

		public bool CompareNames(PdfName outName, PdfName cmpName)
		{
			return cmpName.CompareTo(outName) == 0;
		}

		private bool CompareNamesExtended(PdfName outName, PdfName cmpName, ObjectPath currentPath, CompareResult compareResult)
		{
			if (cmpName.CompareTo(outName) == 0)
			{
				return true;
			}
			if (compareResult != null && currentPath != null)
			{
				compareResult.AddError(currentPath, $"PdfName. Expected: {cmpName.ToString()}. Found: {outName.ToString()}");
			}
			return false;
		}

		public bool CompareNumbers(PdfNumber outNumber, PdfNumber cmpNumber)
		{
			double num = Math.Abs(outNumber.DoubleValue - cmpNumber.DoubleValue);
			if (!absoluteError && cmpNumber.DoubleValue != 0.0)
			{
				num /= cmpNumber.DoubleValue;
			}
			return num <= floatComparisonError;
		}

		private bool CompareNumbersExtended(PdfNumber outNumber, PdfNumber cmpNumber, ObjectPath currentPath, CompareResult compareResult)
		{
			if (CompareNumbers(outNumber, cmpNumber))
			{
				return true;
			}
			if (compareResult != null && currentPath != null)
			{
				compareResult.AddError(currentPath, $"PdfNumber. Expected: {cmpNumber}. Found: {outNumber}");
			}
			return false;
		}

		public bool CompareStrings(PdfString outString, PdfString cmpString)
		{
			return Util.ArraysAreEqual(cmpString.GetBytes(), outString.GetBytes());
		}

		private bool CompareStringsExtended(PdfString outString, PdfString cmpString, ObjectPath currentPath, CompareResult compareResult)
		{
			if (Util.ArraysAreEqual(cmpString.GetBytes(), outString.GetBytes()))
			{
				return true;
			}
			string text = cmpString.ToUnicodeString();
			string text2 = outString.ToUnicodeString();
			if (text.Length != text2.Length)
			{
				if (compareResult != null && currentPath != null)
				{
					compareResult.AddError(currentPath, $"PdfString. Lengths are different. Expected: {text.Length}. Found: {text2.Length}");
				}
			}
			else
			{
				for (int i = 0; i < text.Length; i++)
				{
					if (text[i] != text2[i])
					{
						int startIndex = Math.Max(0, i - 10);
						int length = Math.Min(text.Length, i + 10);
						if (compareResult != null && currentPath != null)
						{
							currentPath.PushOffsetToPath(i);
							compareResult.AddError(currentPath, string.Format("PdfString. Characters differ at position {0}. Expected: {1} ({2}). Found: {3} ({4}).", i, text[i], text.Substring(startIndex, length).Replace("\n", "\\n"), text2[i], text2.Substring(startIndex, length).Replace("\n", "\\n")));
							currentPath.Pop();
						}
						break;
					}
				}
			}
			return false;
		}

		public bool CompareLiterals(PdfLiteral outLiteral, PdfLiteral cmpLiteral)
		{
			return Util.ArraysAreEqual(cmpLiteral.GetBytes(), outLiteral.GetBytes());
		}

		private bool CompareLiteralsExtended(PdfLiteral outLiteral, PdfLiteral cmpLiteral, ObjectPath currentPath, CompareResult compareResult)
		{
			if (CompareLiterals(outLiteral, cmpLiteral))
			{
				return true;
			}
			if (compareResult != null && currentPath != null)
			{
				compareResult.AddError(currentPath, $"PdfLiteral. Expected: {cmpLiteral}. Found: {outLiteral}");
			}
