		private bool CompareStreams(FileStream is1, FileStream is2)
		{
			byte[] array = new byte[65536];
			byte[] array2 = new byte[65536];
			int num;
			do
			{
				num = is1.Read(array, 0, 65536);
				int num2 = is2.Read(array2, 0, 65536);
				if (num != num2)
				{
					return false;
				}
				if (num == -1 || num == 0)
				{
					break;
				}
				for (int i = 0; i < num; i++)
				{
					if (array[i] != array2[i])
					{
						return false;
					}
				}
			}
			while (num >= array.Length);
			return true;
		}

		public virtual string CompareDocumentInfo(string outPdf, string cmpPdf)
		{
			Console.Write("[itext] INFO  Comparing document info.......");
			string text = null;
			PdfReader pdfReader = new PdfReader(outPdf);
			PdfReader pdfReader2 = new PdfReader(cmpPdf);
			string[] array = ConvertInfo(pdfReader2.Info);
			string[] array2 = ConvertInfo(pdfReader.Info);
			for (int i = 0; i < array.Length; i++)
			{
				if (!array[i].Equals(array2[i]))
				{
					text = "Document info fail";
					break;
				}
			}
			pdfReader.Close();
			pdfReader2.Close();
			if (text == null)
			{
				Console.WriteLine("OK");
			}
			else
			{
				Console.WriteLine("Fail");
			}
			Console.Out.Flush();
			return text;
		}

		private bool LinksAreSame(PdfAnnotation.PdfImportedLink cmpLink, PdfAnnotation.PdfImportedLink outLink)
		{
			if (cmpLink.GetDestinationPage() != outLink.GetDestinationPage())
			{
				return false;
			}
			if (!cmpLink.GetRect().ToString().Equals(outLink.GetRect().ToString()))
			{
				return false;
			}
			IDictionary<PdfName, PdfObject> parameters = cmpLink.GetParameters();
			IDictionary<PdfName, PdfObject> parameters2 = outLink.GetParameters();
			if (parameters.Count != parameters2.Count)
			{
				return false;
			}
			foreach (KeyValuePair<PdfName, PdfObject> item in parameters)
			{
				PdfObject value = item.Value;
				if (!parameters2.ContainsKey(item.Key))
				{
					return false;
				}
				PdfObject pdfObject = parameters2[item.Key];
				if (value.Type != pdfObject.Type)
				{
					return false;
				}
				switch (value.Type)
				{
				case 1:
				case 2:
				case 3:
				case 4:
				case 8:
					if (!value.ToString().Equals(pdfObject.ToString()))
					{
						return false;
					}
					break;
				}
			}
			return true;
		}

		public virtual string CompareLinks(string outPdf, string cmpPdf)
		{
			Console.Write("[itext] INFO  Comparing link annotations....");
			string text = null;
			PdfReader pdfReader = new PdfReader(outPdf);
			PdfReader pdfReader2 = new PdfReader(cmpPdf);
			for (int i = 0; i < pdfReader.NumberOfPages && i < pdfReader2.NumberOfPages; i++)
			{
				List<PdfAnnotation.PdfImportedLink> links = pdfReader.GetLinks(i + 1);
				List<PdfAnnotation.PdfImportedLink> links2 = pdfReader2.GetLinks(i + 1);
				if (links2.Count != links.Count)
				{
					text = $"Different number of links on page {i + 1}.";
					break;
				}
				for (int j = 0; j < links2.Count; j++)
				{
					if (!LinksAreSame(links2[j], links[j]))
					{
						text = $"Different links on page {i + 1}.\n{links2[j].ToString()}\n{links[j].ToString()}";
						break;
					}
				}
			}
			pdfReader.Close();
			pdfReader2.Close();
			if (text == null)
			{
				Console.WriteLine("OK");
			}
			else
			{
				Console.WriteLine("Fail");
			}
			Console.Out.Flush();
			return text;
		}

		private string[] ConvertInfo(IDictionary<string, string> info)
		{
			string[] array = new string[4] { "", "", "", "" };
			foreach (string key in info.Keys)
			{
				if (Util.EqualsIgnoreCase("title", key))
				{
					array[0] = info[key];
				}
				else if (Util.EqualsIgnoreCase("author", key))
				{
					array[1] = info[key];
				}
				else if (Util.EqualsIgnoreCase("subject", key))
				{
					array[2] = info[key];
				}
				else if (Util.EqualsIgnoreCase("keywords", key))
				{
					array[3] = info[key];
				}
			}
			return array;
		}

		private bool PngPredicate(FileSystemInfo pathname)
		{
			string name = pathname.Name;
			bool flag = name.EndsWith(".png");
			bool flag2 = name.Contains("cmp_");
			if (flag && !flag2)
			{
				return name.Contains(outPdfName);
			}
			return false;
		}

		private bool CmpPngPredicate(FileSystemInfo pathname)
		{
			string name = pathname.Name;
			bool flag = name.EndsWith(".png");
			bool flag2 = name.Contains("cmp_");
			if (flag && flag2)
			{
				return name.Contains(cmpPdfName);
			}
			return false;
		}
	}
