		internal abstract void AddChar(PdfString mark, PdfObject code);

		internal void AddRange(PdfString from, PdfString to, PdfObject code)
		{
			byte[] array = DecodeStringToByte(from);
			byte[] array2 = DecodeStringToByte(to);
			if (array.Length != array2.Length || array.Length == 0)
			{
				throw new ArgumentException("Invalid map.");
			}
			byte[] array3 = null;
			if (code is PdfString)
			{
				array3 = DecodeStringToByte((PdfString)code);
			}
			int num = ByteArrayToInt(array);
			int num2 = ByteArrayToInt(array2);
			for (int i = num; i <= num2; i++)
			{
				IntToByteArray(i, array);
				PdfString pdfString = new PdfString(array);
				pdfString.SetHexWriting(hexWriting: true);
				if (code is PdfArray)
				{
					AddChar(pdfString, ((PdfArray)code)[i - num]);
				}
				else if (code is PdfNumber)
				{
					int value = ((PdfNumber)code).IntValue + i - num;
					AddChar(pdfString, new PdfNumber(value));
				}
				else if (code is PdfString)
				{
					PdfString pdfString2 = new PdfString(array3);
					pdfString2.SetHexWriting(hexWriting: true);
					array3[^1]++;
					AddChar(pdfString, pdfString2);
				}
			}
		}

		private static void IntToByteArray(int v, byte[] b)
		{
			for (int num = b.Length - 1; num >= 0; num--)
			{
				b[num] = (byte)v;
				v >>= 8;
			}
		}

		private static int ByteArrayToInt(byte[] b)
		{
			int num = 0;
			for (int i = 0; i < b.Length; i++)
			{
				num <<= 8;
				num |= b[i] & 0xFF;
			}
			return num;
		}

		public static byte[] DecodeStringToByte(PdfString s)
		{
			byte[] bytes = s.GetBytes();
			byte[] array = new byte[bytes.Length];
			Array.Copy(bytes, 0, array, 0, bytes.Length);
			return array;
		}

		public virtual string DecodeStringToUnicode(PdfString ps)
		{
			if (ps.IsHexWriting())
			{
				return PdfEncodings.ConvertToString(ps.GetBytes(), "UnicodeBigUnmarked");
			}
			return ps.ToUnicodeString();
		}
	}
	public interface ICidLocation
	{
		PRTokeniser GetLocation(string location);
	}
	public class CidLocationFromByte : ICidLocation
	{
		private byte[] data;

		public CidLocationFromByte(byte[] data)
		{
			this.data = data;
		}

		public virtual PRTokeniser GetLocation(string location)
		{
			return new PRTokeniser(new RandomAccessFileOrArray(new RandomAccessSourceFactory().CreateSource(data)));
		}
	}
	public class CidResource : ICidLocation
	{
		public virtual PRTokeniser GetLocation(string location)
		{
			string text = "iTextSharp.text.pdf.fonts.cmaps." + location;
			Stream resourceStream = StreamUtil.GetResourceStream(text);
			if (resourceStream == null)
			{
				throw new IOException(MessageLocalization.GetComposedMessage("the.cmap.1.was.not.found", text));
			}
			return new PRTokeniser(new RandomAccessFileOrArray(new RandomAccessSourceFactory().CreateSource(resourceStream)));
		}
	}
	public class CMapByteCid : AbstractCMap
	{
		private List<char[]> planes = new List<char[]>();

		public CMapByteCid()
		{
			planes.Add(new char[256]);
		}

		internal override void AddChar(PdfString mark, PdfObject code)
		{
			if (code is PdfNumber)
			{
				EncodeSequence(AbstractCMap.DecodeStringToByte(mark), (char)((PdfNumber)code).IntValue);
			}
		}

		private void EncodeSequence(byte[] seqs, char cid)
		{
			int num = seqs.Length - 1;
			int index = 0;
			char[] array;
			int num2;
			for (int i = 0; i < num; i++)
			{
				array = planes[index];
				num2 = seqs[i] & 0xFF;
				char c = array[num2];
				if (c != 0 && (c & 0x8000) == 0)
				{
					throw new ArgumentException(MessageLocalization.GetComposedMessage("inconsistent.mapping"));
				}
				if (c == '\0')
				{
					planes.Add(new char[256]);
					c = (array[num2] = (char)((uint)(planes.Count - 1) | 0x8000u));
				}
				index = c & 0x7FFF;
			}
			array = planes[index];
			num2 = seqs[num] & 0xFF;
			char c2 = array[num2];
			if ((c2 & 0x8000u) != 0)
			{
				throw new ArgumentException(MessageLocalization.GetComposedMessage("inconsistent.mapping"));
			}
			array[num2] = cid;
		}

		public virtual int DecodeSingle(CMapSequence seq)
		{
			int num = seq.off + seq.len;
			int index = 0;
			while (seq.off < num)
			{
				int num2 = seq.seq[seq.off++] & 0xFF;
				seq.len--;
				char[] array = planes[index];
				int num3 = array[num2];
				if ((num3 & 0x8000) == 0)
				{
					return num3;
				}
				index = num3 & 0x7FFF;
			}
			return -1;
		}

		public virtual string DecodeSequence(CMapSequence seq)
		{
			StringBuilder stringBuilder = new StringBuilder();
			int num = 0;
			while ((num = DecodeSingle(seq)) >= 0)
			{
				stringBuilder.Append((char)num);
			}
			return stringBuilder.ToString();
		}
	}
