		public static InlineImageInfo ParseInlineImage(PdfContentParser ps, PdfDictionary colorSpaceDic)
		{
			PdfDictionary imageDictionary = ParseInlineImageDictionary(ps);
			byte[] samples = ParseInlineImageSamples(imageDictionary, colorSpaceDic, ps);
			return new InlineImageInfo(samples, imageDictionary);
		}

		private static PdfDictionary ParseInlineImageDictionary(PdfContentParser ps)
		{
			PdfDictionary pdfDictionary = new PdfDictionary();
			PdfObject pdfObject = ps.ReadPRObject();
			while (pdfObject != null && !"ID".Equals(pdfObject.ToString()))
			{
				PdfObject value = ps.ReadPRObject();
				inlineImageEntryAbbreviationMap.TryGetValue((PdfName)pdfObject, out var value2);
				if (value2 == null)
				{
					value2 = (PdfName)pdfObject;
				}
				pdfDictionary.Put(value2, GetAlternateValue(value2, value));
				pdfObject = ps.ReadPRObject();
			}
			int num = ps.GetTokeniser().Read();
			if (!PRTokeniser.IsWhitespace(num))
			{
				throw new IOException("Unexpected character " + num + " found after ID in inline image");
			}
			return pdfDictionary;
		}

		private static PdfObject GetAlternateValue(PdfName key, PdfObject value)
		{
			if (key.Equals(PdfName.FILTER))
			{
				if (value is PdfName)
				{
					inlineImageFilterAbbreviationMap.TryGetValue((PdfName)value, out var value2);
					if (value2 != null)
					{
						return value2;
					}
				}
				else if (value is PdfArray)
				{
					PdfArray pdfArray = (PdfArray)value;
					PdfArray pdfArray2 = new PdfArray();
					int size = pdfArray.Size;
					for (int i = 0; i < size; i++)
					{
						pdfArray2.Add(GetAlternateValue(key, pdfArray[i]));
					}
					return pdfArray2;
				}
			}
			else if (key.Equals(PdfName.COLORSPACE) && value is PdfName)
			{
				inlineImageColorSpaceAbbreviationMap.TryGetValue((PdfName)value, out var value3);
				if (value3 != null)
				{
					return value3;
				}
			}
			return value;
		}

		private static int GetComponentsPerPixel(PdfName colorSpaceName, PdfDictionary colorSpaceDic)
		{
			if (colorSpaceName == null)
			{
				return 1;
			}
			if (colorSpaceName.Equals(PdfName.DEVICEGRAY))
			{
				return 1;
			}
			if (colorSpaceName.Equals(PdfName.DEVICERGB))
			{
				return 3;
			}
			if (colorSpaceName.Equals(PdfName.DEVICECMYK))
			{
				return 4;
			}
			if (colorSpaceDic != null)
			{
				PdfArray asArray = colorSpaceDic.GetAsArray(colorSpaceName);
				if (asArray != null)
				{
					if (PdfName.INDEXED.Equals(asArray.GetAsName(0)))
					{
						return 1;
					}
				}
				else
				{
					PdfName asName = colorSpaceDic.GetAsName(colorSpaceName);
					if (asName != null)
					{
						return GetComponentsPerPixel(asName, colorSpaceDic);
					}
				}
			}
			throw new ArgumentException("Unexpected color space " + colorSpaceName);
		}

		private static int ComputeBytesPerRow(PdfDictionary imageDictionary, PdfDictionary colorSpaceDic)
		{
			PdfNumber asNumber = imageDictionary.GetAsNumber(PdfName.WIDTH);
			PdfNumber asNumber2 = imageDictionary.GetAsNumber(PdfName.BITSPERCOMPONENT);
			int componentsPerPixel = GetComponentsPerPixel(imageDictionary.GetAsName(PdfName.COLORSPACE), colorSpaceDic);
			int intValue = asNumber.IntValue;
			int num = asNumber2?.IntValue ?? 1;
			return (intValue * num * componentsPerPixel + 7) / 8;
		}

		private static byte[] ParseUnfilteredSamples(PdfDictionary imageDictionary, PdfDictionary colorSpaceDic, PdfContentParser ps)
		{
			if (imageDictionary.Contains(PdfName.FILTER))
			{
				throw new ArgumentException("Dictionary contains filters");
			}
			PdfNumber asNumber = imageDictionary.GetAsNumber(PdfName.HEIGHT);
			int num = ComputeBytesPerRow(imageDictionary, colorSpaceDic) * asNumber.IntValue;
			byte[] array = new byte[num];
			PRTokeniser tokeniser = ps.GetTokeniser();
			int num2 = tokeniser.Read();
			int num3 = 0;
			if (!PRTokeniser.IsWhitespace(num2) || num2 == 0)
			{
				array[0] = (byte)num2;
				num3++;
			}
			for (int i = num3; i < num; i++)
			{
				int num4 = tokeniser.Read();
				if (num4 == -1)
				{
					throw new InlineImageParseException("End of content stream reached before end of image data");
				}
				array[i] = (byte)num4;
			}
			PdfObject pdfObject = ps.ReadPRObject();
			if (!pdfObject.ToString().Equals("EI"))
			{
				PdfObject pdfObject2 = ps.ReadPRObject();
				if (!pdfObject2.ToString().Equals("EI"))
				{
					throw new InlineImageParseException("EI not found after end of image data");
				}
			}
			return array;
		}

		private static byte[] ParseInlineImageSamples(PdfDictionary imageDictionary, PdfDictionary colorSpaceDic, PdfContentParser ps)
		{
			if (!imageDictionary.Contains(PdfName.FILTER))
			{
				return ParseUnfilteredSamples(imageDictionary, colorSpaceDic, ps);
			}
			MemoryStream memoryStream = new MemoryStream();
			MemoryStream memoryStream2 = new MemoryStream();
			int num = 0;
			PRTokeniser tokeniser = ps.GetTokeniser();
			byte[] array = null;
			int num2;
			while ((num2 = tokeniser.Read()) != -1)
			{
				if (num == 0 && PRTokeniser.IsWhitespace(num2))
				{
					num++;
					memoryStream2.WriteByte((byte)num2);
				}
				else if (num == 1 && num2 == 69)
				{
					num++;
					memoryStream2.WriteByte((byte)num2);
				}
				else if (num == 1 && PRTokeniser.IsWhitespace(num2))
				{
					memoryStream.Write(array = memoryStream2.ToArray(), 0, array.Length);
					memoryStream2.SetLength(0L);
					memoryStream2.WriteByte((byte)num2);
				}
				else if (num == 2 && num2 == 73)
				{
					num++;
					memoryStream2.WriteByte((byte)num2);
				}
				else if (num == 3 && PRTokeniser.IsWhitespace(num2))
				{
					byte[] array2 = memoryStream.ToArray();
					if (InlineImageStreamBytesAreComplete(array2, imageDictionary))
					{
						return array2;
					}
					byte[] array3 = memoryStream2.ToArray();
					memoryStream.Write(array3, 0, array3.Length);
					memoryStream2.SetLength(0L);
					memoryStream.WriteByte((byte)num2);
					num = 0;
				}
				else
				{
					memoryStream.Write(array = memoryStream2.ToArray(), 0, array.Length);
					memoryStream2.SetLength(0L);
					memoryStream.WriteByte((byte)num2);
					num = 0;
				}
			}
			throw new InlineImageParseException("Could not find image data or EI");
		}

		private static bool InlineImageStreamBytesAreComplete(byte[] samples, PdfDictionary imageDictionary)
		{
			try
			{
				PdfReader.DecodeBytes(samples, imageDictionary, FilterHandlers.GetDefaultFilterHandlers());
				return true;
			}
			catch (UnsupportedPdfException ex)
			{
				LOGGER.Warn(ex.Message);
				return true;
			}
			catch (IOException)
			{
				return false;
			}
		}
	}
