	public class PdfConcatenate
	{
		protected internal Document document;

		protected internal PdfCopy copy;

		public virtual PdfCopy Writer => copy;

		public PdfConcatenate(Stream os)
			: this(os, smart: false)
		{
		}

		public PdfConcatenate(Stream os, bool smart)
		{
			document = new Document();
			if (smart)
			{
				copy = new PdfSmartCopy(document, os);
			}
			else
			{
				copy = new PdfCopy(document, os);
			}
		}

		public virtual int AddPages(PdfReader reader)
		{
			Open();
			int numberOfPages = reader.NumberOfPages;
			for (int i = 1; i <= numberOfPages; i++)
			{
				copy.AddPage(copy.GetImportedPage(reader, i));
			}
			copy.FreeReader(reader);
			reader.Close();
			return numberOfPages;
		}

		public virtual void Open()
		{
			if (!document.IsOpen())
			{
				document.Open();
			}
		}

		public virtual void Close()
		{
			document.Close();
		}
	}
