				if ((double?)percentageHeight < 1.0)
				{
					flag = true;
				}
				contentHeight = (num2 - num3) * percentageHeight.Value;
				num3 = num2 - contentHeight;
			}
			if (!simulate && position == PositionType.RELATIVE)
			{
				float? num5 = null;
				num5 = (left.HasValue ? left : ((!right.HasValue) ? new float?(0f) : (0f - right)));
				float? num6 = null;
				num6 = (top.HasValue ? (0f - top) : ((!bottom.HasValue) ? new float?(0f) : bottom));
				canvas.SaveState();
				canvas.Transform(new AffineTransform(1f, 0f, 0f, 1f, num5.Value, num6.Value));
			}
			if (!simulate && (backgroundColor != null || backgroundImage != null) && getActualWidth() > 0f && getActualHeight() > 0f)
			{
				float num7 = getActualWidth();
				float num8 = getActualHeight();
				if (width.HasValue)
				{
					num7 = ((width > 0f) ? width.Value : 0f);
				}
				if (height.HasValue)
				{
					num8 = ((height > 0f) ? height.Value : 0f);
				}
				if (num7 > 0f && num8 > 0f)
				{
					Rectangle rectangle = new Rectangle(num, num2 - num8, num + num7, num2);
					if (backgroundColor != null)
					{
						rectangle.BackgroundColor = backgroundColor;
						PdfArtifact element = new PdfArtifact();
						canvas.OpenMCBlock(element);
						canvas.Rectangle(rectangle);
						canvas.CloseMCBlock(element);
					}
					if (backgroundImage != null)
					{
						if (!backgroundImageWidth.HasValue)
						{
							backgroundImage.ScaleToFit(rectangle);
						}
						else
						{
							backgroundImage.ScaleAbsolute(backgroundImageWidth.Value, backgroundImageHeight);
						}
						backgroundImage.SetAbsolutePosition(rectangle.Left, rectangle.Bottom);
						canvas.OpenMCBlock(backgroundImage);
						canvas.AddImage(backgroundImage);
						canvas.CloseMCBlock(backgroundImage);
					}
				}
			}
			if (!percentageWidth.HasValue)
			{
				contentWidth = 0f;
			}
			if (!percentageHeight.HasValue)
			{
				contentHeight = 0f;
			}
			num3 += paddingBottom;
			num += paddingLeft;
			num4 -= paddingRight;
			yLine -= paddingTop;
			int result = 1;
			if (content.Count > 0)
			{
				if (floatLayout == null)
				{
					List<IElement> elements = new List<IElement>(content);
					floatLayout = new FloatLayout(elements, useAscender);
					floatLayout.RunDirection = runDirection;
				}
				floatLayout.SetSimpleColumn(num, num3, num4, yLine);
				if (borderTopStyle != 0)
				{
					floatLayout.compositeColumn.IgnoreSpacingBefore = false;
				}
				result = floatLayout.Layout(canvas, simulate);
				yLine = floatLayout.YLine;
				if (!percentageWidth.HasValue && contentWidth < floatLayout.FilledWidth)
				{
					contentWidth = floatLayout.FilledWidth;
				}
			}
			if (!simulate && position == PositionType.RELATIVE)
			{
				canvas.RestoreState();
			}
			yLine -= paddingBottom;
			if (!percentageHeight.HasValue)
			{
				contentHeight = num2 - yLine;
			}
			if (!percentageWidth.HasValue)
			{
				contentWidth += paddingLeft + paddingRight;
			}
			if (!flag)
			{
				return result;
			}
			return 1;
		}

		public virtual PdfObject GetAccessibleAttribute(PdfName key)
		{
			if (accessibleAttributes != null && accessibleAttributes.TryGetValue(key, out var value))
			{
				return value;
			}
			return null;
		}

		public virtual void SetAccessibleAttribute(PdfName key, PdfObject value)
		{
			if (accessibleAttributes == null)
			{
				accessibleAttributes = new Dictionary<PdfName, PdfObject>();
			}
			accessibleAttributes[key] = value;
		}

		public virtual Dictionary<PdfName, PdfObject> GetAccessibleAttributes()
		{
			return accessibleAttributes;
		}
	}
	public class PdfSigLockDictionary : PdfDictionary
	{
		public class LockAction
		{
			public static readonly LockAction ALL = new LockAction(PdfName.ALL);

			public static readonly LockAction INCLUDE = new LockAction(PdfName.INCLUDE);

			public static readonly LockAction EXCLUDE = new LockAction(PdfName.EXCLUDE);

			private PdfName name;

			public virtual PdfName Value => name;

			private LockAction(PdfName name)
			{
				this.name = name;
			}
		}

		public class LockPermissions
		{
			public static readonly LockPermissions NO_CHANGES_ALLOWED = new LockPermissions(1);

			public static readonly LockPermissions FORM_FILLING = new LockPermissions(2);

			public static readonly LockPermissions FORM_FILLING_AND_ANNOTATION = new LockPermissions(3);

			private PdfNumber number;

			public virtual PdfNumber Value => number;

			private LockPermissions(int p)
			{
				number = new PdfNumber(p);
			}
		}

		public PdfSigLockDictionary()
			: base(PdfName.SIGFIELDLOCK)
		{
			Put(PdfName.ACTION, LockAction.ALL.Value);
		}

		public PdfSigLockDictionary(LockPermissions p)
			: this()
		{
			Put(PdfName.P, p.Value);
		}

		public PdfSigLockDictionary(LockAction action, params string[] fields)
			: this(action, null, fields)
		{
		}

		public PdfSigLockDictionary(LockAction action, LockPermissions p, params string[] fields)
			: base(PdfName.SIGFIELDLOCK)
		{
			Put(PdfName.ACTION, action.Value);
			if (p != null)
			{
				Put(PdfName.P, p.Value);
			}
			PdfArray pdfArray = new PdfArray();
			foreach (string value in fields)
			{
				pdfArray.Add(new PdfString(value));
			}
			Put(PdfName.FIELDS, pdfArray);
		}
	}
	public class PdfStructTreeController
	{
		public enum ReturnType
		{
			BELOW,
			FOUND,
			ABOVE,
			NOTFOUND
		}

		private PdfDictionary structTreeRoot;

		private PdfCopy writer;

		private PdfStructureTreeRoot structureTreeRoot;

		private PdfDictionary parentTree;

		protected internal PdfReader reader;

		private PdfDictionary roleMap;

		private PdfDictionary sourceRoleMap;

		private PdfDictionary sourceClassMap;

		private PdfIndirectReference nullReference;

		protected internal PdfStructTreeController(PdfReader reader, PdfCopy writer)
		{
			if (!writer.IsTagged())
			{
				throw new BadPdfFormatException(MessageLocalization.GetComposedMessage("no.structtreeroot.found"));
			}
			this.writer = writer;
			structureTreeRoot = writer.StructureTreeRoot;
			structureTreeRoot.Put(PdfName.PARENTTREE, new PdfDictionary(PdfName.STRUCTELEM));
			SetReader(reader);
		}

		protected internal virtual void SetReader(PdfReader reader)
		{
			this.reader = reader;
			PdfObject obj = reader.Catalog.Get(PdfName.STRUCTTREEROOT);
			obj = GetDirectObject(obj);
			if (obj == null || !obj.IsDictionary())
			{
				throw new BadPdfFormatException(MessageLocalization.GetComposedMessage("no.structtreeroot.found"));
			}
			structTreeRoot = (PdfDictionary)obj;
			obj = GetDirectObject(structTreeRoot.Get(PdfName.PARENTTREE));
			if (obj == null || !obj.IsDictionary())
			{
				throw new BadPdfFormatException(MessageLocalization.GetComposedMessage("the.document.does.not.contain.parenttree"));
			}
			parentTree = (PdfDictionary)obj;
			sourceRoleMap = null;
			sourceClassMap = null;
			nullReference = null;
		}

		public static bool CheckTagged(PdfReader reader)
		{
			PdfObject obj = reader.Catalog.Get(PdfName.STRUCTTREEROOT);
			obj = GetDirectObject(obj);
			if (obj == null || !obj.IsDictionary())
			{
				return false;
			}
			PdfDictionary pdfDictionary = (PdfDictionary)obj;
			obj = GetDirectObject(pdfDictionary.Get(PdfName.PARENTTREE));
			if (obj == null || !obj.IsDictionary())
			{
				return false;
			}
			return true;
		}

		public static PdfObject GetDirectObject(PdfObject obj)
		{
			if (obj == null)
			{
				return null;
			}
			while (obj.IsIndirect())
			{
				obj = PdfReader.GetPdfObjectRelease(obj);
			}
			return obj;
		}

		public virtual void CopyStructTreeForPage(PdfNumber sourceArrayNumber, int newArrayNumber)
		{
			if (CopyPageMarks(parentTree, sourceArrayNumber, newArrayNumber) == ReturnType.NOTFOUND)
			{
				throw new BadPdfFormatException(MessageLocalization.GetComposedMessage("structparent.not.found"));
			}
		}

		private ReturnType CopyPageMarks(PdfDictionary parentTree, PdfNumber arrayNumber, int newArrayNumber)
		{
			PdfArray pdfArray = (PdfArray)GetDirectObject(parentTree.Get(PdfName.NUMS));
			if (pdfArray == null)
			{
				PdfArray pdfArray2 = (PdfArray)GetDirectObject(parentTree.Get(PdfName.KIDS));
				if (pdfArray2 == null)
				{
					return ReturnType.NOTFOUND;
				}
				int num = pdfArray2.Size / 2;
				int num2 = 0;
				while (true)
				{
					PdfDictionary pdfDictionary = (PdfDictionary)GetDirectObject(pdfArray2.GetPdfObject(num + num2));
					switch (CopyPageMarks(pdfDictionary, arrayNumber, newArrayNumber))
					{
					case ReturnType.FOUND:
						return ReturnType.FOUND;
					case ReturnType.ABOVE:
						num2 += num;
						num /= 2;
						if (num == 0)
						{
							num = 1;
						}
						if (num + num2 == pdfArray2.Size)
						{
							return ReturnType.ABOVE;
						}
						break;
					case ReturnType.BELOW:
						if (num + num2 == 0)
						{
							return ReturnType.BELOW;
						}
						if (num == 0)
						{
							return ReturnType.NOTFOUND;
						}
						num /= 2;
						break;
					default:
						return ReturnType.NOTFOUND;
					}
				}
			}
			if (pdfArray.Size == 0)
			{
				return ReturnType.NOTFOUND;
			}
			return FindAndCopyMarks(pdfArray, arrayNumber.IntValue, newArrayNumber);
		}

		private ReturnType FindAndCopyMarks(PdfArray pages, int arrayNumber, int newArrayNumber)
		{
			if (pages.GetAsNumber(0).IntValue > arrayNumber)
			{
				return ReturnType.BELOW;
			}
			if (pages.GetAsNumber(pages.Size - 2).IntValue < arrayNumber)
			{
				return ReturnType.ABOVE;
			}
			int num = pages.Size / 4;
			int num2 = 0;
			while (true)
			{
				int intValue = pages.GetAsNumber((num2 + num) * 2).IntValue;
				if (intValue == arrayNumber)
				{
					PdfObject pdfObject = pages.GetPdfObject((num2 + num) * 2 + 1);
					PdfObject inp = pdfObject;
					while (pdfObject.IsIndirect())
					{
						pdfObject = PdfReader.GetPdfObjectRelease(pdfObject);
					}
					if (pdfObject.IsArray())
					{
						PdfObject pdfObject2 = null;
						foreach (PdfObject item in (PdfArray)pdfObject)
						{
							if (item.IsNull())
							{
								if (nullReference == null)
								{
									nullReference = writer.AddToBody(new PdfNull()).IndirectReference;
								}
								structureTreeRoot.SetPageMark(newArrayNumber, nullReference);
								continue;
							}
							PdfObject pdfObject3 = writer.CopyObject(item, keepStruct: true, directRootKids: false);
							if (pdfObject2 == null)
							{
								pdfObject2 = pdfObject3;
							}
							structureTreeRoot.SetPageMark(newArrayNumber, (PdfIndirectReference)pdfObject3);
						}
						AttachStructTreeRootKids(pdfObject2);
					}
					else
					{
						if (!pdfObject.IsDictionary())
						{
							return ReturnType.NOTFOUND;
						}
						PdfDictionary kDict = GetKDict((PdfDictionary)pdfObject);
						if (kDict == null)
						{
							return ReturnType.NOTFOUND;
						}
						PdfObject pdfObject4 = writer.CopyObject(inp, keepStruct: true, directRootKids: false);
						structureTreeRoot.SetAnnotationMark(newArrayNumber, (PdfIndirectReference)pdfObject4);
					}
					return ReturnType.FOUND;
				}
				if (intValue < arrayNumber)
				{
					if (num == 0)
					{
						return ReturnType.NOTFOUND;
					}
					num2 += num;
					if (num != 1)
					{
						num /= 2;
					}
					if (num + num2 == pages.Size)
					{
						return ReturnType.NOTFOUND;
					}
				}
				else
				{
					if (num + num2 == 0)
					{
						return ReturnType.BELOW;
					}
					if (num == 0)
					{
						break;
					}
					num /= 2;
				}
			}
			return ReturnType.NOTFOUND;
		}

		protected internal virtual void AttachStructTreeRootKids(PdfObject firstNotNullKid)
		{
			PdfObject pdfObject = structTreeRoot.Get(PdfName.K);
			if (pdfObject == null || (!pdfObject.IsArray() && !pdfObject.IsIndirect()))
			{
				AddKid(structureTreeRoot, firstNotNullKid);
				return;
			}
			if (pdfObject.IsIndirect())
			{
				AddKid(pdfObject);
				return;
			}
			foreach (PdfObject item in (PdfArray)pdfObject)
			{
				AddKid(item);
			}
		}

		internal static PdfDictionary GetKDict(PdfDictionary obj)
		{
			PdfDictionary asDict = obj.GetAsDict(PdfName.K);
			if (asDict != null)
			{
				if (PdfName.OBJR.Equals(asDict.GetAsName(PdfName.TYPE)))
				{
					return asDict;
				}
			}
			else
			{
				PdfArray asArray = obj.GetAsArray(PdfName.K);
				if (asArray == null)
				{
					return null;
				}
				for (int i = 0; i < asArray.Size; i++)
				{
					asDict = asArray.GetAsDict(i);
					if (asDict != null && PdfName.OBJR.Equals(asDict.GetAsName(PdfName.TYPE)))
					{
						return asDict;
					}
				}
			}
			return null;
		}

		private void AddKid(PdfObject obj)
		{
			if (obj.IsIndirect())
			{
				PRIndirectReference pRIndirectReference = (PRIndirectReference)obj;
				RefKey key = new RefKey(pRIndirectReference);
				if (!writer.indirects.ContainsKey(key))
				{
					writer.CopyIndirect(pRIndirectReference, keepStructure: true, directRootKids: false);
				}
				PdfIndirectReference @ref = writer.indirects[key].Ref;
				if (writer.updateRootKids)
				{
					AddKid(structureTreeRoot, @ref);
					writer.StructureTreeRootKidsForReaderImported(reader);
				}
			}
		}

		private static PdfArray GetDirectArray(PdfArray input)
		{
			PdfArray pdfArray = new PdfArray();
			for (int i = 0; i < input.Size; i++)
			{
				PdfObject directObject = GetDirectObject(input.GetPdfObject(i));
				if (directObject != null)
				{
					if (directObject.IsArray())
					{
						pdfArray.Add(GetDirectArray((PdfArray)directObject));
					}
					else if (directObject.IsDictionary())
					{
						pdfArray.Add(GetDirectDict((PdfDictionary)directObject));
					}
					else
					{
						pdfArray.Add(directObject);
					}
				}
			}
			return pdfArray;
		}

		private static PdfDictionary GetDirectDict(PdfDictionary input)
		{
			PdfDictionary pdfDictionary = new PdfDictionary();
			foreach (KeyValuePair<PdfName, PdfObject> item in input.hashMap)
			{
				PdfObject directObject = GetDirectObject(item.Value);
				if (directObject != null)
				{
					if (directObject.IsArray())
					{
						pdfDictionary.Put(item.Key, GetDirectArray((PdfArray)directObject));
					}
					else if (directObject.IsDictionary())
					{
						pdfDictionary.Put(item.Key, GetDirectDict((PdfDictionary)directObject));
					}
					else
					{
						pdfDictionary.Put(item.Key, directObject);
					}
				}
			}
			return pdfDictionary;
		}

		public static bool CompareObjects(PdfObject value1, PdfObject value2)
		{
			value2 = GetDirectObject(value2);
			if (value2 == null)
			{
				return false;
			}
			if (value1.Type != value2.Type)
			{
				return false;
			}
			if (value1.IsBoolean())
			{
				if (value1 == value2)
				{
					return true;
				}
				if (value2 is PdfBoolean)
				{
					return ((PdfBoolean)value1).BooleanValue == ((PdfBoolean)value2).BooleanValue;
				}
				return false;
			}
			if (value1.IsName())
			{
				return value1.Equals(value2);
			}
			if (value1.IsNumber())
			{
				if (value1 == value2)
				{
					return true;
				}
				if (value2 is PdfNumber)
				{
					return ((PdfNumber)value1).DoubleValue == ((PdfNumber)value2).DoubleValue;
				}
				return false;
			}
			if (value1.IsNull())
			{
				if (value1 == value2)
				{
					return true;
				}
				if (value2 is PdfNull)
				{
					return true;
				}
				return false;
			}
			if (value1.IsString())
			{
				if (value1 == value2)
				{
					return true;
				}
				if (value2 is PdfString)
				{
					if (value2 != null || value1.ToString() != null)
					{
						return value1.ToString() == value2.ToString();
					}
					return true;
				}
				return false;
			}
			if (value1.IsArray())
			{
				PdfArray pdfArray = (PdfArray)value1;
				PdfArray pdfArray2 = (PdfArray)value2;
				if (pdfArray.Size != pdfArray2.Size)
				{
					return false;
				}
				for (int i = 0; i < pdfArray.Size; i++)
				{
					if (!CompareObjects(pdfArray.GetPdfObject(i), pdfArray2.GetPdfObject(i)))
					{
						return false;
					}
				}
				return true;
			}
			if (value1.IsDictionary())
			{
				PdfDictionary pdfDictionary = (PdfDictionary)value1;
				PdfDictionary pdfDictionary2 = (PdfDictionary)value2;
				if (pdfDictionary.Size != pdfDictionary2.Size)
				{
					return false;
				}
				foreach (PdfName key in pdfDictionary.hashMap.Keys)
				{
					if (!CompareObjects(pdfDictionary.Get(key), pdfDictionary2.Get(key)))
					{
						return false;
					}
				}
				return true;
			}
			return false;
		}

		internal void AddClass(PdfObject obj)
		{
			obj = GetDirectObject(obj);
			if (obj.IsDictionary())
			{
				PdfObject pdfObject = ((PdfDictionary)obj).Get(PdfName.C);
				if (pdfObject == null)
				{
					return;
				}
				if (pdfObject.IsArray())
				{
					PdfArray pdfArray = (PdfArray)pdfObject;
					for (int i = 0; i < pdfArray.Size; i++)
					{
						AddClass(pdfArray.GetPdfObject(i));
					}
				}
				else if (pdfObject.IsName())
				{
					AddClass(pdfObject);
				}
			}
			else
			{
				if (!obj.IsName())
				{
					return;
				}
				PdfName pdfName = (PdfName)obj;
				if (sourceClassMap == null)
				{
					obj = GetDirectObject(structTreeRoot.Get(PdfName.CLASSMAP));
					if (obj == null || !obj.IsDictionary())
					{
						return;
					}
					sourceClassMap = (PdfDictionary)obj;
				}
				obj = GetDirectObject(sourceClassMap.Get(pdfName));
				if (obj == null)
				{
					return;
				}
				PdfObject mappedClass = structureTreeRoot.GetMappedClass(pdfName);
				if (mappedClass != null)
				{
					if (!CompareObjects(mappedClass, obj))
					{
						throw new BadPdfFormatException(MessageLocalization.GetComposedMessage("conflict.in.classmap", pdfName));
					}
				}
				else if (obj.IsDictionary())
				{
					structureTreeRoot.MapClass(pdfName, GetDirectDict((PdfDictionary)obj));
				}
				else if (obj.IsArray())
				{
					structureTreeRoot.MapClass(pdfName, GetDirectArray((PdfArray)obj));
				}
			}
		}

		internal void AddRole(PdfName structType)
		{
			if (structType == null)
			{
				return;
			}
			foreach (PdfName standardStructElem in writer.GetStandardStructElems())
			{
				if (standardStructElem.Equals(structType))
				{
					return;
				}
			}
			PdfObject directObject;
			if (sourceRoleMap == null)
			{
				directObject = GetDirectObject(structTreeRoot.Get(PdfName.ROLEMAP));
				if (directObject == null || !directObject.IsDictionary())
				{
					return;
				}
				sourceRoleMap = (PdfDictionary)directObject;
			}
			directObject = sourceRoleMap.Get(structType);
			if (directObject == null || !directObject.IsName())
			{
				return;
			}
			PdfObject pdfObject;
			if (roleMap == null)
			{
				roleMap = new PdfDictionary();
				structureTreeRoot.Put(PdfName.ROLEMAP, roleMap);
				roleMap.Put(structType, directObject);
			}
			else if ((pdfObject = roleMap.Get(structType)) != null)
			{
				if (!pdfObject.Equals(directObject))
				{
					throw new BadPdfFormatException(MessageLocalization.GetComposedMessage("conflict.in.rolemap", structType));
				}
			}
			else
			{
				roleMap.Put(structType, directObject);
			}
		}

		protected virtual void AddKid(PdfDictionary parent, PdfObject kid)
		{
			PdfObject pdfObject = parent.Get(PdfName.K);
			PdfArray pdfArray;
			if (pdfObject is PdfArray)
			{
				pdfArray = (PdfArray)pdfObject;
			}
			else
			{
				pdfArray = new PdfArray();
				if (pdfObject != null)
				{
					pdfArray.Add(pdfObject);
				}
			}
			pdfArray.Add(kid);
			parent.Put(PdfName.K, pdfArray);
		}
	}
}
namespace iTextSharp.text.pdf.security
{
	public static class CertificateInfo
	{
		public class X509Name
		{
			public static DerObjectIdentifier C;

			public static DerObjectIdentifier O;

			public static DerObjectIdentifier OU;

			public static DerObjectIdentifier T;

			public static DerObjectIdentifier CN;

			public static DerObjectIdentifier SN;

			public static DerObjectIdentifier L;

			public static DerObjectIdentifier ST;

			public static DerObjectIdentifier SURNAME;

			public static DerObjectIdentifier GIVENNAME;

			public static DerObjectIdentifier INITIALS;

			public static DerObjectIdentifier GENERATION;

			public static DerObjectIdentifier UNIQUE_IDENTIFIER;

			public static DerObjectIdentifier EmailAddress;

			public static DerObjectIdentifier E;

			public static DerObjectIdentifier DC;

			public static DerObjectIdentifier UID;

			public static readonly Dictionary<DerObjectIdentifier, string> DefaultSymbols;

			public Dictionary<string, List<string>> values = new Dictionary<string, List<string>>();

			static X509Name()
			{
				C = new DerObjectIdentifier("2.5.4.6");
				O = new DerObjectIdentifier("2.5.4.10");
				OU = new DerObjectIdentifier("2.5.4.11");
				T = new DerObjectIdentifier("2.5.4.12");
				CN = new DerObjectIdentifier("2.5.4.3");
				SN = new DerObjectIdentifier("2.5.4.5");
				L = new DerObjectIdentifier("2.5.4.7");
				ST = new DerObjectIdentifier("2.5.4.8");
				SURNAME = new DerObjectIdentifier("2.5.4.4");
				GIVENNAME = new DerObjectIdentifier("2.5.4.42");
				INITIALS = new DerObjectIdentifier("2.5.4.43");
				GENERATION = new DerObjectIdentifier("2.5.4.44");
				UNIQUE_IDENTIFIER = new DerObjectIdentifier("2.5.4.45");
				EmailAddress = new DerObjectIdentifier("1.2.840.113549.1.9.1");
				E = EmailAddress;
				DC = new DerObjectIdentifier("0.9.2342.19200300.100.1.25");
				UID = new DerObjectIdentifier("0.9.2342.19200300.100.1.1");
				DefaultSymbols = new Dictionary<DerObjectIdentifier, string>();
				DefaultSymbols[C] = "C";
				DefaultSymbols[O] = "O";
				DefaultSymbols[T] = "T";
				DefaultSymbols[OU] = "OU";
				DefaultSymbols[CN] = "CN";
				DefaultSymbols[L] = "L";
				DefaultSymbols[ST] = "ST";
				DefaultSymbols[SN] = "SN";
				DefaultSymbols[EmailAddress] = "E";
				DefaultSymbols[DC] = "DC";
				DefaultSymbols[UID] = "UID";
				DefaultSymbols[SURNAME] = "SURNAME";
				DefaultSymbols[GIVENNAME] = "GIVENNAME";
				DefaultSymbols[INITIALS] = "INITIALS";
				DefaultSymbols[GENERATION] = "GENERATION";
			}

			public X509Name(Asn1Sequence seq)
			{
				IEnumerator enumerator = seq.GetEnumerator();
				while (enumerator.MoveNext())
				{
					Asn1Set asn1Set = (Asn1Set)enumerator.Current;
					for (int i = 0; i < asn1Set.Count; i++)
					{
						Asn1Sequence asn1Sequence = (Asn1Sequence)asn1Set[i];
						if (asn1Sequence[0] is DerObjectIdentifier && DefaultSymbols.TryGetValue((DerObjectIdentifier)asn1Sequence[0], out var value))
						{
							if (!values.TryGetValue(value, out var value2))
							{
								value2 = new List<string>();
								values[value] = value2;
							}
							value2.Add(((DerStringBase)asn1Sequence[1]).GetString());
						}
					}
				}
			}

			public X509Name(string dirName)
			{
				X509NameTokenizer x509NameTokenizer = new X509NameTokenizer(dirName);
				while (x509NameTokenizer.HasMoreTokens())
				{
					string text = x509NameTokenizer.NextToken();
					int num = text.IndexOf('=');
					if (num == -1)
					{
						throw new ArgumentException(MessageLocalization.GetComposedMessage("badly.formated.directory.string"));
					}
					string key = text.Substring(0, num).ToUpper(CultureInfo.InvariantCulture);
					string item = text.Substring(num + 1);
					if (!values.TryGetValue(key, out var value))
					{
						value = new List<string>();
						values[key] = value;
					}
					value.Add(item);
				}
			}

			public virtual string GetField(string name)
			{
				if (values.TryGetValue(name, out var value))
				{
					if (value.Count != 0)
					{
						return value[0];
					}
					return null;
				}
				return null;
			}

			public virtual List<string> GetFieldArray(string name)
			{
				if (values.TryGetValue(name, out var value))
				{
					return value;
				}
				return null;
			}

			public virtual Dictionary<string, List<string>> GetFields()
			{
				return values;
			}

			public override string ToString()
			{
				return values.ToString();
			}
		}

		public class X509NameTokenizer
		{
			private string oid;

			private int index;

			private StringBuilder buf = new StringBuilder();

			public X509NameTokenizer(string oid)
			{
				this.oid = oid;
				index = -1;
			}

			public virtual bool HasMoreTokens()
			{
				return index != oid.Length;
			}

			public virtual string NextToken()
			{
				if (index == oid.Length)
				{
					return null;
				}
				int i = index + 1;
				bool flag = false;
				bool flag2 = false;
				buf.Length = 0;
				for (; i != oid.Length; i++)
				{
					char c = oid[i];
					if (c == '"')
					{
						if (!flag2)
						{
							flag = !flag;
						}
						else
						{
							buf.Append(c);
						}
						flag2 = false;
						continue;
					}
					if (flag2 || flag)
					{
						buf.Append(c);
						flag2 = false;
						continue;
					}
					switch (c)
					{
					case '\\':
						flag2 = true;
						continue;
					default:
						buf.Append(c);
						continue;
					case ',':
						break;
					}
					break;
				}
				index = i;
				return buf.ToString().Trim();
			}
		}

		public static X509Name GetIssuerFields(Org.BouncyCastle.X509.X509Certificate cert)
		{
