		public static Asn1Object GetIssuer(byte[] enc)
		{
			Asn1InputStream asn1InputStream = new Asn1InputStream(new MemoryStream(enc));
			Asn1Sequence asn1Sequence = (Asn1Sequence)asn1InputStream.ReadObject();
			return (Asn1Object)asn1Sequence[(asn1Sequence[0] is Asn1TaggedObject) ? 3 : 2];
		}

		public static X509Name GetSubjectFields(Org.BouncyCastle.X509.X509Certificate cert)
		{
			if (cert != null)
			{
				return new X509Name((Asn1Sequence)GetSubject(cert.GetTbsCertificate()));
			}
			return null;
		}

		private static Asn1Object GetSubject(byte[] enc)
		{
			Asn1InputStream asn1InputStream = new Asn1InputStream(new MemoryStream(enc));
			Asn1Sequence asn1Sequence = (Asn1Sequence)asn1InputStream.ReadObject();
			return (Asn1Object)asn1Sequence[(asn1Sequence[0] is Asn1TaggedObject) ? 5 : 4];
		}
	}
	public static class CertificateUtil
	{
		public static string GetCRLURL(Org.BouncyCastle.X509.X509Certificate certificate)
		{
			try
			{
				Asn1Object extensionValue = GetExtensionValue(certificate, X509Extensions.CrlDistributionPoints.Id);
				if (extensionValue == null)
				{
					return null;
				}
				CrlDistPoint instance = CrlDistPoint.GetInstance(extensionValue);
				DistributionPoint[] distributionPoints = instance.GetDistributionPoints();
				DistributionPoint[] array = distributionPoints;
				foreach (DistributionPoint distributionPoint in array)
				{
					DistributionPointName distributionPointName = distributionPoint.DistributionPointName;
					if (distributionPointName.PointType != 0)
					{
						continue;
					}
					GeneralNames generalNames = (GeneralNames)distributionPointName.Name;
					GeneralName[] names = generalNames.GetNames();
					GeneralName[] array2 = names;
					foreach (GeneralName generalName in array2)
					{
						if (generalName.TagNo == 6)
						{
							DerIA5String instance2 = DerIA5String.GetInstance((Asn1TaggedObject)generalName.ToAsn1Object(), isExplicit: false);
							return instance2.GetString();
						}
					}
				}
			}
			catch
			{
			}
			return null;
		}

		public static string GetOCSPURL(Org.BouncyCastle.X509.X509Certificate certificate)
		{
			try
			{
				Asn1Object extensionValue = GetExtensionValue(certificate, X509Extensions.AuthorityInfoAccess.Id);
				if (extensionValue == null)
				{
					return null;
				}
				Asn1Sequence asn1Sequence = (Asn1Sequence)extensionValue;
				for (int i = 0; i < asn1Sequence.Count; i++)
				{
					Asn1Sequence asn1Sequence2 = (Asn1Sequence)asn1Sequence[i];
					if (asn1Sequence2.Count == 2 && asn1Sequence2[0] is DerObjectIdentifier && ((DerObjectIdentifier)asn1Sequence2[0]).Id.Equals("1.3.6.1.5.5.7.48.1"))
					{
						string stringFromGeneralName = GetStringFromGeneralName((Asn1Object)asn1Sequence2[1]);
						if (stringFromGeneralName == null)
						{
							return "";
						}
						return stringFromGeneralName;
					}
				}
			}
			catch
			{
			}
			return null;
		}

		public static string GetTSAURL(Org.BouncyCastle.X509.X509Certificate certificate)
		{
			Asn1OctetString extensionValue = certificate.GetExtensionValue("1.2.840.113583.1.1.9.1");
			if (extensionValue == null)
			{
				return null;
			}
			byte[] octets = extensionValue.GetOctets();
			if (octets == null)
			{
				return null;
			}
			try
			{
				Asn1Object asn1Object = Asn1Object.FromByteArray(octets);
				if (asn1Object is DerOctetString)
				{
					DerOctetString derOctetString = (DerOctetString)asn1Object;
					asn1Object = Asn1Object.FromByteArray(derOctetString.GetOctets());
				}
				Asn1Sequence instance = Asn1Sequence.GetInstance(asn1Object);
				return GetStringFromGeneralName(instance[1].ToAsn1Object());
			}
			catch (IOException)
			{
				return null;
			}
		}

		private static Asn1Object GetExtensionValue(Org.BouncyCastle.X509.X509Certificate cert, string oid)
		{
			byte[] derEncoded = cert.GetExtensionValue(new DerObjectIdentifier(oid)).GetDerEncoded();
			if (derEncoded == null)
			{
				return null;
			}
			Asn1InputStream asn1InputStream = new Asn1InputStream(new MemoryStream(derEncoded));
			Asn1OctetString asn1OctetString = (Asn1OctetString)asn1InputStream.ReadObject();
			asn1InputStream = new Asn1InputStream(new MemoryStream(asn1OctetString.GetOctets()));
			return asn1InputStream.ReadObject();
		}

		private static string GetStringFromGeneralName(Asn1Object names)
		{
			Asn1TaggedObject obj = (Asn1TaggedObject)names;
			return Encoding.GetEncoding(1252).GetString(Asn1OctetString.GetInstance(obj, isExplicit: false).GetOctets());
		}
	}
	public static class CertificateVerification
	{
		public static string VerifyCertificate(Org.BouncyCastle.X509.X509Certificate cert, ICollection<X509Crl> crls, DateTime calendar)
		{
			foreach (string criticalExtensionOid in cert.GetCriticalExtensionOids())
			{
				if (criticalExtensionOid == X509Extensions.KeyUsage.Id || criticalExtensionOid == X509Extensions.CertificatePolicies.Id || criticalExtensionOid == X509Extensions.PolicyMappings.Id || criticalExtensionOid == X509Extensions.InhibitAnyPolicy.Id || criticalExtensionOid == X509Extensions.CrlDistributionPoints.Id || criticalExtensionOid == X509Extensions.IssuingDistributionPoint.Id || criticalExtensionOid == X509Extensions.DeltaCrlIndicator.Id || criticalExtensionOid == X509Extensions.PolicyConstraints.Id || criticalExtensionOid == X509Extensions.BasicConstraints.Id || criticalExtensionOid == X509Extensions.SubjectAlternativeName.Id || criticalExtensionOid == X509Extensions.NameConstraints.Id)
				{
					continue;
				}
				try
				{
					if (criticalExtensionOid == X509Extensions.ExtendedKeyUsage.Id && cert.GetExtendedKeyUsage().Contains("1.3.6.1.5.5.7.3.8"))
					{
						continue;
					}
				}
				catch (CertificateParsingException)
				{
				}
				return "Has unsupported critical extension";
			}
			try
			{
				if (!cert.IsValid(calendar.ToUniversalTime()))
				{
					return "The certificate has expired or is not yet valid";
				}
				if (crls != null)
				{
					foreach (X509Crl crl in crls)
					{
						if (crl.IsRevoked(cert))
						{
							return "Certificate revoked";
						}
					}
				}
			}
			catch (Exception ex2)
			{
				return ex2.ToString();
			}
			return null;
		}

		public static IList<VerificationException> VerifyCertificates(ICollection<Org.BouncyCastle.X509.X509Certificate> certs, ICollection<Org.BouncyCastle.X509.X509Certificate> keystore, ICollection<X509Crl> crls, DateTime calendar)
		{
			IList<VerificationException> list = new List<VerificationException>();
			Org.BouncyCastle.X509.X509Certificate[] array = new Org.BouncyCastle.X509.X509Certificate[certs.Count];
			certs.CopyTo(array, 0);
			for (int i = 0; i < array.Length; i++)
			{
				Org.BouncyCastle.X509.X509Certificate x509Certificate = array[i];
				string text = VerifyCertificate(x509Certificate, crls, calendar);
				if (text != null)
				{
					list.Add(new VerificationException(x509Certificate, text));
				}
				foreach (Org.BouncyCastle.X509.X509Certificate item in keystore)
				{
					try
					{
						if (VerifyCertificate(item, crls, calendar) == null)
						{
							try
							{
								x509Certificate.Verify(item.GetPublicKey());
								return list;
							}
							catch
							{
							}
						}
					}
					catch
					{
					}
				}
				int j;
				for (j = 0; j < array.Length; j++)
				{
					if (j != i)
					{
						Org.BouncyCastle.X509.X509Certificate x509Certificate2 = array[j];
						try
						{
							x509Certificate.Verify(x509Certificate2.GetPublicKey());
						}
						catch
						{
							continue;
						}
						break;
					}
				}
				if (j == array.Length)
				{
					list.Add(new VerificationException(x509Certificate, "Cannot be verified against the KeyStore or the certificate chain"));
				}
			}
			if (list.Count == 0)
			{
				list.Add(new VerificationException(null, "Invalid state. Possible circular certificate chain"));
			}
			return list;
		}

		public static IList<VerificationException> VerifyCertificates(ICollection<Org.BouncyCastle.X509.X509Certificate> certs, ICollection<Org.BouncyCastle.X509.X509Certificate> keystore, DateTime calendar)
		{
			return VerifyCertificates(certs, keystore, null, calendar);
		}

		public static bool VerifyOcspCertificates(BasicOcspResp ocsp, ICollection<Org.BouncyCastle.X509.X509Certificate> keystore)
		{
			try
			{
				foreach (Org.BouncyCastle.X509.X509Certificate item in keystore)
				{
					try
					{
						if (ocsp.Verify(item.GetPublicKey()))
						{
							return true;
						}
					}
					catch
					{
					}
				}
			}
			catch
			{
			}
			return false;
		}

		public static bool VerifyTimestampCertificates(TimeStampToken ts, ICollection<Org.BouncyCastle.X509.X509Certificate> keystore)
		{
			try
			{
				foreach (Org.BouncyCastle.X509.X509Certificate item in keystore)
				{
					try
					{
						ts.Validate(item);
						return true;
					}
					catch
					{
					}
				}
			}
			catch
			{
			}
			return false;
		}
	}
	public class CertificateVerifier
	{
		protected CertificateVerifier verifier;

		protected bool onlineCheckingAllowed = true;

		public virtual bool OnlineCheckingAllowed
		{
			set
			{
				onlineCheckingAllowed = value;
			}
		}

		public CertificateVerifier(CertificateVerifier verifier)
		{
			this.verifier = verifier;
		}

		public virtual List<VerificationOK> Verify(Org.BouncyCastle.X509.X509Certificate signCert, Org.BouncyCastle.X509.X509Certificate issuerCert, DateTime signDate)
		{
			signCert.CheckValidity(signDate);
			if (issuerCert != null)
			{
				signCert.Verify(issuerCert.GetPublicKey());
			}
			else
			{
				signCert.Verify(signCert.GetPublicKey());
			}
			List<VerificationOK> list = new List<VerificationOK>();
			if (verifier != null)
			{
				list.AddRange(verifier.Verify(signCert, issuerCert, signDate));
			}
			return list;
		}
	}
