	public class CrlClientOnline : ICrlClient
	{
		private static readonly ILogger LOGGER = LoggerFactory.GetLogger(typeof(CrlClientOnline));

		protected IList<string> urls = new List<string>();

		public CrlClientOnline()
		{
		}

		public CrlClientOnline(params string[] crls)
		{
			foreach (string url in crls)
			{
				AddUrl(url);
			}
		}

		public CrlClientOnline(ICollection<Org.BouncyCastle.X509.X509Certificate> chain)
		{
			foreach (Org.BouncyCastle.X509.X509Certificate item in chain)
			{
				string text = null;
				try
				{
					LOGGER.Info("Checking certificate: " + item.SubjectDN.ToString());
					text = CertificateUtil.GetCRLURL(item);
					if (text != null)
					{
						AddUrl(text);
					}
				}
				catch (CertificateParsingException)
				{
					LOGGER.Info("Skipped CRL url: (certificate could not be parsed)");
				}
			}
		}

		protected virtual void AddUrl(string url)
		{
			if (urls.Contains(url))
			{
				LOGGER.Info("Skipped CRL url (duplicate): " + url);
				return;
			}
			LOGGER.Info("Added CRL url: " + url);
			urls.Add(url);
		}

		public virtual ICollection<byte[]> GetEncoded(Org.BouncyCastle.X509.X509Certificate checkCert, string url)
		{
			if (checkCert == null)
			{
				return null;
			}
			List<string> list = new List<string>(urls);
			if (list.Count == 0)
			{
				LOGGER.Info("Looking for CRL for certificate " + checkCert.SubjectDN.ToString());
				try
				{
					if (url == null)
					{
						url = CertificateUtil.GetCRLURL(checkCert);
					}
					if (url == null)
					{
						throw new ArgumentNullException();
					}
					list.Add(url);
					LOGGER.Info("Found CRL url: " + url);
				}
				catch (Exception ex)
				{
					LOGGER.Info("Skipped CRL url: " + ex.Message);
				}
			}
			List<byte[]> list2 = new List<byte[]>();
			foreach (string item in list)
			{
				try
				{
					LOGGER.Info("Checking CRL: " + item);
					HttpWebRequest httpWebRequest = (HttpWebRequest)WebRequest.Create(item);
					HttpWebResponse httpWebResponse = (HttpWebResponse)httpWebRequest.GetResponse();
					if (httpWebResponse.StatusCode != HttpStatusCode.OK)
					{
						throw new IOException(MessageLocalization.GetComposedMessage("invalid.http.response.1", (int)httpWebResponse.StatusCode));
					}
					Stream responseStream = httpWebResponse.GetResponseStream();
					byte[] array = new byte[1024];
					MemoryStream memoryStream = new MemoryStream();
					while (true)
					{
						int num = responseStream.Read(array, 0, array.Length);
						if (num <= 0)
						{
							break;
						}
						memoryStream.Write(array, 0, num);
					}
					responseStream.Close();
					list2.Add(memoryStream.ToArray());
					LOGGER.Info("Added CRL found at: " + item);
				}
				catch (Exception ex2)
				{
					LOGGER.Info("Skipped CRL: " + ex2.Message + " for " + item);
				}
			}
			return list2;
		}
	}
	public class RootStoreVerifier : CertificateVerifier
	{
		private static ILogger LOGGER = LoggerFactory.GetLogger(typeof(RootStoreVerifier));

		protected List<Org.BouncyCastle.X509.X509Certificate> certificates;

		public virtual List<Org.BouncyCastle.X509.X509Certificate> Certificates
		{
			set
			{
				certificates = value;
			}
		}

		public RootStoreVerifier(CertificateVerifier verifier)
			: base(verifier)
		{
		}

		public override List<VerificationOK> Verify(Org.BouncyCastle.X509.X509Certificate signCert, Org.BouncyCastle.X509.X509Certificate issuerCert, DateTime signDate)
		{
			LOGGER.Info("Root store verification: " + signCert.SubjectDN);
			if (certificates == null)
			{
				return base.Verify(signCert, issuerCert, signDate);
			}
			try
			{
				List<VerificationOK> list = new List<VerificationOK>();
				foreach (Org.BouncyCastle.X509.X509Certificate certificate in certificates)
				{
					try
					{
						signCert.Verify(certificate.GetPublicKey());
						LOGGER.Info("Certificate verified against root store");
						list.Add(new VerificationOK(signCert, this, "Certificate verified against root store."));
						list.AddRange(base.Verify(signCert, issuerCert, signDate));
						return list;
					}
					catch (GeneralSecurityException)
					{
					}
				}
				list.AddRange(base.Verify(signCert, issuerCert, signDate));
				return list;
			}
			catch (GeneralSecurityException)
			{
				return base.Verify(signCert, issuerCert, signDate);
			}
		}
	}
	public class CrlVerifier : RootStoreVerifier
	{
		private static ILogger LOGGER = LoggerFactory.GetLogger(typeof(CrlVerifier));

		private List<X509Crl> crls;

		public CrlVerifier(CertificateVerifier verifier, List<X509Crl> crls)
			: base(verifier)
		{
			this.crls = crls;
		}

		public override List<VerificationOK> Verify(Org.BouncyCastle.X509.X509Certificate signCert, Org.BouncyCastle.X509.X509Certificate issuerCert, DateTime signDate)
		{
			List<VerificationOK> list = new List<VerificationOK>();
			int num = 0;
			if (crls != null)
			{
				foreach (X509Crl crl in crls)
				{
					if (Verify(crl, signCert, issuerCert, signDate))
					{
						num++;
					}
				}
			}
			bool flag = false;
			if (onlineCheckingAllowed && num == 0 && Verify(GetCrl(signCert, issuerCert), signCert, issuerCert, signDate))
			{
				num++;
				flag = true;
			}
			LOGGER.Info("Valid CRLs found: " + num);
			if (num > 0)
			{
				list.Add(new VerificationOK(signCert, this, "Valid CRLs found: " + num + (flag ? " (online)" : "")));
			}
			if (verifier != null)
			{
				list.AddRange(verifier.Verify(signCert, issuerCert, signDate));
			}
			return list;
		}

		public virtual bool Verify(X509Crl crl, Org.BouncyCastle.X509.X509Certificate signCert, Org.BouncyCastle.X509.X509Certificate issuerCert, DateTime signDate)
		{
			if (crl == null || signDate == DateTime.MaxValue)
			{
				return false;
			}
			if (crl.IssuerDN.Equals(signCert.IssuerDN) && signDate.CompareTo(crl.ThisUpdate) > 0 && signDate.CompareTo(crl.NextUpdate.Value) < 0)
			{
				if (IsSignatureValid(crl, issuerCert) && crl.IsRevoked(signCert))
				{
					throw new VerificationException(signCert, $"{signCert} The certificate has been revoked.");
				}
				return true;
			}
			return false;
		}

		public virtual X509Crl GetCrl(Org.BouncyCastle.X509.X509Certificate signCert, Org.BouncyCastle.X509.X509Certificate issuerCert)
		{
			try
			{
				string cRLURL = CertificateUtil.GetCRLURL(signCert);
				if (cRLURL == null)
				{
					return null;
				}
				LOGGER.Info("Getting CRL from " + cRLURL);
				X509CrlParser x509CrlParser = new X509CrlParser();
				Stream responseStream = WebRequest.Create(cRLURL).GetResponse().GetResponseStream();
				return x509CrlParser.ReadCrl(responseStream);
			}
			catch (IOException)
			{
				return null;
			}
			catch (GeneralSecurityException)
			{
				return null;
			}
		}

		public virtual bool IsSignatureValid(X509Crl crl, Org.BouncyCastle.X509.X509Certificate crlIssuer)
		{
			if (crlIssuer != null)
			{
				try
				{
					crl.Verify(crlIssuer.GetPublicKey());
					return true;
				}
				catch (GeneralSecurityException)
				{
					LOGGER.Warn("CRL not issued by the same authority as the certificate that is being checked");
				}
			}
			if (certificates == null)
			{
				return false;
			}
			try
			{
				foreach (Org.BouncyCastle.X509.X509Certificate certificate in certificates)
				{
					try
					{
						crl.Verify(certificate.GetPublicKey());
						return true;
					}
					catch (GeneralSecurityException)
					{
					}
				}
			}
			catch (GeneralSecurityException)
			{
				return false;
			}
			return false;
		}
	}
