	public static class LtvTimestamp
	{
		public static void Timestamp(PdfSignatureAppearance sap, ITSAClient tsa, string signatureName)
		{
			int tokenSizeEstimate = tsa.GetTokenSizeEstimate();
			sap.AddDeveloperExtension(PdfDeveloperExtension.ESIC_1_7_EXTENSIONLEVEL5);
			sap.SetVisibleSignature(new Rectangle(0f, 0f, 0f, 0f), 1, signatureName);
			PdfSignature pdfSignature = new PdfSignature(PdfName.ADOBE_PPKLITE, PdfName.ETSI_RFC3161);
			pdfSignature.Put(PdfName.TYPE, PdfName.DOCTIMESTAMP);
			sap.CryptoDictionary = pdfSignature;
			Dictionary<PdfName, int> dictionary = new Dictionary<PdfName, int>();
			dictionary[PdfName.CONTENTS] = tokenSizeEstimate * 2 + 2;
			sap.PreClose(dictionary);
			Stream rangeStream = sap.GetRangeStream();
			IDigest messageDigest = tsa.GetMessageDigest();
			byte[] array = new byte[4096];
			int length;
			while ((length = rangeStream.Read(array, 0, array.Length)) > 0)
			{
				messageDigest.BlockUpdate(array, 0, length);
			}
			byte[] array2 = new byte[messageDigest.GetDigestSize()];
			messageDigest.DoFinal(array2, 0);
			byte[] timeStampToken;
			try
			{
				timeStampToken = tsa.GetTimeStampToken(array2);
			}
			catch (Exception ex)
			{
				throw new GeneralSecurityException(ex.Message);
			}
			if (tokenSizeEstimate + 2 < timeStampToken.Length)
			{
				throw new IOException("Not enough space");
			}
			byte[] array3 = new byte[tokenSizeEstimate];
			Array.Copy(timeStampToken, 0, array3, 0, timeStampToken.Length);
			PdfDictionary pdfDictionary = new PdfDictionary();
			pdfDictionary.Put(PdfName.CONTENTS, new PdfString(array3).SetHexWriting(hexWriting: true));
			sap.Close(pdfDictionary);
		}
	}
	public class LtvVerification
	{
		public enum Level
		{
			OCSP,
			CRL,
			OCSP_CRL,
			OCSP_OPTIONAL_CRL
		}

		public enum CertificateOption
		{
			SIGNING_CERTIFICATE,
			WHOLE_CHAIN
		}

		public enum CertificateInclusion
		{
			YES,
			NO
		}

		private class ValidationData
		{
			public IList<byte[]> crls = new List<byte[]>();

			public IList<byte[]> ocsps = new List<byte[]>();

			public IList<byte[]> certs = new List<byte[]>();
		}

		private ILogger LOGGER = LoggerFactory.GetLogger(typeof(LtvVerification));

		private PdfStamper stp;

		private PdfWriter writer;

		private PdfReader reader;

		private AcroFields acroFields;

		private IDictionary<PdfName, ValidationData> validated = new Dictionary<PdfName, ValidationData>();

		private bool used;

		public LtvVerification(PdfStamper stp)
		{
			this.stp = stp;
			writer = stp.Writer;
			reader = stp.Reader;
			acroFields = stp.AcroFields;
		}

		public virtual bool AddVerification(string signatureName, IOcspClient ocsp, ICrlClient crl, CertificateOption certOption, Level level, CertificateInclusion certInclude)
		{
			if (used)
			{
				throw new InvalidOperationException(MessageLocalization.GetComposedMessage("verification.already.output"));
			}
			PdfPKCS7 pdfPKCS = acroFields.VerifySignature(signatureName);
			LOGGER.Info("Adding verification for " + signatureName);
			Org.BouncyCastle.X509.X509Certificate[] certificates = pdfPKCS.Certificates;
			Org.BouncyCastle.X509.X509Certificate signingCertificate = pdfPKCS.SigningCertificate;
			ValidationData validationData = new ValidationData();
			for (int i = 0; i < certificates.Length; i++)
			{
				Org.BouncyCastle.X509.X509Certificate x509Certificate = certificates[i];
				LOGGER.Info("Certificate: " + x509Certificate.SubjectDN);
				if (certOption == CertificateOption.SIGNING_CERTIFICATE && !x509Certificate.Equals(signingCertificate))
				{
					continue;
				}
				byte[] array = null;
				if (ocsp != null && level != Level.CRL)
				{
					array = ocsp.GetEncoded(x509Certificate, GetParent(x509Certificate, certificates), null);
					if (array != null)
					{
						validationData.ocsps.Add(BuildOCSPResponse(array));
						LOGGER.Info("OCSP added");
					}
				}
				if (crl != null && (level == Level.CRL || level == Level.OCSP_CRL || (level == Level.OCSP_OPTIONAL_CRL && array == null)))
				{
					ICollection<byte[]> encoded = crl.GetEncoded(certificates[i], null);
					if (encoded != null)
					{
						foreach (byte[] item in encoded)
						{
							bool flag = false;
							foreach (byte[] crl2 in validationData.crls)
							{
								if (Arrays.AreEqual(crl2, item))
								{
									flag = true;
									break;
								}
							}
							if (!flag)
							{
								validationData.crls.Add(item);
								LOGGER.Info("CRL added");
							}
						}
					}
				}
				if (certInclude == CertificateInclusion.YES)
				{
					validationData.certs.Add(certificates[i].GetEncoded());
				}
			}
			if (validationData.crls.Count == 0 && validationData.ocsps.Count == 0)
			{
				return false;
			}
			validated[GetSignatureHashKey(signatureName)] = validationData;
			return true;
		}

		private Org.BouncyCastle.X509.X509Certificate GetParent(Org.BouncyCastle.X509.X509Certificate cert, Org.BouncyCastle.X509.X509Certificate[] certs)
		{
			foreach (Org.BouncyCastle.X509.X509Certificate x509Certificate in certs)
			{
				if (cert.IssuerDN.Equals(x509Certificate.SubjectDN))
				{
					try
					{
						cert.Verify(x509Certificate.GetPublicKey());
						return x509Certificate;
					}
					catch
					{
					}
				}
			}
			return null;
		}

		public virtual bool AddVerification(string signatureName, ICollection<byte[]> ocsps, ICollection<byte[]> crls, ICollection<byte[]> certs)
		{
			if (used)
			{
				throw new InvalidOperationException(MessageLocalization.GetComposedMessage("verification.already.output"));
			}
			ValidationData validationData = new ValidationData();
			if (ocsps != null)
			{
				foreach (byte[] ocsp in ocsps)
				{
					validationData.ocsps.Add(BuildOCSPResponse(ocsp));
				}
			}
			if (crls != null)
			{
				foreach (byte[] crl in crls)
				{
					validationData.crls.Add(crl);
				}
			}
			if (certs != null)
			{
				foreach (byte[] cert in certs)
				{
					validationData.certs.Add(cert);
				}
			}
			validated[GetSignatureHashKey(signatureName)] = validationData;
			return true;
		}

		private static byte[] BuildOCSPResponse(byte[] BasicOCSPResponse)
		{
			DerOctetString element = new DerOctetString(BasicOCSPResponse);
			Asn1EncodableVector asn1EncodableVector = new Asn1EncodableVector();
			asn1EncodableVector.Add(OcspObjectIdentifiers.PkixOcspBasic);
			asn1EncodableVector.Add(element);
			DerEnumerated element2 = new DerEnumerated(0);
			Asn1EncodableVector asn1EncodableVector2 = new Asn1EncodableVector();
			asn1EncodableVector2.Add(element2);
			asn1EncodableVector2.Add(new DerTaggedObject(explicitly: true, 0, new DerSequence(asn1EncodableVector)));
			DerSequence derSequence = new DerSequence(asn1EncodableVector2);
			return derSequence.GetEncoded();
		}

		private PdfName GetSignatureHashKey(string signatureName)
		{
			PdfDictionary signatureDictionary = acroFields.GetSignatureDictionary(signatureName);
			PdfString asString = signatureDictionary.GetAsString(PdfName.CONTENTS);
			byte[] array = asString.GetOriginalBytes();
			byte[] array2 = null;
			if (PdfName.ETSI_RFC3161.Equals(signatureDictionary.GetAsName(PdfName.SUBFILTER)))
			{
				Asn1InputStream asn1InputStream = new Asn1InputStream(new MemoryStream(array));
				Asn1Object asn1Object = asn1InputStream.ReadObject();
				array = asn1Object.GetEncoded();
			}
			array2 = HashBytesSha1(array);
			return new PdfName(Utilities.ConvertToHex(array2));
		}

		private static byte[] HashBytesSha1(byte[] b)
		{
			return DigestAlgorithms.Digest("SHA1", b);
		}

		public virtual void Merge()
		{
			if (!used && validated.Count != 0)
			{
				used = true;
				PdfDictionary catalog = reader.Catalog;
				PdfObject pdfObject = catalog.Get(PdfName.DSS);
				if (pdfObject == null)
				{
					CreateDss();
				}
				else
				{
					UpdateDss();
				}
			}
		}

		private void UpdateDss()
		{
			PdfDictionary catalog = reader.Catalog;
			stp.MarkUsed(catalog);
			PdfDictionary asDict = catalog.GetAsDict(PdfName.DSS);
			PdfArray pdfArray = asDict.GetAsArray(PdfName.OCSPS);
			PdfArray pdfArray2 = asDict.GetAsArray(PdfName.CRLS);
			PdfArray pdfArray3 = asDict.GetAsArray(PdfName.CERTS);
			asDict.Remove(PdfName.OCSPS);
			asDict.Remove(PdfName.CRLS);
			asDict.Remove(PdfName.CERTS);
			PdfDictionary pdfDictionary = asDict.GetAsDict(PdfName.VRI);
			if (pdfDictionary != null)
			{
				foreach (PdfName key in pdfDictionary.Keys)
				{
					if (validated.ContainsKey(key))
					{
						PdfDictionary asDict2 = pdfDictionary.GetAsDict(key);
						if (asDict2 != null)
						{
							DeleteOldReferences(pdfArray, asDict2.GetAsArray(PdfName.OCSP));
							DeleteOldReferences(pdfArray2, asDict2.GetAsArray(PdfName.CRL));
							DeleteOldReferences(pdfArray3, asDict2.GetAsArray(PdfName.CERT));
						}
					}
				}
			}
			if (pdfArray == null)
			{
				pdfArray = new PdfArray();
			}
			if (pdfArray2 == null)
			{
				pdfArray2 = new PdfArray();
			}
			if (pdfArray3 == null)
			{
				pdfArray3 = new PdfArray();
			}
			if (pdfDictionary == null)
			{
				pdfDictionary = new PdfDictionary();
			}
			OutputDss(asDict, pdfDictionary, pdfArray, pdfArray2, pdfArray3);
		}

		private static void DeleteOldReferences(PdfArray all, PdfArray toDelete)
		{
			if (all == null || toDelete == null)
			{
				return;
			}
			foreach (PdfObject item in toDelete)
			{
				if (!item.IsIndirect())
				{
					continue;
				}
				PRIndirectReference pRIndirectReference = (PRIndirectReference)item;
				for (int i = 0; i < all.Size; i++)
				{
					PdfObject pdfObject = all[i];
					if (pdfObject.IsIndirect())
					{
						PRIndirectReference pRIndirectReference2 = (PRIndirectReference)pdfObject;
						if (pRIndirectReference.Number == pRIndirectReference2.Number)
						{
							all.Remove(i);
							i--;
						}
					}
				}
			}
		}

		private void CreateDss()
		{
			OutputDss(new PdfDictionary(), new PdfDictionary(), new PdfArray(), new PdfArray(), new PdfArray());
		}

		private void OutputDss(PdfDictionary dss, PdfDictionary vrim, PdfArray ocsps, PdfArray crls, PdfArray certs)
		{
			writer.AddDeveloperExtension(PdfDeveloperExtension.ESIC_1_7_EXTENSIONLEVEL5);
			PdfDictionary catalog = reader.Catalog;
			stp.MarkUsed(catalog);
			foreach (PdfName key in validated.Keys)
			{
				PdfArray pdfArray = new PdfArray();
				PdfArray pdfArray2 = new PdfArray();
				PdfArray pdfArray3 = new PdfArray();
				PdfDictionary pdfDictionary = new PdfDictionary();
				foreach (byte[] crl in validated[key].crls)
				{
					PdfStream pdfStream = new PdfStream(crl);
					pdfStream.FlateCompress();
					PdfIndirectReference indirectReference = writer.AddToBody(pdfStream, inObjStm: false).IndirectReference;
					pdfArray2.Add(indirectReference);
					crls.Add(indirectReference);
				}
				foreach (byte[] ocsp in validated[key].ocsps)
				{
					PdfStream pdfStream2 = new PdfStream(ocsp);
					pdfStream2.FlateCompress();
					PdfIndirectReference indirectReference2 = writer.AddToBody(pdfStream2, inObjStm: false).IndirectReference;
					pdfArray.Add(indirectReference2);
					ocsps.Add(indirectReference2);
				}
				foreach (byte[] cert in validated[key].certs)
				{
					PdfStream pdfStream3 = new PdfStream(cert);
					pdfStream3.FlateCompress();
					PdfIndirectReference indirectReference3 = writer.AddToBody(pdfStream3, inObjStm: false).IndirectReference;
					pdfArray3.Add(indirectReference3);
					certs.Add(indirectReference3);
				}
				if (pdfArray.Size > 0)
				{
					pdfDictionary.Put(PdfName.OCSP, writer.AddToBody(pdfArray, inObjStm: false).IndirectReference);
				}
				if (pdfArray2.Size > 0)
				{
					pdfDictionary.Put(PdfName.CRL, writer.AddToBody(pdfArray2, inObjStm: false).IndirectReference);
				}
				if (pdfArray3.Size > 0)
				{
					pdfDictionary.Put(PdfName.CERT, writer.AddToBody(pdfArray3, inObjStm: false).IndirectReference);
				}
				vrim.Put(key, writer.AddToBody(pdfDictionary, inObjStm: false).IndirectReference);
			}
			dss.Put(PdfName.VRI, writer.AddToBody(vrim, inObjStm: false).IndirectReference);
			if (ocsps.Size > 0)
			{
				dss.Put(PdfName.OCSPS, writer.AddToBody(ocsps, inObjStm: false).IndirectReference);
			}
			if (crls.Size > 0)
			{
				dss.Put(PdfName.CRLS, writer.AddToBody(crls, inObjStm: false).IndirectReference);
			}
			if (certs.Size > 0)
			{
				dss.Put(PdfName.CERTS, writer.AddToBody(certs, inObjStm: false).IndirectReference);
			}
			catalog.Put(PdfName.DSS, writer.AddToBody(dss, inObjStm: false).IndirectReference);
		}
	}
	public class LtvVerifier : RootStoreVerifier
	{
		private static ILogger LOGGER = LoggerFactory.GetLogger(typeof(LtvVerifier));

		protected LtvVerification.CertificateOption option;

		protected bool verifyRootCertificate = true;

		protected PdfReader reader;

		protected AcroFields fields;

		protected DateTime signDate;

		protected string signatureName;

		protected PdfPKCS7 pkcs7;

		protected bool latestRevision = true;

		protected PdfDictionary dss;

		public virtual CertificateVerifier Verifier
		{
			set
			{
				verifier = value;
			}
		}

		public virtual LtvVerification.CertificateOption CertificateOption
		{
			set
			{
				option = value;
			}
		}

		public virtual bool VerifyRootCertificate
		{
			set
			{
				verifyRootCertificate = value;
			}
		}

		public LtvVerifier(PdfReader reader)
			: base(null)
		{
			this.reader = reader;
			fields = reader.AcroFields;
			List<string> signatureNames = fields.GetSignatureNames();
			signatureName = signatureNames[signatureNames.Count - 1];
			signDate = DateTime.Now;
			pkcs7 = CoversWholeDocument();
			if (LOGGER.IsLogging(Level.INFO))
			{
				LOGGER.Info(string.Format("Checking {0}signature {1}", pkcs7.IsTsp ? "document-level timestamp " : "", signatureName));
			}
		}

		protected virtual PdfPKCS7 CoversWholeDocument()
		{
			PdfPKCS7 pdfPKCS = fields.VerifySignature(signatureName);
			if (fields.SignatureCoversWholeDocument(signatureName))
			{
				LOGGER.Info("The timestamp covers whole document.");
				if (pdfPKCS.Verify())
				{
					LOGGER.Info("The signed document has not been modified.");
					return pdfPKCS;
				}
				throw new VerificationException(null, "The document was altered after the signature was applied.");
			}
			throw new VerificationException(null, "Signature doesn't cover whole document.");
		}

		public virtual List<VerificationOK> Verify(List<VerificationOK> result)
		{
			if (result == null)
			{
				result = new List<VerificationOK>();
			}
			while (pkcs7 != null)
			{
				result.AddRange(VerifySignature());
			}
			return result;
		}

		public virtual List<VerificationOK> VerifySignature()
		{
			LOGGER.Info("Verifying signature.");
			List<VerificationOK> list = new List<VerificationOK>();
			Org.BouncyCastle.X509.X509Certificate[] signCertificateChain = pkcs7.SignCertificateChain;
			VerifyChain(signCertificateChain);
			int num = 1;
			if (LtvVerification.CertificateOption.WHOLE_CHAIN.Equals(option))
			{
				num = signCertificateChain.Length;
			}
			int num2 = 0;
			while (num2 < num)
			{
				Org.BouncyCastle.X509.X509Certificate x509Certificate = signCertificateChain[num2];
				Org.BouncyCastle.X509.X509Certificate issuerCert = null;
				if (++num2 < signCertificateChain.Length)
				{
					issuerCert = signCertificateChain[num2];
				}
				LOGGER.Info(x509Certificate.SubjectDN.ToString());
				List<VerificationOK> list2 = Verify(x509Certificate, issuerCert, signDate);
				if (list2.Count == 0)
				{
					try
					{
						x509Certificate.Verify(x509Certificate.GetPublicKey());
						if (latestRevision && signCertificateChain.Length > 1)
						{
							list2.Add(new VerificationOK(x509Certificate, this, "Root certificate in revision"));
						}
						if (list2.Count == 0 && verifyRootCertificate)
						{
							throw new GeneralSecurityException();
						}
						if (signCertificateChain.Length > 1)
						{
							list2.Add(new VerificationOK(x509Certificate, this, "Root certificate passed without checking"));
						}
					}
					catch (GeneralSecurityException)
					{
						throw new VerificationException(x509Certificate, "Couldn't verify with CRL or OCSP or trusted anchor");
					}
				}
				list.AddRange(list2);
			}
			SwitchToPreviousRevision();
			return list;
		}

		public virtual void VerifyChain(Org.BouncyCastle.X509.X509Certificate[] chain)
		{
			for (int i = 0; i < chain.Length; i++)
			{
				Org.BouncyCastle.X509.X509Certificate x509Certificate = chain[i];
				x509Certificate.CheckValidity(signDate);
				if (i > 0)
				{
					chain[i - 1].Verify(chain[i].GetPublicKey());
				}
			}
			LOGGER.Info("All certificates are valid on " + signDate.ToString("F"));
		}

		public override List<VerificationOK> Verify(Org.BouncyCastle.X509.X509Certificate signCert, Org.BouncyCastle.X509.X509Certificate issuerCert, DateTime sigDate)
		{
			RootStoreVerifier rootStoreVerifier = new RootStoreVerifier(verifier);
			rootStoreVerifier.Certificates = certificates;
			CrlVerifier crlVerifier = new CrlVerifier(rootStoreVerifier, GetCRLsFromDSS());
			crlVerifier.Certificates = certificates;
			crlVerifier.OnlineCheckingAllowed = latestRevision || onlineCheckingAllowed;
			OcspVerifier ocspVerifier = new OcspVerifier(crlVerifier, GetOCSPResponsesFromDSS());
			ocspVerifier.Certificates = certificates;
			ocspVerifier.OnlineCheckingAllowed = latestRevision || onlineCheckingAllowed;
			return ocspVerifier.Verify(signCert, issuerCert, sigDate);
		}

		public virtual void SwitchToPreviousRevision()
		{
			LOGGER.Info("Switching to previous revision.");
			latestRevision = false;
			dss = reader.Catalog.GetAsDict(PdfName.DSS);
			DateTime timeStampDate = pkcs7.TimeStampDate;
			if (timeStampDate == DateTime.MaxValue)
			{
				timeStampDate = pkcs7.SignDate;
			}
			signDate = timeStampDate;
			List<string> signatureNames = fields.GetSignatureNames();
			if (signatureNames.Count > 1)
			{
				signatureName = signatureNames[signatureNames.Count - 2];
				reader = new PdfReader(fields.ExtractRevision(signatureName));
				fields = reader.AcroFields;
				signatureNames = fields.GetSignatureNames();
				signatureName = signatureNames[signatureNames.Count - 1];
				pkcs7 = CoversWholeDocument();
				if (LOGGER.IsLogging(Level.INFO))
				{
					LOGGER.Info(string.Format("Checking {0}signature {1}", pkcs7.IsTsp ? "document-level timestamp " : "", signatureName));
				}
			}
			else
			{
				LOGGER.Info("No signatures in revision");
				pkcs7 = null;
			}
		}

		public virtual List<X509Crl> GetCRLsFromDSS()
		{
			List<X509Crl> list = new List<X509Crl>();
			if (dss == null)
			{
				return list;
			}
			PdfArray asArray = dss.GetAsArray(PdfName.CRLS);
			if (asArray == null)
			{
				return list;
			}
			X509CrlParser x509CrlParser = new X509CrlParser();
			for (int i = 0; i < asArray.Size; i++)
			{
				PRStream stream = (PRStream)asArray.GetAsStream(i);
				X509Crl item = x509CrlParser.ReadCrl(new MemoryStream(PdfReader.GetStreamBytes(stream)));
				list.Add(item);
			}
			return list;
		}

		public virtual List<BasicOcspResp> GetOCSPResponsesFromDSS()
		{
			List<BasicOcspResp> list = new List<BasicOcspResp>();
			if (dss == null)
			{
				return list;
			}
			PdfArray asArray = dss.GetAsArray(PdfName.OCSPS);
			if (asArray == null)
			{
				return list;
			}
			for (int i = 0; i < asArray.Size; i++)
			{
				PRStream stream = (PRStream)asArray.GetAsStream(i);
				OcspResp ocspResp = new OcspResp(PdfReader.GetStreamBytes(stream));
				if (ocspResp.Status == 0)
				{
					try
					{
						list.Add((BasicOcspResp)ocspResp.GetResponseObject());
					}
					catch (OcspException ex)
					{
						throw new GeneralSecurityException(ex.ToString());
					}
				}
			}
			return list;
		}
	}
	public enum CryptoStandard
	{
		CMS,
		CADES
	}
	public static class MakeSignature
	{
		private static readonly ILogger LOGGER = LoggerFactory.GetLogger(typeof(MakeSignature));

		public static void SignDetached(PdfSignatureAppearance sap, IExternalSignature externalSignature, ICollection<Org.BouncyCastle.X509.X509Certificate> chain, ICollection<ICrlClient> crlList, IOcspClient ocspClient, ITSAClient tsaClient, int estimatedSize, CryptoStandard sigtype)
		{
			SignDetached(sap, externalSignature, chain, crlList, ocspClient, tsaClient, estimatedSize, sigtype, (SignaturePolicyIdentifier)null);
		}

		public static void SignDetached(PdfSignatureAppearance sap, IExternalSignature externalSignature, ICollection<Org.BouncyCastle.X509.X509Certificate> chain, ICollection<ICrlClient> crlList, IOcspClient ocspClient, ITSAClient tsaClient, int estimatedSize, CryptoStandard sigtype, SignaturePolicyInfo signaturePolicy)
		{
			SignDetached(sap, externalSignature, chain, crlList, ocspClient, tsaClient, estimatedSize, sigtype, signaturePolicy?.ToSignaturePolicyIdentifier());
		}

		public static void SignDetached(PdfSignatureAppearance sap, IExternalSignature externalSignature, ICollection<Org.BouncyCastle.X509.X509Certificate> chain, ICollection<ICrlClient> crlList, IOcspClient ocspClient, ITSAClient tsaClient, int estimatedSize, CryptoStandard sigtype, SignaturePolicyIdentifier signaturePolicy)
		{
			List<Org.BouncyCastle.X509.X509Certificate> list = new List<Org.BouncyCastle.X509.X509Certificate>(chain);
			ICollection<byte[]> collection = null;
			int num = 0;
			while (collection == null && num < list.Count)
			{
				collection = ProcessCrl(list[num++], crlList);
			}
			if (estimatedSize == 0)
			{
				estimatedSize = 8192;
				if (collection != null)
				{
					foreach (byte[] item in collection)
					{
						estimatedSize += item.Length + 10;
					}
				}
				if (ocspClient != null)
				{
					estimatedSize += 4192;
				}
				if (tsaClient != null)
				{
					estimatedSize += 4192;
				}
			}
			sap.Certificate = list[0];
			if (sigtype == CryptoStandard.CADES)
			{
				sap.AddDeveloperExtension(PdfDeveloperExtension.ESIC_1_7_EXTENSIONLEVEL2);
			}
			PdfSignature pdfSignature = new PdfSignature(PdfName.ADOBE_PPKLITE, (sigtype == CryptoStandard.CADES) ? PdfName.ETSI_CADES_DETACHED : PdfName.ADBE_PKCS7_DETACHED);
			pdfSignature.Reason = sap.Reason;
			pdfSignature.Location = sap.Location;
			pdfSignature.SignatureCreator = sap.SignatureCreator;
			pdfSignature.Contact = sap.Contact;
			pdfSignature.Date = new PdfDate(sap.SignDate);
			sap.CryptoDictionary = pdfSignature;
			Dictionary<PdfName, int> dictionary = new Dictionary<PdfName, int>();
			dictionary[PdfName.CONTENTS] = estimatedSize * 2 + 2;
			sap.PreClose(dictionary);
			string hashAlgorithm = externalSignature.GetHashAlgorithm();
			PdfPKCS7 pdfPKCS = new PdfPKCS7(null, chain, hashAlgorithm, hasRSAdata: false);
			if (signaturePolicy != null)
			{
				pdfPKCS.SetSignaturePolicy(signaturePolicy);
			}
			DigestUtilities.GetDigest(hashAlgorithm);
			Stream rangeStream = sap.GetRangeStream();
			byte[] secondDigest = DigestAlgorithms.Digest(rangeStream, hashAlgorithm);
			byte[] ocsp = null;
			if (chain.Count >= 2 && ocspClient != null)
			{
				ocsp = ocspClient.GetEncoded(list[0], list[1], null);
			}
			byte[] authenticatedAttributeBytes = pdfPKCS.getAuthenticatedAttributeBytes(secondDigest, ocsp, collection, sigtype);
			byte[] digest = externalSignature.Sign(authenticatedAttributeBytes);
			pdfPKCS.SetExternalDigest(digest, null, externalSignature.GetEncryptionAlgorithm());
			byte[] encodedPKCS = pdfPKCS.GetEncodedPKCS7(secondDigest, tsaClient, ocsp, collection, sigtype);
			if (estimatedSize < encodedPKCS.Length)
			{
				throw new IOException("Not enough space");
			}
			byte[] array = new byte[estimatedSize];
			Array.Copy(encodedPKCS, 0, array, 0, encodedPKCS.Length);
			PdfDictionary pdfDictionary = new PdfDictionary();
			pdfDictionary.Put(PdfName.CONTENTS, new PdfString(array).SetHexWriting(hexWriting: true));
			sap.Close(pdfDictionary);
		}

		public static ICollection<byte[]> ProcessCrl(Org.BouncyCastle.X509.X509Certificate cert, ICollection<ICrlClient> crlList)
		{
			if (crlList == null)
			{
				return null;
			}
			List<byte[]> list = new List<byte[]>();
			foreach (ICrlClient crl in crlList)
			{
				if (crl != null)
				{
					ICollection<byte[]> encoded = crl.GetEncoded(cert, null);
					if (encoded != null)
					{
						LOGGER.Info("Processing " + crl.GetType().Name);
						list.AddRange(encoded);
					}
				}
			}
			if (list.Count == 0)
			{
				return null;
			}
			return list;
		}

		public static void SignExternalContainer(PdfSignatureAppearance sap, IExternalSignatureContainer externalSignatureContainer, int estimatedSize)
		{
			PdfSignature pdfSignature = new PdfSignature(null, null);
			pdfSignature.Reason = sap.Reason;
			pdfSignature.Location = sap.Location;
			pdfSignature.SignatureCreator = sap.SignatureCreator;
			pdfSignature.Contact = sap.Contact;
			pdfSignature.Date = new PdfDate(sap.SignDate);
			externalSignatureContainer.ModifySigningDictionary(pdfSignature);
			sap.CryptoDictionary = pdfSignature;
			Dictionary<PdfName, int> dictionary = new Dictionary<PdfName, int>();
			dictionary[PdfName.CONTENTS] = estimatedSize * 2 + 2;
			sap.PreClose(dictionary);
			Stream rangeStream = sap.GetRangeStream();
			byte[] array = externalSignatureContainer.Sign(rangeStream);
			if (estimatedSize < array.Length)
			{
				throw new IOException("Not enough space");
			}
			byte[] array2 = new byte[estimatedSize];
			Array.Copy(array, 0, array2, 0, array.Length);
			PdfDictionary pdfDictionary = new PdfDictionary();
			pdfDictionary.Put(PdfName.CONTENTS, new PdfString(array2).SetHexWriting(hexWriting: true));
			sap.Close(pdfDictionary);
		}

		public static void SignDeferred(PdfReader reader, string fieldName, Stream outs, IExternalSignatureContainer externalSignatureContainer)
		{
			AcroFields acroFields = reader.AcroFields;
			PdfDictionary signatureDictionary = acroFields.GetSignatureDictionary(fieldName);
			if (signatureDictionary == null)
			{
				throw new DocumentException("No field");
			}
			if (!acroFields.SignatureCoversWholeDocument(fieldName))
			{
				throw new DocumentException("Not the last signature");
			}
			PdfArray asArray = signatureDictionary.GetAsArray(PdfName.BYTERANGE);
			long[] array = asArray.AsLongArray();
			if (asArray.Size != 4 || array[0] != 0)
			{
				throw new DocumentException("Single exclusion space supported");
			}
			IRandomAccessSource source = reader.SafeFile.CreateSourceView();
			Stream data = new RASInputStream(new RandomAccessSourceFactory().CreateRanged(source, array));
			byte[] array2 = externalSignatureContainer.Sign(data);
			int num = (int)(array[2] - array[1]) - 2;
			if (((uint)num & (true ? 1u : 0u)) != 0)
			{
				throw new DocumentException("Gap is not a multiple of 2");
			}
			num /= 2;
			if (num < array2.Length)
			{
				throw new DocumentException("Not enough space");
			}
			StreamUtil.CopyBytes(source, 0L, array[1] + 1, outs);
			ByteBuffer byteBuffer = new ByteBuffer(num * 2);
			byte[] array3 = array2;
			foreach (byte b in array3)
			{
				byteBuffer.AppendHex(b);
			}
			int num2 = (num - array2.Length) * 2;
			for (int j = 0; j < num2; j++)
			{
				byteBuffer.Append((byte)48);
			}
			byteBuffer.WriteTo(outs);
			StreamUtil.CopyBytes(source, array[2] - 1, array[3] + 1, outs);
		}
	}
	public class OcspClientBouncyCastle : IOcspClient
	{
		private static readonly ILogger LOGGER = LoggerFactory.GetLogger(typeof(OcspClientBouncyCastle));

		private readonly OcspVerifier verifier;

		[Obsolete]
		public OcspClientBouncyCastle()
		{
			verifier = null;
		}

		public OcspClientBouncyCastle(OcspVerifier verifier)
		{
			this.verifier = verifier;
		}

		public virtual BasicOcspResp GetBasicOCSPResp(Org.BouncyCastle.X509.X509Certificate checkCert, Org.BouncyCastle.X509.X509Certificate rootCert, string url)
		{
			try
			{
				OcspResp ocspResponse = GetOcspResponse(checkCert, rootCert, url);
				if (ocspResponse == null)
				{
					return null;
				}
				if (ocspResponse.Status != 0)
				{
					return null;
				}
				BasicOcspResp basicOcspResp = (BasicOcspResp)ocspResponse.GetResponseObject();
				if (verifier != null)
				{
					verifier.IsValidResponse(basicOcspResp, rootCert);
				}
				return basicOcspResp;
			}
			catch (Exception ex)
			{
				if (LOGGER.IsLogging(Level.ERROR))
				{
					LOGGER.Error(ex.Message);
				}
			}
			return null;
		}

		public byte[] GetEncoded(Org.BouncyCastle.X509.X509Certificate checkCert, Org.BouncyCastle.X509.X509Certificate rootCert, string url)
		{
			try
			{
				BasicOcspResp basicOCSPResp = GetBasicOCSPResp(checkCert, rootCert, url);
				if (basicOCSPResp != null)
				{
					SingleResp[] responses = basicOCSPResp.Responses;
					if (responses.Length == 1)
					{
						SingleResp singleResp = responses[0];
						object certStatus = singleResp.GetCertStatus();
						if (certStatus == CertificateStatus.Good)
						{
							return basicOCSPResp.GetEncoded();
						}
						if (certStatus is RevokedStatus)
						{
							throw new IOException(MessageLocalization.GetComposedMessage("ocsp.status.is.revoked"));
						}
						throw new IOException(MessageLocalization.GetComposedMessage("ocsp.status.is.unknown"));
					}
				}
			}
			catch (Exception ex)
			{
				if (LOGGER.IsLogging(Level.ERROR))
				{
					LOGGER.Error(ex.Message);
				}
			}
			return null;
		}

		private static OcspReq GenerateOCSPRequest(Org.BouncyCastle.X509.X509Certificate issuerCert, BigInteger serialNumber)
		{
			CertificateID certId = new CertificateID("1.3.14.3.2.26", issuerCert, serialNumber);
			OcspReqGenerator ocspReqGenerator = new OcspReqGenerator();
			ocspReqGenerator.AddRequest(certId);
			IDictionary dictionary = new Hashtable();
			dictionary[OcspObjectIdentifiers.PkixOcspNonce] = new Org.BouncyCastle.Asn1.X509.X509Extension(critical: false, new DerOctetString(new DerOctetString(PdfEncryption.CreateDocumentId()).GetEncoded()));
			ocspReqGenerator.SetRequestExtensions(new X509Extensions(dictionary));
			return ocspReqGenerator.Generate();
		}

		private OcspResp GetOcspResponse(Org.BouncyCastle.X509.X509Certificate checkCert, Org.BouncyCastle.X509.X509Certificate rootCert, string url)
		{
			if (checkCert == null || rootCert == null)
			{
				return null;
			}
			if (url == null)
			{
				url = CertificateUtil.GetOCSPURL(checkCert);
			}
			if (url == null)
			{
				return null;
			}
			LOGGER.Info("Getting OCSP from " + url);
			OcspReq ocspReq = GenerateOCSPRequest(rootCert, checkCert.SerialNumber);
			byte[] encoded = ocspReq.GetEncoded();
			HttpWebRequest httpWebRequest = (HttpWebRequest)WebRequest.Create(url);
			httpWebRequest.ContentLength = encoded.Length;
			httpWebRequest.ContentType = "application/ocsp-request";
			httpWebRequest.Accept = "application/ocsp-response";
			httpWebRequest.Method = "POST";
			Stream requestStream = httpWebRequest.GetRequestStream();
			requestStream.Write(encoded, 0, encoded.Length);
			requestStream.Close();
			HttpWebResponse httpWebResponse = (HttpWebResponse)httpWebRequest.GetResponse();
			if (httpWebResponse.StatusCode != HttpStatusCode.OK)
			{
				throw new IOException(MessageLocalization.GetComposedMessage("invalid.http.response.1", (int)httpWebResponse.StatusCode));
			}
			Stream responseStream = httpWebResponse.GetResponseStream();
			OcspResp result = new OcspResp(responseStream);
			responseStream.Close();
			httpWebResponse.Close();
			return result;
		}
	}
	public class OcspVerifier : RootStoreVerifier
	{
		private static ILogger LOGGER = LoggerFactory.GetLogger(typeof(OcspVerifier));

		protected static readonly string id_kp_OCSPSigning = "1.3.6.1.5.5.7.3.9";

		protected List<BasicOcspResp> ocsps;

		public OcspVerifier(CertificateVerifier verifier, List<BasicOcspResp> ocsps)
			: base(verifier)
		{
			this.ocsps = ocsps;
		}

		public override List<VerificationOK> Verify(Org.BouncyCastle.X509.X509Certificate signCert, Org.BouncyCastle.X509.X509Certificate issuerCert, DateTime signDate)
		{
			List<VerificationOK> list = new List<VerificationOK>();
			int num = 0;
			if (ocsps != null)
			{
				foreach (BasicOcspResp ocsp in ocsps)
				{
					if (Verify(ocsp, signCert, issuerCert, signDate))
					{
						num++;
					}
				}
			}
			bool flag = false;
			if (onlineCheckingAllowed && num == 0 && Verify(GetOcspResponse(signCert, issuerCert), signCert, issuerCert, signDate))
			{
				num++;
				flag = true;
			}
			LOGGER.Info("Valid OCSPs found: " + num);
			if (num > 0)
			{
				list.Add(new VerificationOK(signCert, this, "Valid OCSPs Found: " + num + (flag ? " (online)" : "")));
			}
			if (verifier != null)
			{
				list.AddRange(verifier.Verify(signCert, issuerCert, signDate));
			}
			return list;
		}

		public virtual bool Verify(BasicOcspResp ocspResp, Org.BouncyCastle.X509.X509Certificate signCert, Org.BouncyCastle.X509.X509Certificate issuerCert, DateTime signDate)
		{
			if (ocspResp == null)
			{
				return false;
			}
			SingleResp[] responses = ocspResp.Responses;
			for (int i = 0; i < responses.Length; i++)
			{
				if (!signCert.SerialNumber.Equals(responses[i].GetCertID().SerialNumber))
				{
					continue;
				}
				try
				{
					if (issuerCert == null)
					{
						issuerCert = signCert;
					}
					if (!responses[i].GetCertID().MatchesIssuer(issuerCert))
					{
						LOGGER.Info("OCSP: Issuers doesn't match.");
						continue;
					}
				}
				catch (OcspException)
				{
					continue;
				}
				DateTimeObject nextUpdate = responses[i].NextUpdate;
				DateTime dateTime;
				if (nextUpdate == null)
				{
					dateTime = responses[i].ThisUpdate.AddSeconds(180.0);
					LOGGER.Info("No 'next update' for OCSP Response; assuming " + dateTime);
				}
				else
				{
					dateTime = nextUpdate.Value;
				}
				if (signDate > dateTime)
				{
					if (LOGGER.IsLogging(Level.INFO))
					{
						LOGGER.Info($"OCSP no longer valid: {signDate} after {dateTime}");
					}
					continue;
				}
				object certStatus = responses[i].GetCertStatus();
				if (certStatus != CertificateStatus.Good)
				{
					continue;
				}
				IsValidResponse(ocspResp, issuerCert);
				return true;
			}
			return false;
		}

		public virtual void IsValidResponse(BasicOcspResp ocspResp, Org.BouncyCastle.X509.X509Certificate issuerCert)
		{
			Org.BouncyCastle.X509.X509Certificate x509Certificate = null;
			if (IsSignatureValid(ocspResp, issuerCert))
			{
				x509Certificate = issuerCert;
			}
			if (x509Certificate == null)
			{
				if (ocspResp.GetCerts() != null)
				{
					Org.BouncyCastle.X509.X509Certificate[] certs = ocspResp.GetCerts();
					Org.BouncyCastle.X509.X509Certificate[] array = certs;
					foreach (Org.BouncyCastle.X509.X509Certificate x509Certificate2 in array)
					{
						Org.BouncyCastle.X509.X509Certificate x509Certificate3;
						try
						{
							x509Certificate3 = x509Certificate2;
						}
						catch (Exception)
						{
							continue;
						}
						IList list = null;
						try
						{
							list = x509Certificate3.GetExtendedKeyUsage();
							if (list != null && list.Contains(id_kp_OCSPSigning) && IsSignatureValid(ocspResp, x509Certificate3))
							{
								x509Certificate = x509Certificate3;
								break;
							}
						}
						catch (CertificateParsingException)
						{
						}
					}
					if (x509Certificate == null)
					{
						throw new VerificationException(issuerCert, "OCSP response could not be verified");
					}
				}
				else
				{
					if (certificates != null)
					{
						foreach (Org.BouncyCastle.X509.X509Certificate certificate in certificates)
						{
							try
							{
								if (IsSignatureValid(ocspResp, certificate))
								{
									x509Certificate = certificate;
									break;
								}
							}
							catch (GeneralSecurityException)
							{
							}
						}
					}
					if (x509Certificate == null)
					{
						throw new VerificationException(issuerCert, "OCSP response could not be verified");
					}
				}
			}
			x509Certificate.Verify(issuerCert.GetPublicKey());
			if (x509Certificate.GetExtensionValue(OcspObjectIdentifiers.PkixOcspNocheck.Id) == null)
			{
				X509Crl x509Crl;
				try
				{
					X509CrlParser x509CrlParser = new X509CrlParser();
					Stream responseStream = WebRequest.Create(CertificateUtil.GetCRLURL(x509Certificate)).GetResponse().GetResponseStream();
					x509Crl = x509CrlParser.ReadCrl(responseStream);
				}
				catch (Exception)
				{
					x509Crl = null;
				}
				if (x509Crl != null)
				{
					CrlVerifier crlVerifier = new CrlVerifier(null, null);
					crlVerifier.Certificates = certificates;
					crlVerifier.OnlineCheckingAllowed = onlineCheckingAllowed;
					crlVerifier.Verify(x509Crl, x509Certificate, issuerCert, DateTime.UtcNow);
					return;
				}
			}
			x509Certificate.CheckValidity();
		}

		[Obsolete]
		public virtual bool VerifyResponse(BasicOcspResp ocspResp, Org.BouncyCastle.X509.X509Certificate issuerCert)
		{
			try
			{
				IsValidResponse(ocspResp, issuerCert);
				return true;
			}
			catch (Exception)
			{
				return false;
			}
		}

		public virtual bool IsSignatureValid(BasicOcspResp ocspResp, Org.BouncyCastle.X509.X509Certificate responderCert)
		{
			try
			{
				return ocspResp.Verify(responderCert.GetPublicKey());
			}
			catch (OcspException)
			{
				return false;
			}
		}

		public virtual BasicOcspResp GetOcspResponse(Org.BouncyCastle.X509.X509Certificate signCert, Org.BouncyCastle.X509.X509Certificate issuerCert)
		{
			if (signCert == null && issuerCert == null)
			{
				return null;
			}
			OcspClientBouncyCastle ocspClientBouncyCastle = new OcspClientBouncyCastle();
			BasicOcspResp basicOCSPResp = ocspClientBouncyCastle.GetBasicOCSPResp(signCert, issuerCert, null);
			if (basicOCSPResp == null)
			{
				return null;
			}
			SingleResp[] responses = basicOCSPResp.Responses;
			for (int i = 0; i < responses.Length; i++)
			{
				object certStatus = responses[i].GetCertStatus();
				if (certStatus == CertificateStatus.Good)
				{
					return basicOCSPResp;
				}
			}
			return null;
		}
	}
