	public class SignaturePermissions
	{
		public class FieldLock
		{
			private readonly PdfName action;

			private readonly PdfArray fields;

			public virtual PdfName Action => action;

			public virtual PdfArray Fields => fields;

			public FieldLock(PdfName action, PdfArray fields)
			{
				this.action = action;
				this.fields = fields;
			}

			public override string ToString()
			{
				return string.Concat(action, (fields == null) ? "" : fields.ToString());
			}
		}

		private readonly bool certification;

		private readonly bool fillInAllowed = true;

		private readonly bool annotationsAllowed = true;

		private readonly List<FieldLock> fieldLocks = new List<FieldLock>();

		public virtual bool Certification => certification;

		public virtual bool FillInAllowed => fillInAllowed;

		public virtual bool AnnotationsAllowed => annotationsAllowed;

		public virtual List<FieldLock> FieldLocks => fieldLocks;

		public SignaturePermissions(PdfDictionary sigDict, SignaturePermissions previous)
		{
			if (previous != null)
			{
				annotationsAllowed &= previous.AnnotationsAllowed;
				fillInAllowed &= previous.FillInAllowed;
				fieldLocks.AddRange(previous.FieldLocks);
			}
			PdfArray asArray = sigDict.GetAsArray(PdfName.REFERENCE);
			if (asArray == null)
			{
				return;
			}
			for (int i = 0; i < asArray.Size; i++)
			{
				PdfDictionary asDict = asArray.GetAsDict(i);
				PdfDictionary asDict2 = asDict.GetAsDict(PdfName.TRANSFORMPARAMS);
				if (PdfName.DOCMDP.Equals(asDict.GetAsName(PdfName.TRANSFORMMETHOD)))
				{
					certification = true;
				}
				PdfName asName = asDict2.GetAsName(PdfName.ACTION);
				if (asName != null)
				{
					fieldLocks.Add(new FieldLock(asName, asDict2.GetAsArray(PdfName.FIELDS)));
				}
				PdfNumber asNumber = asDict2.GetAsNumber(PdfName.P);
				if (asNumber != null)
				{
					switch (asNumber.IntValue)
					{
					case 1:
						fillInAllowed = false;
						break;
					case 2:
						annotationsAllowed = false;
						break;
					}
				}
			}
		}
	}
	public class TSAClientBouncyCastle : ITSAClient
	{
		public const int DEFAULTTOKENSIZE = 4096;

		public const string DEFAULTHASHALGORITHM = "SHA-256";

		private static readonly ILogger LOGGER = LoggerFactory.GetLogger(typeof(TSAClientBouncyCastle));

		protected internal string tsaURL;

		protected internal string tsaUsername;

		protected internal string tsaPassword;

		protected ITSAInfoBouncyCastle tsaInfo;

		protected internal int tokenSizeEstimate;

		protected internal string digestAlgorithm;

		private string tsaReqPolicy;

		public TSAClientBouncyCastle(string url)
			: this(url, null, null, 4096, "SHA-256")
		{
		}

		public TSAClientBouncyCastle(string url, string username, string password)
			: this(url, username, password, 4096, "SHA-256")
		{
		}

		public TSAClientBouncyCastle(string url, string username, string password, int tokSzEstimate, string digestAlgorithm)
		{
			tsaURL = url;
