	public class X509Certificate2Signature : IExternalSignature
	{
		private X509Certificate2 certificate;

		private string hashAlgorithm;

		private string encryptionAlgorithm;

		public X509Certificate2Signature(X509Certificate2 certificate, string hashAlgorithm)
		{
			if (!certificate.HasPrivateKey)
			{
				throw new ArgumentException("No private key.");
			}
			this.certificate = certificate;
			this.hashAlgorithm = DigestAlgorithms.GetDigest(DigestAlgorithms.GetAllowedDigests(hashAlgorithm));
			if (certificate.PrivateKey is RSACryptoServiceProvider)
			{
				encryptionAlgorithm = "RSA";
				return;
			}
			if (certificate.PrivateKey is DSACryptoServiceProvider)
			{
				encryptionAlgorithm = "DSA";
				return;
			}
			throw new ArgumentException("Unknown encryption algorithm " + certificate.PrivateKey);
		}

		public virtual byte[] Sign(byte[] message)
		{
			if (certificate.PrivateKey is RSACryptoServiceProvider)
			{
				RSACryptoServiceProvider rSACryptoServiceProvider = (RSACryptoServiceProvider)certificate.PrivateKey;
				return rSACryptoServiceProvider.SignData(message, hashAlgorithm);
			}
			DSACryptoServiceProvider dSACryptoServiceProvider = (DSACryptoServiceProvider)certificate.PrivateKey;
			return dSACryptoServiceProvider.SignData(message);
		}

		public virtual string GetHashAlgorithm()
		{
			return hashAlgorithm;
		}

		public virtual string GetEncryptionAlgorithm()
		{
			return encryptionAlgorithm;
		}
	}
