		private static Type GetLicenseKeyClass()
		{
			string text = "iText.License.LicenseKey, itext.licensekey";
			string text2 = null;
			object[] customAttributes = typeof(Version).Assembly.GetCustomAttributes(typeof(KeyVersionAttribute), inherit: false);
