					catch
					{
					}
					if ((object)type == null && text3 != null)
					{
						logger.Error(text3);
					}
				}
			}
			return type;
		}

		public static Version GetInstance()
		{
			lock (staticLock)
			{
				if (Version.version != null)
				{
					return Version.version;
				}
			}
			Version version = new Version();
			try
			{
				Type licenseKeyClass = GetLicenseKeyClass();
				Type[] types = new Type[1] { typeof(string) };
				MethodInfo method = licenseKeyClass.GetMethod("GetLicenseeInfoForVersion", types);
				string text = "5.5.13.2";
				object[] parameters = new object[1] { text };
				string[] array = (string[])method.Invoke(Activator.CreateInstance(licenseKeyClass), parameters);
				if (array[3] != null && array[3].Trim().Length > 0)
				{
					version.key = array[3];
				}
				else
				{
					version.key = "Trial version ";
					if (array[5] == null)
					{
						version.key += "unauthorised";
					}
					else
					{
						version.key += array[5];
					}
				}
				if (array[4] != null && array[4].Trim().Length > 0)
				{
					version.iTextVersion = array[4];
				}
				else if (array[2] != null && array[2].Trim().Length > 0)
				{
					version.iTextVersion = version.iTextVersion + " (" + array[2];
					if (!version.key.ToLower().StartsWith("trial"))
					{
						version.iTextVersion += "; licensed version)";
					}
					else
					{
						version.iTextVersion = version.iTextVersion + "; " + version.key + ")";
					}
				}
				else
				{
					if (array[0] == null || array[0].Trim().Length <= 0)
					{
