					}
					version.iTextVersion = version.iTextVersion + " (" + array[0];
					if (!version.key.ToLower().StartsWith("trial"))
					{
						version.iTextVersion += "; licensed version)";
					}
					else
					{
						version.iTextVersion = version.iTextVersion + "; " + version.key + ")";
					}
				}
